window.MV_DATA=window.MV_DATA||{};window.MV_DATA[3]={"id":3,"topics":[{"id":21,"words":[{"en":"bolt","pos":"noun","ipa":"/boʊlt/","ja":"ボルト","kana":"ボルト","romaji":"boruto","vi":"bu lông","level":1,"def_vi":"Chi tiết kẹp chặt có đầu và thân ren ngoài, thường dùng cùng đai ốc để ghép các chi tiết với nhau.","def_en":"A headed fastener with an externally threaded shank, usually used with a nut to clamp parts together.","def_ja":"頭部とおねじの軸部をもち、通常ナットと組み合わせて部品を締結する締結部品。","usage_en":"Danh từ đếm được. Hay đi với: tighten / loosen / torque a bolt, M12 bolt, bolt hole, bolt head; lưu ý \"bolt\" thường đi với nut, còn \"screw\" thường vặn vào lỗ ren.","usage_ja":"Động từ đi kèm: ボルトを締める, 締め付ける, 緩める, 本締めする. Ghi kích thước kiểu M12×40 (đường kính × chiều dài); đếm bằng 本 (ボルト4本).","context_vi":"Dùng ở mọi mối ghép tháo được: mặt bích, khung máy, bệ đỡ, nắp hộp giảm tốc.","ex_en":"Tighten each M16 bolt on the flange in a cross pattern.","ex_ja":"フランジのM16ボルトを対角順に締め付けてください。","ex_vi":"Siết từng bu lông M16 trên mặt bích theo thứ tự chéo.","syn_en":["threaded fastener (nghĩa rộng hơn)","hex bolt (một loại)"],"syn_ja":["六角ボルト (một loại)","締結部品 (nghĩa rộng hơn)"]},{"en":"nut","pos":"noun","ipa":"/nʌt/","ja":"ナット","kana":"ナット","romaji":"natto","vi":"đai ốc (ê-cu)","level":1,"def_vi":"Chi tiết có lỗ ren trong, vặn vào bu lông hoặc vít cấy để tạo lực kẹp.","def_en":"A fastener with an internally threaded hole that is screwed onto a bolt or stud to produce clamping force.","def_ja":"めねじをもち、ボルトや植込みボルトにねじ込んで締付け力を生む締結部品。","usage_en":"Danh từ đếm được. Hay đi với: run down / tighten / back off a nut, nut and bolt, nut face; người Việt hay nói \"ê-cu\" nhưng tài liệu tiếng Anh luôn dùng nut.","usage_ja":"Động từ: ナットを締める, ナットを回す, ナットを外す. Văn bản JIS có lúc ghi chữ Hán ナット không có; luôn dùng katakana ナット, đếm bằng 個.","context_vi":"Dùng cùng bu lông ở mối ghép kết cấu thép, mặt bích ống, khung máy và cụm lắp ráp.","ex_en":"The nut had backed off because no washer was used under it.","ex_ja":"座金を使っていなかったため、ナットが緩んでいた。","ex_vi":"Đai ốc bị tự nới ra vì không dùng vòng đệm bên dưới.","syn_en":["hex nut (một loại)"],"syn_ja":["六角ナット (một loại)"]},{"en":"screw","pos":"noun","ipa":"/skruː/","ja":"ねじ","kana":"ねじ","romaji":"neji","vi":"vít","level":1,"def_vi":"Chi tiết có ren ngoài, thường được vặn trực tiếp vào lỗ ren hoặc vật liệu mà không cần đai ốc.","def_en":"An externally threaded fastener usually driven directly into a tapped hole or material without a nut.","def_ja":"おねじをもち、通常ナットを使わずにねじ穴や材料に直接ねじ込む締結部品。","usage_en":"Danh từ đếm được; cũng là động từ (screw something in/down). Hay đi với: drive / tighten / remove a screw, screw head; phân biệt screw (vặn vào lỗ ren) và bolt (dùng với nut).","usage_ja":"Trong JIS viết ねじ bằng hiragana (chữ Hán 螺子 hầu như không dùng); ねじ vừa là \"vít\" vừa là \"ren\". Động từ: ねじを締める, ねじ込む, ねじを外す.","context_vi":"Dùng ở vỏ máy, tấm che, bảng điện, cụm chi tiết nhỏ và đồ gá.","ex_en":"Remove the four screws holding the cover plate.","ex_ja":"カバープレートを固定している4本のねじを外す。","ex_vi":"Tháo bốn con vít giữ tấm nắp.","syn_en":["threaded fastener (nghĩa rộng hơn)"],"syn_ja":["ビス (khẩu ngữ, vít nhỏ)","小ねじ (một loại)"]},{"en":"washer","pos":"noun","ipa":"/ˈwɑːʃər/","ja":"座金","kana":"ざがね","romaji":"zagane","vi":"vòng đệm (long đền)","level":1,"def_vi":"Đĩa mỏng có lỗ, đặt dưới đầu bu lông hoặc đai ốc để phân bố lực và bảo vệ bề mặt.","def_en":"A thin perforated disc placed under a bolt head or nut to spread load and protect the surface.","def_ja":"ボルト頭部やナットの下に入れ、荷重を分散し座面を保護する穴あきの薄板。","usage_en":"Danh từ đếm được. Hay đi với: flat washer, plain washer, fit / place a washer under the nut; không nhầm với \"washer\" là máy rửa.","usage_ja":"Tên JIS là 座金 (ví dụ 平座金); ngoài xưởng nói ワッシャー hoặc ワッシャ. Động từ: 座金を入れる, かませる.","context_vi":"Dùng ở hầu hết mối ghép bu lông, nhất là trên vật liệu mềm như nhôm, nhựa hoặc lỗ ô van.","ex_en":"Place a hardened washer under the nut on the aluminum housing.","ex_ja":"アルミハウジング側のナットの下には焼入れ座金を入れること。","ex_vi":"Đặt một vòng đệm đã tôi cứng dưới đai ốc phía vỏ nhôm.","syn_en":["flat washer (một loại)","plain washer (một loại)"],"syn_ja":["ワッシャー","平座金 (một loại)"]},{"en":"hex bolt","pos":"noun","ipa":"/ˈheks boʊlt/","ja":"六角ボルト","kana":"ろっかくボルト","romaji":"rokkakuboruto","vi":"bu lông lục giác","level":1,"def_vi":"Bu lông có đầu hình lục giác ngoài, được siết bằng cờ lê hoặc khẩu.","def_en":"A bolt with a six-sided head that is tightened with a wrench or socket.","def_ja":"頭部が六角形で、スパナやソケットで締め付けるボルト。","usage_en":"Danh từ đếm được. Hay viết: hex bolt M10 x 50, hex head bolt, fully threaded / partially threaded hex bolt; \"hex cap screw\" là tên gần nghĩa ở Mỹ.","usage_ja":"Tên JIS B 1180 là 六角ボルト; ghi M10×50 sau tên. Phân biệt 全ねじ (ren suốt) và 半ねじ (ren lửng).","context_vi":"Là loại bu lông phổ biến nhất ở kết cấu thép, khung máy, mặt bích và bệ máy.","ex_en":"Use a fully threaded hex bolt M10 x 40, property class 8.8.","ex_ja":"全ねじの六角ボルトM10×40、強度区分8.8を使用する。","ex_vi":"Dùng bu lông lục giác ren suốt M10 x 40, cấp bền 8.8.","syn_en":["hex head bolt","hex cap screw (Mỹ, gần nghĩa)"],"syn_ja":["ボルト (nghĩa rộng hơn)"]},{"en":"hex nut","pos":"noun","ipa":"/ˈheks nʌt/","ja":"六角ナット","kana":"ろっかくナット","romaji":"rokkakunatto","vi":"đai ốc lục giác","level":1,"def_vi":"Đai ốc có sáu cạnh ngoài, loại tiêu chuẩn dùng với bu lông lục giác.","def_en":"A six-sided nut, the standard type used with hex bolts.","def_ja":"外形が六角形のナットで、六角ボルトと組み合わせる標準的なもの。","usage_en":"Danh từ đếm được. Hay đi với: M12 hex nut, heavy hex nut, thin hex nut (jam nut); chọn cấp bền nut tương ứng với bolt (ví dụ class 8 với 8.8).","usage_ja":"Tên JIS B 1181 là 六角ナット; có các loại 1種, 2種, 3種 (loại mỏng). Đếm bằng 個.","context_vi":"Dùng cùng bu lông lục giác ở kết cấu thép, mặt bích, khung đỡ và thiết bị cơ khí chung.","ex_en":"Each anchor uses one hex nut and one hardened washer.","ex_ja":"各アンカーには六角ナット1個と焼入れ座金1枚を使う。","ex_vi":"Mỗi bu lông neo dùng một đai ốc lục giác và một vòng đệm tôi cứng.","syn_en":["hexagon nut","nut (nghĩa rộng hơn)"],"syn_ja":["ナット (nghĩa rộng hơn)"]},{"en":"socket head cap screw","pos":"noun phrase","ipa":"/ˈsɑːkɪt hed ˈkæp skruː/","ja":"六角穴付きボルト","kana":"ろっかくあなつきボルト","romaji":"rokkakuanatsukiboruto","vi":"bu lông lục giác chìm (đầu trụ)","level":1,"def_vi":"Vít/bu lông đầu trụ có lỗ lục giác ở đầu, siết bằng lục giác chìm (chìa lục giác).","def_en":"A cylindrical-head screw with a hexagon socket in the head, driven with a hex key.","def_ja":"円筒形の頭部に六角穴があり、六角棒スパナで締め付けるボルト。","usage_en":"Danh từ đếm được, viết tắt SHCS. Hay đi với: M8 socket head cap screw, counterbored for a socket head cap screw; hay gọi ngắn \"cap screw\" hoặc \"Allen bolt\" (khẩu ngữ).","usage_ja":"Tên JIS B 1176 là 六角穴付きボルト; ngoài xưởng gọi キャップボルト hoặc キャップスクリュー. Thường lắp vào lỗ 座ぐり để đầu chìm.","context_vi":"Dùng rất nhiều trong đồ gá, khuôn, máy công cụ và cụm cơ khí chính xác vì đầu nhỏ, lực siết lớn.","ex_en":"The clamp block is fixed with two M8 socket head cap screws in counterbored holes.","ex_ja":"クランプブロックは座ぐり穴に入れたM8の六角穴付きボルト2本で固定する。","ex_vi":"Khối kẹp được cố định bằng hai bu lông lục giác chìm M8 lắp trong lỗ bậc.","syn_en":["SHCS","cap screw","Allen bolt (khẩu ngữ)"],"syn_ja":["キャップボルト","キャップスクリュー"]},{"en":"spring washer","pos":"noun","ipa":"/ˈsprɪŋ ˌwɑːʃər/","ja":"ばね座金","kana":"ばねざがね","romaji":"banezagane","vi":"vòng đệm vênh (long đền vênh)","level":1,"def_vi":"Vòng đệm bị cắt và vênh dạng lò xo, đặt dưới đai ốc với mục đích hạn chế lỏng ren.","def_en":"A split, helically bent washer placed under a nut or bolt head, intended to resist loosening.","def_ja":"切れ目を入れてねじった形状の座金で、ナットなどの緩み止めを目的に使う。","usage_en":"Danh từ đếm được. Hay gọi \"split lock washer\" ở Mỹ; lưu ý nhiều tài liệu (VDI 2230) cho rằng spring washer chống lỏng kém dưới rung ngang.","usage_ja":"Tên JIS là ばね座金; ngoài xưởng gọi スプリングワッシャー hoặc nói tắt スプワ. Thường đặt trên 平座金: 平座金＋ばね座金.","context_vi":"Dùng ở máy móc, tủ điện, thiết bị gia dụng; với mối ghép quan trọng chịu rung nên dùng biện pháp chống lỏng khác.","ex_en":"The drawing specifies a flat washer plus a spring washer under every nut.","ex_ja":"図面ではすべてのナットの下に平座金とばね座金を入れるよう指示している。","ex_vi":"Bản vẽ yêu cầu lắp một vòng đệm phẳng và một vòng đệm vênh dưới mỗi đai ốc.","syn_en":["split lock washer (Mỹ)","lock washer (nghĩa rộng hơn)"],"syn_ja":["スプリングワッシャー","スプワ (khẩu ngữ)"]},{"en":"wing nut","pos":"noun","ipa":"/ˈwɪŋ nʌt/","ja":"蝶ナット","kana":"ちょうナット","romaji":"chounatto","vi":"đai ốc tai hồng (đai ốc cánh bướm)","level":1,"def_vi":"Đai ốc có hai tai lớn để siết và tháo bằng tay mà không cần dụng cụ.","def_en":"A nut with two large wings so it can be tightened and loosened by hand without tools.","def_ja":"2枚の羽をもち、工具を使わず手で締め外しできるナット。","usage_en":"Danh từ đếm được. Hay đi với: hand-tighten a wing nut, secured by a wing nut; chỉ dùng cho lực siết nhỏ.","usage_ja":"Tên JIS là 蝶ナット (chữ Hán 蝶 = con bướm); đôi khi viết ちょうナット. Thường nói 手で締める.","context_vi":"Dùng ở nắp kiểm tra, tấm che, đồ gá tháo lắp nhanh và thiết bị cần điều chỉnh thường xuyên.","ex_en":"The inspection cover is held by a wing nut so operators can open it quickly.","ex_ja":"点検カバーは作業者がすぐ開けられるよう蝶ナットで固定している。","ex_vi":"Nắp kiểm tra được giữ bằng đai ốc tai hồng để công nhân mở nhanh.","syn_en":["butterfly nut"],"syn_ja":["ちょうナット","ローレットナット (liên quan)"]},{"en":"external thread","pos":"noun phrase","ipa":"/ɪkˈstɜːrnl θred/","ja":"おねじ","kana":"おねじ","romaji":"oneji","vi":"ren ngoài","level":1,"def_vi":"Ren được tạo trên mặt ngoài của chi tiết trụ, như thân bu lông hay vít.","def_en":"A thread formed on the outside surface of a cylindrical part, such as a bolt shank.","def_ja":"ボルトの軸部のように、円筒の外面に設けたねじ。","usage_en":"Danh từ đếm được. Hay đi với: cut / roll an external thread, external thread M20 x 1.5; đối lập với internal thread; khẩu ngữ Mỹ: male thread.","usage_ja":"JIS viết おねじ (chữ Hán 雄ねじ cũng gặp). Động từ: おねじを切る, 転造する. Đối lập với めねじ.","context_vi":"Dùng khi đọc bản vẽ, ghi ký hiệu ren, chọn dao tiện ren hoặc bàn ren.","ex_en":"The external thread on the shaft end is M20 x 1.5, tolerance class 6g.","ex_ja":"軸端のおねじはM20×1.5、公差域クラス6gである。","ex_vi":"Ren ngoài ở đầu trục là M20 x 1,5, miền dung sai 6g.","syn_en":["male thread (khẩu ngữ)"],"syn_ja":["雄ねじ"]},{"en":"internal thread","pos":"noun phrase","ipa":"/ɪnˈtɜːrnl θred/","ja":"めねじ","kana":"めねじ","romaji":"meneji","vi":"ren trong","level":1,"def_vi":"Ren được tạo trên mặt trong của lỗ, như ren trong đai ốc hoặc lỗ ren.","def_en":"A thread formed on the inside surface of a hole, such as in a nut or tapped hole.","def_ja":"ナットやねじ穴のように、穴の内面に設けたねじ。","usage_en":"Danh từ đếm được. Hay đi với: tap an internal thread, internal thread depth, damaged internal thread; khẩu ngữ Mỹ: female thread.","usage_ja":"JIS viết めねじ (chữ Hán 雌ねじ cũng gặp). Động từ: めねじを立てる, タップでめねじを加工する.","context_vi":"Dùng khi ghi lỗ ren trên bản vẽ, kiểm tra ren bằng calip nút, sửa ren hỏng.","ex_en":"The internal thread in the cast iron housing was damaged during assembly.","ex_ja":"鋳鉄ハウジングのめねじが組立中に損傷した。","ex_vi":"Ren trong ở vỏ gang bị hỏng trong lúc lắp ráp.","syn_en":["female thread (khẩu ngữ)","tapped hole (liên quan)"],"syn_ja":["雌ねじ","ねじ穴 (liên quan)"]},{"en":"machine screw","pos":"noun","ipa":"/məˈʃiːn skruː/","ja":"小ねじ","kana":"こねじ","romaji":"koneji","vi":"vít máy (vít nhỏ)","level":2,"def_vi":"Vít cỡ nhỏ có ren hệ mét đều, đầu xẻ rãnh hoặc chữ thập, vặn vào lỗ ren hoặc đai ốc.","def_en":"A small screw with a uniform machine thread and slotted or cross-recess head, used in tapped holes or nuts.","def_ja":"すりわりや十字穴の頭部をもつ小径のねじで、ねじ穴やナットに使う。","usage_en":"Danh từ đếm được. Hay đi với: pan head machine screw, flat head machine screw, M3 machine screw; khác với tapping screw ở chỗ cần lỗ đã có ren.","usage_ja":"Tên JIS là 小ねじ; ghép loại đầu phía trước: なべ小ねじ, 皿小ねじ, 十字穴付き小ねじ. Ngoài xưởng hay gọi ビス.","context_vi":"Dùng trong thiết bị điện, bảng điều khiển, cụm cảm biến và các chi tiết nhỏ.","ex_en":"Fix the sensor bracket with two M4 pan head machine screws.","ex_ja":"センサブラケットはM4のなべ小ねじ2本で固定する。","ex_vi":"Cố định giá đỡ cảm biến bằng hai vít máy đầu tròn M4.","syn_en":["screw (nghĩa rộng hơn)"],"syn_ja":["ビス (khẩu ngữ)","なべ小ねじ (một loại)"]},{"en":"tapping screw","pos":"noun","ipa":"/ˈtæpɪŋ skruː/","ja":"タッピンねじ","kana":"タッピンねじ","romaji":"tappinneji","vi":"vít tự ren (vít tự cắt ren)","level":2,"def_vi":"Vít tự tạo ren khi vặn vào lỗ trơn trên tôn mỏng, nhựa hoặc kim loại mềm.","def_en":"A screw that forms or cuts its own thread when driven into a plain hole in sheet metal, plastic or soft metal.","def_ja":"薄板や樹脂などの下穴にねじ込むと、自らねじ山を成形または切削するねじ。","usage_en":"Danh từ đếm được. Hay gọi \"self-tapping screw\"; đi với: pilot hole, drive a tapping screw into sheet metal; không nên tháo lắp nhiều lần.","usage_ja":"Tên JIS là タッピンねじ (không phải タッピングねじ). Cần 下穴 đúng cỡ; có các kiểu 1種, 2種, 3種 và ねじ形成タッピンねじ.","context_vi":"Dùng ở vỏ tôn, tủ điện, chi tiết nhựa đúc và đồ gia dụng.","ex_en":"Drill a 2.5 mm pilot hole before driving the tapping screw into the plastic boss.","ex_ja":"樹脂ボスにタッピンねじを締める前に、直径2.5 mmの下穴をあけておく。","ex_vi":"Khoan lỗ mồi 2,5 mm trước khi bắt vít tự ren vào trụ nhựa.","syn_en":["self-tapping screw","thread-forming screw (một loại)"],"syn_ja":["タッピングビス (khẩu ngữ)","セルフタッピンねじ"]},{"en":"set screw","pos":"noun","ipa":"/ˈset skruː/","ja":"止めねじ","kana":"とめねじ","romaji":"tomeneji","vi":"vít trí (vít định vị)","level":2,"def_vi":"Vít không đầu, vặn vào lỗ ren để mũi vít ép lên chi tiết khác, giữ nó không xoay hay trượt.","def_en":"A headless screw whose tip presses against another part to stop it rotating or sliding.","def_ja":"頭部がなく、先端を相手部品に押し付けて回り止めや位置決めをするねじ。","usage_en":"Danh từ đếm được. Hay đi với: cup point set screw, tighten the set screw onto the shaft flat; ở Anh còn gọi grub screw.","usage_ja":"Tên JIS là 止めねじ; loại lục giác chìm gọi 六角穴付き止めねじ, ngoài xưởng gọi イモネジ. Ghép kiểu mũi: とがり先, くぼみ先, 平先.","context_vi":"Dùng để giữ puly, bánh răng, tay quay, vòng chặn trên trục nhỏ.","ex_en":"Tighten the set screw against the flat on the shaft so the pulley cannot slip.","ex_ja":"プーリが滑らないよう、止めねじを軸のDカット面に締め付ける。","ex_vi":"Siết vít trí tì lên mặt vát phẳng của trục để puly không bị trượt.","syn_en":["grub screw (Anh)"],"syn_ja":["イモネジ (khẩu ngữ)","セットスクリュー"]},{"en":"stud bolt","pos":"noun","ipa":"/ˈstʌd boʊlt/","ja":"植込みボルト","kana":"うえこみボルト","romaji":"uekomiboruto","vi":"vít cấy (bu lông cấy)","level":2,"def_vi":"Thanh có ren hai đầu, một đầu vặn cố định vào lỗ ren của thân máy, đầu kia lắp đai ốc.","def_en":"A rod threaded at both ends; one end is screwed permanently into a tapped hole and the other takes a nut.","def_ja":"両端にねじを切った棒で、一端を本体のねじ穴に植え込み、他端にナットを締める。","usage_en":"Danh từ đếm được, hay nói gọn \"stud\". Hay đi với: install / drive a stud, stud and nut; \"stud bolt\" cũng chỉ thanh ren suốt dùng cho mặt bích ống.","usage_ja":"Tên JIS là 植込みボルト; ngoài xưởng gọi スタッドボルト hoặc スタッド. Động từ: 植え込む. Phía cấy gọi 植込み側, phía đai ốc gọi ナット側.","context_vi":"Dùng ở nắp xi lanh, thân động cơ, vỏ tuabin, nơi thân máy bằng gang/nhôm cần tháo nắp nhiều lần.","ex_en":"Each stud bolt is screwed into the cylinder block before the head is fitted.","ex_ja":"シリンダヘッドを載せる前に、各植込みボルトをシリンダブロックにねじ込む。","ex_vi":"Mỗi vít cấy được vặn vào thân xi lanh trước khi lắp nắp máy.","syn_en":["stud","double-end stud"],"syn_ja":["スタッドボルト","スタッド"]},{"en":"flange nut","pos":"noun","ipa":"/ˈflændʒ nʌt/","ja":"フランジナット","kana":"フランジナット","romaji":"furanjinatto","vi":"đai ốc có vành (đai ốc bích)","level":2,"def_vi":"Đai ốc lục giác có vành rộng liền khối ở mặt tựa, thay cho vòng đệm.","def_en":"A hex nut with an integral wide flange on its bearing face that replaces a separate washer.","def_ja":"座面に一体のつばをもち、座金の代わりをする六角ナット。","usage_en":"Danh từ đếm được. Hay đi với: serrated flange nut, hex flange nut; dùng khi muốn giảm số chi tiết rời trong lắp ráp.","usage_ja":"Tên JIS là 六角フランジ付きナット; ngoài xưởng gọi フランジナット. Loại có răng chống lỏng gọi セレート付きフランジナット.","context_vi":"Dùng nhiều trong ô tô, xe máy, thiết bị điện, dây chuyền lắp ráp số lượng lớn.","ex_en":"We replaced the nut and washer with a serrated flange nut to cut assembly time.","ex_ja":"組立時間短縮のため、ナットと座金をセレート付きフランジナットに置き換えた。","ex_vi":"Chúng tôi thay đai ốc và vòng đệm bằng đai ốc có vành răng cưa để giảm thời gian lắp.","syn_en":["hex flange nut","serrated flange nut (một loại)"],"syn_ja":["六角フランジ付きナット"]},{"en":"lock nut","pos":"noun","ipa":"/ˈlɑːk nʌt/","ja":"緩み止めナット","kana":"ゆるみどめナット","romaji":"yurumidomenatto","vi":"đai ốc hãm (đai ốc chống lỏng)","level":2,"def_vi":"Đai ốc có cấu tạo đặc biệt (vòng nylon, biến dạng ren…) để chống tự nới lỏng khi rung.","def_en":"A nut with a special feature, such as a nylon insert or distorted thread, that resists loosening under vibration.","def_ja":"ナイロンリングやねじ部の変形などにより、振動による緩みを防ぐ構造をもつナット。","usage_en":"Danh từ đếm được, cũng viết locknut. Hay đi với: nylon-insert lock nut (nyloc), prevailing-torque lock nut; \"jam nut\" là đai ốc mỏng siết đè lên đai ốc chính.","usage_ja":"Từ chung là 緩み止めナット; loại nylon gọi ナイロンナット, hai đai ốc chồng gọi ダブルナット. Lưu ý ロックナット trong catalog Nhật thường là đai ốc giữ ổ lăn.","context_vi":"Dùng ở máy rung, xe cộ, sàng rung, máy nông nghiệp và nơi không được phép lỏng mối ghép.","ex_en":"A nylon-insert lock nut must not be reused after removal.","ex_ja":"ナイロンリング付きの緩み止めナットは、一度外したら再使用しないこと。","ex_vi":"Đai ốc hãm có vòng nylon không được dùng lại sau khi đã tháo.","syn_en":["locknut","nyloc nut (một loại)","jam nut (liên quan)"],"syn_ja":["ナイロンナット (một loại)","ダブルナット (liên quan)"]},{"en":"thread pitch","pos":"noun phrase","ipa":"/ˈθred pɪtʃ/","ja":"ピッチ","kana":"ピッチ","romaji":"pitchi","vi":"bước ren","level":2,"def_vi":"Khoảng cách dọc trục giữa hai đỉnh ren kề nhau, tính bằng mm với ren hệ mét.","def_en":"The axial distance between adjacent thread crests, given in millimetres for metric threads.","def_ja":"隣り合うねじ山の対応する点の軸方向距離。メートルねじではmmで表す。","usage_en":"Danh từ đếm được. Hay đi với: a thread pitch of 1.5 mm, measure the thread pitch with a pitch gauge; ren inch dùng TPI (threads per inch) thay cho pitch.","usage_ja":"Trong ngữ cảnh ren nói ピッチ hoặc ねじのピッチ; ghi trong ký hiệu M20×1.5 (1.5 là ピッチ). Dụng cụ đo: ピッチゲージ.","context_vi":"Dùng khi ghi ký hiệu ren, lập trình tiện ren, chọn mũi ta rô và kiểm tra ren.","ex_en":"An M12 coarse thread has a thread pitch of 1.75 mm.","ex_ja":"M12並目ねじのピッチは1.75 mmである。","ex_vi":"Ren bước lớn M12 có bước ren 1,75 mm.","syn_en":["pitch","TPI (liên quan, hệ inch)"],"syn_ja":["ねじのピッチ","山数 (liên quan, hệ inch)"]},{"en":"metric thread","pos":"noun phrase","ipa":"/ˈmetrɪk θred/","ja":"メートルねじ","kana":"メートルねじ","romaji":"meetoruneji","vi":"ren hệ mét","level":2,"def_vi":"Ren tam giác góc 60° theo tiêu chuẩn ISO, ký hiệu bằng chữ M và đường kính tính bằng mm.","def_en":"An ISO 60-degree triangular thread designated by the letter M and the diameter in millimetres.","def_ja":"ISOによる山の角度60度の三角ねじで、Mと呼び径(mm)で表す。","usage_en":"Danh từ đếm được. Hay đi với: ISO metric thread, metric coarse / fine thread; ký hiệu ví dụ M8, M10 x 1.25.","usage_ja":"Tên JIS là メートルねじ; chia thành メートル並目ねじ và メートル細目ねじ. Trên bản vẽ chỉ ghi M8, M10×1.25.","context_vi":"Là hệ ren chuẩn ở Việt Nam, Nhật Bản, châu Âu cho hầu hết chi tiết máy.","ex_en":"All fasteners on this machine use metric thread sizes; no inch parts are allowed.","ex_ja":"この機械の締結部品はすべてメートルねじとし、インチねじは使用しない。","ex_vi":"Mọi chi tiết ghép trên máy này dùng ren hệ mét; không dùng chi tiết hệ inch.","syn_en":["ISO metric thread","M thread"],"syn_ja":["Mねじ","ユニファイねじ (liên quan, hệ inch)"]},{"en":"coarse thread","pos":"noun phrase","ipa":"/ˈkɔːrs θred/","ja":"並目ねじ","kana":"なみめねじ","romaji":"namimeneji","vi":"ren bước lớn (ren thô, ren tiêu chuẩn)","level":2,"def_vi":"Ren có bước tiêu chuẩn lớn nhất cho mỗi đường kính, dùng mặc định cho bu lông thông thường.","def_en":"The standard thread series with the larger pitch for each diameter, used by default for general fasteners.","def_ja":"各呼び径に対して標準的な大きいピッチをもつねじで、一般の締結に用いる。","usage_en":"Danh từ không đếm được khi nói chung (coarse thread series). Hay đi với: M10 coarse thread, coarse-thread bolt; trên bản vẽ không ghi pitch nghĩa là coarse thread.","usage_ja":"Tên JIS là 並目ねじ; trên bản vẽ chỉ ghi M10 (không ghi ピッチ) là hiểu 並目. Đối lập với 細目ねじ.","context_vi":"Dùng mặc định trong khung máy, kết cấu thép và các chi tiết tháo lắp thường xuyên.","ex_en":"Coarse thread is preferred for aluminum parts because it strips less easily.","ex_ja":"アルミ部品ではねじ山が崩れにくい並目ねじが好まれる。","ex_vi":"Ren bước lớn được ưu tiên cho chi tiết nhôm vì ít bị toét ren hơn.","syn_en":["standard pitch thread","UNC (liên quan, hệ inch)"],"syn_ja":["並目","メートル並目ねじ"]},{"en":"fine thread","pos":"noun phrase","ipa":"/ˈfaɪn θred/","ja":"細目ねじ","kana":"ほそめねじ","romaji":"hosomeneji","vi":"ren bước nhỏ (ren mịn)","level":2,"def_vi":"Ren có bước nhỏ hơn ren tiêu chuẩn cùng đường kính, cho điều chỉnh tinh và ít lỏng hơn.","def_en":"A thread with a smaller pitch than the standard series for the same diameter, giving finer adjustment and better resistance to loosening.","def_ja":"同じ呼び径の並目より小さいピッチのねじで、微調整や緩みにくさに優れる。","usage_en":"Danh từ không đếm được khi nói chung. Hay đi với: M16 x 1.5 fine thread, fine-thread bolt; luôn phải ghi pitch trên bản vẽ.","usage_ja":"Tên JIS là 細目ねじ; bắt buộc ghi ピッチ như M16×1.5. Hay dùng cho 薄肉部品 và 調整ねじ.","context_vi":"Dùng ở chi tiết thành mỏng, ren điều chỉnh, đai ốc giữ ổ lăn, ngành ô tô và hàng không.","ex_en":"The bearing lock nut uses an M40 x 1.5 fine thread.","ex_ja":"軸受用ロックナットにはM40×1.5の細目ねじを用いる。","ex_vi":"Đai ốc hãm ổ lăn dùng ren bước nhỏ M40 x 1,5.","syn_en":["fine pitch thread","UNF (liên quan, hệ inch)"],"syn_ja":["細目","メートル細目ねじ"]},{"en":"left-hand thread","pos":"noun phrase","ipa":"/ˌleft hænd ˈθred/","ja":"左ねじ","kana":"ひだりねじ","romaji":"hidarineji","vi":"ren trái","level":2,"def_vi":"Ren được siết vào khi xoay ngược chiều kim đồng hồ, dùng để tránh tự nới do chiều quay.","def_en":"A thread that tightens when turned anticlockwise, used where normal rotation would loosen a right-hand thread.","def_ja":"反時計回りに回すと締まるねじで、回転方向による緩みを防ぐ場合などに用いる。","usage_en":"Danh từ đếm được. Ký hiệu LH (ví dụ M12-LH); hay đi với: left-hand thread nut, cut a left-hand thread; ngược với right-hand thread.","usage_ja":"Tên JIS là 左ねじ, ký hiệu LH (ví dụ M12-LH). Đối lập với 右ねじ; trên chi tiết thường khắc rãnh nhận biết.","context_vi":"Dùng ở trục máy mài, bàn đạp xe đạp bên trái, tăng đơ, van chai khí cháy.","ex_en":"The grinding wheel nut on the left side has a left-hand thread.","ex_ja":"左側の砥石固定ナットは左ねじになっている。","ex_vi":"Đai ốc giữ đá mài phía bên trái là ren trái.","syn_en":["LH thread","right-hand thread (liên quan, ngược nghĩa)"],"syn_ja":["逆ねじ (khẩu ngữ)","右ねじ (liên quan, ngược nghĩa)"]},{"en":"tightening torque","pos":"noun phrase","ipa":"/ˈtaɪtnɪŋ tɔːrk/","ja":"締付けトルク","kana":"しめつけトルク","romaji":"shimetsuketoruku","vi":"mô-men xiết","level":2,"def_vi":"Mô-men xoắn tác dụng lên bu lông hoặc đai ốc khi siết, thường quy định bằng N·m.","def_en":"The torque applied to a bolt or nut during tightening, usually specified in N·m.","def_ja":"ボルトやナットを締め付けるときに加えるトルク。通常N·mで指示する。","usage_en":"Danh từ không đếm được. Hay đi với: specified tightening torque, apply a tightening torque of 50 N·m, torque wrench; cũng nói ngắn \"torque\".","usage_ja":"Viết 締付けトルク hoặc 締め付けトルク. Hay đi với: 締付けトルクを管理する, 規定トルクで締める, トルクレンチ.","context_vi":"Dùng trong bản vẽ lắp, hướng dẫn bảo trì, quy trình lắp ráp ô tô, kết cấu thép và mặt bích.","ex_en":"The tightening torque for these M10 bolts is 49 N·m.","ex_ja":"このM10ボルトの締付けトルクは49 N·mである。","ex_vi":"Mô-men xiết cho các bu lông M10 này là 49 N·m.","syn_en":["torque","assembly torque"],"syn_ja":["締め付けトルク","規定トルク (liên quan)"]},{"en":"property class","pos":"noun phrase","ipa":"/ˈprɑːpərti klæs/","ja":"強度区分","kana":"きょうどくぶん","romaji":"kyoudokubun","vi":"cấp bền","level":2,"def_vi":"Ký hiệu số chỉ độ bền kéo và giới hạn chảy của bu lông, vít hoặc đai ốc, như 8.8, 10.9.","def_en":"A numerical designation of the tensile and yield strength of a bolt, screw or nut, such as 8.8 or 10.9.","def_ja":"ボルトやナットの引張強さと降伏点を示す記号で、8.8や10.9のように表す。","usage_en":"Danh từ đếm được. Hay đi với: property class 8.8 / 10.9 / 12.9, bolts of property class 10.9; \"grade\" là cách gọi ở Mỹ (Grade 5, Grade 8).","usage_ja":"Tên JIS là 強度区分; ví dụ 強度区分8.8, 10.9. Thường được dập nổi trên đầu bu lông.","context_vi":"Dùng khi chọn bu lông, đọc bản vẽ, kiểm tra hàng nhập và tính toán mối ghép.","ex_en":"Only bolts of property class 10.9 may be used for the motor mount.","ex_ja":"モータ取付部には強度区分10.9のボルトのみ使用すること。","ex_vi":"Chỉ được dùng bu lông cấp bền 10.9 cho bệ lắp động cơ.","syn_en":["strength grade","grade (Mỹ)"],"syn_ja":["強度等級"]},{"en":"threadlocker","pos":"noun","ipa":"/ˈθredlɑːkər/","ja":"ねじロック剤","kana":"ねじロックざい","romaji":"nejirokkuzai","vi":"keo khóa ren","level":2,"def_vi":"Keo lỏng kỵ khí bôi lên ren, đông cứng khi siết để chống lỏng và làm kín ren.","def_en":"An anaerobic liquid adhesive applied to threads that cures after tightening to prevent loosening and seal the thread.","def_ja":"ねじ部に塗布し、締付け後に硬化して緩み止めとシールを行う嫌気性の液状接着剤。","usage_en":"Danh từ không đếm được. Hay đi với: apply threadlocker, medium-strength (blue) / high-strength (red) threadlocker; thường gọi theo thương hiệu Loctite.","usage_ja":"Ngoài xưởng gọi theo tên hãng: ロックタイト, スリーボンド. Động từ: ねじロック剤を塗布する; phân biệt 中強度 và 高強度.","context_vi":"Dùng trong bảo trì máy, lắp ráp ô tô, đồ gá, vít trí và những mối ghép chịu rung.","ex_en":"Apply medium-strength threadlocker to the set screw before final tightening.","ex_ja":"本締めの前に、止めねじに中強度のねじロック剤を塗布する。","ex_vi":"Bôi keo khóa ren độ bền trung bình lên vít trí trước khi siết lần cuối.","syn_en":["thread-locking adhesive","Loctite (thương hiệu)"],"syn_ja":["嫌気性接着剤 (nghĩa rộng hơn)","ロックタイト (thương hiệu)"]},{"en":"bolt preload","pos":"noun phrase","ipa":"/ˈboʊlt ˈpriːloʊd/","ja":"軸力","kana":"じくりょく","romaji":"jikuryoku","vi":"lực xiết dọc trục (lực căng ban đầu của bu lông)","level":3,"def_vi":"Lực kéo dọc trục sinh ra trong bu lông khi siết, tạo lực kẹp giữa các chi tiết ghép.","def_en":"The axial tensile force created in a bolt by tightening, which produces the clamp force on the joint.","def_ja":"締付けによってボルトに生じる軸方向の引張力で、被締結部材を締め付ける力となる。","usage_en":"Danh từ không đếm được. Hay đi với: achieve / lose bolt preload, preload scatter, target preload; liên quan clamp force, chỉ khoảng 10% mô-men xiết biến thành preload.","usage_ja":"Đầy đủ là 締付け軸力; hay đi với: 軸力を管理する, 軸力が低下する, 軸力計. Tiếng Nhật dùng 軸力 rất phổ biến trong thiết kế và kiểm tra.","context_vi":"Dùng khi tính toán mối ghép bu lông theo VDI 2230, phân tích lỏng hoặc gãy bu lông, mặt bích chịu áp.","ex_en":"Loss of bolt preload caused the joint to slip and the bolt to fail by fatigue.","ex_ja":"軸力の低下により継手が滑り、ボルトが疲労破壊した。","ex_vi":"Sự sụt giảm lực xiết dọc trục làm mối ghép bị trượt và bu lông gãy do mỏi.","syn_en":["preload","clamp force (gần nghĩa)"],"syn_ja":["締付け軸力","締付け力 (gần nghĩa)"]},{"en":"pitch diameter","pos":"noun phrase","ipa":"/ˈpɪtʃ daɪˌæmɪtər/","ja":"有効径","kana":"ゆうこうけい","romaji":"yuukoukei","vi":"đường kính trung bình (của ren)","level":3,"def_vi":"Đường kính của hình trụ tưởng tượng mà trên đó bề rộng rãnh và bề rộng ren bằng nhau.","def_en":"The diameter of an imaginary cylinder on which the thread groove width equals the thread ridge width.","def_ja":"ねじ溝の幅とねじ山の幅が等しくなる仮想円筒の直径。","usage_en":"Danh từ đếm được. Hay đi với: measure the pitch diameter with thread wires, pitch diameter tolerance; trong ISO còn gọi effective diameter.","usage_ja":"Tên JIS là 有効径; đo bằng 三針法 hoặc ねじマイクロメータ. Là kích thước quyết định độ ăn khớp ren.","context_vi":"Dùng trong kiểm tra ren, thiết kế calip ren, tính toán độ bền ren và ren truyền động.","ex_en":"The pitch diameter of the thread was checked using the three-wire method.","ex_ja":"ねじの有効径を三針法で測定した。","ex_vi":"Đường kính trung bình của ren được kiểm tra bằng phương pháp ba dây.","syn_en":["effective diameter","simple pitch diameter (gần nghĩa)"],"syn_ja":["ピッチ径 (khẩu ngữ)"]},{"en":"thread engagement length","pos":"noun phrase","ipa":"/ˈθred ɪnˈɡeɪdʒmənt leŋθ/","ja":"はめあい長さ","kana":"はめあいながさ","romaji":"hameainagasa","vi":"chiều dài ăn khớp ren","level":3,"def_vi":"Chiều dài dọc trục mà ren ngoài và ren trong thực sự ăn khớp với nhau.","def_en":"The axial length over which the external and internal threads are actually in contact.","def_ja":"おねじとめねじが実際にかみ合っている軸方向の長さ。","usage_en":"Danh từ không đếm được. Hay đi với: minimum thread engagement length, 1.5 x d engagement in aluminum; nói ngắn \"thread engagement\".","usage_ja":"Đầy đủ là ねじのはめあい長さ; ngoài xưởng hay nói かかり代 hoặc ねじ込み深さ. Thường lấy 1d với thép, 1.5d–2d với nhôm.","context_vi":"Dùng khi thiết kế chiều sâu lỗ ren, tránh toét ren trong vật liệu mềm như nhôm, gang.","ex_en":"For the aluminum housing, a thread engagement length of at least 2d is required.","ex_ja":"アルミハウジングでは、はめあい長さを2d以上確保する必要がある。","ex_vi":"Với vỏ nhôm, cần chiều dài ăn khớp ren tối thiểu 2d.","syn_en":["thread engagement","length of engagement"],"syn_ja":["ねじ込み深さ (gần nghĩa)","かかり代 (khẩu ngữ)"]},{"en":"torque coefficient","pos":"noun phrase","ipa":"/ˈtɔːrk ˌkoʊɪˈfɪʃnt/","ja":"トルク係数","kana":"トルクけいすう","romaji":"torukukeisuu","vi":"hệ số mô-men xiết (hệ số K)","level":3,"def_vi":"Hệ số K trong công thức T = K·d·F, liên hệ mô-men xiết với lực xiết dọc trục, phụ thuộc ma sát.","def_en":"The factor K in T = K·d·F relating tightening torque to bolt preload, mainly governed by friction.","def_ja":"T=K·d·Fにおける係数Kで、締付けトルクと軸力の関係を表し、主に摩擦で決まる。","usage_en":"Danh từ đếm được. Hay gọi \"nut factor\" hoặc \"K factor\"; giá trị điển hình 0.15–0.20 cho bu lông thép khô, giảm khi bôi trơn.","usage_ja":"Tên JIS là トルク係数, ký hiệu K. Hay đi với: トルク係数のばらつき, 潤滑によりトルク係数が下がる.","context_vi":"Dùng khi tính mô-men xiết, đánh giá ảnh hưởng của bôi trơn, lớp mạ đến lực xiết thực tế.","ex_en":"Using molybdenum paste lowered the torque coefficient from 0.18 to 0.12.","ex_ja":"二硫化モリブデンペーストの使用でトルク係数が0.18から0.12に下がった。","ex_vi":"Dùng mỡ molypden làm hệ số mô-men xiết giảm từ 0,18 xuống 0,12.","syn_en":["nut factor","K factor"],"syn_ja":["K値 (khẩu ngữ)","摩擦係数 (liên quan)"]},{"en":"angle-controlled tightening","pos":"noun phrase","ipa":"/ˈæŋɡl kənˌtroʊld ˈtaɪtnɪŋ/","ja":"回転角法","kana":"かいてんかくほう","romaji":"kaitenkakuhou","vi":"phương pháp siết theo góc xoay","level":3,"def_vi":"Phương pháp siết bu lông đến một mô-men khởi đầu rồi xoay thêm một góc quy định để đạt lực xiết chính xác hơn.","def_en":"A method of tightening a bolt to a snug torque and then turning it through a specified angle for more consistent preload.","def_ja":"スナグトルクまで締めた後、規定角度だけ回転させて軸力のばらつきを小さくする締付け方法。","usage_en":"Danh từ không đếm được. Hay nói \"torque-angle tightening\" hoặc \"turn-of-nut method\" (kết cấu thép); ví dụ: 30 N·m + 90°.","usage_ja":"Tên JIS là 回転角法 (cùng với トルク法, トルクこう配法). Ghi chỉ thị kiểu 30 N·m＋90°; trong kết cấu thép gọi ナット回転法.","context_vi":"Dùng trong lắp nắp máy động cơ, bu lông thanh truyền, bu lông cường độ cao kết cấu thép.","ex_en":"Cylinder head bolts are installed by angle-controlled tightening: 40 N·m plus 90 degrees.","ex_ja":"シリンダヘッドボルトは回転角法で、40 N·m締付け後に90度回して締める。","ex_vi":"Bu lông nắp máy được siết theo góc xoay: 40 N·m rồi xoay thêm 90 độ.","syn_en":["torque-angle tightening","turn-of-nut method"],"syn_ja":["ナット回転法","塑性域締付け (liên quan)"]}]},{"id":22,"words":[{"en":"shaft","pos":"noun","ipa":"/ʃæft/","ja":"軸","kana":"じく","romaji":"jiku","vi":"trục","level":1,"def_vi":"Chi tiết máy dạng thanh tròn, quay để truyền mô-men xoắn và đỡ các chi tiết như bánh răng, puly.","def_en":"A rotating cylindrical machine element that transmits torque and supports parts such as gears and pulleys.","def_ja":"回転してトルクを伝え、歯車やプーリなどを支持する円柱状の機械要素。","usage_en":"Danh từ đếm được. Hay đi với: input / output shaft, shaft diameter, shaft end, mount a gear on the shaft; phân biệt shaft (truyền mô-men) với axle (thường chỉ đỡ bánh).","usage_ja":"Viết 軸 hoặc katakana シャフト (rất phổ biến ngoài xưởng). Hay ghép: 入力軸, 出力軸, 軸径, 軸端; động từ: 軸を支持する, 軸に圧入する.","context_vi":"Có mặt trong mọi hộp giảm tốc, động cơ, bơm, quạt, máy công cụ và băng tải.","ex_en":"The output shaft of the gearbox is 40 mm in diameter.","ex_ja":"減速機の出力軸の軸径は40 mmである。","ex_vi":"Trục ra của hộp giảm tốc có đường kính 40 mm.","syn_en":["axle (gần nghĩa)","spindle (một loại)"],"syn_ja":["シャフト","主軸 (một loại)"]},{"en":"axle","pos":"noun","ipa":"/ˈæksl/","ja":"車軸","kana":"しゃじく","romaji":"shajiku","vi":"trục bánh xe (trục xe)","level":1,"def_vi":"Trục mang bánh xe hoặc bánh lăn, chủ yếu chịu uốn; có thể quay cùng bánh hoặc đứng yên.","def_en":"A shaft that carries wheels or rollers, mainly loaded in bending; it may rotate with the wheels or be fixed.","def_ja":"車輪やローラを支持する軸で、主に曲げを受け、回転する場合と固定の場合がある。","usage_en":"Danh từ đếm được. Hay đi với: front / rear axle, axle load, fixed axle, live axle; không dùng axle cho trục truyền trong hộp số.","usage_ja":"Tên chung là 車軸; trong đường sắt và xe tải dùng nhiều. Ngoài xưởng còn nói アクスル. Hay đi với: 車軸荷重, 車軸を交換する.","context_vi":"Dùng ở xe đẩy, xe tải, toa tàu, xe nâng, con lăn băng tải.","ex_en":"The trolley wheels run on a fixed axle with needle bearings.","ex_ja":"台車の車輪は固定された車軸上で針状ころ軸受を介して回転する。","ex_vi":"Bánh xe đẩy quay trên trục bánh xe cố định qua ổ kim.","syn_en":["wheel shaft (gần nghĩa)"],"syn_ja":["アクスル","輪軸 (đường sắt, liên quan)"]},{"en":"key","pos":"noun","ipa":"/kiː/","ja":"キー","kana":"キー","romaji":"kii","vi":"then","level":1,"def_vi":"Chi tiết nhỏ lắp vào rãnh giữa trục và moay-ơ để truyền mô-men xoắn giữa chúng.","def_en":"A small part fitted in grooves between a shaft and hub to transmit torque between them.","def_ja":"軸とボスの溝にはめ込み、両者の間でトルクを伝える小さな部品。","usage_en":"Danh từ đếm được. Hay đi với: fit / insert a key, key size 10 x 8, keyed shaft; động từ \"key\" (key a pulley to a shaft) cũng dùng.","usage_ja":"Luôn viết katakana キー. Hay ghép loại phía trước: 平行キー, 半月キー, こう配キー; động từ: キーを打ち込む, はめ込む.","context_vi":"Dùng để lắp bánh răng, puly, khớp nối, bánh xích lên trục.","ex_en":"The pulley is fixed to the shaft with a key and a set screw.","ex_ja":"プーリはキーと止めねじで軸に固定されている。","ex_vi":"Puly được cố định lên trục bằng một then và một vít trí.","syn_en":["machine key","parallel key (một loại)"],"syn_ja":["平行キー (một loại)"]},{"en":"keyway","pos":"noun","ipa":"/ˈkiːweɪ/","ja":"キー溝","kana":"キーみぞ","romaji":"kiimizo","vi":"rãnh then","level":1,"def_vi":"Rãnh được gia công trên trục hoặc lỗ moay-ơ để lắp then.","def_en":"A slot machined in a shaft or hub bore to receive a key.","def_ja":"軸またはボスの穴に設け、キーをはめ込むための溝。","usage_en":"Danh từ đếm được. Hay đi với: cut / mill a keyway, keyway width, shaft keyway, hub keyway; rãnh trên trục còn gọi keyseat (Mỹ).","usage_ja":"Viết キー溝. Phân biệt 軸のキー溝 (phay bằng エンドミル) và ボスのキー溝 (xọc bằng スロッタ hoặc chuốt). Động từ: キー溝を加工する, 切る.","context_vi":"Dùng trên bản vẽ trục, bánh răng, puly và trong gia công phay, xọc.","ex_en":"Mill a 10 mm wide keyway, 5 mm deep, on the shaft end.","ex_ja":"軸端に幅10 mm、深さ5 mmのキー溝を加工する。","ex_vi":"Phay một rãnh then rộng 10 mm, sâu 5 mm ở đầu trục.","syn_en":["keyseat (Mỹ, rãnh trên trục)","key slot"],"syn_ja":["キーシート (ít dùng)"]},{"en":"hub","pos":"noun","ipa":"/hʌb/","ja":"ボス","kana":"ボス","romaji":"bosu","vi":"moay-ơ (may-ơ)","level":1,"def_vi":"Phần trung tâm dày của bánh răng, puly hoặc khớp nối, có lỗ lắp lên trục.","def_en":"The thickened central part of a gear, pulley or coupling, with a bore that fits on the shaft.","def_ja":"歯車、プーリ、軸継手などの中心にある厚肉部で、軸にはめる穴をもつ部分。","usage_en":"Danh từ đếm được. Hay đi với: hub bore, hub length, gear hub, coupling hub; trong ô tô \"wheel hub\" là cụm moay-ơ bánh xe.","usage_ja":"Trong JIS cơ khí, ボス là phần moay-ơ; còn ハブ dùng cho xe (ホイールハブ) và khớp nối (カップリングハブ). Hay đi với: ボス穴, ボス幅.","context_vi":"Dùng khi thiết kế mối ghép trục – moay-ơ, chọn chiều dài then và kiểm tra lắp ghép.","ex_en":"The hub length should be at least 1.2 times the shaft diameter.","ex_ja":"ボスの長さは軸径の1.2倍以上とする。","ex_vi":"Chiều dài moay-ơ nên tối thiểu bằng 1,2 lần đường kính trục.","syn_en":["boss (gần nghĩa)"],"syn_ja":["ハブ"]},{"en":"coupling","pos":"noun","ipa":"/ˈkʌplɪŋ/","ja":"軸継手","kana":"じくつぎて","romaji":"jikutsugite","vi":"khớp nối (trục)","level":1,"def_vi":"Bộ phận nối đầu hai trục để truyền mô-men xoắn, ví dụ nối trục động cơ với trục bơm.","def_en":"A device that connects the ends of two shafts to transmit torque, for example a motor to a pump.","def_ja":"2本の軸端を連結してトルクを伝える装置。例えばモータとポンプをつなぐ。","usage_en":"Danh từ đếm được. Hay đi với: shaft coupling, motor-pump coupling, install / align a coupling, coupling hub; đừng nhầm với pipe coupling (măng sông ống).","usage_ja":"Tên JIS là 軸継手; ngoài xưởng gọi カップリング rất phổ biến. Hay đi với: 軸継手で連結する, カップリングの芯出し.","context_vi":"Dùng giữa động cơ và hộp giảm tốc, bơm, quạt, máy nén, trục vít me.","ex_en":"The motor is connected to the pump through a flexible coupling.","ex_ja":"モータとポンプはたわみ軸継手で連結されている。","ex_vi":"Động cơ được nối với bơm qua một khớp nối mềm.","syn_en":["shaft coupling"],"syn_ja":["カップリング","継手 (nghĩa rộng hơn)"]},{"en":"spline","pos":"noun","ipa":"/splaɪn/","ja":"スプライン","kana":"スプライン","romaji":"supurain","vi":"then hoa","level":1,"def_vi":"Nhiều răng hoặc rãnh song song đều quanh trục và lỗ, truyền mô-men lớn và cho phép trượt dọc trục.","def_en":"A series of evenly spaced ridges on a shaft mating with grooves in a hub, transmitting high torque and allowing axial sliding.","def_ja":"軸と穴に等間隔に設けた複数の歯と溝で、大きなトルクを伝え軸方向の滑動も可能にする。","usage_en":"Danh từ đếm được; cũng dùng tính từ (splined shaft). Hay đi với: involute spline, straight-sided spline, spline shaft, spline hub.","usage_ja":"Viết katakana スプライン; ghép: スプライン軸, 角形スプライン, インボリュートスプライン. Động từ: スプラインでかみ合わせる.","context_vi":"Dùng ở hộp số ô tô, trục các-đăng, máy công cụ, trục bơm thủy lực.","ex_en":"The gear slides along the spline when the operator shifts gears.","ex_ja":"変速操作をすると歯車はスプラインに沿って滑動する。","ex_vi":"Khi người vận hành sang số, bánh răng trượt dọc then hoa.","syn_en":["splined shaft","spline joint"],"syn_ja":["スプライン軸","スプライン継手"]},{"en":"retaining ring","pos":"noun","ipa":"/rɪˈteɪnɪŋ rɪŋ/","ja":"止め輪","kana":"とめわ","romaji":"tomewa","vi":"vòng chặn (phanh hãm, circlip)","level":1,"def_vi":"Vòng thép đàn hồi lắp vào rãnh trên trục hoặc lỗ để chặn dịch chuyển dọc trục của chi tiết.","def_en":"A spring-steel ring fitted into a groove on a shaft or in a bore to stop axial movement of a part.","def_ja":"軸や穴の溝にはめ、部品の軸方向の移動を止めるばね鋼製の輪。","usage_en":"Danh từ đếm được. Hay đi với: external / internal retaining ring, install with circlip pliers, retaining ring groove; ở Anh hay gọi circlip.","usage_ja":"Tên JIS là 止め輪 (C形止め輪, E形止め輪). Ngoài xưởng gọi スナップリング, Cリング, Eリング; dụng cụ là スナップリングプライヤ.","context_vi":"Dùng để chặn ổ lăn, bánh răng, chốt trên trục hoặc trong lỗ vỏ hộp.","ex_en":"The bearing is held in the housing by an internal retaining ring.","ex_ja":"軸受は穴用の止め輪でハウジング内に保持されている。","ex_vi":"Ổ lăn được giữ trong vỏ bằng một vòng chặn lỗ.","syn_en":["circlip (Anh)","snap ring"],"syn_ja":["スナップリング","Cリング (một loại)"]},{"en":"split pin","pos":"noun","ipa":"/ˈsplɪt pɪn/","ja":"割りピン","kana":"わりピン","romaji":"waripin","vi":"chốt chẻ","level":1,"def_vi":"Chốt làm từ dây kim loại gập đôi, luồn qua lỗ rồi bẻ hai đầu ra để giữ chi tiết khỏi tuột.","def_en":"A pin made of doubled-over wire, passed through a hole and its legs bent apart to stop parts coming off.","def_ja":"半円断面の線材を二つ折りにしたピンで、穴に通して先端を開き、部品の抜けを防ぐ。","usage_en":"Danh từ đếm được. Hay đi với: insert a split pin, bend the legs of the split pin, castle nut and split pin; ở Mỹ gọi cotter pin.","usage_ja":"Tên JIS là 割りピン; ngoài xưởng còn gọi コッタピン. Động từ: 割りピンを差す, 先端を開く (割る). Không được dùng lại.","context_vi":"Dùng với đai ốc xẻ rãnh ở trục bánh xe, khớp thanh giằng, chốt xi lanh.","ex_en":"Always fit a new split pin after adjusting the wheel bearing nut.","ex_ja":"ホイールベアリングナットを調整した後は、必ず新しい割りピンを入れること。","ex_vi":"Luôn lắp chốt chẻ mới sau khi chỉnh đai ốc ổ bi bánh xe.","syn_en":["cotter pin (Mỹ)"],"syn_ja":["コッタピン"]},{"en":"dowel pin","pos":"noun","ipa":"/ˈdaʊəl pɪn/","ja":"平行ピン","kana":"へいこうピン","romaji":"heikoupin","vi":"chốt định vị (chốt trụ)","level":1,"def_vi":"Chốt trụ chính xác lắp chặt vào lỗ để định vị chính xác hai chi tiết với nhau.","def_en":"A precision cylindrical pin press-fitted into holes to locate two parts accurately relative to each other.","def_ja":"穴に圧入して2部品の相対位置を正確に決める精密な円筒形のピン。","usage_en":"Danh từ đếm được. Hay đi với: press in a dowel pin, dowel pin hole, locate with two dowel pins; trên bản vẽ thường ghi \"dowel\" kèm dung sai m6.","usage_ja":"Tên JIS là 平行ピン; ngoài xưởng gọi ノックピン hoặc ダウエルピン. Hay nói: ノックピンで位置決めする, 打ち込む.","context_vi":"Dùng ở đồ gá, khuôn, nắp hộp giảm tốc, bệ máy cần tháo lắp mà vẫn giữ đúng vị trí.","ex_en":"The two halves of the gearbox are located by two dowel pins.","ex_ja":"減速機の上下ケースは2本の平行ピンで位置決めされている。","ex_vi":"Hai nửa vỏ hộp giảm tốc được định vị bằng hai chốt định vị.","syn_en":["parallel pin","locating pin (gần nghĩa)"],"syn_ja":["ノックピン","ダウエルピン"]},{"en":"parallel key","pos":"noun","ipa":"/ˈpærəlel kiː/","ja":"平行キー","kana":"へいこうキー","romaji":"heikoukii","vi":"then bằng","level":2,"def_vi":"Then có tiết diện chữ nhật với hai mặt song song, truyền mô-men bằng mặt bên; loại then phổ biến nhất.","def_en":"A key of rectangular section with parallel faces that transmits torque through its sides; the most common key type.","def_ja":"長方形断面で上下面が平行なキーで、側面でトルクを伝える最も一般的なキー。","usage_en":"Danh từ đếm được. Hay ghi: parallel key 8 x 7 x 40 (b x h x L), round-ended / square-ended parallel key; chuẩn ISO 773 / DIN 6885.","usage_ja":"Tên JIS B 1301 là 平行キー; ghép: 両丸形, 片丸形, 両角形. Ghi kích thước b×h×l như 8×7×40.","context_vi":"Dùng để lắp bánh răng, puly, khớp nối lên trục động cơ và hộp giảm tốc.","ex_en":"A parallel key 10 x 8 x 50 transmits the torque from the shaft to the gear.","ex_ja":"軸から歯車へのトルクは10×8×50の平行キーで伝える。","ex_vi":"Then bằng 10 x 8 x 50 truyền mô-men từ trục sang bánh răng.","syn_en":["rectangular key","sunk key (nghĩa rộng hơn)"],"syn_ja":["キー (nghĩa rộng hơn)"]},{"en":"Woodruff key","pos":"noun","ipa":"/ˈwʊdrʌf kiː/","ja":"半月キー","kana":"はんげつキー","romaji":"hangetsukii","vi":"then bán nguyệt","level":2,"def_vi":"Then hình nửa đĩa tròn, lắp vào rãnh cong trên trục, tự lựa được và dễ lắp.","def_en":"A half-disc shaped key that sits in a curved seat in the shaft, self-aligning and easy to fit.","def_ja":"半円板状のキーで、軸の円弧状の溝にはめ込み、自動調心性があり組付けが容易。","usage_en":"Danh từ đếm được, chữ W viết hoa (tên riêng). Hay đi với: Woodruff key seat, Woodruff keyway cutter; phù hợp trục nhỏ và đầu trục côn.","usage_ja":"Tên JIS là 半月キー; gia công rãnh bằng 半月キー溝フライス (ウッドラフカッタ). Ngoài xưởng ít khi nói ウッドラフキー.","context_vi":"Dùng ở trục côn, máy công cụ nhỏ, động cơ ô tô, xe máy, máy nông nghiệp.","ex_en":"The flywheel is located on the tapered crankshaft by a Woodruff key.","ex_ja":"フライホイールはテーパ部のクランク軸に半月キーで位置決めされる。","ex_vi":"Bánh đà được định vị trên đầu côn trục khuỷu bằng then bán nguyệt.","syn_en":["half-moon key (khẩu ngữ)","semicircular key"],"syn_ja":["ウッドラフキー"]},{"en":"taper key","pos":"noun","ipa":"/ˈteɪpər kiː/","ja":"こう配キー","kana":"こうばいキー","romaji":"koubaikii","vi":"then vát (then côn, then nêm)","level":2,"def_vi":"Then có mặt trên vát độ dốc 1:100, đóng chặt vào rãnh để truyền mô-men và chặn dọc trục.","def_en":"A key with a 1:100 taper on its top face, driven in tightly to transmit torque and resist axial movement.","def_ja":"上面に1/100のこう配をもち、打ち込んで締め付け、トルク伝達と軸方向の固定を行うキー。","usage_en":"Danh từ đếm được. Hay đi với: gib-head taper key, drive in a taper key; gây lệch tâm nên ít dùng cho máy chính xác.","usage_ja":"Tên JIS là こう配キー (cũng viết 勾配キー); loại có đầu móc gọi 頭付きこう配キー. Động từ: 打ち込む.","context_vi":"Dùng ở máy nông nghiệp, máy cũ, trục tốc độ thấp chịu va đập.","ex_en":"The old pulley was held by a gib-head taper key.","ex_ja":"古いプーリは頭付きこう配キーで固定されていた。","ex_vi":"Puly cũ được giữ bằng một then vát có đầu móc.","syn_en":["gib-head key (một loại)","tapered key"],"syn_ja":["勾配キー","頭付きこう配キー (một loại)"]},{"en":"stepped shaft","pos":"noun phrase","ipa":"/ˈstept ʃæft/","ja":"段付き軸","kana":"だんつきじく","romaji":"dantsukijiku","vi":"trục bậc","level":2,"def_vi":"Trục có nhiều đoạn đường kính khác nhau, tạo vai để định vị ổ lăn, bánh răng.","def_en":"A shaft with several sections of different diameters, forming shoulders that locate bearings and gears.","def_ja":"直径の異なる部分をもち、段差(肩)で軸受や歯車を位置決めする軸。","usage_en":"Danh từ đếm được. Hay đi với: shaft shoulder, fillet radius at the step, stepped shaft design; chú ý tập trung ứng suất tại góc lượn.","usage_ja":"Viết 段付き軸; phần bậc gọi 段部 hoặc 肩, góc lượn gọi 隅R. Hay nói: 段付き部の応力集中.","context_vi":"Dùng trong thiết kế trục hộp giảm tốc, trục động cơ, trục chính máy công cụ.","ex_en":"Fatigue cracks started at the sharp corner of the stepped shaft.","ex_ja":"段付き軸の鋭い隅部から疲労き裂が発生した。","ex_vi":"Vết nứt mỏi bắt đầu từ góc sắc của trục bậc.","syn_en":["shouldered shaft"],"syn_ja":["段付きシャフト"]},{"en":"hollow shaft","pos":"noun phrase","ipa":"/ˈhɑːloʊ ʃæft/","ja":"中空軸","kana":"ちゅうくうじく","romaji":"chuukuujiku","vi":"trục rỗng","level":2,"def_vi":"Trục có lỗ dọc tâm, nhẹ hơn trục đặc nhưng vẫn giữ được phần lớn khả năng chịu xoắn.","def_en":"A shaft with a central bore, lighter than a solid shaft while keeping most of its torsional strength.","def_ja":"中心に穴をもつ軸で、中実軸より軽く、ねじり強さの大部分を保つ。","usage_en":"Danh từ đếm được. Hay đi với: hollow shaft gearbox, hollow shaft encoder, inner / outer diameter ratio; đối lập với solid shaft.","usage_ja":"Viết 中空軸; đối lập 中実軸. Hay đi với: 中空軸減速機, 中空シャフト, 内外径比.","context_vi":"Dùng ở trục chính máy tiện (luồn phôi), trục các-đăng, hộp giảm tốc trục rỗng, ngành hàng không.","ex_en":"Switching to a hollow shaft reduced the weight by 30% with only a small loss of stiffness.","ex_ja":"中空軸に変更したことで、剛性をほとんど落とさずに重量を30%減らした。","ex_vi":"Chuyển sang trục rỗng giảm 30% khối lượng mà độ cứng chỉ giảm ít.","syn_en":["tubular shaft","solid shaft (liên quan, ngược nghĩa)"],"syn_ja":["中空シャフト","中実軸 (liên quan, ngược nghĩa)"]},{"en":"transmission shaft","pos":"noun phrase","ipa":"/trænsˈmɪʃn ʃæft/","ja":"伝動軸","kana":"でんどうじく","romaji":"dendoujiku","vi":"trục truyền động","level":2,"def_vi":"Trục chịu xoắn và uốn, dùng để truyền công suất từ nguồn động lực đến máy công tác.","def_en":"A shaft loaded in torsion and bending that transmits power from a prime mover to driven machinery.","def_ja":"ねじりと曲げを受け、原動機から作業機械へ動力を伝える軸。","usage_en":"Danh từ đếm được. Hay đi với: design a transmission shaft, power transmission shaft; trong ô tô dùng drive shaft / propeller shaft.","usage_ja":"Tên trong sách giáo khoa là 伝動軸; thực tế hay nói 駆動軸 hoặc ドライブシャフト. Phân biệt với 車軸 (chủ yếu chịu uốn).","context_vi":"Dùng trong bài toán thiết kế trục, hệ truyền động băng tải, máy nông nghiệp, tàu thủy.","ex_en":"The transmission shaft must be sized for both bending and torsion.","ex_ja":"伝動軸は曲げとねじりの両方を考慮して軸径を決める必要がある。","ex_vi":"Trục truyền động phải được chọn kích thước theo cả uốn và xoắn.","syn_en":["drive shaft","power transmission shaft"],"syn_ja":["駆動軸","ドライブシャフト"]},{"en":"flexible coupling","pos":"noun phrase","ipa":"/ˈfleksəbl ˈkʌplɪŋ/","ja":"たわみ軸継手","kana":"たわみじくつぎて","romaji":"tawamijikutsugite","vi":"khớp nối mềm (khớp nối đàn hồi)","level":2,"def_vi":"Khớp nối có phần tử đàn hồi hoặc linh hoạt, bù được sai lệch tâm nhỏ và giảm chấn động.","def_en":"A coupling with an elastic or flexible element that accommodates small misalignment and absorbs shock.","def_ja":"弾性体などを介して連結し、わずかな芯ずれを許容し衝撃を吸収する軸継手。","usage_en":"Danh từ đếm được. Hay đi với: elastomeric flexible coupling, jaw coupling, disc coupling, accommodate misalignment; không thay thế được việc căn tâm.","usage_ja":"Tên JIS là たわみ軸継手; catalog hay ghi ゴム軸継手, ジョー形カップリング, ディスクカップリング. Ngoài xưởng nói フレキシブルカップリング.","context_vi":"Dùng giữa động cơ điện và bơm, quạt, hộp giảm tốc, servo với vít me.","ex_en":"A flexible coupling protects the gearbox from motor start-up shocks.","ex_ja":"たわみ軸継手がモータ起動時の衝撃から減速機を保護する。","ex_vi":"Khớp nối mềm bảo vệ hộp giảm tốc khỏi va đập khi động cơ khởi động.","syn_en":["elastic coupling","jaw coupling (một loại)"],"syn_ja":["フレキシブルカップリング","弾性軸継手"]},{"en":"rigid coupling","pos":"noun phrase","ipa":"/ˈrɪdʒɪd ˈkʌplɪŋ/","ja":"固定軸継手","kana":"こていじくつぎて","romaji":"koteijikutsugite","vi":"khớp nối cứng","level":2,"def_vi":"Khớp nối liên kết cứng hai trục, không bù được sai lệch nên hai trục phải đồng tâm chính xác.","def_en":"A coupling that joins two shafts rigidly, allowing no misalignment, so the shafts must be accurately aligned.","def_ja":"2軸を剛に連結し芯ずれを許容しないため、両軸を正確に芯出しする必要がある軸継手。","usage_en":"Danh từ đếm được. Hay đi với: sleeve-type / clamp-type rigid coupling; dùng khi cần độ cứng xoắn cao, không có khe hở.","usage_ja":"Tên JIS là 固定軸継手; catalog gọi リジッドカップリング. Kiểu phổ biến: 筒形, 割り形, フランジ形固定軸継手.","context_vi":"Dùng ở trục dài nhiều đoạn, cơ cấu vít me chính xác, nơi hai trục đã cố định trên cùng bệ.","ex_en":"A rigid coupling was chosen because the servo axis requires zero backlash.","ex_ja":"サーボ軸はバックラッシゼロが必要なため、固定軸継手を採用した。","ex_vi":"Chọn khớp nối cứng vì trục servo yêu cầu không có khe hở.","syn_en":["solid coupling","sleeve coupling (một loại)"],"syn_ja":["リジッドカップリング"]},{"en":"flange coupling","pos":"noun phrase","ipa":"/ˈflændʒ ˈkʌplɪŋ/","ja":"フランジ形軸継手","kana":"フランジがたじくつぎて","romaji":"furanjigatajikutsugite","vi":"khớp nối mặt bích","level":2,"def_vi":"Khớp nối gồm hai mặt bích lắp trên hai đầu trục, được bắt chặt với nhau bằng bu lông.","def_en":"A coupling of two flanges mounted on the shaft ends and bolted together.","def_ja":"両軸端に取り付けた2枚のフランジをボルトで締結する軸継手。","usage_en":"Danh từ đếm được. Hay đi với: rigid flange coupling, flexible flange coupling (có bạc cao su ở bu lông), coupling bolts.","usage_ja":"JIS có フランジ形固定軸継手 (B 1451) và フランジ形たわみ軸継手 (B 1452, bu lông có bạc cao su). Ngoài xưởng nói フランジ継手.","context_vi":"Dùng ở trục bơm lớn, máy nghiền, băng tải, trục truyền công suất lớn.","ex_en":"Check that all the bolts of the flange coupling are tightened evenly.","ex_ja":"フランジ形軸継手のボルトがすべて均一に締められているか確認する。","ex_vi":"Kiểm tra mọi bu lông của khớp nối mặt bích được siết đều.","syn_en":["flanged coupling"],"syn_ja":["フランジ継手","フランジ形たわみ軸継手 (một loại)"]},{"en":"universal joint","pos":"noun phrase","ipa":"/ˌjuːnɪˈvɜːrsl dʒɔɪnt/","ja":"自在継手","kana":"じざいつぎて","romaji":"jizaitsugite","vi":"khớp các-đăng (khớp nối chữ thập)","level":2,"def_vi":"Khớp nối dùng chữ thập và hai chạc, truyền mô-men giữa hai trục giao nhau ở một góc.","def_en":"A joint with a cross and two yokes that transmits torque between shafts meeting at an angle.","def_ja":"十字軸と2つのヨークにより、交差角をもつ2軸の間でトルクを伝える継手。","usage_en":"Danh từ đếm được, viết tắt U-joint. Hay đi với: universal joint shaft, cardan joint, operating angle; một khớp đơn gây dao động vận tốc góc.","usage_ja":"Tên JIS là 自在継手; còn gọi ユニバーサルジョイント, フック継手, カルダン継手. Hay đi với: 交差角, 等速性.","context_vi":"Dùng ở trục các-đăng ô tô, máy nông nghiệp, máy cán, cơ cấu lái.","ex_en":"Two universal joints in phase cancel the speed fluctuation of the drive shaft.","ex_ja":"位相をそろえた2個の自在継手により、駆動軸の速度変動を打ち消す。","ex_vi":"Hai khớp các-đăng lắp cùng pha triệt tiêu dao động tốc độ của trục truyền.","syn_en":["U-joint","cardan joint","Hooke's joint"],"syn_ja":["ユニバーサルジョイント","フック継手"]},{"en":"shaft collar","pos":"noun phrase","ipa":"/ˈʃæft ˌkɑːlər/","ja":"セットカラー","kana":"セットカラー","romaji":"settokaraa","vi":"vòng chặn trục (khâu chặn)","level":2,"def_vi":"Vòng kim loại kẹp hoặc bắt vít trên trục để chặn dịch chuyển dọc trục của chi tiết.","def_en":"A metal ring clamped or screwed onto a shaft to stop axial movement of parts.","def_ja":"軸に止めねじやクランプで固定し、部品の軸方向の移動を止める金属製の輪。","usage_en":"Danh từ đếm được. Hay đi với: set-screw shaft collar, clamp-type / split shaft collar; không cần gia công rãnh như retaining ring.","usage_ja":"Catalog (Misumi…) gọi セットカラー hoặc 軸用カラー; loại kẹp gọi クランプカラー. Động từ: カラーで抜け止めする.","context_vi":"Dùng ở trục băng tải, đồ gá, máy tự động, cơ cấu dẫn hướng.","ex_en":"A split shaft collar keeps the roller from moving along the shaft.","ex_ja":"割り形のセットカラーでローラの軸方向移動を止めている。","ex_vi":"Một vòng chặn trục kiểu xẻ giữ con lăn không dịch dọc trục.","syn_en":["collar","locking collar"],"syn_ja":["カラー","止め輪 (liên quan)"]},{"en":"shaft alignment","pos":"noun phrase","ipa":"/ˈʃæft əˈlaɪnmənt/","ja":"芯出し","kana":"しんだし","romaji":"shindashi","vi":"căn tâm trục (cân chỉnh đồng tâm)","level":2,"def_vi":"Công việc điều chỉnh vị trí máy để đường tâm hai trục nối với nhau trùng nhau trong giới hạn cho phép.","def_en":"The process of positioning machines so that the centrelines of coupled shafts coincide within tolerance.","def_ja":"連結される2軸の中心線が許容範囲内で一致するよう機械の位置を調整する作業。","usage_en":"Danh từ không đếm được. Hay đi với: laser shaft alignment, perform / check shaft alignment, dial indicator alignment; động từ: align the shafts.","usage_ja":"Viết 芯出し (cũng gặp 心出し). Động từ: 芯出しをする, レーザで芯出しする; ngoài xưởng gọi センタリング, カップリング芯出し.","context_vi":"Dùng khi lắp đặt, bảo trì bơm, quạt, máy nén, động cơ – hộp giảm tốc.","ex_en":"Poor shaft alignment caused early bearing failure on the pump.","ex_ja":"芯出し不良がポンプ軸受の早期損傷の原因となった。","ex_vi":"Căn tâm trục kém đã gây hỏng sớm ổ lăn của bơm.","syn_en":["coupling alignment","alignment"],"syn_ja":["心出し","アライメント調整"]},{"en":"misalignment","pos":"noun","ipa":"/ˌmɪsəˈlaɪnmənt/","ja":"芯ずれ","kana":"しんずれ","romaji":"shinzure","vi":"độ lệch tâm (sai lệch đồng trục)","level":2,"def_vi":"Sai lệch giữa đường tâm hai trục, gồm lệch song song và lệch góc, gây rung và mòn.","def_en":"Deviation between the centrelines of two shafts, either parallel or angular, causing vibration and wear.","def_ja":"2軸の中心線のずれで、平行ずれと角度ずれがあり、振動や摩耗の原因となる。","usage_en":"Danh từ không đếm được (đếm được khi chỉ loại). Hay đi với: parallel / angular misalignment, correct / allow misalignment.","usage_ja":"Viết 芯ずれ hoặc 軸心ずれ; catalog khớp nối ghi 許容ミスアライメント (偏心, 偏角, エンドプレイ). Động từ: 芯ずれを修正する.","context_vi":"Dùng trong chẩn đoán rung động, chọn khớp nối và báo cáo bảo trì.","ex_en":"Vibration analysis showed angular misalignment between the motor and gearbox.","ex_ja":"振動解析の結果、モータと減速機の間に角度の芯ずれがあることが分かった。","ex_vi":"Phân tích rung cho thấy lệch tâm góc giữa động cơ và hộp giảm tốc.","syn_en":["shaft misalignment"],"syn_ja":["ミスアライメント","軸心ずれ"]},{"en":"taper pin","pos":"noun","ipa":"/ˈteɪpər pɪn/","ja":"テーパピン","kana":"テーパピン","romaji":"teepapin","vi":"chốt côn","level":2,"def_vi":"Chốt có độ côn 1:50, đóng vào lỗ doa côn để định vị hoặc cố định chi tiết chính xác.","def_en":"A pin with a 1:50 taper, driven into a taper-reamed hole for accurate locating or fixing.","def_ja":"1/50のテーパをもち、テーパリーマ穴に打ち込んで正確に位置決め・固定するピン。","usage_en":"Danh từ đếm được. Hay đi với: taper-reamed hole, drive in a taper pin, threaded-end taper pin (để rút ra).","usage_ja":"Tên JIS là テーパピン; loại có ren để rút gọi おねじ付きテーパピン. Lỗ gia công bằng テーパピンリーマ.","context_vi":"Dùng để cố định tay quay, bánh răng lên trục nhỏ, định vị bệ máy tháo lắp nhiều lần.","ex_en":"The handwheel is fixed to the shaft with a taper pin.","ex_ja":"ハンドルはテーパピンで軸に固定されている。","ex_vi":"Tay quay được cố định lên trục bằng một chốt côn.","syn_en":["tapered pin"],"syn_ja":["テーパーピン","平行ピン (liên quan)"]},{"en":"feather key","pos":"noun","ipa":"/ˈfeðər kiː/","ja":"滑りキー","kana":"すべりキー","romaji":"suberikii","vi":"then dẫn hướng (then trượt)","level":3,"def_vi":"Then được bắt vít cố định vào trục, cho phép moay-ơ trượt dọc trục trong khi vẫn truyền mô-men.","def_en":"A key screwed to the shaft that lets the hub slide axially while still transmitting torque.","def_ja":"軸にねじで固定し、トルクを伝えながらボスを軸方向に滑らせることができるキー。","usage_en":"Danh từ đếm được. Hay đi với: sliding hub, feather key with retaining screws; ở Anh feather key đôi khi chỉ then bằng nói chung.","usage_ja":"Tên JIS là 滑りキー; thường có lỗ ねじ止め. Ngoài xưởng có lúc gọi フェザーキー.","context_vi":"Dùng ở bánh răng di trượt trong hộp tốc độ máy công cụ, ly hợp vấu.","ex_en":"The sliding gear moves on a feather key to change the spindle speed.","ex_ja":"滑りキー上を歯車が移動して主軸の回転速度を切り替える。","ex_vi":"Bánh răng di trượt chạy trên then dẫn hướng để đổi tốc độ trục chính.","syn_en":["sliding key","guide key"],"syn_ja":["フェザーキー"]},{"en":"serration","pos":"noun","ipa":"/səˈreɪʃn/","ja":"セレーション","kana":"セレーション","romaji":"sereeshon","vi":"then hoa răng tam giác (răng khía)","level":3,"def_vi":"Mối ghép có nhiều răng nhỏ dạng tam giác trên trục và lỗ, dùng cho trục nhỏ và lắp chặt.","def_en":"A joint of many small triangular teeth on a shaft and hub, used for small shafts and fixed connections.","def_ja":"軸と穴に多数の小さな三角歯を設けた結合で、細い軸の固定結合に用いる。","usage_en":"Danh từ đếm được, hay dùng số nhiều. Hay đi với: serrated shaft, serration joint; khác spline ở chỗ răng nhỏ, thường không trượt.","usage_ja":"Viết katakana セレーション; ghép: セレーション軸, 三角歯セレーション, インボリュートセレーション.","context_vi":"Dùng ở trục tay lái, cần gạt, trục cảm biến, các chi tiết ô tô và xe máy.","ex_en":"The steering arm is fixed to the shaft by a fine serration.","ex_ja":"ステアリングアームは細かいセレーションで軸に固定されている。","ex_vi":"Tay đòn lái được cố định lên trục bằng then hoa răng tam giác nhỏ.","syn_en":["serrated spline","spline (gần nghĩa)"],"syn_ja":["セレーション軸","スプライン (gần nghĩa)"]},{"en":"Oldham coupling","pos":"noun phrase","ipa":"/ˈoʊldəm ˈkʌplɪŋ/","ja":"オルダム継手","kana":"オルダムつぎて","romaji":"orudamutsugite","vi":"khớp nối Oldham (khớp nối chữ thập trượt)","level":3,"def_vi":"Khớp nối dùng đĩa giữa có hai vấu vuông góc trượt trong rãnh, bù được độ lệch song song lớn.","def_en":"A coupling with a centre disc carrying two perpendicular tongues sliding in slots, accommodating large parallel offset.","def_ja":"直交する2つの突起をもつ中間円板が溝内を滑り、大きな平行ずれを許容する軸継手。","usage_en":"Danh từ đếm được, chữ O viết hoa. Hay đi với: Oldham coupling disc, parallel offset; vận tốc góc truyền đều.","usage_ja":"Viết オルダム継手 hoặc オルダムカップリング. Hay nói: 偏心を吸収する, 中間ディスク.","context_vi":"Dùng ở trục bơm nhỏ, cơ cấu vít me, máy in, máy nén xoắn ốc.","ex_en":"An Oldham coupling absorbs the offset between the stepper motor and lead screw.","ex_ja":"オルダム継手でステッピングモータと送りねじの偏心を吸収する。","ex_vi":"Khớp nối Oldham hấp thụ độ lệch giữa động cơ bước và vít me.","syn_en":["Oldham joint","flexible coupling (nghĩa rộng hơn)"],"syn_ja":["オルダムカップリング"]},{"en":"gear coupling","pos":"noun phrase","ipa":"/ˈɡɪr ˈkʌplɪŋ/","ja":"歯車形軸継手","kana":"はぐるまがたじくつぎて","romaji":"hagurumagatajikutsugite","vi":"khớp nối răng","level":3,"def_vi":"Khớp nối gồm moay-ơ răng ngoài vành khuyên ăn khớp với ống răng trong, truyền mô-men rất lớn.","def_en":"A coupling of crowned externally toothed hubs meshing with an internally toothed sleeve, carrying very high torque.","def_ja":"クラウニングした外歯ハブと内歯スリーブをかみ合わせ、大トルクを伝える軸継手。","usage_en":"Danh từ đếm được. Hay đi với: grease-lubricated gear coupling, crowned teeth, high-torque gear coupling; cần bôi trơn định kỳ.","usage_ja":"Tên JIS là 歯車形軸継手; catalog gọi ギヤカップリング. Hay đi với: グリース給脂, クラウニング歯.","context_vi":"Dùng ở máy cán thép, máy nghiền, cần trục, bơm và quạt công suất lớn.","ex_en":"The rolling mill drive uses a grease-lubricated gear coupling.","ex_ja":"圧延機の駆動部にはグリース潤滑の歯車形軸継手を使用している。","ex_vi":"Hệ truyền động máy cán dùng khớp nối răng bôi trơn bằng mỡ.","syn_en":["toothed coupling"],"syn_ja":["ギヤカップリング"]},{"en":"shear pin","pos":"noun","ipa":"/ˈʃɪr pɪn/","ja":"シャーピン","kana":"シャーピン","romaji":"shaapin","vi":"chốt an toàn (chốt cắt)","level":3,"def_vi":"Chốt được thiết kế để bị cắt đứt khi quá tải, bảo vệ các chi tiết đắt tiền trong hệ truyền động.","def_en":"A pin designed to shear off under overload, protecting more expensive parts of the drive.","def_ja":"過負荷時にせん断破断するよう設計し、駆動系の高価な部品を保護するピン。","usage_en":"Danh từ đếm được. Hay đi với: replace a broken shear pin, shear pin hub, overload protection; nên dùng đúng vật liệu thay thế.","usage_ja":"Viết シャーピン hoặc せん断ピン; hay nói: シャーピンが切れる, 過負荷保護. Liên quan トルクリミッタ.","context_vi":"Dùng ở máy nông nghiệp, máy thổi tuyết, băng tải, máy nghiền, chân vịt thuyền nhỏ.","ex_en":"When the auger jammed, the shear pin broke and protected the gearbox.","ex_ja":"オーガが詰まったとき、シャーピンが切れて減速機を保護した。","ex_vi":"Khi vít tải bị kẹt, chốt an toàn bị cắt đứt và bảo vệ hộp giảm tốc.","syn_en":["breaking pin","torque limiter (liên quan)"],"syn_ja":["せん断ピン","トルクリミッタ (liên quan)"]},{"en":"critical speed","pos":"noun phrase","ipa":"/ˈkrɪtɪkl spiːd/","ja":"危険速度","kana":"きけんそくど","romaji":"kikensokudo","vi":"tốc độ tới hạn (của trục)","level":3,"def_vi":"Tốc độ quay trùng với tần số dao động riêng uốn của trục, khiến trục rung mạnh do cộng hưởng.","def_en":"The rotational speed that coincides with a shaft's natural bending frequency, causing resonant vibration.","def_ja":"軸の曲げ固有振動数と一致する回転速度で、共振により大きく振れる。","usage_en":"Danh từ đếm được. Hay đi với: first critical speed, operate below / above the critical speed, pass through the critical speed.","usage_ja":"Tên trong sách là 危険速度 (hoặc 危険回転速度). Hay nói: 1次危険速度, 危険速度を避ける, 危険速度を通過する.","context_vi":"Dùng khi thiết kế trục quay nhanh: tuabin, máy nén, trục chính, trục các-đăng dài.","ex_en":"The first critical speed of the rotor is 20% above the maximum operating speed.","ex_ja":"ロータの1次危険速度は最高運転速度より20%高い。","ex_vi":"Tốc độ tới hạn bậc một của rô to cao hơn tốc độ vận hành tối đa 20%.","syn_en":["whirling speed","critical rotational speed"],"syn_ja":["危険回転速度","固有振動数 (liên quan)"]}]},{"id":23,"words":[{"en":"bearing","pos":"noun","ipa":"/ˈberɪŋ/","ja":"軸受","kana":"じくうけ","romaji":"jikuuke","vi":"ổ trục (ổ đỡ)","level":1,"def_vi":"Chi tiết máy đỡ trục quay hoặc chi tiết chuyển động, chịu tải và giảm ma sát giữa chúng với thân máy.","def_en":"A machine element that supports a rotating shaft or moving part, carrying load while reducing friction.","def_ja":"回転軸や運動部品を支え、荷重を受けながら摩擦を低減する機械要素。","usage_en":"Danh từ đếm được. Hay đi với: install / replace a bearing, bearing failure, bearing seat, bearing life; \"bearing\" trong ngữ cảnh khác còn nghĩa là phương vị, chú ý ngữ cảnh.","usage_ja":"Tên JIS là 軸受 (cũng viết 軸受け); ngoài xưởng nói ベアリング rất phổ biến. Động từ: 軸受を圧入する, 交換する; ghép: 軸受寿命, 軸受損傷.","context_vi":"Có mặt ở động cơ điện, bơm, quạt, hộp giảm tốc, bánh xe, trục chính máy công cụ.","ex_en":"The pump bearing was replaced after the vibration level exceeded the alarm limit.","ex_ja":"振動値が警報値を超えたため、ポンプの軸受を交換した。","ex_vi":"Ổ trục của bơm đã được thay sau khi mức rung vượt ngưỡng cảnh báo.","syn_en":["rolling bearing (một loại)","plain bearing (một loại)"],"syn_ja":["ベアリング","軸受け"]},{"en":"ball bearing","pos":"noun","ipa":"/ˌbɔːl ˈberɪŋ/","ja":"玉軸受","kana":"たまじくうけ","romaji":"tamajikuuke","vi":"ổ bi","level":1,"def_vi":"Ổ lăn dùng các viên bi giữa vòng trong và vòng ngoài để đỡ tải với ma sát thấp.","def_en":"A rolling bearing that uses balls between two rings to carry load with low friction.","def_ja":"内輪と外輪の間に玉を入れ、低い摩擦で荷重を支える転がり軸受。","usage_en":"Danh từ đếm được. Hay đi với: deep-groove ball bearing, angular-contact ball bearing; động từ: press-fit / mount / replace a ball bearing.","usage_ja":"Tên JIS là 玉軸受; ngoài xưởng nói ボールベアリング hoặc gọi chung ベアリング. Ghép loại phía trước: 深溝玉軸受, アンギュラ玉軸受.","context_vi":"Dùng trong động cơ điện, bơm, quạt, hộp giảm tốc, nơi tải vừa phải và tốc độ quay cao.","ex_en":"The fan motor uses a sealed ball bearing on each end of the shaft.","ex_ja":"ファンモータには軸の両端にシール付きの玉軸受が使われている。","ex_vi":"Động cơ quạt dùng một ổ bi kín ở mỗi đầu trục.","syn_en":["rolling-element bearing (nghĩa rộng hơn)"],"syn_ja":["ボールベアリング","ベアリング (nghĩa rộng hơn)"]},{"en":"roller bearing","pos":"noun","ipa":"/ˈroʊlər ˌberɪŋ/","ja":"ころ軸受","kana":"ころじくうけ","romaji":"korojikuuke","vi":"ổ đũa","level":1,"def_vi":"Ổ lăn dùng con lăn hình trụ, côn, cầu hoặc kim, tiếp xúc đường nên chịu tải lớn hơn ổ bi.","def_en":"A rolling bearing using cylindrical, tapered, spherical or needle rollers; line contact gives higher load capacity than balls.","def_ja":"円筒、円すい、球面、針状のころを用い、線接触のため玉軸受より大きな荷重を受けられる転がり軸受。","usage_en":"Danh từ đếm được. Hay đi với: cylindrical / tapered / spherical roller bearing, heavy-duty roller bearing; đừng nhầm với \"roller\" là con lăn băng tải.","usage_ja":"Tên JIS là ころ軸受 (ころ viết hiragana); ngoài xưởng nói ローラベアリング. Ghép: 円筒ころ軸受, 円すいころ軸受.","context_vi":"Dùng ở hộp giảm tốc lớn, máy cán, máy nghiền, trục bánh xe tải và toa tàu.","ex_en":"The crusher shaft runs on two large roller bearings.","ex_ja":"クラッシャの軸は2個の大形ころ軸受で支持されている。","ex_vi":"Trục máy nghiền quay trên hai ổ đũa cỡ lớn.","syn_en":["roller-type rolling bearing"],"syn_ja":["ローラベアリング"]},{"en":"plain bearing","pos":"noun","ipa":"/ˈpleɪn ˌberɪŋ/","ja":"滑り軸受","kana":"すべりじくうけ","romaji":"suberijikuuke","vi":"ổ trượt","level":1,"def_vi":"Ổ trục trong đó trục trượt trực tiếp trên bề mặt lót, thường có màng dầu hoặc vật liệu tự bôi trơn.","def_en":"A bearing in which the shaft slides directly on a bearing surface, usually with an oil film or self-lubricating material.","def_ja":"軸が軸受面上を直接滑る軸受で、通常は油膜や自己潤滑材を介する。","usage_en":"Danh từ đếm được. Hay đi với: sleeve bearing, journal bearing, oil-lubricated plain bearing; đối lập với rolling bearing.","usage_ja":"Tên JIS là 滑り軸受; ngoài xưởng ô tô gọi メタル (クランクメタル), còn có プレーンベアリング. Hay đi với: 油膜, ジャーナル.","context_vi":"Dùng ở trục khuỷu động cơ, tuabin, máy nén lớn, khớp bản lề máy xây dựng.","ex_en":"Large steam turbines are supported on oil-lubricated plain bearings.","ex_ja":"大形蒸気タービンは油潤滑の滑り軸受で支持されている。","ex_vi":"Tuabin hơi cỡ lớn được đỡ trên các ổ trượt bôi trơn bằng dầu.","syn_en":["sleeve bearing","journal bearing (một loại)"],"syn_ja":["すべり軸受","メタル (khẩu ngữ)"]},{"en":"inner ring","pos":"noun phrase","ipa":"/ˈɪnər rɪŋ/","ja":"内輪","kana":"ないりん","romaji":"nairin","vi":"vòng trong","level":1,"def_vi":"Vòng của ổ lăn lắp lên trục, có rãnh lăn ở mặt ngoài.","def_en":"The bearing ring mounted on the shaft, with the raceway on its outer surface.","def_ja":"軸にはめ込まれる軌道輪で、外周面に軌道をもつ。","usage_en":"Danh từ đếm được. Hay đi với: inner ring rotation, inner ring raceway, press the inner ring onto the shaft; Anh–Mỹ đôi khi nói inner race.","usage_ja":"Tên JIS là 内輪; thường nói: 内輪回転, 内輪を軸に圧入する, 内輪軌道面. Đối lập 外輪.","context_vi":"Dùng khi lắp ổ lăn, chọn lắp ghép trục, phân tích hư hỏng và tần số hỏng vòng trong.","ex_en":"Heat the inner ring to 100 °C before mounting it on the shaft.","ex_ja":"軸に取り付ける前に、内輪を100 °Cに加熱する。","ex_vi":"Nung vòng trong lên 100 °C trước khi lắp lên trục.","syn_en":["inner race (khẩu ngữ)","outer ring (liên quan)"],"syn_ja":["インナーレース","外輪 (liên quan)"]},{"en":"outer ring","pos":"noun phrase","ipa":"/ˈaʊtər rɪŋ/","ja":"外輪","kana":"がいりん","romaji":"gairin","vi":"vòng ngoài","level":1,"def_vi":"Vòng của ổ lăn lắp vào lỗ thân hộp, có rãnh lăn ở mặt trong.","def_en":"The bearing ring fitted into the housing bore, with the raceway on its inner surface.","def_ja":"ハウジング穴にはめ込まれる軌道輪で、内周面に軌道をもつ。","usage_en":"Danh từ đếm được. Hay đi với: outer ring creep, outer ring raceway, stationary outer ring; khẩu ngữ: outer race.","usage_ja":"Tên JIS là 外輪; hay nói: 外輪回転, 外輪のクリープ, 外輪軌道面. Ngoài xưởng nói アウターレース.","context_vi":"Dùng khi chọn lắp ghép lỗ thân hộp, kiểm tra hiện tượng xoay vòng ngoài và phân tích rung.","ex_en":"Creep marks on the outer ring show that the housing fit was too loose.","ex_ja":"外輪にクリープ痕があり、ハウジングのはめあいが緩すぎたことが分かる。","ex_vi":"Vết xoay trên vòng ngoài cho thấy lắp ghép với thân hộp quá lỏng.","syn_en":["outer race (khẩu ngữ)","inner ring (liên quan)"],"syn_ja":["アウターレース","内輪 (liên quan)"]},{"en":"cage","pos":"noun","ipa":"/keɪdʒ/","ja":"保持器","kana":"ほじき","romaji":"hojiki","vi":"vòng cách","level":1,"def_vi":"Bộ phận giữ các viên bi hoặc con lăn cách đều nhau và dẫn hướng chúng khi quay.","def_en":"The part that keeps the balls or rollers evenly spaced and guides them during rotation.","def_ja":"玉やころを等間隔に保持し、回転中に案内する部品。","usage_en":"Danh từ đếm được. Hay đi với: pressed-steel cage, machined brass cage, polyamide cage, cage failure; còn gọi retainer hoặc separator.","usage_ja":"Tên JIS là 保持器; ngoài xưởng gọi リテーナ. Ghép vật liệu: 鋼板保持器, もみ抜き保持器, 樹脂保持器.","context_vi":"Dùng khi chọn ổ lăn theo nhiệt độ, tốc độ và khi phân tích hư hỏng ổ.","ex_en":"A machined brass cage was selected because of the high operating temperature.","ex_ja":"使用温度が高いため、黄銅製のもみ抜き保持器を選定した。","ex_vi":"Chọn vòng cách bằng đồng thau gia công vì nhiệt độ làm việc cao.","syn_en":["retainer","separator"],"syn_ja":["リテーナ"]},{"en":"bushing","pos":"noun","ipa":"/ˈbʊʃɪŋ/","ja":"ブシュ","kana":"ブシュ","romaji":"bushu","vi":"bạc lót (bạc)","level":1,"def_vi":"Ống lót hình trụ lắp trong lỗ, làm ổ trượt đơn giản cho trục hoặc chốt quay.","def_en":"A cylindrical sleeve fitted in a bore that acts as a simple plain bearing for a shaft or pin.","def_ja":"穴にはめ込む円筒形のスリーブで、軸やピンの簡単な滑り軸受として働く。","usage_en":"Danh từ đếm được; tiếng Anh–Anh hay dùng bush. Hay đi với: bronze bushing, oilless bushing, press in a bushing, worn bushing.","usage_ja":"Tên JIS viết ブシュ; ngoài xưởng nói ブッシュ. Ghép: 含油ブシュ, 銅ブシュ; động từ: ブシュを圧入する.","context_vi":"Dùng ở chốt bản lề, khớp gầu máy xúc, tay đòn, xi lanh thủy lực, cơ cấu tốc độ thấp.","ex_en":"The worn bronze bushing in the bucket pin was replaced.","ex_ja":"バケットピンの摩耗した銅製ブシュを交換した。","ex_vi":"Bạc lót đồng bị mòn ở chốt gầu đã được thay.","syn_en":["bush (Anh)","sleeve bearing"],"syn_ja":["ブッシュ","含油軸受 (một loại)"]},{"en":"sealed bearing","pos":"noun phrase","ipa":"/ˈsiːld ˌberɪŋ/","ja":"シール付き軸受","kana":"シールつきじくうけ","romaji":"shiirutsukijikuuke","vi":"ổ lăn có phớt chặn (ổ bi kín)","level":1,"def_vi":"Ổ lăn có phớt cao su ở hai bên, đã được nạp sẵn mỡ và không cần bôi trơn lại.","def_en":"A rolling bearing with rubber seals on both sides, pre-filled with grease and normally not relubricated.","def_ja":"両側にゴムシールを備え、グリースを封入済みで通常は再給脂しない転がり軸受。","usage_en":"Danh từ đếm được. Ký hiệu hậu tố 2RS / DDU; khác shielded bearing (nắp chắn thép ZZ, không tiếp xúc).","usage_ja":"Viết シール付き軸受 hoặc 密封玉軸受; hậu tố ký hiệu DDU, 2RS. Loại nắp chắn thép gọi シールド付き (ZZ).","context_vi":"Dùng ở động cơ điện nhỏ, quạt, bánh xe đẩy, thiết bị gia dụng và nơi khó bảo trì.","ex_en":"We switched to a sealed bearing to keep dust out of the conveyor roller.","ex_ja":"コンベヤローラへの粉じん侵入を防ぐため、シール付き軸受に変更した。","ex_vi":"Chúng tôi chuyển sang ổ bi kín để ngăn bụi vào con lăn băng tải.","syn_en":["2RS bearing","shielded bearing (gần nghĩa, ZZ)"],"syn_ja":["密封軸受","シールド軸受 (gần nghĩa, ZZ)"]},{"en":"radial load","pos":"noun phrase","ipa":"/ˈreɪdiəl loʊd/","ja":"ラジアル荷重","kana":"ラジアルかじゅう","romaji":"rajiarukajuu","vi":"tải trọng hướng tâm","level":1,"def_vi":"Tải trọng tác dụng vuông góc với đường tâm trục, hướng vào tâm ổ.","def_en":"A load acting perpendicular to the shaft axis, toward the bearing centre.","def_ja":"軸の中心線に直角に作用する荷重。","usage_en":"Danh từ không đếm được (hoặc đếm được khi so sánh). Hay đi với: carry / support a radial load, pure radial load, radial load capacity.","usage_ja":"Viết ラジアル荷重; đối lập アキシアル荷重. Hay đi với: ラジアル荷重を受ける, 負荷する.","context_vi":"Dùng khi chọn loại ổ lăn, tính tuổi thọ và đọc catalog ổ bi.","ex_en":"The belt tension produces a large radial load on the motor bearing.","ex_ja":"ベルト張力によりモータ軸受に大きなラジアル荷重がかかる。","ex_vi":"Lực căng đai tạo ra tải trọng hướng tâm lớn lên ổ trục động cơ.","syn_en":["radial force"],"syn_ja":["半径方向荷重"]},{"en":"rolling element","pos":"noun phrase","ipa":"/ˈroʊlɪŋ ˈelɪmənt/","ja":"転動体","kana":"てんどうたい","romaji":"tendoutai","vi":"con lăn (phần tử lăn)","level":2,"def_vi":"Viên bi hoặc con lăn lăn giữa vòng trong và vòng ngoài của ổ lăn để truyền tải.","def_en":"A ball or roller that rolls between the inner and outer rings of a rolling bearing, transferring load.","def_ja":"転がり軸受の内輪と外輪の間を転がり、荷重を伝える玉やころ。","usage_en":"Danh từ đếm được. Hay đi với: rolling element bearing, rolling element defect, ball pass frequency; dùng chung cho ball và roller.","usage_ja":"Tên JIS là 転動体; dùng chung cho 玉 và ころ. Hay ghép: 転動体の損傷, 転動体通過周波数.","context_vi":"Dùng trong tài liệu kỹ thuật ổ lăn, phân tích rung động và hư hỏng.","ex_en":"Spalling was found on one rolling element during the teardown.","ex_ja":"分解点検で1個の転動体にはく離が見つかった。","ex_vi":"Khi tháo kiểm tra phát hiện tróc rỗ trên một con lăn.","syn_en":["ball (một loại)","roller (một loại)"],"syn_ja":["玉 (một loại)","ころ (một loại)"]},{"en":"axial load","pos":"noun phrase","ipa":"/ˈæksiəl loʊd/","ja":"アキシアル荷重","kana":"アキシアルかじゅう","romaji":"akishiarukajuu","vi":"tải trọng dọc trục","level":2,"def_vi":"Tải trọng tác dụng song song với đường tâm trục, đẩy trục theo phương dọc.","def_en":"A load acting parallel to the shaft axis, pushing the shaft lengthwise.","def_ja":"軸の中心線と平行に作用し、軸を軸方向に押す荷重。","usage_en":"Danh từ không đếm được. Hay đi với: axial load in one / both directions, thrust load (đồng nghĩa); ổ bi đỡ chặn và ổ chặn dùng cho axial load.","usage_ja":"Viết アキシアル荷重; ngoài xưởng còn nói スラスト荷重. Hay đi với: アキシアル荷重を受ける, 一方向のアキシアル荷重.","context_vi":"Dùng khi chọn ổ cho bánh răng nghiêng, trục vít, bơm ly tâm, quạt hướng trục.","ex_en":"The helical gear creates an axial load that the tapered roller bearing must carry.","ex_ja":"はすば歯車によって生じるアキシアル荷重を円すいころ軸受で受ける。","ex_vi":"Bánh răng nghiêng tạo tải trọng dọc trục mà ổ đũa côn phải chịu.","syn_en":["thrust load"],"syn_ja":["スラスト荷重","軸方向荷重"]},{"en":"deep groove ball bearing","pos":"noun phrase","ipa":"/ˈdiːp ɡruːv ˈbɔːl ˌberɪŋ/","ja":"深溝玉軸受","kana":"ふかみぞたまじくうけ","romaji":"fukamizotamajikuuke","vi":"ổ bi đỡ một dãy (ổ bi rãnh sâu)","level":2,"def_vi":"Loại ổ bi phổ biến nhất, rãnh lăn sâu nên chịu được tải hướng tâm và một phần tải dọc trục hai chiều.","def_en":"The most common ball bearing, whose deep raceways carry radial load and moderate axial load in both directions.","def_ja":"最も一般的な玉軸受で、深い軌道溝によりラジアル荷重と両方向の適度なアキシアル荷重を受ける。","usage_en":"Danh từ đếm được. Hay viết: deep groove ball bearing 6205-2RS; dãy 60xx, 62xx, 63xx; có thể viết deep-groove.","usage_ja":"Tên JIS là 深溝玉軸受; số hiệu 6000, 6200, 6300 系列. Ngoài xưởng nói 6200番 hoặc 深溝ベアリング.","context_vi":"Dùng trong động cơ điện, bơm nhỏ, quạt, thiết bị gia dụng, hộp giảm tốc nhỏ.","ex_en":"The motor uses a 6205 deep groove ball bearing on the drive end.","ex_ja":"モータの負荷側には6205の深溝玉軸受を使用している。","ex_vi":"Động cơ dùng ổ bi đỡ một dãy 6205 ở đầu trục ra.","syn_en":["Conrad bearing (Mỹ)","radial ball bearing (gần nghĩa)"],"syn_ja":["ラジアル玉軸受 (gần nghĩa)"]},{"en":"angular contact ball bearing","pos":"noun phrase","ipa":"/ˈæŋɡjələr ˈkɑːntækt ˈbɔːl ˌberɪŋ/","ja":"アンギュラ玉軸受","kana":"アンギュラたまじくうけ","romaji":"angyuratamajikuuke","vi":"ổ bi đỡ chặn","level":2,"def_vi":"Ổ bi có góc tiếp xúc nghiêng, chịu đồng thời tải hướng tâm và tải dọc trục lớn theo một chiều.","def_en":"A ball bearing with an inclined contact angle that carries combined radial and high one-direction axial load.","def_ja":"接触角をもち、ラジアル荷重と一方向の大きなアキシアル荷重を同時に受ける玉軸受。","usage_en":"Danh từ đếm được. Hay đi với: contact angle 15° / 25° / 40°, back-to-back / face-to-face arrangement, matched pair; thường lắp theo cặp.","usage_ja":"Tên JIS là アンギュラ玉軸受; hay nói 背面組合せ (DB), 正面組合せ (DF), 接触角. Ngoài xưởng nói アンギュラ.","context_vi":"Dùng ở trục chính máy công cụ, bơm, vít me bi, máy nén.","ex_en":"The spindle uses angular contact ball bearings in a back-to-back arrangement.","ex_ja":"主軸には背面組合せのアンギュラ玉軸受を使用している。","ex_vi":"Trục chính dùng các ổ bi đỡ chặn lắp theo kiểu quay lưng vào nhau.","syn_en":["angular-contact bearing"],"syn_ja":["アンギュラ","アンギュラコンタクト玉軸受"]},{"en":"tapered roller bearing","pos":"noun phrase","ipa":"/ˈteɪpərd ˈroʊlər ˌberɪŋ/","ja":"円すいころ軸受","kana":"えんすいころじくうけ","romaji":"ensuikorojikuuke","vi":"ổ đũa côn","level":2,"def_vi":"Ổ đũa có con lăn hình côn, chịu tải hướng tâm và dọc trục lớn, tách được vòng ngoài (cup) và cụm vòng trong (cone).","def_en":"A roller bearing with conical rollers that carries heavy radial and axial loads; the cup and cone separate.","def_ja":"円すい形のころをもち、大きなラジアル荷重とアキシアル荷重を受け、外輪と内輪組立体が分離できる軸受。","usage_en":"Danh từ đếm được. Hay đi với: cup and cone, adjust the end play, preload a pair of tapered roller bearings; dãy 302xx, 322xx.","usage_ja":"Tên JIS là 円すいころ軸受 (cũng viết 円錐ころ軸受); ngoài xưởng gọi テーパローラベアリング. Hay nói: すきま調整, 外輪 (カップ), 内輪組立体 (コーン).","context_vi":"Dùng ở moay-ơ bánh xe ô tô, hộp số, cầu xe, hộp giảm tốc bánh răng nghiêng.","ex_en":"The wheel hub is supported by two tapered roller bearings with adjusted end play.","ex_ja":"ホイールハブはすきまを調整した2個の円すいころ軸受で支持されている。","ex_vi":"Moay-ơ bánh xe được đỡ bởi hai ổ đũa côn đã chỉnh khe hở dọc trục.","syn_en":["taper roller bearing"],"syn_ja":["テーパローラベアリング","円錐ころ軸受"]},{"en":"cylindrical roller bearing","pos":"noun phrase","ipa":"/səˈlɪndrɪkl ˈroʊlər ˌberɪŋ/","ja":"円筒ころ軸受","kana":"えんとうころじくうけ","romaji":"entoukorojikuuke","vi":"ổ đũa trụ","level":2,"def_vi":"Ổ đũa có con lăn hình trụ, chịu tải hướng tâm rất lớn và tốc độ cao, phần lớn cho phép trục giãn nở dọc.","def_en":"A roller bearing with cylindrical rollers for very high radial load and speed, most types allowing axial shaft movement.","def_ja":"円筒形のころをもち、大きなラジアル荷重と高速に適し、多くの形式で軸の軸方向移動を許す軸受。","usage_en":"Danh từ đếm được. Hay đi với: NU-type / NJ-type cylindrical roller bearing, high radial capacity; NU thường dùng làm ổ tùy động.","usage_ja":"Tên JIS là 円筒ころ軸受; ký hiệu kiểu NU, NJ, N, NUP. Ngoài xưởng gọi 円筒ローラ.","context_vi":"Dùng ở động cơ điện lớn, hộp giảm tốc, máy cán, trục chính máy công cụ.","ex_en":"An NU-type cylindrical roller bearing is fitted on the non-drive end of the motor.","ex_ja":"モータの反負荷側にはNU形の円筒ころ軸受を取り付けている。","ex_vi":"Đầu không tải của động cơ lắp ổ đũa trụ kiểu NU.","syn_en":["cylindrical roller"],"syn_ja":["円筒ローラベアリング"]},{"en":"needle roller bearing","pos":"noun phrase","ipa":"/ˈniːdl ˈroʊlər ˌberɪŋ/","ja":"針状ころ軸受","kana":"しんじょうころじくうけ","romaji":"shinjoukorojikuuke","vi":"ổ kim (ổ đũa kim)","level":2,"def_vi":"Ổ đũa dùng con lăn dài mảnh như kim, có tiết diện hướng kính rất nhỏ mà vẫn chịu tải khá lớn.","def_en":"A roller bearing with long thin needle rollers, giving a very small radial section with good load capacity.","def_ja":"細長い針状のころを用い、断面高さが非常に小さいが大きな負荷能力をもつ軸受。","usage_en":"Danh từ đếm được, hay nói gọn needle bearing. Hay đi với: drawn-cup needle roller bearing, needle cage; trục thường làm rãnh lăn trực tiếp.","usage_ja":"Tên JIS là 針状ころ軸受; ngoài xưởng gọi ニードルベアリング hoặc ニードル. Ghép: シェル形, 保持器付き針状ころ.","context_vi":"Dùng ở hộp số ô tô, khớp các-đăng, cần gạt, bơm piston, nơi không gian hướng kính hạn chế.","ex_en":"A needle roller bearing was used because there was only 3 mm of radial space.","ex_ja":"半径方向のスペースが3 mmしかないため、針状ころ軸受を採用した。","ex_vi":"Dùng ổ kim vì không gian hướng kính chỉ có 3 mm.","syn_en":["needle bearing"],"syn_ja":["ニードルベアリング","ニードル (khẩu ngữ)"]},{"en":"spherical roller bearing","pos":"noun phrase","ipa":"/ˈsferɪkl ˈroʊlər ˌberɪŋ/","ja":"自動調心ころ軸受","kana":"じどうちょうしんころじくうけ","romaji":"jidouchoushinkorojikuuke","vi":"ổ đũa cầu tự lựa (ổ tang trống)","level":2,"def_vi":"Ổ đũa hai dãy có rãnh lăn vòng ngoài hình cầu, tự lựa theo độ nghiêng trục và chịu tải rất lớn.","def_en":"A double-row roller bearing with a spherical outer raceway that self-aligns to shaft deflection and carries very heavy loads.","def_ja":"外輪軌道が球面の複列ころ軸受で、軸のたわみに自動調心し、非常に大きな荷重を受ける。","usage_en":"Danh từ đếm được. Hay đi với: self-aligning, tapered bore with adapter sleeve, 222xx / 223xx series; chịu được lệch tâm và va đập.","usage_ja":"Tên JIS là 自動調心ころ軸受; ngoài xưởng nói 自動調心 hoặc スフェリカル. Hay đi với: テーパ穴, アダプタスリーブ.","context_vi":"Dùng ở máy nghiền, sàng rung, quạt công nghiệp, băng tải hạng nặng, máy giấy.","ex_en":"The vibrating screen runs on spherical roller bearings with C4 clearance.","ex_ja":"振動ふるいにはC4すきまの自動調心ころ軸受を使っている。","ex_vi":"Sàng rung chạy trên ổ đũa cầu tự lựa có khe hở C4.","syn_en":["self-aligning roller bearing"],"syn_ja":["スフェリカルローラベアリング","自動調心玉軸受 (liên quan)"]},{"en":"thrust bearing","pos":"noun phrase","ipa":"/ˈθrʌst ˌberɪŋ/","ja":"スラスト軸受","kana":"スラストじくうけ","romaji":"surasutojikuuke","vi":"ổ chặn","level":2,"def_vi":"Ổ trục được thiết kế chủ yếu để chịu tải dọc trục, không chịu hoặc chịu rất ít tải hướng tâm.","def_en":"A bearing designed mainly to carry axial load, with little or no radial load capacity.","def_ja":"主にアキシアル荷重を受けるよう設計され、ラジアル荷重はほとんど受けない軸受。","usage_en":"Danh từ đếm được. Hay đi với: thrust ball bearing, thrust roller bearing, thrust collar; ngược với radial bearing.","usage_ja":"Viết スラスト軸受 hoặc スラストベアリング; ghép: スラスト玉軸受, スラストころ軸受. Đối lập ラジアル軸受.","context_vi":"Dùng ở bàn xoay, trục đứng của bơm, chân vịt tàu, móc cẩu, kích thủy lực.","ex_en":"The crane hook rotates on a thrust bearing so the load can be turned easily.","ex_ja":"クレーンフックはスラスト軸受で支持され、荷を容易に回すことができる。","ex_vi":"Móc cẩu quay trên ổ chặn để dễ xoay tải.","syn_en":["axial bearing","thrust ball bearing (một loại)"],"syn_ja":["スラストベアリング","スラスト玉軸受 (một loại)"]},{"en":"pillow block","pos":"noun phrase","ipa":"/ˈpɪloʊ blɑːk/","ja":"ピロー形軸受ユニット","kana":"ピローがたじくうけユニット","romaji":"piroogatajikuukeyunitto","vi":"gối đỡ ổ bi (gối UCP)","level":2,"def_vi":"Cụm gối đỡ gồm thân gang có chân bắt bu lông và ổ bi lắp sẵn bên trong, lắp nhanh lên khung máy.","def_en":"A bearing unit with a bolt-down cast housing and a pre-mounted bearing, for quick installation on a frame.","def_ja":"ボルト固定用の脚をもつ鋳鉄製ハウジングと軸受を一体にした、取付けが容易な軸受ユニット。","usage_en":"Danh từ đếm được. Hay đi với: pillow block bearing, UCP pillow block, mount / bolt down a pillow block; còn gọi plummer block (Anh, loại lớn tách đôi).","usage_ja":"Tên JIS là ピロー形軸受ユニット (ví dụ UCP205); ngoài xưởng gọi ピローブロック hoặc ユニット. Loại hộp tách đôi gọi プランマブロック.","context_vi":"Dùng ở băng tải, quạt, máy nông nghiệp, trục truyền động dài trong nhà máy.","ex_en":"Each conveyor drum is supported by two UCP pillow block units.","ex_ja":"各コンベヤドラムは2個のUCPピロー形軸受ユニットで支持されている。","ex_vi":"Mỗi tang băng tải được đỡ bởi hai gối đỡ UCP.","syn_en":["pillow block bearing","plummer block (Anh, gần nghĩa)"],"syn_ja":["ピローブロック","プランマブロック (gần nghĩa)"]},{"en":"bore diameter","pos":"noun phrase","ipa":"/ˈbɔːr daɪˌæmɪtər/","ja":"内径","kana":"ないけい","romaji":"naikei","vi":"đường kính lỗ (đường kính trong của ổ)","level":2,"def_vi":"Đường kính lỗ của vòng trong ổ lăn, bằng đường kính ngõng trục lắp ổ.","def_en":"The diameter of the bore of a bearing's inner ring, matching the shaft seat diameter.","def_ja":"軸受内輪の穴の直径で、軸の取付け部の径に対応する。","usage_en":"Danh từ đếm được. Ký hiệu d; hay đi với: bore diameter of 25 mm, bore code (hai số cuối nhân 5); đi cùng outside diameter (D) và width (B).","usage_ja":"Tên JIS là 内径 (ký hiệu d); hay nói 内径番号 (hai số cuối ×5). Đi cùng 外径 D và 幅 B.","context_vi":"Dùng khi tra catalog, đọc mã ổ bi, chọn kích thước trục và lắp ghép.","ex_en":"Bearing 6208 has a bore diameter of 40 mm.","ex_ja":"6208軸受の内径は40 mmである。","ex_vi":"Ổ 6208 có đường kính lỗ 40 mm.","syn_en":["bore size","outside diameter (liên quan)"],"syn_ja":["穴径","外径 (liên quan)"]},{"en":"bearing number","pos":"noun phrase","ipa":"/ˈberɪŋ ˌnʌmbər/","ja":"呼び番号","kana":"よびばんごう","romaji":"yobibangou","vi":"ký hiệu ổ lăn (mã ổ bi)","level":2,"def_vi":"Mã chữ số quy định loại, dãy kích thước, đường kính lỗ và các đặc tính phụ của ổ lăn, ví dụ 6205ZZ C3.","def_en":"The alphanumeric code giving a bearing's type, dimension series, bore size and features, e.g. 6205ZZ C3.","def_ja":"軸受の形式、寸法系列、内径、補助記号を表す記号で、例えば6205ZZ C3。","usage_en":"Danh từ đếm được. Hay đi với: read the bearing number, the bearing number stamped on the ring, suffix / prefix; còn gọi bearing designation.","usage_ja":"Tên JIS là 呼び番号; gồm 基本番号 và 補助記号 (ZZ, DDU, C3). Ngoài xưởng hay nói 型番.","context_vi":"Dùng khi đặt hàng thay thế, tra catalog NSK/SKF/NTN và lập danh mục phụ tùng.","ex_en":"Check the bearing number on the old ring before ordering a replacement.","ex_ja":"交換品を注文する前に、古い軸受の呼び番号を確認する。","ex_vi":"Kiểm tra ký hiệu ổ lăn trên vòng cũ trước khi đặt hàng thay thế.","syn_en":["bearing designation","part number (nghĩa rộng hơn)"],"syn_ja":["型番 (khẩu ngữ)","軸受番号"]},{"en":"internal clearance","pos":"noun phrase","ipa":"/ɪnˈtɜːrnl ˈklɪrəns/","ja":"内部すきま","kana":"ないぶすきま","romaji":"naibusukima","vi":"khe hở trong (khe hở ổ lăn)","level":2,"def_vi":"Lượng một vòng ổ lăn có thể dịch chuyển tương đối với vòng kia theo hướng kính hoặc dọc trục.","def_en":"The amount one bearing ring can move relative to the other in the radial or axial direction.","def_ja":"一方の軌道輪を他方に対してラジアルまたはアキシアル方向に動かせる量。","usage_en":"Danh từ không đếm được. Hay đi với: radial internal clearance, C3 / C4 clearance, normal (CN) clearance; khe hở giảm khi lắp chặt và khi nóng.","usage_ja":"Tên JIS là 内部すきま; cấp: C2, CN (普通), C3, C4. Hay nói: ラジアル内部すきま, すきまが減少する.","context_vi":"Dùng khi chọn ổ cho động cơ nhiệt độ cao, trục lắp chặt, sàng rung, khi tra catalog.","ex_en":"Motor bearings usually have C3 internal clearance to allow for thermal expansion.","ex_ja":"モータ用軸受は熱膨張を考慮し、内部すきまをC3とするのが一般的である。","ex_vi":"Ổ lăn động cơ thường có khe hở trong C3 để bù giãn nở nhiệt.","syn_en":["bearing clearance","radial clearance (một loại)"],"syn_ja":["軸受すきま","ラジアルすきま (một loại)"]},{"en":"raceway","pos":"noun","ipa":"/ˈreɪsweɪ/","ja":"軌道","kana":"きどう","romaji":"kidou","vi":"rãnh lăn (đường lăn)","level":2,"def_vi":"Bề mặt trên vòng trong và vòng ngoài mà bi hoặc con lăn lăn lên trong khi ổ quay.","def_en":"The surface on the inner or outer ring on which the balls or rollers roll.","def_ja":"内輪や外輪で、玉やころが転がる面。","usage_en":"Danh từ đếm được. Hay đi với: inner / outer raceway, raceway damage, raceway surface; khẩu ngữ gọi race.","usage_ja":"Tên JIS là 軌道 hoặc 軌道面; ghép: 内輪軌道, 外輪軌道, 軌道面の損傷. Chú ý 軌道 cũng nghĩa là đường ray/quỹ đạo.","context_vi":"Dùng khi kiểm tra, phân tích hư hỏng ổ lăn và đọc báo cáo rung động.","ex_en":"Brinelling marks were found on the outer raceway after transport.","ex_ja":"輸送後、外輪の軌道に圧痕が見つかった。","ex_vi":"Sau vận chuyển, phát hiện vết lõm trên rãnh lăn vòng ngoài.","syn_en":["race (khẩu ngữ)","raceway surface"],"syn_ja":["軌道面","レース (khẩu ngữ)"]},{"en":"basic dynamic load rating","pos":"noun phrase","ipa":"/ˈbeɪsɪk daɪˈnæmɪk ˈloʊd ˌreɪtɪŋ/","ja":"基本動定格荷重","kana":"きほんどうていかくかじゅう","romaji":"kihondouteikakukajuu","vi":"khả năng tải động cơ bản (C)","level":3,"def_vi":"Tải không đổi mà một nhóm ổ lăn giống nhau chịu được trong một triệu vòng quay với 90% số ổ không hỏng.","def_en":"The constant load a group of identical bearings can endure for one million revolutions with 90% reliability.","def_ja":"同一軸受群の90%が100万回転の寿命に耐えられる一定の荷重。","usage_en":"Danh từ đếm được, ký hiệu C (Cr cho hướng tâm, Ca cho dọc trục). Hay đi với: catalog value of C, compare the basic dynamic load rating with the equivalent load.","usage_ja":"Tên JIS B 1518 là 基本動定格荷重 (ký hiệu Cr, Ca). Thường nói gọn 動定格荷重; đi cặp với 基本静定格荷重 C0.","context_vi":"Dùng khi chọn và tính tuổi thọ ổ lăn theo ISO 281, đọc catalog nhà sản xuất.","ex_en":"The basic dynamic load rating of the 6310 bearing is about 62 kN.","ex_ja":"6310軸受の基本動定格荷重は約62 kNである。","ex_vi":"Khả năng tải động cơ bản của ổ 6310 khoảng 62 kN.","syn_en":["dynamic load rating","basic static load rating (liên quan)"],"syn_ja":["動定格荷重","基本静定格荷重 (liên quan)"]},{"en":"basic rating life","pos":"noun phrase","ipa":"/ˈbeɪsɪk ˈreɪtɪŋ laɪf/","ja":"基本定格寿命","kana":"きほんていかくじゅみょう","romaji":"kihonteikakujumyou","vi":"tuổi thọ danh định cơ bản (L10)","level":3,"def_vi":"Tuổi thọ mà 90% số ổ lăn giống nhau trong cùng điều kiện đạt được trước khi xuất hiện tróc mỏi.","def_en":"The life reached by 90% of a group of identical bearings under the same conditions before fatigue flaking appears.","def_ja":"同一条件で運転した同一軸受群の90%が転がり疲れによるはく離を起こさずに達する寿命。","usage_en":"Danh từ không đếm được, ký hiệu L10 (triệu vòng) hoặc L10h (giờ). Hay đi với: calculate the basic rating life, L10 = (C/P)^3 cho ổ bi.","usage_ja":"Tên JIS là 基本定格寿命 (L10); tính bằng giờ gọi L10h. Hay nói: 寿命計算, 定格寿命が短い.","context_vi":"Dùng trong thiết kế hộp giảm tốc, động cơ, kiểm tra đủ tuổi thọ theo yêu cầu (ví dụ 20.000 giờ).","ex_en":"The calculated basic rating life of the output bearing is 35,000 hours.","ex_ja":"出力軸軸受の基本定格寿命は計算で35,000時間となった。","ex_vi":"Tuổi thọ danh định cơ bản tính toán của ổ trục ra là 35.000 giờ.","syn_en":["L10 life","rating life"],"syn_ja":["定格寿命","L10寿命"]},{"en":"equivalent dynamic load","pos":"noun phrase","ipa":"/ɪˈkwɪvələnt daɪˈnæmɪk loʊd/","ja":"動等価荷重","kana":"どうとうかかじゅう","romaji":"doutoukakajuu","vi":"tải trọng động tương đương (P)","level":3,"def_vi":"Tải giả định không đổi về phương và trị số cho cùng tuổi thọ với tổ hợp tải hướng tâm và dọc trục thực tế.","def_en":"A hypothetical constant load giving the same bearing life as the actual combined radial and axial loads.","def_ja":"実際のラジアル荷重とアキシアル荷重の組合せと同じ寿命を与える、一定の仮想荷重。","usage_en":"Danh từ đếm được, ký hiệu P. Hay đi với: P = X·Fr + Y·Fa, radial / axial load factors X and Y.","usage_ja":"Tên JIS là 動等価荷重, thường gọi 動等価ラジアル荷重 Pr. Hay nói: 係数X, Yを用いて求める.","context_vi":"Dùng ở bước tính tuổi thọ ổ lăn chịu tải kết hợp trong thiết kế.","ex_en":"With Fr = 4 kN and Fa = 1.5 kN, the equivalent dynamic load is 4.8 kN.","ex_ja":"Fr=4 kN、Fa=1.5 kNのとき、動等価荷重は4.8 kNとなる。","ex_vi":"Với Fr = 4 kN và Fa = 1,5 kN, tải trọng động tương đương là 4,8 kN.","syn_en":["equivalent bearing load","equivalent radial load"],"syn_ja":["動等価ラジアル荷重","等価荷重"]},{"en":"preload","pos":"noun","ipa":"/ˈpriːloʊd/","ja":"予圧","kana":"よあつ","romaji":"yoatsu","vi":"lực căng trước (dự tải ổ lăn)","level":3,"def_vi":"Tải dọc trục tạo trước khi lắp để triệt tiêu khe hở ổ, tăng độ cứng và độ chính xác quay.","def_en":"An axial load applied at assembly to remove bearing clearance, increasing stiffness and running accuracy.","def_ja":"組立時にアキシアル荷重を与えて軸受すきまをなくし、剛性と回転精度を高めること。","usage_en":"Danh từ không đếm được; cũng là động từ (preload the bearings). Hay đi với: light / medium / heavy preload, spring preload, position preload.","usage_ja":"Tên JIS là 予圧; hay nói: 予圧をかける, 定位置予圧, 定圧予圧, 軽予圧. Quá lớn gây sinh nhiệt.","context_vi":"Dùng ở trục chính máy công cụ, vít me bi, cầu xe, cặp ổ bi đỡ chặn.","ex_en":"Too much preload made the spindle bearings run 20 °C hotter.","ex_ja":"予圧が大きすぎたため、主軸軸受の温度が20 °C上昇した。","ex_vi":"Lực căng trước quá lớn làm ổ trục chính nóng thêm 20 °C.","syn_en":["bearing preload"],"syn_ja":["プリロード","与圧 (cách viết sai thường gặp)"]},{"en":"limiting speed","pos":"noun phrase","ipa":"/ˈlɪmɪtɪŋ spiːd/","ja":"許容回転速度","kana":"きょようかいてんそくど","romaji":"kyoyoukaitensokudo","vi":"tốc độ giới hạn","level":3,"def_vi":"Tốc độ quay tối đa cho phép của ổ lăn, phụ thuộc kiểu ổ, vòng cách, phớt và cách bôi trơn.","def_en":"The maximum permissible rotational speed of a bearing, depending on type, cage, seals and lubrication.","def_ja":"軸受の形式、保持器、シール、潤滑方法などで決まる、許容できる最高回転速度。","usage_en":"Danh từ đếm được. Hay đi với: grease / oil limiting speed, exceed the limiting speed, reference speed (SKF); thường tính bằng min⁻¹.","usage_ja":"Catalog Nhật ghi 許容回転速度 (グリース潤滑, 油潤滑 riêng). Hay nói: 許容回転速度を超える, dmn値 (liên quan).","context_vi":"Dùng khi chọn ổ cho trục chính tốc độ cao, động cơ, tuabin nhỏ.","ex_en":"At 12,000 min⁻¹ the shaft speed exceeds the grease limiting speed of this bearing.","ex_ja":"12,000 min⁻¹ではこの軸受のグリース潤滑の許容回転速度を超える。","ex_vi":"Ở 12.000 vòng/phút, tốc độ trục vượt tốc độ giới hạn khi bôi trơn mỡ của ổ này.","syn_en":["speed limit","reference speed (gần nghĩa)"],"syn_ja":["限界回転速度","dmn値 (liên quan)"]},{"en":"flaking","pos":"noun","ipa":"/ˈfleɪkɪŋ/","ja":"はく離","kana":"はくり","romaji":"hakuri","vi":"tróc rỗ (bong tróc bề mặt rãnh lăn)","level":3,"def_vi":"Hư hỏng do mỏi tiếp xúc lăn, bề mặt rãnh lăn hoặc con lăn bị bong ra thành vảy.","def_en":"Rolling-contact fatigue damage in which material flakes off the raceway or rolling element surface.","def_ja":"転がり疲れにより、軌道面や転動体の表面がうろこ状にはがれる損傷。","usage_en":"Danh từ không đếm được. Hay đi với: flaking on the inner ring, early flaking; Mỹ hay dùng spalling với nghĩa gần như nhau.","usage_ja":"Tên JIS là はく離 (cũng viết 剥離); hay nói: はく離が発生する, 早期はく離. Gần nghĩa: ピーリング (bong rất nông).","context_vi":"Dùng trong báo cáo hư hỏng ổ lăn, phân tích nguyên nhân và đánh giá tuổi thọ.","ex_en":"Flaking on the inner ring raceway indicated the end of fatigue life.","ex_ja":"内輪軌道面のはく離から、疲れ寿命に達したと判断した。","ex_vi":"Tróc rỗ trên rãnh lăn vòng trong cho thấy ổ đã hết tuổi thọ mỏi.","syn_en":["spalling","rolling contact fatigue (liên quan)"],"syn_ja":["剥離","フレーキング"]}]},{"id":24,"words":[{"en":"gear","pos":"noun","ipa":"/ɡɪr/","ja":"歯車","kana":"はぐるま","romaji":"haguruma","vi":"bánh răng","level":1,"def_vi":"Chi tiết máy có răng trên chu vi, ăn khớp với bánh răng khác để truyền chuyển động quay và mô-men.","def_en":"A toothed machine element that meshes with another to transmit rotation and torque.","def_ja":"周囲に歯をもち、他の歯車とかみ合って回転とトルクを伝える機械要素。","usage_en":"Danh từ đếm được. Hay đi với: drive / driven gear, gear teeth, mesh with a gear, gear train; \"gear\" trong ô tô còn nghĩa là số (first gear).","usage_ja":"Tên JIS là 歯車; ngoài xưởng nói ギヤ hoặc ギア. Động từ: 歯車がかみ合う, 歯車を組み付ける; đếm bằng 枚 hoặc 個.","context_vi":"Có mặt trong hộp giảm tốc, hộp số, máy công cụ, đồng hồ, robot.","ex_en":"The small gear on the motor shaft drives a larger gear on the output shaft.","ex_ja":"モータ軸の小さい歯車が出力軸の大きい歯車を駆動する。","ex_vi":"Bánh răng nhỏ trên trục động cơ dẫn động bánh răng lớn trên trục ra.","syn_en":["gearwheel","toothed wheel"],"syn_ja":["ギヤ","ギア"]},{"en":"pinion","pos":"noun","ipa":"/ˈpɪnjən/","ja":"ピニオン","kana":"ピニオン","romaji":"pinion","vi":"bánh răng nhỏ (bánh răng dẫn)","level":1,"def_vi":"Bánh răng nhỏ hơn trong một cặp ăn khớp, thường là bánh dẫn lắp trên trục động cơ.","def_en":"The smaller gear of a meshing pair, usually the driving gear on the motor shaft.","def_ja":"かみ合う一対の歯車のうち小さい方で、通常はモータ軸側の駆動歯車。","usage_en":"Danh từ đếm được. Hay đi với: pinion and gear, pinion shaft, rack and pinion; số răng ký hiệu z1.","usage_ja":"Viết katakana ピニオン; còn gọi 小歯車. Đối lập với 大歯車 (ギヤ). Ghép: ピニオン軸, ラックとピニオン.","context_vi":"Dùng trong tính toán cặp bánh răng, hộp giảm tốc, cầu xe, cơ cấu thanh răng.","ex_en":"The pinion has 18 teeth and the gear has 72, giving a 4:1 ratio.","ex_ja":"ピニオンの歯数は18、大歯車は72で、減速比は4となる。","ex_vi":"Bánh răng nhỏ có 18 răng, bánh lớn có 72 răng, tỉ số truyền 4:1.","syn_en":["driving gear (gần nghĩa)"],"syn_ja":["小歯車","ピニオンギヤ"]},{"en":"tooth","pos":"noun","ipa":"/tuːθ/","ja":"歯","kana":"は","romaji":"ha","vi":"răng (bánh răng)","level":1,"def_vi":"Phần nhô ra trên vành bánh răng, tiếp xúc với răng của bánh kia để truyền lực.","def_en":"One of the projections on a gear rim that contacts the teeth of the mating gear to transmit force.","def_ja":"歯車の外周に設けた突起で、相手歯車の歯と接触して力を伝える部分。","usage_en":"Danh từ đếm được, số nhiều bất quy tắc teeth. Hay đi với: gear tooth, number of teeth, broken tooth, tooth profile.","usage_ja":"Viết 歯; ghép rất nhiều: 歯数, 歯形, 歯面, 歯先, 歯元. Động từ: 歯が欠ける (mẻ răng).","context_vi":"Dùng khi kiểm tra, đếm răng, phân tích gãy răng và mòn bánh răng.","ex_en":"One tooth of the gear broke off because of a sudden overload.","ex_ja":"急な過負荷により、歯車の歯が1枚欠けた。","ex_vi":"Một răng của bánh răng bị gãy do quá tải đột ngột.","syn_en":["gear tooth","cog (khẩu ngữ)"],"syn_ja":["歯車の歯","ギヤ歯"]},{"en":"spur gear","pos":"noun","ipa":"/ˈspɜːr ɡɪr/","ja":"平歯車","kana":"ひらはぐるま","romaji":"hirahaguruma","vi":"bánh răng trụ răng thẳng","level":1,"def_vi":"Bánh răng trụ có răng thẳng song song với trục, truyền chuyển động giữa hai trục song song.","def_en":"A cylindrical gear with straight teeth parallel to the axis, used between parallel shafts.","def_ja":"歯すじが軸に平行な直線の円筒歯車で、平行な2軸間の伝動に用いる。","usage_en":"Danh từ đếm được. Hay đi với: spur gear pair, module 2 spur gear; ồn hơn helical gear ở tốc độ cao, không sinh lực dọc trục.","usage_ja":"Tên JIS là 平歯車; ngoài xưởng nói スパーギヤ. Catalog ghi m2 z30 平歯車.","context_vi":"Dùng ở hộp giảm tốc đơn giản, máy công cụ, bơm bánh răng, đồ chơi, thiết bị văn phòng.","ex_en":"A module 2 spur gear with 40 teeth was ordered from the catalog.","ex_ja":"カタログからモジュール2、歯数40の平歯車を注文した。","ex_vi":"Đã đặt từ catalog một bánh răng trụ răng thẳng mô-đun 2, 40 răng.","syn_en":["straight-cut gear (khẩu ngữ)"],"syn_ja":["スパーギヤ"]},{"en":"helical gear","pos":"noun","ipa":"/ˈhelɪkl ɡɪr/","ja":"はすば歯車","kana":"はすばはぐるま","romaji":"hasubahaguruma","vi":"bánh răng trụ răng nghiêng","level":1,"def_vi":"Bánh răng trụ có răng nghiêng theo đường xoắn, ăn khớp êm hơn nhưng sinh lực dọc trục.","def_en":"A cylindrical gear with teeth cut at a helix angle, running more quietly but producing axial thrust.","def_ja":"歯すじがつる巻線状に傾いた円筒歯車で、静かにかみ合うがアキシアル力が生じる。","usage_en":"Danh từ đếm được. Hay đi với: helix angle, left-hand / right-hand helical gear, double helical gear; cần ổ chịu tải dọc trục.","usage_ja":"Tên JIS là はすば歯車 (cũng viết 斜歯歯車); ngoài xưởng nói ヘリカルギヤ. Hay đi với: ねじれ角, 右ねじれ, 左ねじれ.","context_vi":"Dùng trong hộp số ô tô, hộp giảm tốc công nghiệp, máy nén, nơi cần êm và tải lớn.","ex_en":"Helical gears were chosen to reduce gearbox noise.","ex_ja":"減速機の騒音を下げるため、はすば歯車を採用した。","ex_vi":"Chọn bánh răng trụ răng nghiêng để giảm tiếng ồn hộp giảm tốc.","syn_en":["helical spur gear (ít dùng)"],"syn_ja":["ヘリカルギヤ","斜歯歯車"]},{"en":"bevel gear","pos":"noun","ipa":"/ˈbevl ɡɪr/","ja":"かさ歯車","kana":"かさはぐるま","romaji":"kasahaguruma","vi":"bánh răng côn","level":1,"def_vi":"Bánh răng có dạng hình nón, truyền chuyển động giữa hai trục cắt nhau, thường vuông góc.","def_en":"A cone-shaped gear that transmits motion between intersecting shafts, usually at right angles.","def_ja":"円すい形の歯車で、交わる2軸、通常は直交軸の間で運動を伝える。","usage_en":"Danh từ đếm được. Hay đi với: straight / spiral bevel gear, bevel gear pair, miter gear (tỉ số 1:1).","usage_ja":"Tên JIS là かさ歯車 (傘歯車); ngoài xưởng nói ベベルギヤ. Ghép: すぐばかさ歯車, まがりばかさ歯車, マイタ歯車.","context_vi":"Dùng ở bộ vi sai ô tô, máy khoan tay, hộp giảm tốc góc vuông, máy nông nghiệp.","ex_en":"A pair of bevel gears turns the drive through 90 degrees.","ex_ja":"一対のかさ歯車で動力の方向を90度変える。","ex_vi":"Một cặp bánh răng côn đổi hướng truyền động 90 độ.","syn_en":["miter gear (một loại, 1:1)"],"syn_ja":["ベベルギヤ","傘歯車"]},{"en":"worm gear","pos":"noun","ipa":"/ˈwɜːrm ɡɪr/","ja":"ウォームギヤ","kana":"ウォームギヤ","romaji":"woomugiya","vi":"bộ truyền trục vít – bánh vít","level":1,"def_vi":"Bộ truyền gồm trục vít ăn khớp với bánh vít, giữa hai trục chéo nhau, cho tỉ số truyền lớn trong một cấp.","def_en":"A drive of a worm meshing with a worm wheel on crossed shafts, giving a high ratio in one stage.","def_ja":"ウォームとウォームホイールを食い違い軸でかみ合わせ、1段で大きな減速比を得る歯車対。","usage_en":"Danh từ đếm được; worm gear có thể chỉ cả bộ hoặc riêng bánh vít. Hay đi với: worm gear reducer, self-locking, low efficiency.","usage_ja":"Tên JIS là ウォームギヤ (cặp); riêng trục vít gọi ウォーム, bánh vít gọi ウォームホイール. Ghép: ウォーム減速機.","context_vi":"Dùng ở hộp giảm tốc góc vuông, tời, cửa cuốn, cơ cấu nâng có tự hãm.","ex_en":"The worm gear has a 40:1 ratio and is self-locking.","ex_ja":"このウォームギヤは減速比40で、セルフロック性がある。","ex_vi":"Bộ truyền trục vít – bánh vít có tỉ số 40:1 và tự hãm.","syn_en":["worm drive","worm and wheel"],"syn_ja":["ウォーム歯車","ウォーム減速機 (liên quan)"]},{"en":"rack","pos":"noun","ipa":"/ræk/","ja":"ラック","kana":"ラック","romaji":"rakku","vi":"thanh răng","level":1,"def_vi":"Thanh thẳng có răng, ăn khớp với bánh răng để biến chuyển động quay thành tịnh tiến và ngược lại.","def_en":"A straight toothed bar that meshes with a pinion to convert rotation into linear motion and vice versa.","def_ja":"直線状に歯を刻んだ棒で、ピニオンとかみ合い回転運動を直線運動に変える。","usage_en":"Danh từ đếm được. Hay đi với: rack and pinion, gear rack, ground rack; \"rack\" còn nghĩa là giá kệ, chú ý ngữ cảnh.","usage_ja":"Viết ラック; ghép: ラックアンドピニオン, ラック歯車. Hay nói: ラックを継ぐ (nối thanh răng).","context_vi":"Dùng ở cơ cấu lái ô tô, trục X máy CNC cỡ lớn, cửa trượt, máy khoan cần.","ex_en":"The gantry moves along a 6 m rack driven by a servo pinion.","ex_ja":"ガントリはサーボ駆動のピニオンにより6 mのラックに沿って移動する。","ex_vi":"Cổng trục di chuyển dọc thanh răng dài 6 m nhờ bánh răng dẫn servo.","syn_en":["gear rack","toothed rack"],"syn_ja":["ラック歯車","ギヤラック"]},{"en":"number of teeth","pos":"noun phrase","ipa":"/ˈnʌmbər əv ˈtiːθ/","ja":"歯数","kana":"はすう","romaji":"hasuu","vi":"số răng","level":1,"def_vi":"Tổng số răng trên một bánh răng, ký hiệu z, dùng để tính tỉ số truyền và đường kính.","def_en":"The total count of teeth on a gear, symbol z, used to calculate ratio and diameter.","def_ja":"歯車の歯の総数で、記号zで表し、歯数比や直径の計算に使う。","usage_en":"Danh từ đếm được. Hay đi với: the number of teeth on the pinion, a gear with 30 teeth; viết tắt trong bảng: z hoặc N.","usage_ja":"Tên JIS là 歯数 (ký hiệu z); hay nói 歯数比, 歯数30の歯車. Không đọc は-かず mà đọc はすう.","context_vi":"Dùng trong bảng thông số bánh răng trên bản vẽ, catalog và tính toán tỉ số truyền.","ex_en":"Count the number of teeth on both gears to find the ratio.","ex_ja":"減速比を求めるため、両方の歯車の歯数を数える。","ex_vi":"Đếm số răng của cả hai bánh để tìm tỉ số truyền.","syn_en":["tooth count","teeth number"],"syn_ja":["歯の数","歯数比 (liên quan)"]},{"en":"gear ratio","pos":"noun phrase","ipa":"/ˈɡɪr ˌreɪʃioʊ/","ja":"歯数比","kana":"はすうひ","romaji":"hasuuhi","vi":"tỉ số truyền (bánh răng)","level":1,"def_vi":"Tỉ số giữa số răng bánh lớn và bánh nhỏ, cũng bằng tỉ số tốc độ quay của bánh dẫn và bánh bị dẫn.","def_en":"The ratio of gear to pinion tooth numbers, equal to the speed ratio between the driving and driven gears.","def_ja":"大歯車と小歯車の歯数の比で、駆動側と従動側の回転速度の比に等しい。","usage_en":"Danh từ đếm được. Hay đi với: a gear ratio of 5:1, high / low gear ratio, overall gear ratio; còn gọi reduction ratio khi giảm tốc.","usage_ja":"JIS dùng 歯数比 (u) cho cặp bánh răng; khi nói về hộp giảm tốc dùng 減速比, tổng quát dùng 速比 hoặc ギヤ比.","context_vi":"Dùng khi chọn hộp giảm tốc, tính tốc độ và mô-men đầu ra, hộp số ô tô.","ex_en":"With a gear ratio of 4:1, the output speed is 375 rpm.","ex_ja":"歯数比が4なので、出力回転速度は375 rpmとなる。","ex_vi":"Với tỉ số truyền 4:1, tốc độ đầu ra là 375 vòng/phút.","syn_en":["speed ratio","reduction ratio (gần nghĩa)"],"syn_ja":["ギヤ比","減速比 (gần nghĩa)"]},{"en":"module","pos":"noun","ipa":"/ˈmɑːdʒuːl/","ja":"モジュール","kana":"モジュール","romaji":"mojuuru","vi":"mô-đun (bánh răng)","level":2,"def_vi":"Đại lượng chỉ cỡ răng, bằng đường kính vòng chia chia cho số răng, đơn vị mm.","def_en":"A measure of tooth size equal to the pitch diameter divided by the number of teeth, in millimetres.","def_ja":"歯の大きさを表す値で、基準円直径を歯数で割ったもの(単位mm)。","usage_en":"Danh từ đếm được, ký hiệu m. Hay đi với: module 2 gear, m = d/z, standard modules; Mỹ dùng diametral pitch thay thế.","usage_ja":"Tên JIS là モジュール (ký hiệu m); hay nói: モジュール2, m2. Hai bánh răng ăn khớp phải cùng モジュール.","context_vi":"Dùng khi tra catalog, thiết kế, gia công bánh răng và chọn dao phay lăn răng.","ex_en":"Both gears must have the same module to mesh correctly.","ex_ja":"正しくかみ合うには、両歯車のモジュールが同じでなければならない。","ex_vi":"Hai bánh răng phải cùng mô-đun mới ăn khớp đúng.","syn_en":["metric module","diametral pitch (liên quan, hệ inch)"],"syn_ja":["m (ký hiệu)","ダイヤメトラルピッチ (liên quan)"]},{"en":"pitch circle","pos":"noun phrase","ipa":"/ˈpɪtʃ ˌsɜːrkl/","ja":"基準円","kana":"きじゅんえん","romaji":"kijun'en","vi":"vòng chia","level":2,"def_vi":"Đường tròn tưởng tượng trên bánh răng, đường kính bằng mô-đun nhân số răng, làm chuẩn cho kích thước răng.","def_en":"The imaginary reference circle of a gear, with diameter equal to module times number of teeth.","def_ja":"歯車の寸法の基準となる仮想の円で、直径はモジュールと歯数の積に等しい。","usage_en":"Danh từ đếm được. Hay đi với: pitch circle diameter (PCD), on the pitch circle; lưu ý \"PCD\" cũng dùng cho vòng tâm lỗ bu lông.","usage_ja":"JIS gọi 基準円 (đường kính 基準円直径 d); sách cũ dùng ピッチ円. Khi ăn khớp thực tế gọi かみ合いピッチ円.","context_vi":"Dùng trong tính toán hình học bánh răng, khoảng cách trục và bảng thông số trên bản vẽ.","ex_en":"The pitch circle diameter of a module 3 gear with 40 teeth is 120 mm.","ex_ja":"モジュール3、歯数40の歯車の基準円直径は120 mmである。","ex_vi":"Đường kính vòng chia của bánh răng mô-đun 3, 40 răng là 120 mm.","syn_en":["reference circle","pitch diameter (liên quan)"],"syn_ja":["ピッチ円","基準円直径 (liên quan)"]},{"en":"pressure angle","pos":"noun phrase","ipa":"/ˈpreʃər ˌæŋɡl/","ja":"圧力角","kana":"あつりょくかく","romaji":"atsuryokukaku","vi":"góc áp lực","level":2,"def_vi":"Góc giữa đường tác dụng lực trên răng và tiếp tuyến vòng chia; tiêu chuẩn thường là 20°.","def_en":"The angle between the line of action of the tooth force and the tangent to the pitch circle; standard is 20°.","def_ja":"歯面に働く力の作用線と基準円の接線とのなす角で、標準は20°。","usage_en":"Danh từ đếm được. Hay đi với: 20° pressure angle, standard pressure angle; hai bánh ăn khớp phải cùng pressure angle và module.","usage_ja":"Tên JIS là 圧力角 (ký hiệu α); hay nói 圧力角20°, 基準圧力角. Bánh răng cũ có loại 14.5°.","context_vi":"Dùng trong bảng thông số bánh răng, chọn dao cắt răng và tính lực tác dụng lên ổ.","ex_en":"All gears in this gearbox have a 20° pressure angle.","ex_ja":"この減速機の歯車はすべて圧力角20°である。","ex_vi":"Mọi bánh răng trong hộp giảm tốc này có góc áp lực 20°.","syn_en":["reference pressure angle","line of action (liên quan)"],"syn_ja":["基準圧力角","作用線 (liên quan)"]},{"en":"center distance","pos":"noun phrase","ipa":"/ˈsentər ˌdɪstəns/","ja":"中心距離","kana":"ちゅうしんきょり","romaji":"chuushinkyori","vi":"khoảng cách trục","level":2,"def_vi":"Khoảng cách giữa tâm hai trục của cặp bánh răng ăn khớp.","def_en":"The distance between the axes of two meshing gears.","def_ja":"かみ合う一対の歯車の軸心間の距離。","usage_en":"Danh từ đếm được. Hay đi với: center distance tolerance, a = m(z1 + z2)/2, adjust the center distance; Anh viết centre distance.","usage_ja":"Tên JIS là 中心距離 (ký hiệu a); hay nói 軸間距離 ngoài xưởng. Dung sai ảnh hưởng đến バックラッシ.","context_vi":"Dùng khi thiết kế vỏ hộp giảm tốc, gia công lỗ ổ và kiểm tra khe hở ăn khớp.","ex_en":"The center distance of the gear pair is 150 mm.","ex_ja":"この歯車対の中心距離は150 mmである。","ex_vi":"Khoảng cách trục của cặp bánh răng là 150 mm.","syn_en":["centre distance (Anh)","shaft spacing"],"syn_ja":["軸間距離"]},{"en":"backlash","pos":"noun","ipa":"/ˈbæklæʃ/","ja":"バックラッシ","kana":"バックラッシ","romaji":"bakkurasshi","vi":"khe hở cạnh răng (độ rơ)","level":2,"def_vi":"Khe hở giữa mặt không làm việc của các răng ăn khớp, cho phép bánh răng quay lùi một chút khi đổi chiều.","def_en":"The play between the non-working flanks of meshing teeth, allowing slight free movement on reversal.","def_ja":"かみ合う歯の非作用側歯面間のすきまで、回転方向を変えるとわずかな遊びとなる。","usage_en":"Danh từ không đếm được. Hay đi với: measure / adjust / eliminate backlash, zero backlash, anti-backlash gear.","usage_ja":"Tên JIS là バックラッシ; ngoài xưởng nói バックラッシュ, ガタ. Hay đi với: バックラッシを測る, 調整する, ノンバックラッシ.","context_vi":"Dùng khi lắp ráp, kiểm tra hộp số, thiết kế cơ cấu định vị chính xác và servo.","ex_en":"Measure the backlash with a dial indicator while holding the pinion.","ex_ja":"ピニオンを固定した状態でダイヤルゲージによりバックラッシを測定する。","ex_vi":"Đo khe hở cạnh răng bằng đồng hồ so trong khi giữ chặt bánh nhỏ.","syn_en":["gear play","lash (khẩu ngữ)"],"syn_ja":["バックラッシュ","ガタ (khẩu ngữ)"]},{"en":"gear train","pos":"noun phrase","ipa":"/ˈɡɪr treɪn/","ja":"歯車列","kana":"はぐるまれつ","romaji":"hagurumaretsu","vi":"hệ bánh răng (chuỗi bánh răng)","level":2,"def_vi":"Tập hợp nhiều bánh răng ăn khớp nối tiếp nhau để truyền chuyển động và thay đổi tốc độ.","def_en":"A series of meshing gears that transmits motion and changes speed between shafts.","def_ja":"複数の歯車を順にかみ合わせ、運動を伝え速度を変える装置。","usage_en":"Danh từ đếm được. Hay đi với: simple / compound gear train, idler gear, overall ratio of the gear train.","usage_ja":"Tên trong sách là 歯車列 hoặc 歯車装置; ghép: 遊び歯車 (bánh răng trung gian), 複合歯車列.","context_vi":"Dùng trong tính toán tỉ số truyền nhiều cấp, đồng hồ, hộp tốc độ máy công cụ.","ex_en":"The three-stage gear train reduces the motor speed from 1,500 to 25 rpm.","ex_ja":"3段の歯車列でモータ回転速度を1,500 rpmから25 rpmに減速する。","ex_vi":"Hệ bánh răng ba cấp giảm tốc độ động cơ từ 1.500 xuống 25 vòng/phút.","syn_en":["gear set","gearing"],"syn_ja":["歯車装置","ギヤトレーン"]},{"en":"idler gear","pos":"noun phrase","ipa":"/ˈaɪdlər ɡɪr/","ja":"遊び歯車","kana":"あそびはぐるま","romaji":"asobihaguruma","vi":"bánh răng trung gian (bánh răng đệm)","level":2,"def_vi":"Bánh răng đặt giữa bánh dẫn và bánh bị dẫn để đổi chiều quay hoặc nối khoảng cách trục, không làm thay đổi tỉ số truyền.","def_en":"A gear placed between the driving and driven gears to reverse rotation or bridge distance without changing the ratio.","def_ja":"駆動歯車と従動歯車の間に入れ、減速比を変えずに回転方向を変えたり距離を埋めたりする歯車。","usage_en":"Danh từ đếm được, cũng viết idler. Hay đi với: add an idler gear to reverse direction, idler shaft; số răng của idler không ảnh hưởng đến tỉ số tổng.","usage_ja":"Tên trong sách là 遊び歯車 (cũng viết 遊歯車); ngoài xưởng gọi アイドラ, アイドルギヤ. Hay nói: 回転方向を逆にする.","context_vi":"Dùng trong hộp tốc độ máy công cụ, cơ cấu số lùi hộp số, bánh răng phân phối động cơ.","ex_en":"An idler gear was added so that the two rollers turn in the same direction.","ex_ja":"2本のローラが同じ方向に回るよう、遊び歯車を1枚追加した。","ex_vi":"Đã thêm một bánh răng trung gian để hai con lăn quay cùng chiều.","syn_en":["idler","intermediate gear"],"syn_ja":["アイドラ","アイドルギヤ"]},{"en":"internal gear","pos":"noun phrase","ipa":"/ɪnˈtɜːrnl ɡɪr/","ja":"内歯車","kana":"うちはぐるま","romaji":"uchihaguruma","vi":"bánh răng trong","level":2,"def_vi":"Bánh răng có răng cắt ở mặt trong của vành, ăn khớp với bánh răng ngoài nằm bên trong.","def_en":"A gear with teeth cut on the inside of a ring, meshing with an external gear inside it.","def_ja":"円筒の内側に歯をもち、内側に置いた外歯車とかみ合う歯車。","usage_en":"Danh từ đếm được. Hay đi với: ring gear, annulus gear, internal gear of a planetary set; đối lập với external gear.","usage_ja":"Tên JIS là 内歯車 (đọc うちはぐるま); ngoài xưởng gọi インターナルギヤ, リングギヤ. Gia công bằng 歯車形削り.","context_vi":"Dùng trong hộp giảm tốc hành tinh, ly hợp, bộ khởi động động cơ.","ex_en":"The internal gear is fixed to the housing in this planetary stage.","ex_ja":"この遊星段では内歯車がケースに固定されている。","ex_vi":"Ở cấp hành tinh này, bánh răng trong được cố định vào vỏ.","syn_en":["ring gear","annulus"],"syn_ja":["インターナルギヤ","リングギヤ"]},{"en":"planetary gear","pos":"noun phrase","ipa":"/ˈplænəteri ɡɪr/","ja":"遊星歯車","kana":"ゆうせいはぐるま","romaji":"yuuseihaguruma","vi":"bánh răng hành tinh","level":2,"def_vi":"Hệ gồm bánh răng mặt trời, các bánh hành tinh trên cần dẫn và bánh răng trong, cho tỉ số lớn trong kích thước nhỏ gọn.","def_en":"A system of a sun gear, planet gears on a carrier and a ring gear, giving high ratios in a compact size.","def_ja":"太陽歯車、キャリアに支持された遊星歯車、内歯車から成り、小形で大きな減速比を得る装置。","usage_en":"Danh từ đếm được. Hay đi với: planetary gear set, planetary gearbox, sun gear, planet carrier; còn gọi epicyclic gear.","usage_ja":"Tên JIS là 遊星歯車 (cũng chỉ riêng bánh hành tinh); cả bộ là 遊星歯車装置. Ngoài xưởng gọi プラネタリギヤ.","context_vi":"Dùng ở hộp số tự động, hộp giảm tốc servo, tuabin gió, máy xúc.","ex_en":"A two-stage planetary gear unit delivers 100:1 reduction in a small housing.","ex_ja":"2段の遊星歯車装置により、小さなケースで1/100の減速を実現している。","ex_vi":"Bộ bánh răng hành tinh hai cấp cho tỉ số giảm 100:1 trong vỏ nhỏ gọn.","syn_en":["epicyclic gear","planetary gear set"],"syn_ja":["プラネタリギヤ","遊星歯車装置"]},{"en":"addendum","pos":"noun","ipa":"/əˈdendəm/","ja":"歯末のたけ","kana":"はすえのたけ","romaji":"hasuenotake","vi":"chiều cao đầu răng","level":2,"def_vi":"Khoảng cách hướng kính từ vòng chia đến vòng đỉnh răng; với răng tiêu chuẩn bằng mô-đun.","def_en":"The radial distance from the pitch circle to the tip circle; equal to the module for standard teeth.","def_ja":"基準円から歯先円までの半径方向の距離で、標準歯車ではモジュールに等しい。","usage_en":"Danh từ đếm được, số nhiều addenda. Hay đi với: addendum = 1 m, addendum circle; đi cặp với dedendum.","usage_ja":"Tên JIS là 歯末のたけ (ha); đi cặp với 歯元のたけ. Tổng gọi 全歯たけ.","context_vi":"Dùng trong tính toán hình học răng, kiểm tra đường kính đỉnh và thiết kế dịch chỉnh.","ex_en":"For a standard gear, the addendum equals one module.","ex_ja":"標準歯車では、歯末のたけはモジュールに等しい。","ex_vi":"Với bánh răng tiêu chuẩn, chiều cao đầu răng bằng một mô-đun.","syn_en":["addendum height","dedendum (liên quan)"],"syn_ja":["歯元のたけ (liên quan)","全歯たけ (liên quan)"]},{"en":"tip diameter","pos":"noun phrase","ipa":"/ˈtɪp daɪˌæmɪtər/","ja":"歯先円直径","kana":"はさきえんちょっけい","romaji":"hasakienchokkei","vi":"đường kính vòng đỉnh","level":2,"def_vi":"Đường kính vòng tròn đi qua đỉnh các răng, bằng đường kính ngoài của bánh răng trụ ngoài.","def_en":"The diameter of the circle passing through the tooth tips, the outside diameter of an external gear.","def_ja":"歯先を通る円の直径で、外歯車の外径にあたる。","usage_en":"Danh từ đếm được, ký hiệu da. Hay đi với: tip diameter = m(z + 2), outside diameter (Mỹ); dùng để tiện phôi.","usage_ja":"Tên JIS là 歯先円直径 (da); ngoài xưởng nói 外径 hoặc 歯先径. Phôi tiện theo kích thước này.","context_vi":"Dùng khi tiện phôi bánh răng, kiểm tra kích thước và tính khe hở với vỏ hộp.","ex_en":"Turn the blank to the tip diameter of 84 mm before hobbing.","ex_ja":"ホブ切りの前に、素材を歯先円直径84 mmに旋削する。","ex_vi":"Tiện phôi đến đường kính vòng đỉnh 84 mm trước khi phay lăn răng.","syn_en":["outside diameter","addendum circle diameter"],"syn_ja":["歯先径","外径 (khẩu ngữ)"]},{"en":"face width","pos":"noun phrase","ipa":"/ˈfeɪs wɪdθ/","ja":"歯幅","kana":"はば","romaji":"haba","vi":"chiều rộng vành răng","level":2,"def_vi":"Chiều dài của răng đo theo phương dọc trục bánh răng, ảnh hưởng trực tiếp đến khả năng chịu tải.","def_en":"The length of the teeth measured parallel to the gear axis, directly affecting load capacity.","def_ja":"歯車の軸方向に測った歯の長さで、負荷能力に直接影響する。","usage_en":"Danh từ đếm được, ký hiệu b. Hay đi với: face width of 30 mm, face width ratio b/d, increase the face width; không nhầm với tooth thickness.","usage_ja":"Tên JIS là 歯幅 (ký hiệu b); hay nói: 歯幅を広げる, 有効歯幅, 歯幅係数. Chú ý đọc là はば.","context_vi":"Dùng khi tính bền bánh răng, thiết kế kích thước hộp giảm tốc và bảng thông số trên bản vẽ.","ex_en":"Increasing the face width from 20 to 30 mm raised the load capacity by about 50%.","ex_ja":"歯幅を20 mmから30 mmに広げたことで、負荷能力が約50%向上した。","ex_vi":"Tăng chiều rộng vành răng từ 20 lên 30 mm giúp khả năng tải tăng khoảng 50%.","syn_en":["tooth width","facewidth"],"syn_ja":["有効歯幅 (liên quan)","歯幅係数 (liên quan)"]},{"en":"gear hobbing","pos":"noun phrase","ipa":"/ˈɡɪr ˌhɑːbɪŋ/","ja":"ホブ切り","kana":"ホブぎり","romaji":"hobugiri","vi":"phay lăn răng","level":2,"def_vi":"Phương pháp cắt răng bằng dao phay lăn (hob) quay ăn khớp liên tục với phôi theo nguyên lý bao hình.","def_en":"A generating process in which a rotating hob cuts gear teeth while meshing continuously with the blank.","def_ja":"回転するホブを素材と連続的にかみ合わせ、創成によって歯を切る加工法。","usage_en":"Danh từ không đếm được. Hay đi với: hobbing machine, hob cutter, gear hobbing of spur and helical gears; động từ: hob a gear.","usage_ja":"Viết ホブ切り hoặc ホブ盤加工; dao là ホブ, máy là ホブ盤. Hay nói: 歯切り (cắt răng nói chung).","context_vi":"Dùng trong sản xuất bánh răng trụ thẳng, nghiêng, trục vít và then hoa.","ex_en":"Gear hobbing is the most productive method for cutting spur gears.","ex_ja":"ホブ切りは平歯車の歯切りで最も生産性の高い方法である。","ex_vi":"Phay lăn răng là phương pháp năng suất cao nhất để cắt bánh răng trụ thẳng.","syn_en":["hobbing","gear cutting (nghĩa rộng hơn)"],"syn_ja":["歯切り (nghĩa rộng hơn)","ホブ盤加工"]},{"en":"pitting","pos":"noun","ipa":"/ˈpɪtɪŋ/","ja":"ピッチング","kana":"ピッチング","romaji":"pitchingu","vi":"tróc rỗ bề mặt răng","level":2,"def_vi":"Hư hỏng do mỏi tiếp xúc, tạo các hố nhỏ trên mặt răng gần vòng chia.","def_en":"Contact-fatigue damage forming small pits on the tooth flanks, usually near the pitch line.","def_ja":"接触疲労により、主にピッチ線付近の歯面に小さなくぼみが生じる損傷。","usage_en":"Danh từ không đếm được. Hay đi với: initial / progressive pitting, pitting resistance, micropitting; pitting cũng dùng cho ăn mòn lỗ.","usage_ja":"Viết ピッチング (thuật ngữ JIS về hư hỏng răng); gần nghĩa 歯面の点食. Hay nói: ピッチングが発生する.","context_vi":"Dùng trong kiểm tra hộp giảm tốc, báo cáo hư hỏng và tính bền tiếp xúc răng.","ex_en":"Progressive pitting was found on the pinion teeth during the annual inspection.","ex_ja":"年次点検でピニオンの歯面に進行性のピッチングが見つかった。","ex_vi":"Kiểm tra định kỳ hằng năm phát hiện tróc rỗ tiến triển trên răng bánh nhỏ.","syn_en":["surface fatigue","micropitting (một loại)"],"syn_ja":["点食","歯面損傷 (nghĩa rộng hơn)"]},{"en":"involute","pos":"noun","ipa":"/ˈɪnvəluːt/","ja":"インボリュート","kana":"インボリュート","romaji":"inboryuuto","vi":"đường thân khai","level":3,"def_vi":"Đường cong vạch bởi một điểm trên sợi dây căng khi tháo dây khỏi vòng tròn cơ sở; là dạng prôfin răng phổ biến nhất.","def_en":"The curve traced by a point on a taut string unwound from a base circle; the most common tooth profile.","def_ja":"基礎円に巻いた糸をほどくとき糸上の点が描く曲線で、最も一般的な歯形。","usage_en":"Danh từ đếm được; cũng là tính từ (involute profile, involute gear). Hay đi với: involute tooth profile, involute function, base circle.","usage_ja":"Viết インボリュート; ghép: インボリュート歯形, インボリュート歯車, インボリュート関数. Đối lập サイクロイド歯形.","context_vi":"Dùng trong lý thuyết ăn khớp, thiết kế và đo prôfin răng.","ex_en":"The involute profile keeps the speed ratio constant even if the center distance changes slightly.","ex_ja":"インボリュート歯形では、中心距離が多少変わっても速度比は一定に保たれる。","ex_vi":"Prôfin thân khai giữ tỉ số tốc độ không đổi dù khoảng cách trục thay đổi chút ít.","syn_en":["involute curve","cycloid (liên quan)"],"syn_ja":["インボリュート曲線","サイクロイド (liên quan)"]},{"en":"profile shift","pos":"noun phrase","ipa":"/ˈproʊfaɪl ʃɪft/","ja":"転位","kana":"てんい","romaji":"ten'i","vi":"dịch chỉnh (bánh răng)","level":3,"def_vi":"Dịch dao cắt ra xa hoặc lại gần tâm phôi khi cắt răng để tránh cắt chân răng hoặc điều chỉnh khoảng cách trục.","def_en":"Moving the cutter away from or toward the blank centre to avoid undercut or adjust center distance.","def_ja":"歯切り時に工具を素材中心から離したり近づけたりして、切下げ防止や中心距離調整を行うこと。","usage_en":"Danh từ không đếm được. Hay đi với: profile shift coefficient x, positive / negative profile shift, profile-shifted gear; còn gọi addendum modification.","usage_ja":"Tên JIS là 転位; ghép: 転位係数 x, 転位歯車, 正転位, 負転位. Ngoài xưởng nói 転位量.","context_vi":"Dùng khi thiết kế bánh răng ít răng, khoảng cách trục không tiêu chuẩn, tăng bền răng.","ex_en":"A positive profile shift of x = 0.3 prevents undercut on the 12-tooth pinion.","ex_ja":"歯数12のピニオンには正の転位x=0.3を与えて切下げを防ぐ。","ex_vi":"Dịch chỉnh dương x = 0,3 giúp tránh cắt chân răng cho bánh nhỏ 12 răng.","syn_en":["addendum modification","profile shift coefficient (liên quan)"],"syn_ja":["転位係数 (liên quan)","転位歯車 (liên quan)"]},{"en":"undercut","pos":"noun","ipa":"/ˈʌndərkʌt/","ja":"切下げ","kana":"きりさげ","romaji":"kirisage","vi":"cắt chân răng (hiện tượng lẹm chân răng)","level":3,"def_vi":"Hiện tượng dao cắt lẹm vào chân răng khi số răng quá ít, làm răng yếu và giảm chiều dài ăn khớp.","def_en":"Removal of material at the tooth root by the cutter when the tooth number is too small, weakening the tooth.","def_ja":"歯数が少ないとき工具が歯元を削り取ってしまう現象で、歯が弱くなる。","usage_en":"Danh từ không đếm được (trong ngữ cảnh bánh răng). Hay đi với: avoid undercut, minimum number of teeth to avoid undercut (17 với 20°); undercut còn nghĩa rãnh thoát dao.","usage_ja":"Tên JIS là 切下げ (cũng viết 切り下げ); hay nói: 切下げが生じる, 転位で切下げを防ぐ. Giới hạn số răng: 17枚.","context_vi":"Dùng khi thiết kế bánh răng nhỏ, chọn số răng tối thiểu và dịch chỉnh.","ex_en":"With only 12 teeth, the standard pinion would suffer from undercut.","ex_ja":"歯数12の標準ピニオンでは切下げが生じてしまう。","ex_vi":"Với chỉ 12 răng, bánh nhỏ tiêu chuẩn sẽ bị cắt chân răng.","syn_en":["root undercut","interference (liên quan)"],"syn_ja":["歯の干渉 (liên quan)"]},{"en":"contact ratio","pos":"noun phrase","ipa":"/ˈkɑːntækt ˌreɪʃioʊ/","ja":"かみ合い率","kana":"かみあいりつ","romaji":"kamiairitsu","vi":"hệ số trùng khớp","level":3,"def_vi":"Số đôi răng ăn khớp trung bình cùng lúc; phải lớn hơn 1 để truyền động liên tục và êm.","def_en":"The average number of tooth pairs in contact at once; it must exceed 1 for smooth, continuous drive.","def_ja":"同時にかみ合う歯の対の平均数で、連続して滑らかに伝動するには1より大きい必要がある。","usage_en":"Danh từ đếm được. Hay đi với: transverse contact ratio, overlap ratio, a contact ratio of 1.6; bánh răng nghiêng có total contact ratio lớn hơn.","usage_ja":"Tên JIS là かみ合い率 (噛み合い率); ghép: 正面かみ合い率, 重なりかみ合い率, 全かみ合い率.","context_vi":"Dùng trong thiết kế bánh răng giảm ồn, tính toán độ bền và đánh giá êm dịu.","ex_en":"Increasing the contact ratio above 2 reduced the gear noise noticeably.","ex_ja":"かみ合い率を2以上にしたことで歯車の騒音が明らかに低下した。","ex_vi":"Tăng hệ số trùng khớp lên trên 2 giúp giảm rõ tiếng ồn bánh răng.","syn_en":["transverse contact ratio","overlap ratio (liên quan)"],"syn_ja":["正面かみ合い率","噛み合い率"]},{"en":"tooth root stress","pos":"noun phrase","ipa":"/ˈtuːθ ruːt stres/","ja":"歯元曲げ応力","kana":"はもとまげおうりょく","romaji":"hamotomageouryoku","vi":"ứng suất uốn chân răng","level":3,"def_vi":"Ứng suất uốn lớn nhất xuất hiện ở góc lượn chân răng khi răng chịu tải, dùng để kiểm tra gãy răng.","def_en":"The maximum bending stress at the tooth root fillet under load, used to check against tooth breakage.","def_ja":"荷重を受けたとき歯元すみ肉部に生じる最大曲げ応力で、歯の折損に対する強度評価に用いる。","usage_en":"Danh từ không đếm được. Hay đi với: calculate the tooth root stress, permissible root stress, ISO 6336 bending strength; đi cặp với contact stress.","usage_ja":"Tên JIS là 歯元曲げ応力; đi cặp với 歯面接触応力 (hertz). Hay nói: 曲げ強さの計算, 許容歯元曲げ応力.","context_vi":"Dùng khi tính bền bánh răng theo ISO 6336/JIS B 1759, đánh giá gãy răng do mỏi.","ex_en":"The tooth root stress is 280 MPa, below the permissible value of 350 MPa.","ex_ja":"歯元曲げ応力は280 MPaで、許容値350 MPaを下回っている。","ex_vi":"Ứng suất uốn chân răng là 280 MPa, thấp hơn giá trị cho phép 350 MPa.","syn_en":["root bending stress","contact stress (liên quan)"],"syn_ja":["曲げ応力 (nghĩa rộng hơn)","歯面接触応力 (liên quan)"]},{"en":"tooth contact pattern","pos":"noun phrase","ipa":"/ˈtuːθ ˈkɑːntækt ˌpætərn/","ja":"歯当たり","kana":"はあたり","romaji":"haatari","vi":"vết tiếp xúc răng","level":3,"def_vi":"Vùng tiếp xúc trên mặt răng được kiểm tra bằng bột màu, cho biết độ ăn khớp và sai lệch lắp ráp.","def_en":"The area of contact on the tooth flank, checked with marking compound to judge meshing and alignment.","def_ja":"光明丹などで確認する歯面上の接触範囲で、かみ合い状態や組立誤差を判断する。","usage_en":"Danh từ đếm được. Hay đi với: check the tooth contact pattern with marking blue / Prussian blue, heel / toe contact; khẩu ngữ: contact pattern.","usage_ja":"Viết 歯当たり; hay nói: 歯当たりを確認する, 歯当たりが片寄る (片当たり), 光明丹を塗る.","context_vi":"Dùng khi lắp ráp và điều chỉnh cặp bánh răng côn, hộp giảm tốc lớn, cầu xe.","ex_en":"The tooth contact pattern was shifted toward the toe, so the pinion was moved back 0.1 mm.","ex_ja":"歯当たりがトウ側に寄っていたため、ピニオンを0.1 mm後退させた。","ex_vi":"Vết tiếp xúc răng lệch về phía mũi nên bánh nhỏ được lùi lại 0,1 mm.","syn_en":["contact pattern","tooth bearing (Anh, gần nghĩa)"],"syn_ja":["片当たり (liên quan)","当たり (khẩu ngữ)"]}]},{"id":25,"words":[{"en":"belt","pos":"noun","ipa":"/belt/","ja":"ベルト","kana":"ベルト","romaji":"beruto","vi":"dây đai (dây curoa)","level":1,"def_vi":"Vòng mềm khép kín bằng cao su hoặc vật liệu tổng hợp, quấn qua các puly để truyền chuyển động và công suất.","def_en":"A flexible closed loop of rubber or synthetic material running over pulleys to transmit motion and power.","def_ja":"ゴムや合成材料でできた無端の帯で、プーリに掛けて運動と動力を伝える。","usage_en":"Danh từ đếm được. Hay đi với: drive belt, belt drive, fit / replace / tension a belt, belt slips; người Việt gọi dây curoa (từ tiếng Pháp courroie).","usage_ja":"Luôn viết katakana ベルト. Động từ: ベルトを掛ける, 張る, 交換する; hay nói ベルトが滑る, ベルト鳴き.","context_vi":"Dùng ở máy nén khí, quạt, máy công cụ, động cơ ô tô, máy nông nghiệp.","ex_en":"The belt was squealing because its tension was too low.","ex_ja":"張力が不足していたため、ベルトが鳴いていた。","ex_vi":"Dây đai kêu rít vì lực căng quá thấp.","syn_en":["drive belt","V-belt (một loại)"],"syn_ja":["伝動ベルト","Vベルト (một loại)"]},{"en":"pulley","pos":"noun","ipa":"/ˈpʊli/","ja":"プーリ","kana":"プーリ","romaji":"puuri","vi":"puly (bánh đai)","level":1,"def_vi":"Bánh có rãnh hoặc mặt trơn lắp trên trục, quấn dây đai để truyền chuyển động.","def_en":"A grooved or flat wheel mounted on a shaft, around which a belt runs to transmit motion.","def_ja":"軸に取り付けた溝付きまたは平らな車で、ベルトを掛けて運動を伝える。","usage_en":"Danh từ đếm được. Hay đi với: drive / driven pulley, V-belt pulley, pulley diameter, mount a pulley on the shaft; trong ròng rọc nâng cũng gọi pulley.","usage_ja":"Tên JIS là プーリ; ngoài xưởng nói プーリー, sách cũ dùng ベルト車. Ghép: Vプーリ, 駆動プーリ, 従動プーリ.","context_vi":"Dùng ở bộ truyền đai của động cơ, quạt, máy nén, máy tiện, băng tải.","ex_en":"A larger pulley on the fan shaft reduced the fan speed.","ex_ja":"ファン軸のプーリを大きくしてファンの回転速度を下げた。","ex_vi":"Puly lớn hơn trên trục quạt làm giảm tốc độ quạt.","syn_en":["sheave","belt pulley"],"syn_ja":["プーリー","ベルト車"]},{"en":"chain","pos":"noun","ipa":"/tʃeɪn/","ja":"チェーン","kana":"チェーン","romaji":"cheen","vi":"xích","level":1,"def_vi":"Chuỗi các mắt kim loại nối khớp với nhau, ăn khớp với đĩa xích để truyền công suất hoặc nâng tải.","def_en":"A series of jointed metal links that engages sprockets to transmit power or lift loads.","def_ja":"金属のリンクを連結したもので、スプロケットとかみ合って動力を伝えたり荷を吊ったりする。","usage_en":"Danh từ đếm được. Hay đi với: chain drive, roller chain, chain link, lubricate / adjust the chain, the chain jumps teeth.","usage_ja":"Viết katakana チェーン (JIS dùng チェーン; 鎖 dùng cho xích treo/nâng). Động từ: チェーンを張る, 注油する, 掛ける.","context_vi":"Dùng ở xe máy, xe đạp, băng tải, máy nông nghiệp, palăng xích.","ex_en":"Lubricate the chain every week to reduce wear.","ex_ja":"摩耗を減らすため、チェーンには毎週注油する。","ex_vi":"Bôi trơn xích hằng tuần để giảm mòn.","syn_en":["roller chain (một loại)","drive chain"],"syn_ja":["鎖","ローラチェーン (một loại)"]},{"en":"sprocket","pos":"noun","ipa":"/ˈsprɑːkɪt/","ja":"スプロケット","kana":"スプロケット","romaji":"supuroketto","vi":"đĩa xích (nhông xích)","level":1,"def_vi":"Bánh có răng đặc biệt ăn khớp với các mắt xích để truyền chuyển động.","def_en":"A toothed wheel whose teeth engage the links of a chain to transmit motion.","def_ja":"チェーンのリンクとかみ合う歯をもつ車で、運動を伝える。","usage_en":"Danh từ đếm được. Hay đi với: drive / driven sprocket, 15-tooth sprocket, sprocket teeth wear; người Việt gọi bánh nhỏ là nhông, bánh lớn là đĩa.","usage_ja":"Tên JIS là スプロケット; ghép: 駆動スプロケット, 歯数15のスプロケット. Thường thay cùng lúc với チェーン.","context_vi":"Dùng ở bộ truyền xích của xe máy, băng tải, máy đóng gói, máy nông nghiệp.","ex_en":"Replace the chain and sprocket together when the teeth are hooked.","ex_ja":"歯先がかぎ状に摩耗したら、チェーンとスプロケットを同時に交換する。","ex_vi":"Khi răng bị mòn nhọn như móc câu, thay xích và đĩa xích cùng lúc.","syn_en":["sprocket wheel","chainwheel"],"syn_ja":["鎖車","スプロケットホイール"]},{"en":"V-belt","pos":"noun","ipa":"/ˈviː belt/","ja":"Vベルト","kana":"ブイベルト","romaji":"buiberuto","vi":"đai thang (dây curoa thang)","level":1,"def_vi":"Dây đai tiết diện hình thang, nêm vào rãnh puly nên truyền lực bằng ma sát lớn.","def_en":"A belt with a trapezoidal cross-section that wedges into pulley grooves for high frictional grip.","def_ja":"台形断面のベルトで、プーリの溝にくさび状に食い込み大きな摩擦力で伝動する。","usage_en":"Danh từ đếm được. Hay đi với: A / B / SPA section V-belt, matched set of V-belts, V-belt drive; viết cả vee belt.","usage_ja":"Tên JIS là Vベルト (đọc ブイベルト); ghép: 細幅Vベルト, Vプーリ, 多本掛け. Ký hiệu cỡ A形, B形, 3V.","context_vi":"Dùng phổ biến ở máy nén khí, quạt, bơm, máy công cụ và máy nông nghiệp.","ex_en":"The compressor is driven by three B-section V-belts.","ex_ja":"コンプレッサはB形Vベルト3本掛けで駆動されている。","ex_vi":"Máy nén được dẫn động bằng ba dây đai thang cỡ B.","syn_en":["vee belt","wedge belt (một loại)"],"syn_ja":["細幅Vベルト (một loại)","ベルト (nghĩa rộng hơn)"]},{"en":"belt drive","pos":"noun phrase","ipa":"/ˈbelt draɪv/","ja":"ベルト伝動","kana":"ベルトでんどう","romaji":"berutodendou","vi":"bộ truyền đai","level":1,"def_vi":"Bộ truyền công suất giữa hai trục xa nhau bằng dây đai quấn qua các puly.","def_en":"A power transmission between separated shafts using a belt running over pulleys.","def_ja":"離れた軸の間でプーリとベルトを用いて動力を伝える方式。","usage_en":"Danh từ đếm được. Hay đi với: V-belt drive, open / crossed belt drive, belt drive ratio; ưu điểm: êm, giảm chấn, chống quá tải bằng trượt.","usage_ja":"Viết ベルト伝動 hoặc ベルト駆動 (ngoài xưởng hay dùng hơn). Hay nói: ベルト伝動装置, ベルト駆動方式.","context_vi":"Dùng khi khoảng cách trục lớn, cần êm và đơn giản: máy nén, quạt, máy trộn, máy giặt.","ex_en":"A belt drive was chosen because it absorbs shock and is easy to maintain.","ex_ja":"衝撃を吸収し保守も容易なため、ベルト伝動を採用した。","ex_vi":"Chọn bộ truyền đai vì hấp thụ va đập và dễ bảo trì.","syn_en":["belt transmission"],"syn_ja":["ベルト駆動","巻掛け伝動 (nghĩa rộng hơn)"]},{"en":"chain drive","pos":"noun phrase","ipa":"/ˈtʃeɪn draɪv/","ja":"チェーン伝動","kana":"チェーンでんどう","romaji":"cheendendou","vi":"bộ truyền xích","level":1,"def_vi":"Bộ truyền công suất bằng xích ăn khớp với các đĩa xích, không trượt và chịu tải lớn.","def_en":"A power transmission using a chain engaging sprockets, with no slip and high load capacity.","def_ja":"チェーンとスプロケットのかみ合いで動力を伝える方式で、滑りがなく大きな荷重に耐える。","usage_en":"Danh từ đếm được. Hay đi với: roller chain drive, chain drive ratio, chain drive lubrication; ồn hơn và cần bôi trơn so với belt drive.","usage_ja":"Viết チェーン伝動 hoặc チェーン駆動. Hay nói: チェーン伝動装置, 巻掛け伝動 (nghĩa chung cho đai và xích).","context_vi":"Dùng ở xe máy, băng tải tốc độ thấp, máy nông nghiệp, máy xây dựng.","ex_en":"The chain drive must be lubricated and its slack checked monthly.","ex_ja":"チェーン伝動は毎月、給油とたるみの点検を行う必要がある。","ex_vi":"Bộ truyền xích phải được bôi trơn và kiểm tra độ chùng hằng tháng.","syn_en":["chain transmission"],"syn_ja":["チェーン駆動","巻掛け伝動 (nghĩa rộng hơn)"]},{"en":"belt tension","pos":"noun phrase","ipa":"/ˈbelt ˌtenʃn/","ja":"ベルト張力","kana":"ベルトちょうりょく","romaji":"berutochouryoku","vi":"lực căng đai","level":1,"def_vi":"Lực kéo trong dây đai khi lắp, cần đủ để không trượt nhưng không quá lớn gây hỏng ổ và đai.","def_en":"The pulling force in a belt after installation, high enough to prevent slip but not so high it damages bearings.","def_ja":"取付け時にベルトに与える張力で、滑らない程度に必要だが、大きすぎると軸受やベルトを傷める。","usage_en":"Danh từ không đếm được. Hay đi với: check / adjust the belt tension, belt tension gauge, deflection method; động từ: tension the belt.","usage_ja":"Viết ベルト張力; ngoài xưởng hay nói ベルトの張り. Động từ: 張りを調整する; dụng cụ: 張力計, 音波式張力計.","context_vi":"Dùng khi lắp đặt, bảo trì định kỳ bộ truyền đai và xử lý đai kêu, trượt.","ex_en":"Check the belt tension by pressing the middle of the span with 30 N.","ex_ja":"スパン中央を30 Nで押してベルト張力を確認する。","ex_vi":"Kiểm tra lực căng đai bằng cách ấn giữa nhánh đai với lực 30 N.","syn_en":["belt tightness","initial tension (liên quan)"],"syn_ja":["ベルトの張り","初張力 (liên quan)"]},{"en":"chain link","pos":"noun phrase","ipa":"/ˈtʃeɪn lɪŋk/","ja":"リンク","kana":"リンク","romaji":"rinku","vi":"mắt xích","level":1,"def_vi":"Từng đơn vị cấu tạo của xích, gồm má xích, chốt và ống lót nối với nhau.","def_en":"One unit of a chain, made of plates, pins and bushes joined together.","def_ja":"チェーンを構成する単位で、プレート、ピン、ブシュなどから成る。","usage_en":"Danh từ đếm được. Hay đi với: roller link, pin link, connecting link, count the chain links; chiều dài xích tính bằng số mắt (links).","usage_ja":"Trong JIS gọi リンク (ローラリンク, ピンリンク); số mắt gọi リンク数. Đếm: 100リンク.","context_vi":"Dùng khi đo chiều dài, cắt nối xích, thay thế và đặt hàng xích.","ex_en":"Remove two chain links to shorten the chain after it has stretched.","ex_ja":"伸びたチェーンを短くするため、リンクを2個外す。","ex_vi":"Tháo hai mắt xích để rút ngắn xích sau khi bị giãn.","syn_en":["link","roller link (một loại)"],"syn_ja":["ローラリンク (một loại)","リンク数 (liên quan)"]},{"en":"timing belt","pos":"noun phrase","ipa":"/ˈtaɪmɪŋ belt/","ja":"歯付きベルト","kana":"はつきベルト","romaji":"hatsukiberuto","vi":"đai răng (dây curoa răng)","level":1,"def_vi":"Dây đai có răng ở mặt trong ăn khớp với puly răng, truyền động đồng bộ không trượt.","def_en":"A belt with teeth on its inner side that mesh with toothed pulleys for slip-free synchronous drive.","def_ja":"内側に歯をもち、歯付きプーリとかみ合って滑りなく同期伝動するベルト。","usage_en":"Danh từ đếm được. Hay đi với: synchronous belt, timing belt pulley, HTD / GT profile, replace the timing belt (động cơ ô tô).","usage_ja":"Tên JIS là 歯付きベルト; ngoài xưởng gọi タイミングベルト (rất phổ biến). Ghép: 歯付きプーリ, 歯形 (S8M, T5).","context_vi":"Dùng ở động cơ ô tô (dẫn động cam), máy in 3D, máy CNC nhỏ, robot, máy đóng gói.","ex_en":"The engine's timing belt must be replaced every 100,000 km.","ex_ja":"エンジンの歯付きベルトは10万kmごとに交換しなければならない。","ex_vi":"Đai răng của động cơ phải thay sau mỗi 100.000 km.","syn_en":["synchronous belt","toothed belt"],"syn_ja":["タイミングベルト","同期ベルト"]},{"en":"flat belt","pos":"noun phrase","ipa":"/ˈflæt belt/","ja":"平ベルト","kana":"ひらベルト","romaji":"hiraberuto","vi":"đai dẹt","level":2,"def_vi":"Dây đai có tiết diện chữ nhật mỏng, chạy trên puly mặt trơn, phù hợp tốc độ cao và khoảng cách trục lớn.","def_en":"A thin belt of rectangular section running on flat-faced pulleys, suited to high speed and long center distances.","def_ja":"薄い長方形断面のベルトで、平プーリに掛けて高速・長軸間距離の伝動に用いる。","usage_en":"Danh từ đếm được. Hay đi với: flat belt pulley, crowned pulley, high-speed flat belt; puly thường làm vồng để đai không tuột.","usage_ja":"Viết 平ベルト; ghép: 平プーリ, 高速平ベルト. Puly thường có クラウン để giữ đai ở giữa.","context_vi":"Dùng ở máy dệt, máy giấy, trục chính tốc độ cao, băng tải nhẹ.","ex_en":"A thin flat belt drives the grinding spindle at 10,000 rpm.","ex_ja":"薄い平ベルトで研削主軸を10,000 rpmで駆動している。","ex_vi":"Một đai dẹt mỏng dẫn động trục mài ở 10.000 vòng/phút.","syn_en":["flat drive belt"],"syn_ja":["フラットベルト"]},{"en":"roller chain","pos":"noun phrase","ipa":"/ˈroʊlər tʃeɪn/","ja":"ローラチェーン","kana":"ローラチェーン","romaji":"rooracheen","vi":"xích con lăn","level":2,"def_vi":"Loại xích truyền động phổ biến nhất, gồm các con lăn quay trên ống lót giữa hai má xích.","def_en":"The most common drive chain, with rollers turning on bushes between pairs of link plates.","def_ja":"最も一般的な伝動用チェーンで、ブシュの外側で回転するローラをリンクプレートで挟んだ構造。","usage_en":"Danh từ đếm được. Hay đi với: ANSI 40 / ISO 08B roller chain, single-strand / double-strand roller chain.","usage_ja":"Tên JIS là ローラチェーン (cũng viết ローラーチェーン); số hiệu như RS40, RS60. Ghép: 1列, 2列ローラチェーン.","context_vi":"Dùng ở xe máy, băng tải, máy đóng gói, máy nông nghiệp và thiết bị nâng.","ex_en":"A double-strand RS60 roller chain transmits the conveyor drive torque.","ex_ja":"コンベヤの駆動トルクはRS60の2列ローラチェーンで伝える。","ex_vi":"Xích con lăn hai dãy RS60 truyền mô-men dẫn động băng tải.","syn_en":["bush roller chain","drive chain"],"syn_ja":["ローラーチェーン","伝動用チェーン"]},{"en":"chain pitch","pos":"noun phrase","ipa":"/ˈtʃeɪn pɪtʃ/","ja":"チェーンピッチ","kana":"チェーンピッチ","romaji":"cheenpitchi","vi":"bước xích","level":2,"def_vi":"Khoảng cách giữa tâm hai chốt kề nhau của xích, quyết định cỡ xích và đĩa xích.","def_en":"The distance between the centres of adjacent chain pins, which defines the chain and sprocket size.","def_ja":"隣り合うピンの中心間距離で、チェーンとスプロケットの大きさを決める。","usage_en":"Danh từ đếm được. Hay đi với: a chain pitch of 12.7 mm (1/2 inch), match the chain pitch to the sprocket; số hiệu ANSI 40 = 4/8 inch.","usage_ja":"Viết チェーンピッチ hoặc gọi tắt ピッチ; ví dụ RS40 có ピッチ12.70 mm. Hay nói: ピッチが伸びる.","context_vi":"Dùng khi chọn cỡ xích, tính chiều dài xích và kiểm tra độ giãn xích.","ex_en":"RS40 roller chain has a chain pitch of 12.70 mm.","ex_ja":"RS40ローラチェーンのチェーンピッチは12.70 mmである。","ex_vi":"Xích con lăn RS40 có bước xích 12,70 mm.","syn_en":["pitch"],"syn_ja":["ピッチ"]},{"en":"idler pulley","pos":"noun phrase","ipa":"/ˈaɪdlər ˌpʊli/","ja":"アイドラ","kana":"アイドラ","romaji":"aidora","vi":"puly căng (puly dẫn hướng)","level":2,"def_vi":"Puly không truyền công suất, dùng để căng đai, đổi hướng đai hoặc tăng góc ôm.","def_en":"A pulley that transmits no power, used to tension or guide the belt or increase the wrap angle.","def_ja":"動力を伝えず、ベルトの張り、案内、巻掛け角の増加のために用いるプーリ。","usage_en":"Danh từ đếm được, hay gọi tắt idler. Hay đi với: tensioner idler pulley, backside idler, idler bearing failure.","usage_ja":"Viết アイドラ hoặc アイドラプーリ; loại căng gọi テンションプーリ. Hay nói: アイドラで張りを調整する.","context_vi":"Dùng ở động cơ ô tô, bộ truyền đai dài, máy công cụ, máy nông nghiệp.","ex_en":"A worn bearing in the idler pulley caused the engine noise.","ex_ja":"アイドラの軸受摩耗がエンジン異音の原因だった。","ex_vi":"Ổ bi mòn của puly căng là nguyên nhân gây tiếng ồn động cơ.","syn_en":["idler","tension pulley (gần nghĩa)"],"syn_ja":["アイドラプーリ","テンションプーリ (gần nghĩa)"]},{"en":"belt tensioner","pos":"noun phrase","ipa":"/ˈbelt ˌtenʃənər/","ja":"テンショナ","kana":"テンショナ","romaji":"tenshona","vi":"bộ tăng đai (cơ cấu căng đai)","level":2,"def_vi":"Cơ cấu có lò xo hoặc vít điều chỉnh giữ lực căng đai hoặc xích ổn định trong khi làm việc.","def_en":"A spring-loaded or adjustable device that keeps belt or chain tension steady during operation.","def_ja":"ばねや調整ねじにより、運転中のベルトやチェーンの張力を一定に保つ装置。","usage_en":"Danh từ đếm được. Hay đi với: automatic belt tensioner, spring-loaded tensioner, chain tensioner (cho xích).","usage_ja":"Viết テンショナ hoặc テンショナー; ghép: オートテンショナ, チェーンテンショナ. Hay nói: テンショナで張りを自動調整する.","context_vi":"Dùng ở động cơ ô tô, xe máy (căng xích cam), bộ truyền xích băng tải.","ex_en":"An automatic belt tensioner keeps the accessory belt at the correct tension.","ex_ja":"オートテンショナが補機ベルトの張力を適正に保っている。","ex_vi":"Bộ tăng đai tự động giữ dây đai phụ tải ở lực căng đúng.","syn_en":["tensioner","chain tensioner (một loại)"],"syn_ja":["テンショナー","オートテンショナ (một loại)"]},{"en":"belt slip","pos":"noun phrase","ipa":"/ˈbelt slɪp/","ja":"ベルトの滑り","kana":"ベルトのすべり","romaji":"berutonosuberi","vi":"hiện tượng trượt đai","level":2,"def_vi":"Hiện tượng đai trượt tương đối trên puly do lực căng thấp hoặc quá tải, làm giảm tốc độ và gây nóng, mòn.","def_en":"Relative sliding of a belt on its pulley due to low tension or overload, reducing speed and causing heat and wear.","def_ja":"張力不足や過負荷によりベルトがプーリ上で滑ることで、速度低下や発熱・摩耗を招く。","usage_en":"Danh từ không đếm được; động từ: the belt slips. Hay đi với: prevent belt slip, slip ratio, squeal caused by belt slip.","usage_ja":"Viết ベルトの滑り (cũng viết すべり); ngoài xưởng hay nói ベルトスリップ, ベルトが滑る. Liên quan ベルト鳴き.","context_vi":"Dùng khi chẩn đoán đai kêu rít, tốc độ thấp, đai nóng trong bảo trì.","ex_en":"Belt slip at start-up was eliminated by raising the tension.","ex_ja":"張力を上げることで、起動時のベルトの滑りがなくなった。","ex_vi":"Hiện tượng trượt đai khi khởi động đã hết sau khi tăng lực căng.","syn_en":["slippage","creep (liên quan)"],"syn_ja":["ベルトスリップ","クリープ (liên quan)"]},{"en":"wrap angle","pos":"noun phrase","ipa":"/ˈræp ˌæŋɡl/","ja":"巻掛け角","kana":"まきかけかく","romaji":"makikakekaku","vi":"góc ôm","level":2,"def_vi":"Góc ở tâm puly ứng với cung tiếp xúc giữa đai và puly; góc ôm càng nhỏ đai càng dễ trượt.","def_en":"The angle at the pulley centre covered by the belt contact arc; a smaller angle makes slip more likely.","def_ja":"ベルトがプーリに接触する円弧に対する中心角で、小さいほど滑りやすい。","usage_en":"Danh từ đếm được. Hay đi với: wrap angle on the small pulley, increase the wrap angle with an idler; còn gọi angle of contact.","usage_ja":"Tên JIS là 巻掛け角 (cũng viết 巻き掛け角); hay nói: 小プーリの巻掛け角, 巻掛け角補正係数.","context_vi":"Dùng khi tính toán bộ truyền đai, chọn số dây đai và bố trí puly căng.","ex_en":"The wrap angle on the small pulley should be at least 120°.","ex_ja":"小プーリの巻掛け角は120°以上とする。","ex_vi":"Góc ôm trên puly nhỏ nên tối thiểu 120°.","syn_en":["angle of contact","arc of contact (liên quan)"],"syn_ja":["接触角","巻き掛け角"]},{"en":"chain elongation","pos":"noun phrase","ipa":"/ˈtʃeɪn ˌiːlɔːŋˈɡeɪʃn/","ja":"チェーンの伸び","kana":"チェーンののび","romaji":"cheennonobi","vi":"độ giãn xích","level":2,"def_vi":"Sự tăng chiều dài xích do mòn chốt và ống lót; khi vượt khoảng 1,5% cần thay xích.","def_en":"The increase in chain length caused by pin and bush wear; replace the chain when it exceeds about 1.5%.","def_ja":"ピンとブシュの摩耗によるチェーン全長の増加で、約1.5%を超えたら交換する。","usage_en":"Danh từ không đếm được. Hay đi với: measure chain elongation, wear elongation, elongation limit; khẩu ngữ: chain stretch.","usage_ja":"Viết チェーンの伸び hoặc 摩耗伸び; hay nói: 伸び率を測る, 伸びが限界を超える. Dụng cụ: チェーン摩耗ゲージ.","context_vi":"Dùng trong bảo trì xích băng tải, xích xe máy, xích cam động cơ.","ex_en":"Chain elongation reached 1.8%, so the chain and sprockets were replaced.","ex_ja":"チェーンの伸びが1.8%に達したため、チェーンとスプロケットを交換した。","ex_vi":"Độ giãn xích đạt 1,8% nên đã thay xích và đĩa xích.","syn_en":["chain stretch (khẩu ngữ)","wear elongation"],"syn_ja":["摩耗伸び","伸び率 (liên quan)"]},{"en":"variable speed pulley","pos":"noun phrase","ipa":"/ˈveriəbl spiːd ˈpʊli/","ja":"可変径プーリ","kana":"かへんけいプーリ","romaji":"kahenkeipuuri","vi":"puly biến tốc (puly thay đổi đường kính)","level":2,"def_vi":"Puly có hai nửa côn dịch chuyển được để thay đổi đường kính làm việc, cho phép điều chỉnh tốc độ vô cấp.","def_en":"A pulley whose conical halves move apart or together to change its effective diameter for stepless speed control.","def_ja":"円すい状の半体を移動させて有効径を変え、無段変速を行うプーリ。","usage_en":"Danh từ đếm được. Hay đi với: variable pitch pulley, variable speed belt, CVT pulley; dùng với đai biến tốc rộng.","usage_ja":"Viết 可変径プーリ hoặc 可変ピッチプーリ; ngoài xưởng gọi 変速プーリ. Dùng với 変速ベルト.","context_vi":"Dùng ở xe tay ga, máy khoan bàn biến tốc, máy dệt, máy chế biến gỗ.","ex_en":"The scooter uses a variable speed pulley that opens as engine speed rises.","ex_ja":"スクータは、エンジン回転が上がると開く可変径プーリを使っている。","ex_vi":"Xe tay ga dùng puly biến tốc mở rộng khi tốc độ động cơ tăng.","syn_en":["variable pitch pulley","adjustable pulley"],"syn_ja":["可変ピッチプーリ","変速プーリ"]},{"en":"taper bushing","pos":"noun phrase","ipa":"/ˈteɪpər ˌbʊʃɪŋ/","ja":"テーパブシュ","kana":"テーパブシュ","romaji":"teepabushu","vi":"bạc côn (ống côn lắp puly)","level":2,"def_vi":"Ống lót côn có xẻ rãnh, siết bằng vít để kẹp chặt puly hoặc đĩa xích lên trục mà không cần gia công lỗ.","def_en":"A split tapered bush tightened with screws to clamp a pulley or sprocket onto a shaft without reboring.","def_ja":"割りを入れたテーパ状のブシュで、ねじを締めてプーリやスプロケットを軸に締結する。","usage_en":"Danh từ đếm được. Hay đi với: taper lock bushing, QD bushing, taper bushing pulley; tên thương mại Taper-Lock.","usage_ja":"Viết テーパブシュ (cũng viết テーパーブッシュ); ghép: テーパブシュ付きプーリ. Ngoài xưởng gọi テーパロック.","context_vi":"Dùng ở puly đai thang, đĩa xích, khớp nối trong bộ truyền công nghiệp.","ex_en":"The new pulley uses a taper bushing, so the bore does not need machining.","ex_ja":"新しいプーリはテーパブシュ式なので、穴加工が不要である。","ex_vi":"Puly mới dùng bạc côn nên không cần gia công lỗ.","syn_en":["taper lock bush","QD bushing (một loại)"],"syn_ja":["テーパロック (thương hiệu)","テーパーブッシュ"]},{"en":"pulley alignment","pos":"noun phrase","ipa":"/ˈpʊli əˌlaɪnmənt/","ja":"プーリの芯出し","kana":"プーリのしんだし","romaji":"puurinoshindashi","vi":"căn thẳng hàng puly","level":2,"def_vi":"Việc chỉnh hai puly nằm trên cùng một mặt phẳng và trục song song để đai không mòn lệch hoặc tuột.","def_en":"Adjusting two pulleys to lie in the same plane with parallel shafts so the belt does not wear unevenly or come off.","def_ja":"2つのプーリが同一平面上にあり軸が平行になるよう調整し、ベルトの偏摩耗や外れを防ぐ作業。","usage_en":"Danh từ không đếm được. Hay đi với: laser pulley alignment, check pulley alignment with a straightedge, offset / angular misalignment.","usage_ja":"Viết プーリの芯出し hoặc プーリアライメント; hay nói: 直定規でプーリの芯を合わせる, レーザ芯出し.","context_vi":"Dùng khi lắp đặt, thay đai và bảo trì động cơ – quạt, máy nén, bơm truyền đai.","ex_en":"Poor pulley alignment caused one side of the V-belt to wear quickly.","ex_ja":"プーリの芯出し不良により、Vベルトの片側が早く摩耗した。","ex_vi":"Puly căn không thẳng hàng làm một bên đai thang mòn nhanh.","syn_en":["sheave alignment","belt alignment"],"syn_ja":["プーリアライメント","芯出し (nghĩa rộng hơn)"]},{"en":"ribbed belt","pos":"noun phrase","ipa":"/ˈrɪbd belt/","ja":"Vリブドベルト","kana":"ブイリブドベルト","romaji":"buiribudoberuto","vi":"đai gân (đai nhiều rãnh, đai poly-V)","level":2,"def_vi":"Dây đai dẹt có nhiều gân hình chữ V dọc theo mặt trong, kết hợp độ mềm của đai dẹt và độ bám của đai thang.","def_en":"A flat belt with several V-shaped longitudinal ribs, combining flat-belt flexibility with V-belt grip.","def_ja":"内側に縦方向のV形リブを複数もつベルトで、平ベルトの柔軟性とVベルトの伝動力を兼ねる。","usage_en":"Danh từ đếm được. Hay đi với: poly-V belt, serpentine belt (ô tô), PK profile, 6PK1200; dùng cho puly đường kính nhỏ.","usage_ja":"Tên JIS là Vリブドベルト (đọc ブイリブドベルト); ngoài xưởng gọi リブベルト, ポリVベルト. Cỡ như 6PK.","context_vi":"Dùng ở dây đai phụ tải động cơ ô tô, máy giặt, máy chạy bộ, dụng cụ điện.","ex_en":"The alternator, pump and compressor are driven by one ribbed belt.","ex_ja":"オルタネータ、ポンプ、コンプレッサは1本のVリブドベルトで駆動される。","ex_vi":"Máy phát, bơm và máy nén được dẫn động bằng một đai gân.","syn_en":["poly-V belt","serpentine belt (ô tô)","multi-rib belt"],"syn_ja":["リブベルト","ポリVベルト"]},{"en":"belt length","pos":"noun phrase","ipa":"/ˈbelt leŋθ/","ja":"ベルト長さ","kana":"ベルトながさ","romaji":"berutonagasa","vi":"chiều dài đai","level":2,"def_vi":"Chiều dài chu vi đo theo đường trung bình (hoặc đường chia) của dây đai, dùng để chọn mã đai tiêu chuẩn.","def_en":"The circumferential length of a belt measured along its pitch line, used to select a standard belt size.","def_ja":"ベルトのピッチ線に沿って測った周長で、標準ベルトの呼び番号の選定に用いる。","usage_en":"Danh từ đếm được. Hay đi với: calculate the belt length, pitch length, nominal belt length; công thức dùng hai đường kính puly và khoảng cách trục.","usage_ja":"Viết ベルト長さ hoặc 有効周長, ピッチ周長. Hay nói: ベルト長さを計算する, 呼び番号 (ví dụ B-50).","context_vi":"Dùng khi thiết kế bộ truyền đai, đặt mua dây đai thay thế.","ex_en":"The calculated belt length is 1,270 mm, so a B-50 belt was selected.","ex_ja":"ベルト長さは計算で1,270 mmとなり、B-50のベルトを選定した。","ex_vi":"Chiều dài đai tính được là 1.270 mm nên chọn dây đai B-50.","syn_en":["pitch length","effective length (gần nghĩa)"],"syn_ja":["ピッチ周長","有効周長"]},{"en":"slack side","pos":"noun phrase","ipa":"/ˈslæk saɪd/","ja":"ゆるみ側","kana":"ゆるみがわ","romaji":"yurumigawa","vi":"nhánh chùng","level":2,"def_vi":"Nhánh dây đai hoặc xích có lực căng nhỏ hơn, đi vào puly dẫn; đối lập với nhánh căng.","def_en":"The span of a belt or chain with the lower tension, entering the driving pulley; opposite of the tight side.","def_ja":"ベルトやチェーンのうち張力が小さい側のスパンで、駆動プーリに入る側。張り側と対になる。","usage_en":"Danh từ đếm được. Hay đi với: slack side tension, place the idler on the slack side, tight side (ngược nghĩa).","usage_ja":"Viết ゆるみ側 (cũng viết 緩み側); đối lập 張り側. Hay nói: テンショナはゆるみ側に付ける.","context_vi":"Dùng khi bố trí puly căng, bộ căng xích và tính toán lực căng bộ truyền.","ex_en":"Install the chain tensioner on the slack side, close to the driving sprocket.","ex_ja":"チェーンテンショナは駆動スプロケットに近いゆるみ側に取り付ける。","ex_vi":"Lắp bộ căng xích ở nhánh chùng, gần đĩa xích dẫn.","syn_en":["slack span","tight side (liên quan, ngược nghĩa)"],"syn_ja":["緩み側","張り側 (liên quan, ngược nghĩa)"]},{"en":"silent chain","pos":"noun phrase","ipa":"/ˈsaɪlənt tʃeɪn/","ja":"サイレントチェーン","kana":"サイレントチェーン","romaji":"sairentocheen","vi":"xích răng (xích êm)","level":3,"def_vi":"Xích gồm các má hình răng xếp chồng, ăn khớp với đĩa xích như bánh răng, chạy êm ở tốc độ cao.","def_en":"A chain of stacked toothed plates that mesh with the sprocket like gear teeth, running quietly at high speed.","def_ja":"歯形のプレートを重ねたチェーンで、スプロケットと歯車のようにかみ合い、高速で静かに運転できる。","usage_en":"Danh từ đếm được. Hay đi với: inverted-tooth chain, silent chain drive, timing chain; ít ồn hơn roller chain.","usage_ja":"Tên JIS là サイレントチェーン; ghép: サイレントチェーン用スプロケット. Hay dùng làm カムチェーン động cơ.","context_vi":"Dùng ở xích cam động cơ ô tô, hộp số phân phối 4WD, máy công cụ tốc độ cao.","ex_en":"The engine uses a silent chain instead of a timing belt to drive the camshafts.","ex_ja":"このエンジンはカム軸の駆動にタイミングベルトではなくサイレントチェーンを使っている。","ex_vi":"Động cơ này dùng xích răng thay cho đai răng để dẫn động trục cam.","syn_en":["inverted-tooth chain","timing chain (gần nghĩa)"],"syn_ja":["タイミングチェーン (gần nghĩa)","カムチェーン (gần nghĩa)"]},{"en":"elastic creep","pos":"noun phrase","ipa":"/ɪˈlæstɪk kriːp/","ja":"弾性すべり","kana":"だんせいすべり","romaji":"danseisuberi","vi":"trượt đàn hồi (của đai)","level":3,"def_vi":"Sự trượt nhỏ không tránh khỏi của đai trên puly do đai giãn dài khác nhau giữa nhánh căng và nhánh chùng.","def_en":"The small unavoidable slip of a belt on a pulley caused by different stretch in the tight and slack sides.","def_ja":"張り側とゆるみ側でベルトの伸びが異なるために生じる、避けられない小さな滑り。","usage_en":"Danh từ không đếm được, hay gọi belt creep. Hay đi với: creep loss, speed loss due to elastic creep (1–2%); khác với gross slip khi quá tải.","usage_ja":"Tên trong sách là 弾性すべり (cũng viết 弾性滑り); đối lập với 全面すべり (trượt toàn phần). Liên quan すべり率.","context_vi":"Dùng khi giải thích vì sao tỉ số truyền đai không chính xác tuyệt đối, tính sai số tốc độ.","ex_en":"Elastic creep makes the driven pulley turn about 1% slower than the theoretical speed.","ex_ja":"弾性すべりにより、従動プーリは理論値より約1%遅く回る。","ex_vi":"Trượt đàn hồi làm puly bị dẫn quay chậm hơn khoảng 1% so với lý thuyết.","syn_en":["belt creep","gross slip (liên quan)"],"syn_ja":["弾性滑り","すべり率 (liên quan)"]},{"en":"datum diameter","pos":"noun phrase","ipa":"/ˈdeɪtəm daɪˌæmɪtər/","ja":"呼び径","kana":"よびけい","romaji":"yobikei","vi":"đường kính tính toán của puly (đường kính chuẩn)","level":3,"def_vi":"Đường kính chuẩn của puly đai thang tại chiều rộng chuẩn của rãnh, dùng để tính tỉ số truyền và chiều dài đai.","def_en":"The reference diameter of a V-belt pulley at the datum width of the groove, used for ratio and belt length calculations.","def_ja":"Vプーリの溝の基準幅位置における直径で、速比やベルト長さの計算に用いる。","usage_en":"Danh từ đếm được, ký hiệu dd. Hay đi với: minimum datum diameter, datum diameter of the small pulley; còn gọi pitch diameter (đai cổ điển).","usage_ja":"Catalog Vプーリ ghi 呼び径 (dd) hoặc ピッチ径; khác 外径. Hay nói: 最小呼び径, 呼び径から速比を求める.","context_vi":"Dùng khi chọn puly đai thang, tra catalog và tính tỉ số truyền đai.","ex_en":"An SPA belt needs a datum diameter of at least 90 mm on the small pulley.","ex_ja":"SPA形ベルトでは小プーリの呼び径を90 mm以上とする必要がある。","ex_vi":"Đai SPA cần đường kính tính toán của puly nhỏ tối thiểu 90 mm.","syn_en":["pitch diameter (đai cổ điển)","effective diameter (gần nghĩa)"],"syn_ja":["ピッチ径","有効径 (gần nghĩa)"]},{"en":"basic power rating","pos":"noun phrase","ipa":"/ˈbeɪsɪk ˈpaʊər ˌreɪtɪŋ/","ja":"基準伝動容量","kana":"きじゅんでんどうようりょう","romaji":"kijundendouyouryou","vi":"công suất truyền định mức (của một dây đai)","level":3,"def_vi":"Công suất một dây đai hoặc xích truyền được trong điều kiện chuẩn, dùng để tính số dây đai cần thiết.","def_en":"The power one belt or chain can transmit under standard conditions, used to calculate the number of belts required.","def_ja":"標準条件で1本のベルトやチェーンが伝えられる動力で、必要本数の計算に用いる。","usage_en":"Danh từ đếm được. Hay đi với: basic power rating per belt, corrected by wrap-angle and length factors, kW per belt.","usage_ja":"Catalog Nhật ghi 基準伝動容量 (kW/本); hiệu chỉnh bằng 巻掛け角補正係数, 長さ補正係数. Ngoài xưởng nói 伝動容量.","context_vi":"Dùng trong các bước chọn đai, xích theo catalog của Bando, Mitsuboshi, Tsubaki.","ex_en":"With a basic power rating of 3.2 kW per belt, four belts are needed for the 11 kW motor.","ex_ja":"1本当たりの基準伝動容量が3.2 kWなので、11 kWモータには4本必要となる。","ex_vi":"Với công suất truyền định mức 3,2 kW mỗi dây, động cơ 11 kW cần bốn dây đai.","syn_en":["power rating","rated power per belt"],"syn_ja":["伝動容量","補正伝動容量 (liên quan)"]},{"en":"polygonal action","pos":"noun phrase","ipa":"/pəˈlɪɡənl ˈækʃn/","ja":"弦振動","kana":"げんしんどう","romaji":"genshindou","vi":"hiệu ứng đa giác (dao động dây xích)","level":3,"def_vi":"Hiện tượng xích quấn trên đĩa như đa giác, làm vận tốc xích dao động theo chu kỳ, gây rung và ồn.","def_en":"The chain wrapping a sprocket as a polygon, causing cyclic speed fluctuation, vibration and noise.","def_ja":"チェーンがスプロケットに多角形状に巻き付くため速度が周期的に変動し、振動や騒音を生じる現象。","usage_en":"Danh từ không đếm được. Hay đi với: reduce polygonal action by using more sprocket teeth, chordal action; ảnh hưởng mạnh khi đĩa ít răng.","usage_ja":"Sách Nhật gọi 多角形運動 hoặc 弦振動 (chordal action); hay nói: 歯数を増やして速度変動を抑える.","context_vi":"Dùng khi thiết kế bộ truyền xích tốc độ cao, chọn số răng đĩa xích tối thiểu.","ex_en":"A 25-tooth sprocket was chosen to reduce polygonal action at high speed.","ex_ja":"高速時の弦振動を抑えるため、歯数25のスプロケットを選んだ。","ex_vi":"Chọn đĩa xích 25 răng để giảm hiệu ứng đa giác ở tốc độ cao.","syn_en":["chordal action","polygon effect"],"syn_ja":["多角形運動","コーダルアクション"]},{"en":"centrifugal tension","pos":"noun phrase","ipa":"/ˌsentrɪˈfjuːɡl ˈtenʃn/","ja":"遠心張力","kana":"えんしんちょうりょく","romaji":"enshinchouryoku","vi":"lực căng ly tâm","level":3,"def_vi":"Lực căng phụ sinh ra trong dây đai hoặc xích do lực ly tâm khi quấn quanh puly ở tốc độ cao, làm giảm khả năng truyền tải.","def_en":"Additional tension in a belt or chain caused by centrifugal force at high speed, reducing transmittable power.","def_ja":"高速時に遠心力によってベルトやチェーンに生じる付加張力で、伝達可能な動力を減少させる。","usage_en":"Danh từ không đếm được. Hay đi với: Tc = m·v², account for centrifugal tension, maximum belt speed; có trong công thức Euler–Eytelwein mở rộng.","usage_ja":"Tên trong sách là 遠心張力; hay nói: 遠心張力を考慮する, ベルト速度の上限. Ký hiệu Tc.","context_vi":"Dùng khi tính toán bộ truyền đai tốc độ cao và xác định tốc độ đai tối ưu.","ex_en":"At 30 m/s, centrifugal tension takes up a large share of the allowable belt tension.","ex_ja":"30 m/sでは、遠心張力が許容ベルト張力の大きな割合を占める。","ex_vi":"Ở 30 m/s, lực căng ly tâm chiếm phần lớn lực căng cho phép của đai.","syn_en":["centrifugal belt tension"],"syn_ja":["遠心力による張力","有効張力 (liên quan)"]}]},{"id":26,"words":[{"en":"spring","pos":"noun","ipa":"/sprɪŋ/","ja":"ばね","kana":"ばね","romaji":"bane","vi":"lò xo","level":1,"def_vi":"Chi tiết đàn hồi biến dạng khi chịu tải, tích trữ năng lượng và trở lại hình dạng ban đầu khi bỏ tải.","def_en":"An elastic element that deforms under load, stores energy and returns to its original shape when the load is removed.","def_ja":"荷重を受けると変形してエネルギーを蓄え、除荷すると元の形に戻る弾性要素。","usage_en":"Danh từ đếm được. Hay đi với: return spring, spring force, spring-loaded (tính từ); động từ: compress / stretch / preload a spring.","usage_ja":"Viết bằng hiragana ばね trong JIS; ngoài xưởng cũng viết バネ hoặc nói スプリング. Hay đi với: ばねを縮める, ばねで押し付ける, ばね荷重.","context_vi":"Có mặt trong van, công tắc, cơ cấu kẹp, hệ thống treo xe và hầu hết các cơ cấu cần lực hồi vị.","ex_en":"A spring pushes the valve plate back against its seat when the pressure drops.","ex_ja":"圧力が下がると、ばねが弁板を弁座に押し戻す。","ex_vi":"Khi áp suất giảm, lò xo đẩy đĩa van trở lại tì vào đế van.","syn_en":["elastic element (nghĩa rộng hơn)"],"syn_ja":["スプリング","バネ"]},{"en":"coil spring","pos":"noun","ipa":"/ˈkɔɪl sprɪŋ/","ja":"コイルばね","kana":"コイルばね","romaji":"koirubane","vi":"lò xo xoắn ốc (lò xo cuộn)","level":1,"def_vi":"Lò xo làm từ dây kim loại cuộn thành đường xoắn ốc, có thể làm việc ở dạng nén, kéo hoặc xoắn.","def_en":"A spring made of wire wound into a helix, used in compression, extension or torsion.","def_ja":"線材をらせん状に巻いたばね。圧縮・引張・ねじりに用いる。","usage_en":"Danh từ đếm được. Hay dùng làm từ chung trước khi nói rõ loại: helical coil spring, coil spring suspension; Mỹ hay nói helical spring.","usage_ja":"Từ chung cho mọi loại lò xo xoắn ốc; JIS ghép thêm chữ phía trước: 圧縮コイルばね, 引張コイルばね, ねじりコイルばね.","context_vi":"Dùng trong hệ thống treo ô tô, van an toàn, máy dập, đồ gá và thiết bị gia dụng.","ex_en":"The front suspension uses a coil spring around each shock absorber.","ex_ja":"フロントサスペンションでは、各ショックアブソーバの周りにコイルばねを使っている。","ex_vi":"Hệ treo trước dùng một lò xo xoắn ốc bao quanh mỗi giảm chấn.","syn_en":["helical spring"],"syn_ja":["つる巻ばね","コイルスプリング"]},{"en":"compression spring","pos":"noun","ipa":"/kəmˈpreʃn sprɪŋ/","ja":"圧縮コイルばね","kana":"あっしゅくコイルばね","romaji":"asshukukoirubane","vi":"lò xo nén","level":1,"def_vi":"Lò xo xoắn ốc có các vòng cách nhau, chịu tải nén dọc trục và bị ngắn lại khi làm việc.","def_en":"A helical spring with open coils that resists an axial pushing load and becomes shorter under load.","def_ja":"素線間にすきまがあり、軸方向の圧縮荷重を受けて縮むコイルばね。","usage_en":"Danh từ đếm được. Hay đi với: helical compression spring, die spring (lò xo khuôn); động từ: compress, preload, guide a compression spring on a rod.","usage_ja":"JIS gọi 圧縮コイルばね, ngoài xưởng nói gọn 圧縮ばね. Động từ: 圧縮する, たわませる, ガイドピンに通す.","context_vi":"Dùng trong van, khuôn dập, nút bấm, bộ giảm chấn và cơ cấu hồi vị của xi lanh.","ex_en":"Each ejector pin is returned by a compression spring after the mould opens.","ex_ja":"金型が開いた後、各エジェクタピンは圧縮コイルばねで戻される。","ex_vi":"Sau khi khuôn mở, mỗi chốt đẩy được lò xo nén đẩy trở về.","syn_en":["helical compression spring","push spring (khẩu ngữ)"],"syn_ja":["圧縮ばね"]},{"en":"extension spring","pos":"noun","ipa":"/ɪkˈstenʃn sprɪŋ/","ja":"引張コイルばね","kana":"ひっぱりコイルばね","romaji":"hipparikoirubane","vi":"lò xo kéo","level":1,"def_vi":"Lò xo xoắn ốc quấn sít vòng, có móc ở hai đầu, chịu tải kéo dọc trục và dài ra khi làm việc.","def_en":"A close-wound helical spring with hooks or loops at the ends that resists a pulling load.","def_ja":"密着巻きで両端にフックを持ち、引張荷重を受けて伸びるコイルばね。","usage_en":"Danh từ đếm được. Hay đi với: hook, loop, initial tension; động từ: stretch / hook / attach an extension spring. Anh còn gọi tension spring.","usage_ja":"JIS gọi 引張コイルばね, ngoài xưởng nói 引張ばね hoặc 引きばね. Động từ: 引っ掛ける, 伸ばす.","context_vi":"Dùng ở cửa gara, cần gạt, cơ cấu căng đai, bàn đạp và các cơ cấu kéo hồi vị.","ex_en":"Replace the extension spring if its hook shows any crack.","ex_ja":"フックに割れがあれば、引張コイルばねを交換すること。","ex_vi":"Nếu móc có bất kỳ vết nứt nào thì phải thay lò xo kéo.","syn_en":["tension spring"],"syn_ja":["引張ばね","引きばね (khẩu ngữ)"]},{"en":"torsion spring","pos":"noun","ipa":"/ˈtɔːʃn sprɪŋ/","ja":"ねじりコイルばね","kana":"ねじりコイルばね","romaji":"nejirikoirubane","vi":"lò xo xoắn","level":1,"def_vi":"Lò xo xoắn ốc có hai chân, chịu mô men xoắn quanh trục của nó và sinh mô men chống lại góc xoay.","def_en":"A helical spring with two legs that resists a twisting moment about its axis.","def_ja":"両端に腕を持ち、軸まわりのねじりモーメントを受けるコイルばね。","usage_en":"Danh từ đếm được. Hay đi với: leg, torque, angular deflection; động từ: wind / preload a torsion spring. Lưu ý: khác với torsion bar (thanh xoắn).","usage_ja":"JIS gọi ねじりコイルばね; ngoài xưởng nói ねじりばね hoặc トーションスプリング. Hay đi với: 腕 (chân lò xo), 巻き方向.","context_vi":"Dùng ở bản lề tự đóng, kẹp, nắp hộp, chuột bẫy và cơ cấu hồi vị của cần gạt.","ex_en":"A torsion spring at the hinge keeps the cover closed.","ex_ja":"ヒンジ部のねじりコイルばねがカバーを閉じた状態に保つ。","ex_vi":"Một lò xo xoắn ở bản lề giữ cho nắp luôn đóng.","syn_en":["helical torsion spring"],"syn_ja":["ねじりばね","トーションスプリング"]},{"en":"leaf spring","pos":"noun","ipa":"/ˈliːf sprɪŋ/","ja":"板ばね","kana":"いたばね","romaji":"itabane","vi":"nhíp (lò xo lá)","level":1,"def_vi":"Lò xo làm từ một hoặc nhiều lá thép dẹt chồng lên nhau, chịu uốn để đỡ tải.","def_en":"A spring made of one or more flat steel strips that carries load by bending.","def_ja":"一枚または重ねた平たい鋼板の曲げで荷重を支えるばね。","usage_en":"Danh từ đếm được. Hay đi với: multi-leaf spring, leaf spring suspension, spring eye, U-bolt; số nhiều là leaf springs (không phải leaves).","usage_ja":"Loại nhiều lá chồng gọi là 重ね板ばね. Hay đi với: 板ばね式サスペンション, 目玉 (tai nhíp), Uボルト.","context_vi":"Dùng chủ yếu trong hệ treo xe tải, xe khung gầm, toa xe và rơ moóc.","ex_en":"The truck's rear leaf spring cracked at the centre bolt.","ex_ja":"トラックの後輪の板ばねがセンタボルト部で割れた。","ex_vi":"Nhíp sau của xe tải bị nứt tại vị trí bu lông tâm.","syn_en":["laminated spring","semi-elliptic spring"],"syn_ja":["重ね板ばね","リーフスプリング"]},{"en":"spring constant","pos":"noun phrase","ipa":"/ˈsprɪŋ ˌkɒnstənt/","ja":"ばね定数","kana":"ばねていすう","romaji":"baneteisuu","vi":"độ cứng lò xo (hằng số lò xo)","level":1,"def_vi":"Lực cần thiết để làm lò xo biến dạng một đơn vị chiều dài, thường tính bằng N/mm.","def_en":"The force needed to deflect a spring by one unit of length, usually in N/mm.","def_ja":"ばねを単位長さだけたわませるのに必要な荷重。単位はN/mmなど。","usage_en":"Danh từ đếm được, ký hiệu k. Hay đi với: high / low spring constant, calculate the spring constant; trong catalog Mỹ thường ghi spring rate.","usage_ja":"Ký hiệu k, đơn vị N/mm. Hay đi với: ばね定数が高い／低い, ばね定数を求める. Với lò xo xoắn dùng ねじりばね定数 (N·mm/rad).","context_vi":"Dùng khi tính toán, chọn lò xo theo catalog và kiểm tra lò xo trên máy đo lực.","ex_en":"We need a spring constant of about 12 N/mm to reach the required clamping force.","ex_ja":"必要な締付け力を得るには、約12 N/mmのばね定数が必要だ。","ex_vi":"Để đạt lực kẹp yêu cầu, ta cần độ cứng lò xo khoảng 12 N/mm.","syn_en":["spring rate","spring stiffness"],"syn_ja":["ばねレート"]},{"en":"free length","pos":"noun phrase","ipa":"/ˌfriː ˈleŋθ/","ja":"自由長さ","kana":"じゆうながさ","romaji":"jiyuunagasa","vi":"chiều dài tự do","level":1,"def_vi":"Chiều dài của lò xo khi không chịu bất kỳ tải nào.","def_en":"The overall length of a spring when no load is applied.","def_ja":"荷重を加えていない状態でのばねの全長。","usage_en":"Danh từ không đếm được, ký hiệu L0. Hay đi với: measure the free length, free length tolerance; khi lò xo lún sẽ nói free length has decreased.","usage_ja":"Ký hiệu L0 hoặc H0. Ngoài xưởng hay nói gọn 自由長. Hay đi với: 自由長さを測定する, 自由長さ公差.","context_vi":"Ghi trên bản vẽ lò xo, phiếu kiểm tra đầu vào và dùng để phát hiện lò xo bị lún.","ex_en":"The free length of the returned springs was 2 mm shorter than the drawing value.","ex_ja":"返品されたばねの自由長さは図面値より2 mm短かった。","ex_vi":"Chiều dài tự do của các lò xo bị trả về ngắn hơn giá trị trên bản vẽ 2 mm.","syn_en":["unloaded length"],"syn_ja":["自由長","自由高さ"]},{"en":"wire diameter","pos":"noun phrase","ipa":"/ˈwaɪə daɪˌæmɪtə/","ja":"線径","kana":"せんけい","romaji":"senkei","vi":"đường kính dây","level":1,"def_vi":"Đường kính của sợi dây dùng để cuốn lò xo, ảnh hưởng mạnh đến độ cứng và ứng suất.","def_en":"The diameter of the wire from which a spring is wound.","def_ja":"ばねを巻くのに用いる素線の直径。","usage_en":"Danh từ đếm được, ký hiệu d. Hay đi với: increase / reduce the wire diameter, wire diameter tolerance.","usage_ja":"Ký hiệu d; JIS ghi 材料の直径, còn xưởng và catalog nói 線径. Hay đi với: 線径を太くする, 線径φ2.","context_vi":"Dùng khi thiết kế, đặt mua dây thép và kiểm tra lò xo bằng panme.","ex_en":"Increasing the wire diameter from 2.0 to 2.3 mm raised the stiffness by about 75%.","ex_ja":"線径を2.0 mmから2.3 mmに上げたら、剛性が約75%増えた。","ex_vi":"Tăng đường kính dây từ 2,0 lên 2,3 mm làm độ cứng tăng khoảng 75%.","syn_en":["wire size"],"syn_ja":["素線径","材料の直径"]},{"en":"spring steel","pos":"noun","ipa":"/ˈsprɪŋ stiːl/","ja":"ばね鋼","kana":"ばねこう","romaji":"banekou","vi":"thép lò xo","level":1,"def_vi":"Thép cacbon hoặc thép hợp kim có giới hạn đàn hồi cao sau nhiệt luyện, dùng chế tạo lò xo.","def_en":"Carbon or alloy steel with a high elastic limit after heat treatment, used to make springs.","def_ja":"熱処理後に高い弾性限度をもつ、ばね用の炭素鋼または合金鋼。","usage_en":"Danh từ không đếm được. Hay đi với: spring steel strip / wire, hardened spring steel, grades như SUP9, 65Mn.","usage_ja":"JIS ký hiệu SUP (ばね鋼鋼材). Hay đi với: ばね鋼鋼材, ばね鋼の熱処理. Với dây mảnh thường dùng ピアノ線 hoặc 硬鋼線 thay vì nói ばね鋼.","context_vi":"Dùng làm nhíp, lò xo hệ treo, thanh xoắn, kẹp và chi tiết đàn hồi cần chịu mỏi.","ex_en":"The clip is stamped from 0.5 mm spring steel and then hardened.","ex_ja":"このクリップは厚さ0.5 mmのばね鋼から打ち抜いた後、焼入れする。","ex_vi":"Chiếc kẹp được dập từ thép lò xo dày 0,5 mm rồi đem tôi.","syn_en":["SUP steel (theo JIS)"],"syn_ja":["ばね鋼鋼材","SUP材"]},{"en":"disc spring","pos":"noun","ipa":"/ˈdɪsk sprɪŋ/","ja":"皿ばね","kana":"さらばね","romaji":"sarabane","vi":"lò xo đĩa","level":2,"def_vi":"Lò xo hình đĩa côn có lỗ giữa, cho lực lớn với hành trình nhỏ; có thể xếp chồng để thay đổi đặc tính.","def_en":"A conical washer-shaped spring that gives high force over a short stroke and can be stacked.","def_ja":"円すい状の円板形ばね。小さいたわみで大きな荷重が得られ、重ねて使える。","usage_en":"Danh từ đếm được. Hay đi với: disc spring stack, in series / in parallel; Mỹ hay gọi Belleville washer.","usage_ja":"Hay đi với: 皿ばねを重ねる, 直列・並列組合せ. Lưu ý không nhầm với ばね座金 (long đen vênh).","context_vi":"Dùng trong phanh lò xo, khớp ly hợp, đồ gá kẹp thủy lực, bu lông chịu giãn nở nhiệt và van.","ex_en":"Six disc springs stacked in series provide the clamping force for the tool holder.","ex_ja":"直列に重ねた6枚の皿ばねがツールホルダの把持力を生み出す。","ex_vi":"Sáu lò xo đĩa xếp nối tiếp tạo ra lực kẹp cho bầu cặp dao.","syn_en":["Belleville spring","Belleville washer"],"syn_ja":["さらばね","ディスクスプリング"]},{"en":"wave spring","pos":"noun","ipa":"/ˈweɪv sprɪŋ/","ja":"ウェーブスプリング","kana":"ウェーブスプリング","romaji":"weebusupuringu","vi":"lò xo sóng","level":2,"def_vi":"Lò xo làm từ dây dẹt uốn lượn sóng theo vòng tròn, cho lực tương đương lò xo nén nhưng chiều cao nhỏ hơn nhiều.","def_en":"A spring of flat wire formed into waves around a circle, giving compression-spring force in much less height.","def_ja":"平線を円周方向に波形に成形したばね。少ない高さで圧縮ばね並みの荷重が得られる。","usage_en":"Danh từ đếm được. Hay đi với: single-turn / multi-turn wave spring, wave washer; dùng để preload bearings.","usage_ja":"Thường viết katakana. Loại một vòng mỏng hay gọi ウェーブワッシャ. Hay đi với: 予圧用ウェーブスプリング.","context_vi":"Dùng để tạo tải trước cho ổ lăn, trong phớt cơ khí và các cụm cần tiết kiệm chiều dài trục.","ex_en":"A wave spring behind the outer ring preloads the bearing pair.","ex_ja":"外輪の背面に入れたウェーブスプリングで軸受に予圧をかける。","ex_vi":"Một lò xo sóng đặt sau vòng ngoài tạo tải trước cho cặp ổ lăn.","syn_en":["wave washer (loại một vòng)"],"syn_ja":["ウェーブワッシャ","波形ばね"]},{"en":"spiral spring","pos":"noun","ipa":"/ˈspaɪrəl sprɪŋ/","ja":"渦巻きばね","kana":"うずまきばね","romaji":"uzumakibane","vi":"lò xo xoắn phẳng (dây cót)","level":2,"def_vi":"Lò xo làm từ dải thép mỏng cuộn thành hình xoắn ốc phẳng, tích trữ năng lượng khi bị cuộn chặt.","def_en":"A flat strip wound into a plane spiral that stores energy when it is wound tighter.","def_ja":"薄い帯材を平面内でうず巻状に巻き、巻き締めてエネルギーを蓄えるばね。","usage_en":"Danh từ đếm được. Loại dùng làm nguồn động lực còn gọi power spring hoặc clock spring; động từ: wind up a spiral spring.","usage_ja":"JIS viết うず巻ばね; loại dây cót đồng hồ, đồ chơi gọi ぜんまい. Hay đi với: 巻き上げる, ぜんまいばね.","context_vi":"Dùng trong đồng hồ cơ, cuộn dây tự rút, dây an toàn, cuộn ống và đồ chơi lên cót.","ex_en":"The hose reel is rewound by a spiral spring inside the drum.","ex_ja":"ホースリールはドラム内部の渦巻きばねで巻き戻される。","ex_vi":"Cuộn ống được cuộn lại nhờ một lò xo xoắn phẳng bên trong tang.","syn_en":["power spring","clock spring"],"syn_ja":["ぜんまい","うず巻ばね"]},{"en":"conical spring","pos":"noun","ipa":"/ˈkɒnɪkl sprɪŋ/","ja":"円すいコイルばね","kana":"えんすいコイルばね","romaji":"ensuikoirubane","vi":"lò xo côn","level":2,"def_vi":"Lò xo nén có đường kính vòng thay đổi dần từ đầu này sang đầu kia, cho đặc tính phi tuyến và chiều cao nén thấp.","def_en":"A compression spring whose coil diameter changes along its length, giving a progressive rate and low solid height.","def_ja":"コイル径が一端から他端へ変化する圧縮ばね。非線形特性で密着高さが低い。","usage_en":"Danh từ đếm được. Hay đi với: tapered spring, telescoping coils, progressive rate.","usage_ja":"Ngoài xưởng hay nói 円すいばね hoặc テーパばね. Hay đi với: 密着高さを小さくする.","context_vi":"Dùng trong nút bấm, hộp pin, đệm ghế và nơi không gian theo chiều trục bị hạn chế.","ex_en":"A conical spring in the battery holder lets the coils nest inside each other.","ex_ja":"電池ホルダの円すいコイルばねは、素線が互いの内側に入り込むように縮む。","ex_vi":"Lò xo côn trong hộp pin cho phép các vòng lồng vào nhau khi bị nén.","syn_en":["tapered spring"],"syn_ja":["円すいばね","テーパばね"]},{"en":"air spring","pos":"noun","ipa":"/ˈeə sprɪŋ/","ja":"空気ばね","kana":"くうきばね","romaji":"kuukibane","vi":"lò xo khí (bầu hơi, balon hơi)","level":2,"def_vi":"Lò xo dùng khí nén trong một túi cao su có vải gia cường, độ cứng và chiều cao điều chỉnh được bằng áp suất.","def_en":"A spring using pressurised air in a reinforced rubber bellows, whose height and stiffness are set by pressure.","def_ja":"補強ゴム製ベローズ内の圧縮空気を利用するばね。圧力で高さと剛性を調整できる。","usage_en":"Danh từ đếm được. Hay đi với: air spring suspension, rolling-lobe / convoluted air spring; khẩu ngữ gọi air bag.","usage_ja":"Hay đi với: 空気ばね台車, 空気ばね式除振台. Ngoài xưởng hay gọi エアサス (hệ treo) hoặc エアスプリング.","context_vi":"Dùng trong hệ treo xe buýt, xe tải, toa tàu và bàn chống rung cho máy đo chính xác.","ex_en":"The bus kneels by venting the front air spring.","ex_ja":"バスは前側の空気ばねの空気を抜いて車高を下げる。","ex_vi":"Xe buýt hạ thấp đầu xe bằng cách xả khí ở bầu hơi phía trước.","syn_en":["air bellows","air bag (khẩu ngữ)"],"syn_ja":["エアスプリング","エアサス (hệ treo)"]},{"en":"gas spring","pos":"noun","ipa":"/ˈɡæs sprɪŋ/","ja":"ガススプリング","kana":"ガススプリング","romaji":"gasusupuringu","vi":"lò xo khí (ty chống ga)","level":2,"def_vi":"Xi lanh kín chứa khí nitơ áp suất cao, đẩy cần piston ra với lực gần như không đổi theo hành trình.","def_en":"A sealed cylinder of pressurised nitrogen that pushes a rod out with nearly constant force.","def_ja":"高圧窒素ガスを封入したシリンダで、ほぼ一定の力でロッドを押し出すばね。","usage_en":"Danh từ đếm được. Hay đi với: gas spring force, lockable gas spring, mount / replace a gas spring; khẩu ngữ gọi gas strut.","usage_ja":"Ngoài thị trường hay gọi ガスダンパー hoặc ダンパー. Hay đi với: ガススプリングで開閉を補助する.","context_vi":"Dùng ở cốp xe, nắp máy, ghế văn phòng, cửa tủ điện và khuôn dập (gas spring cho khuôn).","ex_en":"Two gas springs hold the machine guard open during tool changes.","ex_ja":"工具交換中は2本のガススプリングが機械の安全カバーを開いた状態に保つ。","ex_vi":"Hai ty chống ga giữ nắp che máy mở trong lúc thay dao.","syn_en":["gas strut","gas lift"],"syn_ja":["ガスダンパー (khẩu ngữ)","ガスばね"]},{"en":"torsion bar","pos":"noun","ipa":"/ˈtɔːʃn bɑː/","ja":"トーションバー","kana":"トーションバー","romaji":"tooshonbaa","vi":"thanh xoắn","level":2,"def_vi":"Thanh thép thẳng được ngàm một đầu và xoắn ở đầu kia, làm việc như lò xo nhờ biến dạng xoắn.","def_en":"A straight steel bar fixed at one end and twisted at the other, acting as a spring in torsion.","def_ja":"一端を固定し他端をねじり、ねじり変形でばねとして働く棒。","usage_en":"Danh từ đếm được. Hay đi với: torsion bar suspension, twist / preload a torsion bar; đừng nhầm với torsion spring (lò xo xoắn dạng cuộn).","usage_ja":"Thường viết katakana; JIS gọi トーションバー hoặc ねじり棒ばね. Hay đi với: トーションバー式サスペンション.","context_vi":"Dùng trong hệ treo xe tăng, xe tải nhẹ, cửa ca-bin và cơ cấu cân bằng nắp nặng.","ex_en":"The tank's road wheels are carried on a torsion bar suspension.","ex_ja":"戦車の転輪はトーションバー式サスペンションで支えられている。","ex_vi":"Các bánh chịu tải của xe tăng được đỡ bằng hệ treo thanh xoắn.","syn_en":["torsion-bar spring"],"syn_ja":["ねじり棒ばね"]},{"en":"solid height","pos":"noun phrase","ipa":"/ˌsɒlɪd ˈhaɪt/","ja":"密着高さ","kana":"みっちゃくたかさ","romaji":"mitchakutakasa","vi":"chiều cao nén khít","level":2,"def_vi":"Chiều dài của lò xo nén khi các vòng dây đã chạm sát nhau, không thể nén thêm.","def_en":"The length of a compression spring when all its coils are pressed into contact.","def_ja":"圧縮ばねの全ての素線が互いに接触したときの高さ。","usage_en":"Danh từ không đếm được, ký hiệu Ls. Hay đi với: compress to solid height, go solid (động từ khẩu ngữ: lò xo bị nén khít), solid stress.","usage_ja":"Ký hiệu Hs. Hay đi với: 密着高さまで圧縮する, 密着する (bị nén khít). Thiết kế thường để dư khoảng hở trước 密着.","context_vi":"Kiểm tra khi thiết kế lò xo nén để tránh lò xo bị nén khít hoặc quá ứng suất trong vận hành.","ex_en":"The design stroke leaves 1.5 mm margin above the solid height.","ex_ja":"設計ストロークでは、密着高さまで1.5 mmの余裕を残している。","ex_vi":"Hành trình thiết kế vẫn để dư 1,5 mm so với chiều cao nén khít.","syn_en":["solid length"],"syn_ja":["密着長さ"]},{"en":"mean coil diameter","pos":"noun phrase","ipa":"/ˌmiːn ˈkɔɪl daɪˌæmɪtə/","ja":"コイル平均径","kana":"コイルへいきんけい","romaji":"koiruheikinkei","vi":"đường kính trung bình của lò xo","level":2,"def_vi":"Trung bình cộng của đường kính ngoài và đường kính trong của vòng lò xo, dùng trong công thức tính lò xo.","def_en":"The average of the outside and inside coil diameters, used in spring design formulas.","def_ja":"コイルの外径と内径の平均値で、ばねの設計計算に用いる。","usage_en":"Danh từ đếm được, ký hiệu D. Hay đi với: outside diameter (OD), inside diameter (ID); công thức D = OD − d.","usage_ja":"Ký hiệu D. Hay đi với: コイル外径, コイル内径; ngoài xưởng hay nói gọn 平均径 hoặc 中心径.","context_vi":"Dùng trong tính toán độ cứng, ứng suất và chỉ số lò xo, cũng như khi kiểm tra kích thước.","ex_en":"The mean coil diameter is the outside diameter minus one wire diameter.","ex_ja":"コイル平均径はコイル外径から線径を引いた値である。","ex_vi":"Đường kính trung bình của lò xo bằng đường kính ngoài trừ đi một đường kính dây.","syn_en":["mean diameter","pitch diameter of the coil"],"syn_ja":["平均径","中心径"]},{"en":"active coils","pos":"noun phrase","ipa":"/ˌæktɪv ˈkɔɪlz/","ja":"有効巻数","kana":"ゆうこうまきすう","romaji":"yuukoumakisuu","vi":"số vòng làm việc","level":2,"def_vi":"Số vòng lò xo thực sự biến dạng và tham gia chịu tải, không tính các vòng tì ở hai đầu.","def_en":"The number of coils that actually deflect under load, excluding inactive end coils.","def_ja":"荷重を受けて実際にたわむ巻数で、座巻を除いたもの。","usage_en":"Cụm danh từ số nhiều, ký hiệu Na hoặc n. Hay đi với: number of active coils, total coils; độ cứng tỉ lệ nghịch với số active coils.","usage_ja":"Ký hiệu Na. Đối lập với 総巻数 (tổng số vòng). Hay đi với: 有効巻数を減らす／増やす.","context_vi":"Dùng khi tính độ cứng lò xo và ghi thông số trên bản vẽ lò xo.","ex_en":"Reducing the active coils from 8 to 6 makes the spring about 33% stiffer.","ex_ja":"有効巻数を8から6に減らすと、ばねは約33%硬くなる。","ex_vi":"Giảm số vòng làm việc từ 8 xuống 6 làm lò xo cứng hơn khoảng 33%.","syn_en":["number of active coils","working coils"],"syn_ja":["有効巻き数"]},{"en":"end coil","pos":"noun","ipa":"/ˈend kɔɪl/","ja":"座巻","kana":"ざまき","romaji":"zamaki","vi":"vòng tì (vòng đầu lò xo)","level":2,"def_vi":"Vòng ở mỗi đầu lò xo nén được quấn sít và thường mài phẳng để tì lên mặt đỡ, không tham gia biến dạng.","def_en":"A closed coil at each end of a compression spring that seats on the mating surface and does not deflect.","def_ja":"圧縮ばねの両端で座面に接する、たわみに寄与しない巻部分。","usage_en":"Danh từ đếm được. Hay đi với: closed and ground end coils, squared ends; còn gọi inactive coil, dead coil.","usage_ja":"Hay đi với: 座巻部, 座研削 (mài vòng tì), クローズドエンド. 総巻数 = 有効巻数 + 座巻数.","context_vi":"Dùng khi đặt hàng và kiểm tra lò xo nén để đảm bảo lò xo đứng thẳng, tải phân bố đều.","ex_en":"Both end coils are closed and ground so that the spring stands square.","ex_ja":"ばねが直角に立つよう、両端の座巻は密着させて研削してある。","ex_vi":"Cả hai vòng tì đều được quấn sít và mài phẳng để lò xo đứng vuông góc.","syn_en":["inactive coil","dead coil"],"syn_ja":["座巻き","座巻部"]},{"en":"spring index","pos":"noun phrase","ipa":"/ˈsprɪŋ ˌɪndeks/","ja":"ばね指数","kana":"ばねしすう","romaji":"baneshisuu","vi":"chỉ số lò xo","level":2,"def_vi":"Tỉ số giữa đường kính trung bình của vòng lò xo và đường kính dây, phản ánh mức độ dễ cuốn và tập trung ứng suất.","def_en":"The ratio of mean coil diameter to wire diameter, C = D/d.","def_ja":"コイル平均径と線径の比 (c = D/d)。","usage_en":"Danh từ đếm được, ký hiệu C. Hay đi với: low / high spring index; thường nên nằm khoảng 4 đến 12.","usage_ja":"Ký hiệu c. Hay đi với: ばね指数が小さいと加工が難しい, ばね指数は4〜15を推奨.","context_vi":"Dùng khi thiết kế lò xo để đánh giá khả năng chế tạo và hệ số hiệu chỉnh ứng suất.","ex_en":"A spring index below 4 makes the spring difficult to coil.","ex_ja":"ばね指数が4未満だと、コイリングが難しくなる。","ex_vi":"Chỉ số lò xo nhỏ hơn 4 làm lò xo khó cuốn.","syn_en":["coil ratio (ít dùng)"],"syn_ja":["ばね指数c (ký hiệu)"]},{"en":"initial tension","pos":"noun phrase","ipa":"/ɪˌnɪʃl ˈtenʃn/","ja":"初張力","kana":"しょちょうりょく","romaji":"shochouryoku","vi":"lực căng ban đầu","level":2,"def_vi":"Lực ép sẵn giữa các vòng của lò xo kéo do quấn sít, phải vượt qua lực này lò xo mới bắt đầu giãn.","def_en":"The built-in force holding the coils of an extension spring together, which must be overcome before it extends.","def_ja":"引張ばねの密着巻きにより素線間に生じている力。これを超えると伸び始める。","usage_en":"Danh từ không đếm được. Hay đi với: high / low initial tension, overcome the initial tension; chỉ dùng cho extension spring.","usage_ja":"Hay đi với: 初張力を付ける, 初張力を超える荷重. Chỉ dùng cho 引張コイルばね.","context_vi":"Ghi trên bản vẽ lò xo kéo và kiểm tra trên máy đo lực khi nghiệm thu.","ex_en":"The spring does not stretch until the load exceeds its initial tension of 5 N.","ex_ja":"荷重が初張力5 Nを超えるまで、このばねは伸びない。","ex_vi":"Lò xo không giãn ra cho đến khi tải vượt quá lực căng ban đầu 5 N.","syn_en":["preload (nghĩa rộng hơn)"],"syn_ja":["イニシャルテンション"]},{"en":"permanent set","pos":"noun phrase","ipa":"/ˌpɜːmənənt ˈset/","ja":"へたり","kana":"へたり","romaji":"hetari","vi":"lún lò xo (biến dạng dư, mất đàn hồi)","level":2,"def_vi":"Hiện tượng lò xo bị ngắn đi hoặc giảm lực vĩnh viễn sau thời gian chịu tải hoặc nhiệt độ cao.","def_en":"A permanent loss of length or load in a spring after loading or exposure to heat.","def_ja":"荷重や高温を受けた後、ばねの長さや荷重が永久に減少する現象。","usage_en":"Danh từ không đếm được. Hay đi với: take a set, set loss, resistance to set; khẩu ngữ: the spring has sagged.","usage_ja":"Từ khẩu ngữ nhưng JIS cũng dùng. Hay đi với: へたりが生じる, ばねがへたる (động từ), へたり試験.","context_vi":"Dùng khi phân tích lò xo van, nhíp, lò xo ly hợp bị yếu dần trong quá trình sử dụng.","ex_en":"The valve springs showed 4% permanent set after 500 hours at 150 °C.","ex_ja":"150 °Cで500時間使用後、弁ばねに4%のへたりが見られた。","ex_vi":"Sau 500 giờ ở 150 °C, lò xo xú páp bị lún 4%.","syn_en":["set","relaxation (khi giữ biến dạng cố định)"],"syn_ja":["永久変形","リラクセーション (liên quan)"]},{"en":"piano wire","pos":"noun","ipa":"/piˈænəʊ waɪə/","ja":"ピアノ線","kana":"ピアノせん","romaji":"pianosen","vi":"dây thép lò xo (dây piano)","level":2,"def_vi":"Dây thép cacbon cao, kéo nguội, có độ bền kéo rất cao, dùng làm lò xo chất lượng cao.","def_en":"High-carbon, cold-drawn steel wire of very high tensile strength used for quality springs.","def_ja":"高炭素鋼を冷間引抜きした、引張強さが非常に高いばね用鋼線。","usage_en":"Danh từ không đếm được. Mỹ gọi music wire (ASTM A228). Hay đi với: piano wire spring, SWP-A / SWP-B grades.","usage_ja":"JIS G3522 ký hiệu SWP. Hay đi với: ピアノ線製のばね, SWP-B. Ngoài xưởng hay nói tắt ピアノ.","context_vi":"Dùng làm lò xo nhỏ chịu mỏi cao trong thiết bị chính xác, van, máy đo và đồ dùng.","ex_en":"The small return springs are wound from 0.8 mm piano wire.","ex_ja":"小さな戻しばねは0.8 mmのピアノ線で巻いている。","ex_vi":"Các lò xo hồi vị nhỏ được cuốn từ dây thép piano 0,8 mm.","syn_en":["music wire (Mỹ)"],"syn_ja":["SWP"]},{"en":"Wahl correction factor","pos":"noun phrase","ipa":"/ˌwɑːl kəˈrekʃn ˌfæktə/","ja":"応力修正係数","kana":"おうりょくしゅうせいけいすう","romaji":"ouryokushuuseikeisuu","vi":"hệ số hiệu chỉnh ứng suất Wahl","level":3,"def_vi":"Hệ số nhân với ứng suất xoắn danh nghĩa để kể đến độ cong của vòng dây và lực cắt trực tiếp trong lò xo xoắn ốc.","def_en":"A factor applied to nominal torsional stress to account for coil curvature and direct shear in helical springs.","def_ja":"コイルの曲率と直接せん断の影響を考慮して、ねじり応力に掛ける係数。","usage_en":"Danh từ đếm được, ký hiệu K hoặc Kw; viết hoa Wahl (tên riêng). Hay đi với: apply the Wahl correction factor, K = (4C−1)/(4C−4) + 0.615/C.","usage_ja":"Ký hiệu κ; còn gọi ワールの応力修正係数. Hay đi với: 応力修正係数を掛ける, 修正応力.","context_vi":"Dùng trong tính toán ứng suất và kiểm tra bền mỏi lò xo theo JIS B2704 hoặc sách thiết kế chi tiết máy.","ex_en":"With C = 6, the Wahl correction factor raises the calculated stress by about 25%.","ex_ja":"c = 6のとき、応力修正係数によって計算応力は約25%大きくなる。","ex_vi":"Với C = 6, hệ số hiệu chỉnh ứng suất Wahl làm ứng suất tính toán tăng khoảng 25%.","syn_en":["stress correction factor","Wahl factor"],"syn_ja":["ワールの修正係数"]},{"en":"spring surge","pos":"noun phrase","ipa":"/ˈsprɪŋ sɜːdʒ/","ja":"サージング","kana":"サージング","romaji":"saajingu","vi":"cộng hưởng sóng lò xo (hiện tượng surge)","level":3,"def_vi":"Hiện tượng sóng dao động lan dọc các vòng lò xo khi tần số kích thích gần tần số riêng, làm tăng mạnh ứng suất.","def_en":"Resonant waves travelling along the coils when excitation approaches the spring's natural frequency.","def_ja":"加振周波数がばねの固有振動数に近づき、素線に沿って振動波が伝わる共振現象。","usage_en":"Danh từ không đếm được. Hay đi với: avoid / suppress spring surge, surge frequency; thường gặp với valve springs.","usage_ja":"Thường viết katakana. Hay đi với: サージングを防ぐ, サージング対策, 不等ピッチばねで抑える.","context_vi":"Dùng khi thiết kế lò xo xú páp động cơ tốc độ cao và lò xo làm việc với tải dao động.","ex_en":"Spring surge at 6,500 rpm caused the valve to float.","ex_ja":"6,500 rpmでサージングが発生し、バルブが浮き上がった。","ex_vi":"Hiện tượng cộng hưởng sóng lò xo ở 6.500 vòng/phút làm xú páp bị bập bênh không đóng kịp.","syn_en":["coil surge"],"syn_ja":["ばねの共振 (liên quan)"]},{"en":"presetting","pos":"noun","ipa":"/ˌpriːˈsetɪŋ/","ja":"セッチング","kana":"セッチング","romaji":"setchingu","vi":"nén ép trước (khử lún lò xo)","level":3,"def_vi":"Nguyên công nén lò xo vượt quá tải làm việc trong sản xuất để lò xo lún trước, giảm lún trong sử dụng.","def_en":"Compressing a spring beyond its working load during manufacture so that it takes its set before service.","def_ja":"製造時に使用荷重以上に圧縮して先にへたらせ、使用中のへたりを減らす工程。","usage_en":"Danh từ không đếm được. Hay đi với: hot presetting, presetting operation; còn nói set removal, scragging (Anh).","usage_ja":"Hay đi với: セッチングを施す, ホットセッチング (ở nhiệt độ cao). Thường làm sau ショットピーニング.","context_vi":"Dùng trong quy trình sản xuất lò xo hệ treo, lò xo van và lò xo chịu tải cao.","ex_en":"Presetting at 150 °C reduced the set loss in service to below 1%.","ex_ja":"150 °Cでのセッチングにより、使用中のへたりを1%未満に抑えた。","ex_vi":"Nén ép trước ở 150 °C giúp giảm độ lún trong vận hành xuống dưới 1%.","syn_en":["set removal","scragging (Anh)"],"syn_ja":["ホットセッチング (một dạng)","プリセッチング"]},{"en":"oil-tempered wire","pos":"noun","ipa":"/ˌɔɪl ˈtempəd waɪə/","ja":"オイルテンパー線","kana":"オイルテンパーせん","romaji":"oirutenpaasen","vi":"dây thép tôi dầu ram","level":3,"def_vi":"Dây thép lò xo được tôi trong dầu và ram liên tục trước khi cuốn, có độ bền và khả năng chống lún tốt.","def_en":"Spring wire that is continuously oil-quenched and tempered before coiling.","def_ja":"コイリング前に連続的に油焼入れ・焼戻しを施したばね用鋼線。","usage_en":"Danh từ không đếm được. Hay đi với: oil-tempered chrome-silicon wire, valve spring quality (VSQ); viết tắt OT wire.","usage_ja":"JIS G3560/3561, ký hiệu SWO, SWOSC-V... Hay đi với: 弁ばね用オイルテンパー線, OT線.","context_vi":"Dùng làm lò xo xú páp, lò xo hệ treo và lò xo công nghiệp chịu ứng suất cao.","ex_en":"Valve springs are coiled from oil-tempered wire of Si-Cr steel.","ex_ja":"弁ばねはSi-Cr鋼のオイルテンパー線から巻かれる。","ex_vi":"Lò xo xú páp được cuốn từ dây thép Si-Cr tôi dầu ram.","syn_en":["OT wire"],"syn_ja":["OT線","SWO"]},{"en":"variable-pitch spring","pos":"noun","ipa":"/ˌveəriəbl ˈpɪtʃ sprɪŋ/","ja":"不等ピッチばね","kana":"ふとうピッチばね","romaji":"futoupitchibane","vi":"lò xo bước thay đổi","level":3,"def_vi":"Lò xo nén có bước vòng không đều nên các vòng chạm nhau dần, tạo đặc tính lực tăng dần và giảm cộng hưởng.","def_en":"A compression spring with unequal coil pitch, giving a progressive rate and reduced surge.","def_ja":"ピッチを不均一にした圧縮ばね。非線形特性をもち、サージングを抑える。","usage_en":"Danh từ đếm được. Hay đi với: progressive rate, dual-rate spring; dùng để suppress surge.","usage_ja":"Hay đi với: 不等ピッチコイルばね, サージング防止. Trên bản vẽ ghi rõ vùng ピッチ.","context_vi":"Dùng trong lò xo xú páp, lò xo hệ treo xe máy và nơi cần đặc tính lực phi tuyến.","ex_en":"A variable-pitch spring was adopted to suppress surge in the high-speed engine.","ex_ja":"高回転エンジンのサージングを抑えるため、不等ピッチばねを採用した。","ex_vi":"Một lò xo bước thay đổi đã được áp dụng để triệt cộng hưởng trong động cơ tốc độ cao.","syn_en":["progressive-rate spring","dual-rate spring (một dạng)"],"syn_ja":["不等ピッチコイルばね"]}]},{"id":27,"words":[{"en":"seal","pos":"noun","ipa":"/siːl/","ja":"シール","kana":"シール","romaji":"shiiru","vi":"phớt (chi tiết làm kín)","level":1,"def_vi":"Chi tiết hoặc cụm chi tiết ngăn chất lỏng, khí hoặc bụi rò qua khe hở giữa các bộ phận.","def_en":"A component that prevents fluid, gas or dirt from passing through a gap between parts.","def_ja":"部品間のすきまから流体や異物が漏れたり侵入したりするのを防ぐ部品。","usage_en":"Danh từ đếm được; cũng là động từ (to seal = làm kín). Hay đi với: shaft seal, rod seal, seal kit; động từ: replace / install a seal, the seal is leaking.","usage_ja":"Hay đi với: シールする, シール性 (khả năng làm kín), シール交換. Theo JIS chia ra パッキン (chuyển động) và ガスケット (tĩnh).","context_vi":"Có mặt trong bơm, xi lanh thủy lực, hộp số, van, động cơ và mọi chỗ cần ngăn rò rỉ.","ex_en":"The cylinder leaks because the rod seal is worn.","ex_ja":"ロッドのシールが摩耗しているため、シリンダから油が漏れている。","ex_vi":"Xi lanh bị rò dầu vì phớt cần đã mòn.","syn_en":["sealing element"],"syn_ja":["密封装置","シール材 (nghĩa rộng hơn)"]},{"en":"gasket","pos":"noun","ipa":"/ˈɡæskɪt/","ja":"ガスケット","kana":"ガスケット","romaji":"gasuketto","vi":"gioăng (đệm làm kín)","level":1,"def_vi":"Tấm đệm mềm hoặc kim loại kẹp giữa hai bề mặt cố định, như mặt bích, để làm kín mối ghép.","def_en":"A sheet or ring compressed between two stationary surfaces, such as flanges, to seal the joint.","def_ja":"フランジなど静止した二つの面の間に挟んで締め付け、密封する部品。","usage_en":"Danh từ đếm được. Hay đi với: flange gasket, head gasket, gasket material; động từ: fit / replace / compress a gasket, blow a gasket (hỏng gioăng).","usage_ja":"Hay đi với: ガスケットを挟む, 締め付ける, 交換する. Ngoài xưởng hay nói chung chung パッキン cho cả gioăng tĩnh.","context_vi":"Dùng ở mặt bích đường ống, nắp máy, nắp hộp số, nắp bình áp lực và mặt ghép bơm.","ex_en":"Always fit a new gasket when you reassemble the pump flange.","ex_ja":"ポンプのフランジを組み直すときは、必ず新しいガスケットを入れること。","ex_vi":"Khi lắp lại mặt bích bơm, luôn phải dùng gioăng mới.","syn_en":["static seal (nghĩa rộng hơn)"],"syn_ja":["パッキン (khẩu ngữ)"]},{"en":"O-ring","pos":"noun","ipa":"/ˈəʊ rɪŋ/","ja":"Oリング","kana":"オーリング","romaji":"ooringu","vi":"gioăng chữ O (vòng O, oring)","level":1,"def_vi":"Vòng cao su tiết diện tròn, lắp trong rãnh và bị ép biến dạng để làm kín tĩnh hoặc chuyển động.","def_en":"A rubber ring of circular cross-section fitted in a groove and squeezed to seal.","def_ja":"断面が円形のゴム製リング。溝に装着しつぶして密封する。","usage_en":"Danh từ đếm được, viết O-ring (chữ O hoa). Hay đi với: O-ring groove, O-ring size, cross-section; động từ: lubricate / install an O-ring.","usage_ja":"Viết Oリング, đọc オーリング. Kích thước theo JIS B2401 (P, G, V, S). Hay đi với: Oリングを装着する, Oリングがかみ込む.","context_vi":"Dùng ở đầu nối thủy lực, nắp xi lanh, van, khớp nối nhanh và hầu hết thiết bị chứa chất lỏng.","ex_en":"Apply grease to the O-ring before inserting the plug.","ex_ja":"プラグを差し込む前にOリングにグリースを塗る。","ex_vi":"Bôi mỡ lên gioăng chữ O trước khi lắp nút vào.","syn_en":["toric joint (ít dùng)"],"syn_ja":["オーリング"]},{"en":"oil seal","pos":"noun","ipa":"/ˈɔɪl siːl/","ja":"オイルシール","kana":"オイルシール","romaji":"oirushiiru","vi":"phớt chặn dầu","level":1,"def_vi":"Phớt có môi cao su và vỏ kim loại, lắp quanh trục quay để giữ dầu bên trong và ngăn bụi lọt vào.","def_en":"A lip seal with a metal case fitted around a rotating shaft to keep oil in and dirt out.","def_ja":"金属環とゴムリップをもち、回転軸の油漏れと異物侵入を防ぐシール。","usage_en":"Danh từ đếm được. Hay đi với: oil seal size (ví dụ 30×47×7), double-lip oil seal; động từ: press in / drive in an oil seal. Mỹ hay gọi radial shaft seal.","usage_ja":"Kích thước theo JIS B2402. Hay đi với: オイルシールを圧入する, オイルシールのリップ. Ngoài xưởng hay gọi tên hãng như NOK.","context_vi":"Dùng ở đầu trục hộp số, động cơ điện, bơm, cầu xe và hộp giảm tốc.","ex_en":"Oil was leaking past the output shaft oil seal of the gearbox.","ex_ja":"減速機の出力軸のオイルシールから油が漏れていた。","ex_vi":"Dầu bị rò qua phớt chặn dầu ở trục ra của hộp giảm tốc.","syn_en":["radial shaft seal","rotary shaft seal"],"syn_ja":["回転軸用リップシール"]},{"en":"packing","pos":"noun","ipa":"/ˈpækɪŋ/","ja":"パッキン","kana":"パッキン","romaji":"pakkin","vi":"phớt làm kín động (packing)","level":1,"def_vi":"Chi tiết làm kín cho bộ phận chuyển động như cần piston, trục van hoặc trục bơm.","def_en":"A seal for moving parts such as piston rods, valve stems or pump shafts.","def_ja":"ピストンロッドや弁棒、ポンプ軸など運動する部分を密封する部品。","usage_en":"Danh từ thường không đếm được (packing material) hoặc đếm được khi chỉ từng vòng (packing rings). Hay đi với: valve stem packing, pump packing; động từ: repack, tighten the packing.","usage_ja":"JIS dùng パッキン cho làm kín chuyển động. Ngoài xưởng nói パッキン cho gần như mọi loại gioăng/phớt, kể cả vòi nước.","context_vi":"Dùng ở trục van, bơm piston, xi lanh thủy lực và khí nén.","ex_en":"The packing on the valve stem was tightened to stop the weeping.","ex_ja":"弁棒からのにじみを止めるため、パッキンを増し締めした。","ex_vi":"Phớt làm kín ở trục van đã được siết thêm để hết rịn.","syn_en":["dynamic seal (nghĩa rộng hơn)"],"syn_ja":["運動用シール"]},{"en":"leakage","pos":"noun","ipa":"/ˈliːkɪdʒ/","ja":"漏れ","kana":"もれ","romaji":"more","vi":"sự rò rỉ","level":1,"def_vi":"Sự thoát ra không mong muốn của chất lỏng hoặc khí qua chỗ làm kín hoặc khe hở.","def_en":"The unwanted escape of fluid or gas through a seal or gap.","def_ja":"シール部やすきまから流体が意図せず外へ出ること。","usage_en":"Danh từ không đếm được; động từ là leak. Hay đi với: oil leakage, leakage rate, external / internal leakage; mức nhẹ dùng weep, seep.","usage_ja":"Hay đi với: 漏れが発生する, 油漏れ, 漏れ量, 外部漏れ／内部漏れ. Mức nhẹ hay nói にじみ.","context_vi":"Dùng trong báo cáo bảo trì, kiểm tra áp lực, đánh giá phớt và gioăng.","ex_en":"No leakage was observed during the 30-minute pressure test.","ex_ja":"30分間の耐圧試験で漏れは確認されなかった。","ex_vi":"Không phát hiện rò rỉ trong 30 phút thử áp.","syn_en":["leak","seepage (mức nhẹ)"],"syn_ja":["リーク","にじみ (mức nhẹ)"]},{"en":"thread seal tape","pos":"noun","ipa":"/ˈθred siːl teɪp/","ja":"シールテープ","kana":"シールテープ","romaji":"shiiruteepu","vi":"băng tan (cao su non)","level":1,"def_vi":"Băng mỏng bằng PTFE quấn quanh ren ống để làm kín và bôi trơn khi vặn.","def_en":"Thin PTFE tape wrapped around pipe threads to seal and lubricate them.","def_ja":"管用ねじに巻いて密封と潤滑を行うPTFE製の薄いテープ。","usage_en":"Danh từ không đếm được. Hay đi với: wrap / apply thread seal tape, two turns of tape; khẩu ngữ gọi PTFE tape hoặc Teflon tape.","usage_ja":"Hay đi với: シールテープを巻く, 巻き数. Ở Việt Nam gọi băng tan hoặc cao su non.","context_vi":"Dùng khi lắp đầu nối ren côn trên đường ống nước, khí nén và dầu áp thấp.","ex_en":"Wrap thread seal tape clockwise on the male thread before assembly.","ex_ja":"組立前におねじにシールテープを時計回りに巻く。","ex_vi":"Quấn băng tan theo chiều kim đồng hồ lên ren ngoài trước khi lắp.","syn_en":["PTFE tape","Teflon tape (khẩu ngữ)"],"syn_ja":["テフロンテープ (khẩu ngữ)"]},{"en":"dust seal","pos":"noun","ipa":"/ˈdʌst siːl/","ja":"ダストシール","kana":"ダストシール","romaji":"dasutoshiiru","vi":"phớt chắn bụi","level":1,"def_vi":"Phớt lắp ở đầu ngoài xi lanh để gạt bụi, bùn bám trên cần piston khi cần thụt vào.","def_en":"A seal at the outer end of a cylinder that wipes dirt off the rod as it retracts.","def_ja":"シリンダの外側端に付け、ロッドが戻るときに付着した異物をかき落とすシール。","usage_en":"Danh từ đếm được. Hay đi với: rod wiper, scraper; câu thường gặp: the dust seal wipes the rod.","usage_ja":"Hay đi với: ダストシールでかき落とす, ダストワイパ. Đặt ngoài cùng, trước ロッドパッキン.","context_vi":"Dùng trên xi lanh thủy lực máy xúc, máy ép và xi lanh khí nén làm việc ở môi trường bụi.","ex_en":"A torn dust seal let grit into the cylinder and scored the rod.","ex_ja":"ダストシールが破れて砂が入り、ロッドに傷が付いた。","ex_vi":"Phớt chắn bụi bị rách làm cát lọt vào xi lanh và cào xước cần.","syn_en":["wiper seal","scraper"],"syn_ja":["ダストワイパ","スクレーパ"]},{"en":"O-ring groove","pos":"noun phrase","ipa":"/ˈəʊ rɪŋ ɡruːv/","ja":"Oリング溝","kana":"オーリングみぞ","romaji":"ooringumizo","vi":"rãnh lắp gioăng O","level":1,"def_vi":"Rãnh gia công trên chi tiết để chứa gioăng chữ O, kích thước quyết định độ ép và khả năng làm kín.","def_en":"A machined groove that holds an O-ring and sets how much it is squeezed.","def_ja":"Oリングを収め、つぶし量を決めるために加工した溝。","usage_en":"Danh từ đếm được. Hay đi với: groove depth, groove width, gland; động từ: machine / cut an O-ring groove.","usage_ja":"Kích thước tra theo JIS B2401. Hay đi với: 溝深さ, 溝幅, 溝の面粗さ. Trên bản vẽ ghi rõ 溝の公差.","context_vi":"Dùng khi thiết kế và gia công nắp, piston, đầu nối thủy lực và khí nén.","ex_en":"The O-ring groove was cut too shallow, so the ring was over-compressed.","ex_ja":"Oリング溝が浅すぎたため、リングがつぶれ過ぎていた。","ex_vi":"Rãnh lắp gioăng O bị cắt quá nông nên gioăng bị ép quá mức.","syn_en":["O-ring gland"],"syn_ja":["Oリング用溝","グランド (liên quan)"]},{"en":"sealing surface","pos":"noun phrase","ipa":"/ˈsiːlɪŋ ˌsɜːfɪs/","ja":"シール面","kana":"シールめん","romaji":"shiirumen","vi":"bề mặt làm kín","level":1,"def_vi":"Bề mặt tiếp xúc với phớt hoặc gioăng, cần độ nhám và độ phẳng phù hợp để không rò.","def_en":"The surface that a seal or gasket contacts, which needs suitable finish and flatness.","def_ja":"シールやガスケットが接する面で、適切な粗さと平面度が必要。","usage_en":"Danh từ đếm được. Hay đi với: damaged sealing surface, sealing surface finish (Ra); động từ: protect / clean the sealing surface.","usage_ja":"Hay đi với: シール面に傷を付けない, シール面の面粗さ, シール面を清掃する. Với mặt bích gọi ガスケット座.","context_vi":"Dùng khi kiểm tra trục, mặt bích, nắp máy trước khi lắp phớt hoặc gioăng.","ex_en":"A scratch across the sealing surface can cause leakage even with a new gasket.","ex_ja":"シール面に横傷があると、新しいガスケットでも漏れることがある。","ex_vi":"Một vết xước cắt ngang bề mặt làm kín có thể gây rò ngay cả khi dùng gioăng mới.","syn_en":["seal face","seating surface"],"syn_ja":["シール座面","ガスケット座 (mặt bích)"]},{"en":"mechanical seal","pos":"noun","ipa":"/məˈkænɪkl siːl/","ja":"メカニカルシール","kana":"メカニカルシール","romaji":"mekanikarushiiru","vi":"phớt cơ khí","level":2,"def_vi":"Phớt cho trục quay gồm một vòng quay và một vòng tĩnh được lò xo ép sát mặt vào nhau để làm kín.","def_en":"A shaft seal in which a rotating ring and a stationary ring are pressed together face to face by springs.","def_ja":"回転環と固定環の端面をばねで押し付けて密封する回転軸用シール。","usage_en":"Danh từ đếm được. Hay đi với: single / double mechanical seal, cartridge mechanical seal, seal faces; động từ: install / replace a mechanical seal.","usage_ja":"Ngoài xưởng nói tắt メカシール. Hay đi với: メカニカルシールの摺動面, ダブルメカニカルシール.","context_vi":"Dùng trong bơm ly tâm, máy khuấy, máy nén và thiết bị hóa chất.","ex_en":"The pump's mechanical seal failed after running dry for a few minutes.","ex_ja":"ポンプのメカニカルシールは数分間の空運転で損傷した。","ex_vi":"Phớt cơ khí của bơm bị hỏng sau vài phút chạy khô.","syn_en":["face seal","end-face seal"],"syn_ja":["メカシール (khẩu ngữ)","端面シール"]},{"en":"gland packing","pos":"noun","ipa":"/ˈɡlænd ˌpækɪŋ/","ja":"グランドパッキン","kana":"グランドパッキン","romaji":"gurandopakkin","vi":"tết chèn (dây chèn làm kín)","level":2,"def_vi":"Dây bện mềm cắt thành vòng, nhồi vào hộp làm kín quanh trục bơm hoặc trục van rồi ép bằng nắp chèn.","def_en":"Braided rings packed into a stuffing box around a pump or valve shaft and compressed by a gland.","def_ja":"編組パッキンをスタフィングボックスに詰め、グランドで押さえて軸を密封するもの。","usage_en":"Danh từ không đếm được (hoặc packing rings đếm được). Hay đi với: stuffing box, gland follower, lantern ring; động từ: repack, adjust the gland.","usage_ja":"Hay đi với: グランドパッキンを詰める, 増し締め, 適度な漏れを許容する. Còn gọi 編組パッキン.","context_vi":"Dùng trong bơm nước, bơm bùn, van công nghiệp và máy cũ trong nhà máy.","ex_en":"Gland packing must be allowed to drip slightly to cool the shaft sleeve.","ex_ja":"グランドパッキンは、軸スリーブを冷やすため少量の漏れを許容する必要がある。","ex_vi":"Tết chèn phải được cho phép rỉ nhẹ để làm mát ống lót trục.","syn_en":["compression packing","braided packing"],"syn_ja":["編組パッキン","軸封パッキン"]},{"en":"backup ring","pos":"noun","ipa":"/ˈbækʌp rɪŋ/","ja":"バックアップリング","kana":"バックアップリング","romaji":"bakkuappuringu","vi":"vòng chống đùn (vòng đỡ gioăng)","level":2,"def_vi":"Vòng cứng, thường bằng PTFE hoặc nylon, đặt cạnh gioăng chữ O để ngăn gioăng bị đùn vào khe hở khi áp suất cao.","def_en":"A stiff ring placed beside an O-ring to stop it extruding into the clearance gap at high pressure.","def_ja":"高圧時にOリングがすきまへはみ出すのを防ぐため、横に入れる硬いリング。","usage_en":"Danh từ đếm được. Hay đi với: PTFE backup ring, spiral / solid backup ring; đặt on the low-pressure side.","usage_ja":"Hay đi với: バックアップリングを併用する, 低圧側に入れる, はみ出し防止. Tiếng Anh cũng viết back-up ring.","context_vi":"Dùng trong xi lanh, van và đầu nối thủy lực có áp suất trên khoảng 10 MPa.","ex_en":"At 25 MPa a backup ring is required on the low-pressure side of the O-ring.","ex_ja":"25 MPaでは、Oリングの低圧側にバックアップリングが必要だ。","ex_vi":"Ở 25 MPa cần lắp vòng chống đùn ở phía áp thấp của gioăng chữ O.","syn_en":["anti-extrusion ring"],"syn_ja":["はみ出し防止リング"]},{"en":"U-cup seal","pos":"noun","ipa":"/ˈjuː kʌp siːl/","ja":"Uパッキン","kana":"ユーパッキン","romaji":"yuupakkin","vi":"phớt chữ U","level":2,"def_vi":"Phớt có tiết diện hình chữ U, hai môi được áp suất ép vào bề mặt, dùng cho cần và piston xi lanh.","def_en":"A seal with a U-shaped cross-section whose lips are pressed outward by fluid pressure.","def_ja":"断面がU字形で、圧力によりリップが相手面に押し付けられるパッキン。","usage_en":"Danh từ đếm được. Hay đi với: rod U-cup, piston U-cup; lưu ý lắp đúng chiều: lips facing the pressure.","usage_ja":"Hay đi với: Uパッキンの向き, リップを圧力側に向ける. Thuộc nhóm リップパッキン.","context_vi":"Dùng trong xi lanh thủy lực, khí nén và bơm piston.","ex_en":"The U-cup seal was installed backwards, so the cylinder leaked at the first stroke.","ex_ja":"Uパッキンを逆向きに組んだため、最初のストロークでシリンダが漏れた。","ex_vi":"Phớt chữ U bị lắp ngược nên xi lanh rò ngay hành trình đầu tiên.","syn_en":["U-seal","U-packing"],"syn_ja":["リップパッキン (nghĩa rộng hơn)"]},{"en":"squeeze","pos":"noun","ipa":"/skwiːz/","ja":"つぶし代","kana":"つぶししろ","romaji":"tsubushishiro","vi":"độ ép (lượng nén của gioăng)","level":2,"def_vi":"Lượng gioăng hoặc vòng O bị nén biến dạng khi lắp, thường tính theo phần trăm đường kính tiết diện.","def_en":"The amount an O-ring or seal is compressed when installed, usually as a percentage of its cross-section.","def_ja":"装着時にOリングなどがつぶされる量。線径に対する割合で表す。","usage_en":"Danh từ không đếm được trong nghĩa này. Hay đi với: percent squeeze, too much / too little squeeze; ví dụ 15–25% squeeze.","usage_ja":"Hay đi với: つぶし代が不足する, つぶし率 (tính %). Ngoài xưởng cũng nói つぶし量.","context_vi":"Dùng khi thiết kế rãnh gioăng và phân tích nguyên nhân rò rỉ.","ex_en":"A squeeze of 20% is typical for a static O-ring seal.","ex_ja":"静止用Oリングでは20%程度のつぶし代が一般的だ。","ex_vi":"Độ ép khoảng 20% là thông dụng cho gioăng chữ O làm kín tĩnh.","syn_en":["compression (của gioăng)"],"syn_ja":["つぶし量","つぶし率 (tính %)"]},{"en":"sealing lip","pos":"noun phrase","ipa":"/ˈsiːlɪŋ lɪp/","ja":"シールリップ","kana":"シールリップ","romaji":"shiirurippu","vi":"môi phớt","level":2,"def_vi":"Mép đàn hồi của phớt tiếp xúc trực tiếp với trục hoặc cần để chặn chất lỏng.","def_en":"The flexible edge of a seal that contacts the shaft or rod and holds back the fluid.","def_ja":"軸やロッドに接触して流体をせき止める、シールの弾性的な先端部。","usage_en":"Danh từ đếm được. Hay đi với: main lip, dust lip, lip contact, the sealing lip faces the oil side.","usage_ja":"Hay đi với: 主リップ, 副リップ (ダストリップ), リップの摩耗, リップがめくれる.","context_vi":"Dùng khi lắp, kiểm tra và phân tích hư hỏng phớt chặn dầu, phớt chữ U.","ex_en":"The sealing lip must face the oil side of the housing.","ex_ja":"シールリップはハウジングの油側に向けなければならない。","ex_vi":"Môi phớt phải hướng về phía dầu của vỏ.","syn_en":["seal lip","main lip"],"syn_ja":["主リップ","リップ"]},{"en":"spiral wound gasket","pos":"noun","ipa":"/ˌspaɪrəl ˈwaʊnd ˈɡæskɪt/","ja":"うず巻形ガスケット","kana":"うずまきがたガスケット","romaji":"uzumakigatagasuketto","vi":"gioăng xoắn kim loại (gioăng spiral)","level":2,"def_vi":"Gioăng làm từ băng thép hình chữ V cuộn xoắn xen kẽ với lớp graphit hoặc PTFE, chịu áp suất và nhiệt độ cao.","def_en":"A gasket of V-shaped metal strip spirally wound with graphite or PTFE filler, for high pressure and temperature.","def_ja":"V字形の金属帯と黒鉛などのフィラーを交互にうず巻状に巻いたガスケット。","usage_en":"Danh từ đếm được. Hay đi với: inner ring, outer ring (centering ring), graphite filler; theo ASME B16.20.","usage_ja":"JIS B2404 dùng うず巻形ガスケット; ngoài công trường gọi スパイラルガスケット. Hay đi với: 内輪付き, 外輪付き.","context_vi":"Dùng ở mặt bích đường ống hơi, dầu khí, hóa chất và bình áp lực.","ex_en":"Spiral wound gaskets with inner rings are specified for the 300# steam flanges.","ex_ja":"300#の蒸気フランジには内輪付きのうず巻形ガスケットが指定されている。","ex_vi":"Các mặt bích hơi 300# được chỉ định dùng gioăng xoắn kim loại có vòng trong.","syn_en":["spiral-wound gasket","SWG"],"syn_ja":["スパイラルガスケット"]},{"en":"compressed fiber sheet","pos":"noun","ipa":"/kəmˌprest ˈfaɪbə ʃiːt/","ja":"ジョイントシート","kana":"ジョイントシート","romaji":"jointoshiito","vi":"tấm gioăng sợi ép (tấm amiăng, không amiăng)","level":2,"def_vi":"Tấm vật liệu làm từ sợi ép với cao su liên kết, cắt ra thành gioăng mặt bích dùng chung.","def_en":"Sheet made of fibres bonded with rubber, cut into general-purpose flange gaskets.","def_ja":"繊維をゴムで結合して圧延したシートで、汎用のフランジガスケットに切って使う。","usage_en":"Danh từ không đếm được (chỉ vật liệu). Hay đi với: non-asbestos, CNAF, cut gaskets from compressed fiber sheet.","usage_ja":"Hay đi với: ノンアスベストジョイントシート, ジョイントシートから切り出す. Trước đây làm từ アスベスト, nay đã cấm.","context_vi":"Dùng cắt gioăng cho mặt bích đường ống nước, dầu, hơi áp suất thấp và trung bình.","ex_en":"The flange gaskets were cut from 1.5 mm compressed fiber sheet.","ex_ja":"フランジガスケットは厚さ1.5 mmのジョイントシートから切り出した。","ex_vi":"Các gioăng mặt bích được cắt từ tấm gioăng sợi ép dày 1,5 mm.","syn_en":["CNAF sheet","gasket sheet"],"syn_ja":["ノンアスベストジョイントシート"]},{"en":"metal gasket","pos":"noun","ipa":"/ˈmetl ˌɡæskɪt/","ja":"メタルガスケット","kana":"メタルガスケット","romaji":"metarugasuketto","vi":"gioăng kim loại","level":2,"def_vi":"Gioăng làm hoàn toàn bằng kim loại như đồng, thép hoặc nhôm, dùng ở nơi nhiệt độ và áp suất cao.","def_en":"A gasket made entirely of metal such as copper, steel or aluminium for high temperature and pressure.","def_ja":"銅、鋼、アルミニウムなど金属だけで作られ、高温・高圧に用いるガスケット。","usage_en":"Danh từ đếm được. Hay đi với: copper washer gasket, multi-layer steel (MLS) gasket, crush gasket.","usage_ja":"Hay đi với: 銅パッキン (khẩu ngữ), メタルガスケットは再使用不可. Gioăng nắp máy nhiều lớp gọi メタルヘッドガスケット.","context_vi":"Dùng ở nắp máy động cơ, đầu nối ống dầu thủy lực, thiết bị chân không và nhiệt độ cao.","ex_en":"The metal gasket under the drain plug must not be reused.","ex_ja":"ドレンプラグのメタルガスケットは再使用してはならない。","ex_vi":"Không được dùng lại gioăng kim loại dưới nút xả dầu.","syn_en":["metallic gasket"],"syn_ja":["金属ガスケット","銅パッキン (khẩu ngữ)"]},{"en":"formed-in-place gasket","pos":"noun","ipa":"/ˌfɔːmd ɪn ˈpleɪs ˈɡæskɪt/","ja":"液状ガスケット","kana":"えきじょうガスケット","romaji":"ekijougasuketto","vi":"gioăng lỏng (keo làm kín bề mặt)","level":2,"def_vi":"Keo làm kín dạng lỏng hoặc sệt bôi lên mặt ghép, đông cứng tại chỗ để thay gioăng cắt sẵn.","def_en":"A liquid sealant applied to a flange face that cures in place to replace a cut gasket.","def_ja":"接合面に塗布してその場で硬化させ、ガスケットの代わりに使う液状シール剤。","usage_en":"Danh từ đếm được; viết tắt FIPG. Hay đi với: apply a bead of FIPG, RTV silicone; khẩu ngữ: liquid gasket.","usage_ja":"Hay đi với: 液状ガスケットを塗布する, ビード径. Ngoài xưởng hay gọi theo tên hãng như スリーボンド, hoặc FIPG.","context_vi":"Dùng ở các mặt ghép vỏ hộp số, cácte dầu, nắp xích cam trong ô tô và máy móc.","ex_en":"Apply a 3 mm bead of formed-in-place gasket around the oil pan flange.","ex_ja":"オイルパンのフランジに沿って液状ガスケットを3 mm幅で塗布する。","ex_vi":"Bôi một đường gioăng lỏng rộng 3 mm quanh mặt bích cácte dầu.","syn_en":["liquid gasket","FIPG"],"syn_ja":["FIPG","シール剤 (nghĩa rộng hơn)"]},{"en":"nitrile rubber","pos":"noun","ipa":"/ˈnaɪtraɪl ˌrʌbə/","ja":"ニトリルゴム","kana":"ニトリルゴム","romaji":"nitorirugomu","vi":"cao su nitrile (NBR)","level":2,"def_vi":"Cao su tổng hợp chịu dầu khoáng tốt, là vật liệu phổ biến nhất cho gioăng chữ O và phớt dầu.","def_en":"A synthetic rubber with good resistance to mineral oil, the most common seal material.","def_ja":"鉱物油に強い合成ゴムで、Oリングやオイルシールに最も多く使われる。","usage_en":"Danh từ không đếm được; viết tắt NBR. Hay đi với: NBR O-ring, 70 Shore A nitrile rubber; giới hạn nhiệt khoảng −30 đến 100 °C.","usage_ja":"Hay gọi tắt NBR. Hay đi với: NBR製Oリング, 硬度70. JIS B2401 ký hiệu 1種A.","context_vi":"Dùng làm phớt và gioăng cho hệ thống dầu thủy lực, dầu nhờn, nhiên liệu.","ex_en":"Nitrile rubber swells badly in brake fluid, so EPDM was chosen instead.","ex_ja":"ニトリルゴムはブレーキ液で大きく膨潤するため、代わりにEPDMを選んだ。","ex_vi":"Cao su nitrile bị trương nở mạnh trong dầu phanh nên đã chọn EPDM thay thế.","syn_en":["NBR","Buna-N"],"syn_ja":["NBR"]},{"en":"fluoroelastomer","pos":"noun","ipa":"/ˌflʊərəʊɪˈlæstəmə/","ja":"フッ素ゴム","kana":"ふっそゴム","romaji":"fussogomu","vi":"cao su flo (FKM, Viton)","level":2,"def_vi":"Cao su chứa flo chịu nhiệt độ cao và hóa chất tốt, dùng cho phớt làm việc khắc nghiệt.","def_en":"A fluorine-containing rubber with excellent heat and chemical resistance for demanding seals.","def_ja":"フッ素を含み、耐熱性と耐薬品性に優れたゴム。過酷な条件のシールに用いる。","usage_en":"Danh từ không đếm được (đếm được khi nói các loại). Viết tắt FKM; khẩu ngữ gọi Viton theo tên thương mại. Hay đi với: FKM O-ring, up to 200 °C.","usage_ja":"Hay gọi FKM hoặc バイトン (tên thương mại). Hay đi với: フッ素ゴム製Oリング, 耐熱200 °C.","context_vi":"Dùng trong động cơ, máy bơm hóa chất, bán dẫn và thiết bị nhiệt độ cao.","ex_en":"The turbocharger seals are made of fluoroelastomer to withstand 200 °C.","ex_ja":"ターボチャージャのシールは200 °Cに耐えるようフッ素ゴムで作られている。","ex_vi":"Các phớt của bộ tăng áp làm bằng cao su flo để chịu được 200 °C.","syn_en":["FKM","Viton (tên thương mại)"],"syn_ja":["FKM","バイトン (tên thương mại)"]},{"en":"static seal","pos":"noun","ipa":"/ˈstætɪk siːl/","ja":"静止用シール","kana":"せいしようシール","romaji":"seishiyoushiiru","vi":"làm kín tĩnh (phớt tĩnh)","level":2,"def_vi":"Chi tiết làm kín giữa hai bề mặt không chuyển động tương đối với nhau.","def_en":"A seal between two surfaces that do not move relative to each other.","def_ja":"相対運動のない二つの面の間を密封するシール。","usage_en":"Danh từ đếm được. Đối lập với dynamic seal. Hay đi với: static O-ring seal, face seal, gasket.","usage_ja":"Còn gọi 固定用シール; theo JIS gioăng tĩnh là ガスケット. Hay đi với: 静止用Oリング (Gシリーズ).","context_vi":"Dùng khi thiết kế nắp, mặt bích, đầu nối và chọn loại gioăng chữ O.","ex_en":"For a static seal, the O-ring can tolerate a higher squeeze than in a moving rod.","ex_ja":"静止用シールでは、運動部よりもOリングのつぶし代を大きく取れる。","ex_vi":"Với làm kín tĩnh, gioăng chữ O có thể chịu độ ép lớn hơn so với ở cần chuyển động.","syn_en":["stationary seal"],"syn_ja":["固定用シール","ガスケット (theo JIS)"]},{"en":"dynamic seal","pos":"noun","ipa":"/daɪˈnæmɪk siːl/","ja":"運動用シール","kana":"うんどうようシール","romaji":"undouyoushiiru","vi":"làm kín động (phớt động)","level":2,"def_vi":"Chi tiết làm kín giữa hai bề mặt chuyển động tương đối, như trục quay hoặc cần tịnh tiến.","def_en":"A seal between surfaces in relative motion, such as a rotating shaft or a reciprocating rod.","def_ja":"回転軸や往復ロッドなど、相対運動する面の間を密封するシール。","usage_en":"Danh từ đếm được. Đối lập với static seal. Hay đi với: reciprocating / rotary dynamic seal, friction, wear.","usage_ja":"Theo JIS gọi là パッキン. Hay đi với: 往復運動用, 回転運動用, 運動用Oリング (Pシリーズ).","context_vi":"Dùng khi chọn phớt cho xi lanh, bơm, van điều khiển và trục quay.","ex_en":"A dynamic seal needs a smoother counter-surface than a static one.","ex_ja":"運動用シールの相手面は静止用より滑らかに仕上げる必要がある。","ex_vi":"Làm kín động cần bề mặt đối tiếp nhẵn hơn so với làm kín tĩnh.","syn_en":["moving seal"],"syn_ja":["パッキン (theo JIS)"]},{"en":"garter spring","pos":"noun","ipa":"/ˈɡɑːtə sprɪŋ/","ja":"ガータスプリング","kana":"ガータスプリング","romaji":"gaatasupuringu","vi":"lò xo vòng (lò xo ôm môi phớt)","level":3,"def_vi":"Lò xo xoắn nhỏ nối thành vòng, ôm quanh môi phớt chặn dầu để duy trì lực ép môi lên trục.","def_en":"A small coil spring joined into a ring that keeps an oil-seal lip pressed against the shaft.","def_ja":"リング状につないだ小さなコイルばねで、オイルシールのリップを軸に押し付ける。","usage_en":"Danh từ đếm được. Hay đi với: the garter spring has slipped off, spring-loaded lip; thường bằng thép không gỉ.","usage_ja":"Ngoài xưởng thường chỉ gọi スプリング hoặc ばね (của オイルシール). Hay đi với: スプリングが外れる.","context_vi":"Dùng khi lắp và kiểm tra phớt chặn dầu, đặc biệt sau khi phớt bị rò do lò xo tuột.","ex_en":"The garter spring had jumped off during installation, so the seal leaked at once.","ex_ja":"組付け時にガータスプリングが外れていたため、シールはすぐに漏れた。","ex_vi":"Lò xo vòng bị tuột khi lắp nên phớt rò ngay lập tức.","syn_en":["lip spring","seal spring"],"syn_ja":["ガータースプリング","スプリング (khẩu ngữ)"]},{"en":"compression set","pos":"noun phrase","ipa":"/kəmˈpreʃn set/","ja":"圧縮永久ひずみ","kana":"あっしゅくえいきゅうひずみ","romaji":"asshukueikyuuhizumi","vi":"độ biến dạng nén dư","level":3,"def_vi":"Phần biến dạng không hồi phục của vật liệu đàn hồi sau khi bị nén trong thời gian dài, làm giảm khả năng làm kín.","def_en":"The permanent deformation left in an elastomer after prolonged compression, reducing its sealing force.","def_ja":"ゴムを長時間圧縮した後に残る永久変形の割合で、シール力低下の原因となる。","usage_en":"Danh từ không đếm được, thường ghi theo %. Hay đi với: low compression set, compression set test (ASTM D395), take a compression set.","usage_ja":"Hay đi với: 圧縮永久ひずみ試験 (JIS K6262), 圧縮永久ひずみが大きい. Còn gọi 永久圧縮ひずみ.","context_vi":"Dùng khi chọn vật liệu gioăng, đánh giá tuổi thọ phớt và phân tích gioăng chữ O bị dẹt.","ex_en":"The O-rings showed 60% compression set and had become flat on both sides.","ex_ja":"Oリングの圧縮永久ひずみは60%に達し、両側が平らになっていた。","ex_vi":"Các gioăng chữ O có độ biến dạng nén dư 60% và đã bị dẹt hai bên.","syn_en":["permanent set (nghĩa rộng hơn)"],"syn_ja":["永久圧縮ひずみ","へたり (khẩu ngữ)"]},{"en":"labyrinth seal","pos":"noun","ipa":"/ˈlæbərɪnθ siːl/","ja":"ラビリンスシール","kana":"ラビリンスシール","romaji":"rabirinsushiiru","vi":"phớt mê cung (phớt zích zắc)","level":3,"def_vi":"Phớt không tiếp xúc, dùng một loạt răng và khe hẹp tạo đường đi khúc khuỷu để giảm lưu lượng rò.","def_en":"A non-contact seal that uses a series of teeth and narrow gaps to restrict leakage.","def_ja":"多数の歯と狭いすきまで流路を複雑にし、漏れを抑える非接触シール。","usage_en":"Danh từ đếm được. Hay đi với: non-contact, labyrinth teeth, clearance, rub; không làm kín tuyệt đối mà chỉ giảm rò.","usage_ja":"Hay đi với: 非接触シール, ラビリンスのすきま, フィン. Không hao mòn nhưng vẫn có 漏れ nhỏ.","context_vi":"Dùng trong tuabin hơi, tuabin khí, máy nén ly tâm và ổ trục tốc độ cao.","ex_en":"Steam leakage through the labyrinth seal increased after the rotor rubbed.","ex_ja":"ロータが接触した後、ラビリンスシールからの蒸気漏れが増えた。","ex_vi":"Sau khi rô to bị cọ, lượng hơi rò qua phớt mê cung tăng lên.","syn_en":["labyrinth packing","non-contact seal (nghĩa rộng hơn)"],"syn_ja":["ラビリンスパッキン","非接触シール (nghĩa rộng hơn)"]},{"en":"gasket factor","pos":"noun phrase","ipa":"/ˈɡæskɪt ˌfæktə/","ja":"ガスケット係数","kana":"ガスケットけいすう","romaji":"gasukettokeisuu","vi":"hệ số gioăng (m)","level":3,"def_vi":"Hệ số m trong tính toán mặt bích theo ASME, cho biết ứng suất ép gioăng cần duy trì khi làm việc so với áp suất.","def_en":"The factor m used in ASME flange design: required operating gasket stress relative to internal pressure.","def_ja":"フランジ設計で使う係数mで、運転時に必要なガスケット面圧と内圧の比を表す。","usage_en":"Danh từ đếm được, ký hiệu m. Hay đi với: gasket factor m and seating stress y, ASME Section VIII Appendix 2.","usage_ja":"Ký hiệu m; dùng cùng 最小設計締付圧力 y theo JIS B8265. Hay đi với: ガスケット係数を用いて計算する.","context_vi":"Dùng khi tính bu lông và mặt bích cho bình áp lực, thiết bị trao đổi nhiệt và đường ống công nghệ.","ex_en":"A gasket factor of 3.0 was used for the spiral wound gasket in the flange calculation.","ex_ja":"フランジ計算では、うず巻形ガスケットのガスケット係数を3.0とした。","ex_vi":"Trong tính toán mặt bích đã dùng hệ số gioăng 3,0 cho gioăng xoắn kim loại.","syn_en":["maintenance factor m"],"syn_ja":["m値"]},{"en":"gasket seating stress","pos":"noun phrase","ipa":"/ˈɡæskɪt ˈsiːtɪŋ stres/","ja":"最小設計締付圧力","kana":"さいしょうせっけいしめつけあつりょく","romaji":"saishousekkeishimetsukeatsuryoku","vi":"ứng suất ép gioăng ban đầu tối thiểu (y)","level":3,"def_vi":"Ứng suất nén tối thiểu cần đặt lên gioăng khi siết bu lông để gioăng điền kín các nhấp nhô bề mặt mặt bích.","def_en":"The minimum stress, y, that must be applied to a gasket at bolt-up so it seats into the flange surface.","def_ja":"ボルト締付け時、ガスケットをフランジ面になじませるのに必要な最小面圧y。","usage_en":"Danh từ không đếm được, ký hiệu y, đơn vị MPa hoặc psi. Hay đi với: minimum design seating stress, achieve seating stress.","usage_ja":"Ký hiệu y theo JIS B8265; ngoài hiện trường hay nói chung ガスケット面圧 hoặc 締付面圧.","context_vi":"Dùng trong tính toán lực siết bu lông mặt bích và lựa chọn loại gioăng.","ex_en":"The bolt load must exceed the gasket seating stress times the gasket contact area.","ex_ja":"ボルト荷重は、最小設計締付圧力にガスケット接触面積を掛けた値を上回らなければならない。","ex_vi":"Lực bu lông phải vượt quá ứng suất ép gioăng ban đầu tối thiểu nhân với diện tích tiếp xúc của gioăng.","syn_en":["seating stress y","minimum seating stress"],"syn_ja":["ガスケット面圧 (nghĩa rộng hơn)","y値"]},{"en":"ring joint gasket","pos":"noun","ipa":"/ˈrɪŋ dʒɔɪnt ˌɡæskɪt/","ja":"リングジョイントガスケット","kana":"リングジョイントガスケット","romaji":"ringujointogasuketto","vi":"gioăng vòng kim loại (gioăng RTJ)","level":3,"def_vi":"Vòng kim loại đặc tiết diện ô van hoặc bát giác, lắp vào rãnh của mặt bích RTJ cho áp suất rất cao.","def_en":"A solid metal ring of oval or octagonal section seated in grooves of RTJ flanges for very high pressure.","def_ja":"楕円形または八角形断面の金属リングで、RTJフランジの溝に入れて超高圧を密封する。","usage_en":"Danh từ đếm được. Hay đi với: RTJ flange, oval / octagonal ring, R-number (ví dụ R45); theo ASME B16.20.","usage_ja":"Hay gọi tắt RTJガスケット hoặc リングガスケット. Hay đi với: オーバル形, オクタゴナル形, リング溝.","context_vi":"Dùng ở đầu giếng dầu khí, đường ống áp suất rất cao và van cấp áp cao.","ex_en":"A soft-iron ring joint gasket is fitted between the wellhead flanges.","ex_ja":"坑口装置のフランジ間には軟鉄製のリングジョイントガスケットを入れる。","ex_vi":"Một gioăng vòng kim loại bằng sắt mềm được lắp giữa các mặt bích đầu giếng.","syn_en":["RTJ gasket","ring-type joint"],"syn_ja":["RTJガスケット","リングガスケット"]}]},{"id":28,"words":[{"en":"clutch","pos":"noun","ipa":"/klʌtʃ/","ja":"クラッチ","kana":"クラッチ","romaji":"kuratchi","vi":"ly hợp (côn)","level":1,"def_vi":"Cơ cấu nối hoặc ngắt truyền mô men giữa trục dẫn và trục bị dẫn trong khi máy vẫn có thể đang chạy.","def_en":"A device that connects or disconnects torque transmission between a driving and a driven shaft.","def_ja":"駆動軸と従動軸の間で動力の伝達をつないだり切ったりする装置。","usage_en":"Danh từ đếm được. Hay đi với: clutch disc, clutch pedal, clutch slip; động từ: engage / disengage / release the clutch.","usage_ja":"Hay đi với: クラッチをつなぐ, クラッチを切る, クラッチ板. Khẩu ngữ Việt gọi côn.","context_vi":"Dùng trong ô tô, xe máy, máy công cụ, máy ép và băng tải để khởi động hoặc ngắt truyền động.","ex_en":"The press uses a clutch to connect the flywheel to the crankshaft for each stroke.","ex_ja":"プレスは各行程ごとにクラッチでフライホイールとクランク軸をつなぐ。","ex_vi":"Máy ép dùng ly hợp để nối bánh đà với trục khuỷu cho mỗi hành trình.","syn_en":["coupling (liên quan, loại không ngắt được)"],"syn_ja":["継手 (liên quan)"]},{"en":"brake","pos":"noun","ipa":"/breɪk/","ja":"ブレーキ","kana":"ブレーキ","romaji":"bureeki","vi":"phanh (thắng)","level":1,"def_vi":"Cơ cấu làm giảm tốc độ, dừng hoặc giữ đứng yên một bộ phận chuyển động, thường bằng ma sát.","def_en":"A device that slows, stops or holds a moving part, usually by friction.","def_ja":"運動している部分を減速・停止・保持する装置で、多くは摩擦を利用する。","usage_en":"Danh từ đếm được; cũng là động từ (to brake). Hay đi với: apply / release the brake, brake force, parking brake; lưu ý không viết nhầm thành break.","usage_ja":"Hay đi với: ブレーキをかける, ブレーキを解放する, ブレーキが効く. Thuật ngữ JIS còn dùng 制動装置.","context_vi":"Dùng trên xe, cần trục, thang máy, động cơ servo và máy công cụ để dừng an toàn.","ex_en":"The hoist brake must hold 150% of the rated load.","ex_ja":"巻上げ機のブレーキは定格荷重の150%を保持できなければならない。","ex_vi":"Phanh của tời nâng phải giữ được 150% tải định mức.","syn_en":["braking device"],"syn_ja":["制動装置","制動機"]},{"en":"brake pad","pos":"noun","ipa":"/ˈbreɪk pæd/","ja":"ブレーキパッド","kana":"ブレーキパッド","romaji":"bureekipaddo","vi":"má phanh đĩa","level":1,"def_vi":"Tấm thép phủ vật liệu ma sát, được cùm phanh ép vào đĩa phanh để tạo lực hãm.","def_en":"A steel backing plate with friction material that the caliper presses against the disc.","def_ja":"裏板に摩擦材を貼ったもので、キャリパによりディスクに押し付けられる。","usage_en":"Danh từ đếm được. Hay đi với: worn brake pads, pad wear indicator, replace the brake pads; thường dùng số nhiều.","usage_ja":"Ngoài xưởng nói tắt パッド. Hay đi với: パッドの残量, パッドを交換する, 鳴き (tiếng rít).","context_vi":"Dùng trong phanh đĩa ô tô, xe máy, phanh công nghiệp và phanh tuabin gió.","ex_en":"Replace the brake pads when the lining is thinner than 2 mm.","ex_ja":"摩擦材の厚さが2 mm未満になったらブレーキパッドを交換すること。","ex_vi":"Thay má phanh đĩa khi lớp ma sát mỏng hơn 2 mm.","syn_en":["disc pad","pad"],"syn_ja":["パッド","ディスクパッド"]},{"en":"disc brake","pos":"noun","ipa":"/ˈdɪsk breɪk/","ja":"ディスクブレーキ","kana":"ディスクブレーキ","romaji":"disukubureeki","vi":"phanh đĩa","level":1,"def_vi":"Loại phanh trong đó má phanh kẹp hai mặt của một đĩa quay gắn với bánh xe hoặc trục.","def_en":"A brake in which pads clamp both faces of a rotating disc attached to the wheel or shaft.","def_ja":"回転するディスクの両面をパッドで挟んで制動するブレーキ。","usage_en":"Danh từ đếm được; Mỹ viết disk brake. Hay đi với: disc (rotor), caliper, ventilated disc, front disc brakes.","usage_ja":"Hay đi với: ディスクロータ, キャリパ, ベンチレーテッドディスク. Ưu điểm so với ドラムブレーキ: tản nhiệt tốt.","context_vi":"Dùng trên ô tô, xe máy, tàu hỏa, tuabin gió và băng tải lớn.","ex_en":"Disc brakes recover from heavy use faster than drum brakes because they cool better.","ex_ja":"ディスクブレーキは放熱性が良いため、ドラムブレーキより連続使用からの回復が早い。","ex_vi":"Phanh đĩa phục hồi nhanh hơn phanh tang trống sau khi phanh liên tục vì tản nhiệt tốt hơn.","syn_en":["disk brake (Mỹ)"],"syn_ja":["円板ブレーキ"]},{"en":"drum brake","pos":"noun","ipa":"/ˈdrʌm breɪk/","ja":"ドラムブレーキ","kana":"ドラムブレーキ","romaji":"doramubureeki","vi":"phanh tang trống (phanh đùm)","level":1,"def_vi":"Loại phanh trong đó guốc phanh ép vào mặt trong của một tang trống quay cùng bánh xe.","def_en":"A brake in which shoes press against the inside of a drum rotating with the wheel.","def_ja":"車輪と共に回るドラムの内面にシューを押し付けて制動するブレーキ。","usage_en":"Danh từ đếm được. Hay đi với: brake drum, brake shoes, wheel cylinder, leading / trailing shoe.","usage_ja":"Hay đi với: ブレーキドラム, ブレーキシュー, ホイールシリンダ, リーディングトレーリング式.","context_vi":"Dùng ở bánh sau xe tải, xe con giá rẻ, xe máy và cơ cấu phanh tời.","ex_en":"Most heavy trucks still use drum brakes on the rear axle.","ex_ja":"大型トラックの多くは、今も後軸にドラムブレーキを使っている。","ex_vi":"Phần lớn xe tải nặng vẫn dùng phanh tang trống ở cầu sau.","syn_en":["internal expanding brake"],"syn_ja":["内部拡張式ブレーキ"]},{"en":"brake shoe","pos":"noun","ipa":"/ˈbreɪk ʃuː/","ja":"ブレーキシュー","kana":"ブレーキシュー","romaji":"bureekishuu","vi":"guốc phanh","level":1,"def_vi":"Chi tiết hình cung mang lớp vật liệu ma sát, được ép vào tang trống hoặc bánh xe để phanh.","def_en":"A curved part carrying friction lining that is pressed against a drum or wheel to brake.","def_ja":"摩擦材を張った円弧状の部品で、ドラムや車輪に押し付けて制動する。","usage_en":"Danh từ đếm được. Hay đi với: leading shoe, trailing shoe, shoe lining; động từ: adjust / reline the brake shoes.","usage_ja":"Ngoài xưởng nói tắt シュー. Đường sắt dùng 制輪子 cho guốc hãm bánh xe.","context_vi":"Dùng trong phanh tang trống ô tô, phanh guốc của tời, cần trục và đầu máy toa xe.","ex_en":"The brake shoe return spring was broken, so the shoe dragged on the drum.","ex_ja":"戻しばねが折れていたため、ブレーキシューがドラムに引きずっていた。","ex_vi":"Lò xo hồi guốc phanh bị gãy nên guốc phanh bị bó vào tang trống.","syn_en":["shoe"],"syn_ja":["シュー","制輪子 (đường sắt)"]},{"en":"brake lining","pos":"noun","ipa":"/ˈbreɪk ˌlaɪnɪŋ/","ja":"ブレーキライニング","kana":"ブレーキライニング","romaji":"bureekirainingu","vi":"bố phanh (lớp ma sát guốc phanh)","level":1,"def_vi":"Lớp vật liệu ma sát được tán hoặc dán lên guốc phanh, trực tiếp tiếp xúc với tang trống.","def_en":"The layer of friction material riveted or bonded to a brake shoe.","def_ja":"ブレーキシューにリベットや接着で取り付けた摩擦材の層。","usage_en":"Danh từ đếm được hoặc không đếm được. Hay đi với: bonded / riveted lining, lining thickness, worn lining.","usage_ja":"Ngoài xưởng nói tắt ライニング. Hay đi với: ライニングの残厚, ライニングを張り替える.","context_vi":"Dùng khi bảo dưỡng phanh tang trống xe tải, cần trục và tời.","ex_en":"The brake lining was worn down to the rivet heads.","ex_ja":"ブレーキライニングがリベット頭まですり減っていた。","ex_vi":"Bố phanh đã mòn tới tận đầu đinh tán.","syn_en":["lining","friction lining"],"syn_ja":["ライニング"]},{"en":"friction plate","pos":"noun","ipa":"/ˈfrɪkʃn pleɪt/","ja":"摩擦板","kana":"まさつばん","romaji":"masatsuban","vi":"đĩa ma sát (lá côn)","level":1,"def_vi":"Đĩa có phủ vật liệu ma sát, được ép xen kẽ với đĩa thép trong ly hợp hoặc phanh nhiều đĩa.","def_en":"A disc faced with friction material, stacked alternately with steel plates in a clutch or brake.","def_ja":"摩擦材を張った板で、多板クラッチやブレーキで鋼板と交互に重ねる。","usage_en":"Danh từ đếm được. Hay đi với: steel plate, separator plate, friction plate wear; xe máy gọi clutch plates.","usage_ja":"Ngoài xưởng gọi フリクションプレート hoặc クラッチ板. Đi cặp với 鋼板 (セパレートプレート).","context_vi":"Dùng trong ly hợp xe máy, hộp số tự động, phanh đa đĩa và ly hợp máy công cụ.","ex_en":"Each friction plate is measured for thickness before reassembly.","ex_ja":"再組立前に各摩擦板の厚さを測定する。","ex_vi":"Trước khi lắp lại, từng đĩa ma sát đều được đo chiều dày.","syn_en":["friction disc","clutch plate"],"syn_ja":["フリクションプレート","クラッチ板"]},{"en":"engage","pos":"verb","ipa":"/ɪnˈɡeɪdʒ/","ja":"連結する","kana":"れんけつする","romaji":"renketsusuru","vi":"đóng ly hợp (nối truyền động)","level":1,"def_vi":"Làm cho ly hợp hoặc phanh vào khớp để truyền mô men hoặc tạo lực hãm.","def_en":"To bring a clutch or brake into contact so that it transmits torque.","def_ja":"クラッチやブレーキを接触させ、トルクを伝える状態にすること。","usage_en":"Động từ, dùng cả ngoại động (engage the clutch) lẫn nội động (the clutch engages). Danh từ: engagement; hay đi với: engagement time, smoothly / fully engaged.","usage_ja":"Văn bản kỹ thuật dùng 連結する hoặc 締結する; ngoài xưởng nói クラッチをつなぐ. Danh từ: 連結, 連結時間.","context_vi":"Dùng khi mô tả trình tự vận hành, thời gian đáp ứng của ly hợp và phanh điện từ.","ex_en":"The clutch must engage within 50 ms after the coil is energized.","ex_ja":"コイルに通電してから50 ms以内にクラッチが連結する必要がある。","ex_vi":"Ly hợp phải đóng trong vòng 50 ms sau khi cuộn dây được cấp điện.","syn_en":["couple","connect"],"syn_ja":["つなぐ (khẩu ngữ)","締結する"]},{"en":"disengage","pos":"verb","ipa":"/ˌdɪsɪnˈɡeɪdʒ/","ja":"切り離す","kana":"きりはなす","romaji":"kirihanasu","vi":"ngắt ly hợp (cắt truyền động)","level":1,"def_vi":"Tách ly hợp hoặc phanh ra để ngừng truyền mô men hoặc thôi tạo lực hãm.","def_en":"To separate a clutch or brake so that it no longer transmits torque.","def_ja":"クラッチやブレーキを離して、トルクを伝えない状態にすること。","usage_en":"Động từ, ngoại động hoặc nội động. Danh từ: disengagement; hay đi với: fully disengaged, disengage the drive.","usage_ja":"Ngoài xưởng nói クラッチを切る; với phanh dùng 解放する. Danh từ: 切り離し, 解放.","context_vi":"Dùng khi mô tả sang số, dừng khẩn cấp và cơ cấu an toàn của máy.","ex_en":"Disengage the drive before you clear a jam on the conveyor.","ex_ja":"コンベヤの詰まりを取る前に、駆動を切り離すこと。","ex_vi":"Ngắt truyền động trước khi gỡ vật kẹt trên băng tải.","syn_en":["declutch","release"],"syn_ja":["切る (khẩu ngữ)","解放する"]},{"en":"multi-plate clutch","pos":"noun","ipa":"/ˌmʌlti ˈpleɪt klʌtʃ/","ja":"多板クラッチ","kana":"たばんクラッチ","romaji":"tabankuratchi","vi":"ly hợp nhiều đĩa","level":2,"def_vi":"Ly hợp có nhiều đĩa ma sát và đĩa thép xếp xen kẽ, truyền mô men lớn với đường kính nhỏ.","def_en":"A clutch with several friction and steel plates stacked alternately to carry high torque in a small diameter.","def_ja":"複数の摩擦板と鋼板を交互に重ね、小径で大きなトルクを伝えるクラッチ。","usage_en":"Danh từ đếm được. Hay đi với: wet multi-plate clutch, clutch pack, number of friction surfaces.","usage_ja":"Hay đi với: 湿式多板クラッチ, 乾式多板クラッチ, クラッチパック.","context_vi":"Dùng trong xe máy, hộp số tự động, máy cắt kim loại và tời.","ex_en":"Motorcycles normally use a wet multi-plate clutch running in engine oil.","ex_ja":"オートバイでは通常、エンジンオイル中で作動する湿式多板クラッチを使う。","ex_vi":"Xe máy thường dùng ly hợp nhiều đĩa ướt chạy trong dầu động cơ.","syn_en":["multi-disc clutch","clutch pack (cụm đĩa)"],"syn_ja":["マルチプレートクラッチ"]},{"en":"electromagnetic clutch","pos":"noun","ipa":"/ɪˌlektrəʊmæɡˈnetɪk klʌtʃ/","ja":"電磁クラッチ","kana":"でんじクラッチ","romaji":"denjikuratchi","vi":"ly hợp điện từ","level":2,"def_vi":"Ly hợp được đóng nhờ lực hút của cuộn dây điện từ kéo phần ứng ép vào rô to.","def_en":"A clutch engaged by an electromagnet that pulls an armature against a rotor.","def_ja":"電磁コイルの吸引力でアーマチュアをロータに吸着させて連結するクラッチ。","usage_en":"Danh từ đếm được. Hay đi với: coil voltage (24 V DC), armature, air gap; động từ: energize / de-energize the electromagnetic clutch.","usage_ja":"Hay đi với: 電磁クラッチに通電する, 励磁, 電磁クラッチ・ブレーキユニット.","context_vi":"Dùng ở máy nén điều hòa ô tô, máy đóng gói, máy in và băng tải gián đoạn.","ex_en":"The compressor's electromagnetic clutch did not engage because the coil was open.","ex_ja":"コイルが断線していたため、コンプレッサの電磁クラッチが連結しなかった。","ex_vi":"Ly hợp điện từ của máy nén không đóng vì cuộn dây bị đứt.","syn_en":["magnetic clutch","electromagnetic coupling (liên quan)"],"syn_ja":["マグネットクラッチ"]},{"en":"electromagnetic brake","pos":"noun","ipa":"/ɪˌlektrəʊmæɡˈnetɪk breɪk/","ja":"電磁ブレーキ","kana":"でんじブレーキ","romaji":"denjibureeki","vi":"phanh điện từ","level":2,"def_vi":"Phanh được tác động hoặc nhả nhờ lực từ của cuộn dây điện, thường gắn ở đuôi động cơ.","def_en":"A brake applied or released by the force of an electromagnet, often mounted on a motor.","def_ja":"電磁コイルの磁力で作動・解放するブレーキで、モータ後部によく付く。","usage_en":"Danh từ đếm được. Hay đi với: motor with electromagnetic brake, brake coil, holding torque, manual release lever.","usage_ja":"Hay đi với: ブレーキ付きモータ, 電磁ブレーキの手動解放, 励磁作動形／無励磁作動形.","context_vi":"Dùng trên động cơ trục đứng, robot, cần trục, cổng tự động và máy công cụ.","ex_en":"The Z-axis motor has an electromagnetic brake to stop the head from dropping at power loss.","ex_ja":"Z軸モータには、停電時にヘッドが落下しないよう電磁ブレーキが付いている。","ex_vi":"Động cơ trục Z có phanh điện từ để đầu máy không rơi xuống khi mất điện.","syn_en":["magnetic brake","motor brake"],"syn_ja":["マグネットブレーキ"]},{"en":"one-way clutch","pos":"noun","ipa":"/ˌwʌn weɪ ˈklʌtʃ/","ja":"ワンウェイクラッチ","kana":"ワンウェイクラッチ","romaji":"wanweikuratchi","vi":"ly hợp một chiều","level":2,"def_vi":"Ly hợp chỉ truyền mô men theo một chiều quay và tự quay trơn theo chiều ngược lại.","def_en":"A clutch that transmits torque in one direction and freewheels in the other.","def_ja":"一方向にだけトルクを伝え、逆方向には空転するクラッチ。","usage_en":"Danh từ đếm được. Hay đi với: overrunning, freewheel, backstop; loại con lăn hoặc loại sprag.","usage_ja":"Hay đi với: 逆転防止, 空転, スプラグ形／ローラ形. JIS dùng 一方向クラッチ.","context_vi":"Dùng trong bộ đề khởi động, líp xe đạp, băng tải nghiêng chống quay ngược và hộp số tự động.","ex_en":"A one-way clutch on the head pulley prevents the inclined conveyor from running back.","ex_ja":"ヘッドプーリのワンウェイクラッチが傾斜コンベヤの逆走を防ぐ。","ex_vi":"Ly hợp một chiều ở puly đầu ngăn băng tải nghiêng chạy ngược.","syn_en":["overrunning clutch","freewheel","backstop (chống quay ngược)"],"syn_ja":["一方向クラッチ","逆転防止装置 (liên quan)"]},{"en":"dog clutch","pos":"noun","ipa":"/ˈdɒɡ klʌtʃ/","ja":"ドグクラッチ","kana":"ドグクラッチ","romaji":"dogukuratchi","vi":"ly hợp vấu","level":2,"def_vi":"Ly hợp truyền mô men bằng các vấu hoặc răng ăn khớp với nhau, không dùng ma sát nên không trượt.","def_en":"A clutch that transmits torque through interlocking teeth or jaws instead of friction.","def_ja":"摩擦ではなく、歯やつめのかみ合いでトルクを伝えるクラッチ。","usage_en":"Danh từ đếm được. Hay đi với: jaw clutch, dog teeth, engage only at low speed; không trượt nên truyền chính xác.","usage_ja":"JIS gọi かみあいクラッチ; ngoài xưởng nói ドグクラッチ hoặc ドッグクラッチ. Chỉ nên 連結 khi đứng yên hoặc tốc độ thấp.","context_vi":"Dùng trong hộp số xe máy, hộp số máy công cụ, cơ cấu khóa vi sai và máy nông nghiệp.","ex_en":"The dog clutch can only be engaged when the shafts are almost stationary.","ex_ja":"ドグクラッチは軸がほぼ停止しているときにしか連結できない。","ex_vi":"Ly hợp vấu chỉ có thể đóng khi các trục gần như đứng yên.","syn_en":["jaw clutch","positive clutch"],"syn_ja":["かみあいクラッチ","ドッグクラッチ"]},{"en":"centrifugal clutch","pos":"noun","ipa":"/ˌsentrɪˈfjuːɡl klʌtʃ/","ja":"遠心クラッチ","kana":"えんしんクラッチ","romaji":"enshinkuratchi","vi":"ly hợp ly tâm (nồi)","level":2,"def_vi":"Ly hợp tự đóng khi tốc độ tăng, nhờ lực ly tâm đẩy các má ma sát văng ra ép vào tang.","def_en":"A clutch that engages automatically as speed rises, when centrifugal force throws shoes against a drum.","def_ja":"回転数が上がると遠心力でシューがドラムに押し付けられ、自動的に連結するクラッチ。","usage_en":"Danh từ đếm được. Hay đi với: engagement speed, clutch shoes, clutch bell; thường không cần cơ cấu điều khiển.","usage_ja":"Hay đi với: 遠心クラッチの連結回転数, クラッチシュー. Xe tay ga Việt Nam gọi là nồi (bộ nồi sau).","context_vi":"Dùng trong xe tay ga, máy cưa xích, máy cắt cỏ và máy phát nhỏ.","ex_en":"The chainsaw's centrifugal clutch engages at about 3,000 rpm.","ex_ja":"チェーンソーの遠心クラッチは約3,000 rpmで連結する。","ex_vi":"Ly hợp ly tâm của máy cưa xích đóng ở khoảng 3.000 vòng/phút.","syn_en":["automatic clutch (nghĩa rộng hơn)"],"syn_ja":["セントリフューガルクラッチ"]},{"en":"band brake","pos":"noun","ipa":"/ˈbænd breɪk/","ja":"バンドブレーキ","kana":"バンドブレーキ","romaji":"bandobureeki","vi":"phanh đai","level":2,"def_vi":"Phanh dùng một dải thép có lót ma sát quấn quanh tang trống, siết lại để tạo lực hãm.","def_en":"A brake in which a lined steel band is tightened around a drum.","def_ja":"摩擦材を張った鋼帯をドラムに巻き付けて締め付けるブレーキ。","usage_en":"Danh từ đếm được. Hay đi với: band, drum, tight side, slack side; lực hãm tính theo công thức Euler (e^μθ).","usage_ja":"Hay đi với: 張り側, ゆるみ側, 巻き付け角. Tính toán dùng công thức オイラーの式.","context_vi":"Dùng trong tời, máy trục cũ, hộp số tự động và máy nông nghiệp.","ex_en":"The winch is fitted with a band brake operated by a hand lever.","ex_ja":"このウインチには手動レバーで操作するバンドブレーキが付いている。","ex_vi":"Tời này được lắp một phanh đai điều khiển bằng cần tay.","syn_en":["strap brake"],"syn_ja":["帯ブレーキ"]},{"en":"friction material","pos":"noun","ipa":"/ˈfrɪkʃn məˌtɪəriəl/","ja":"摩擦材","kana":"まさつざい","romaji":"masatsuzai","vi":"vật liệu ma sát","level":2,"def_vi":"Vật liệu có hệ số ma sát ổn định và chịu mòn, chịu nhiệt, dùng làm bề mặt làm việc của phanh và ly hợp.","def_en":"Material with a stable friction coefficient and good wear and heat resistance used in brakes and clutches.","def_ja":"安定した摩擦係数と耐摩耗性・耐熱性をもち、ブレーキやクラッチに使う材料。","usage_en":"Danh từ không đếm được (đếm được khi nói các loại). Hay đi với: organic / semi-metallic / sintered friction material, non-asbestos.","usage_ja":"Hay đi với: ノンアスベスト摩擦材, 焼結摩擦材, 摩擦材の摩耗量. Ngoài xưởng hay nói ライニング hoặc パッド theo vị trí.","context_vi":"Dùng khi chọn và đánh giá má phanh, bố ly hợp, phanh công nghiệp và phanh tàu hỏa.","ex_en":"A sintered friction material was chosen for its stability at high temperature.","ex_ja":"高温での安定性を重視して、焼結の摩擦材を選定した。","ex_vi":"Đã chọn vật liệu ma sát thiêu kết vì tính ổn định ở nhiệt độ cao.","syn_en":["lining material","friction lining"],"syn_ja":["ライニング材"]},{"en":"wet clutch","pos":"noun","ipa":"/ˈwet klʌtʃ/","ja":"湿式クラッチ","kana":"しっしきクラッチ","romaji":"shisshikikuratchi","vi":"ly hợp ướt","level":2,"def_vi":"Ly hợp có các đĩa làm việc trong dầu, dầu giúp làm mát và giảm mòn nhưng gây mô men kéo khi ngắt.","def_en":"A clutch whose plates run in oil for cooling and reduced wear, at the cost of some drag torque.","def_ja":"摩擦板が油中で作動するクラッチ。冷却性と耐摩耗性に優れるが引きずりトルクがある。","usage_en":"Danh từ đếm được. Đối lập với dry clutch. Hay đi với: wet multi-plate clutch, drag torque, clutch oil.","usage_ja":"Hay đi với: 湿式多板クラッチ, 引きずりトルク. Đối lập: 乾式クラッチ.","context_vi":"Dùng trong xe máy, hộp số tự động, máy kéo và ly hợp máy ép.","ex_en":"A wet clutch tolerates frequent slipping better than a dry one.","ex_ja":"湿式クラッチは乾式より頻繁な滑りに強い。","ex_vi":"Ly hợp ướt chịu được việc trượt thường xuyên tốt hơn ly hợp khô.","syn_en":["oil-immersed clutch"],"syn_ja":["油中クラッチ"]},{"en":"dry clutch","pos":"noun","ipa":"/ˈdraɪ klʌtʃ/","ja":"乾式クラッチ","kana":"かんしきクラッチ","romaji":"kanshikikuratchi","vi":"ly hợp khô","level":2,"def_vi":"Ly hợp có bề mặt ma sát làm việc trong không khí, hiệu suất cao và không có mô men kéo nhưng tản nhiệt kém hơn.","def_en":"A clutch whose friction surfaces run in air, giving no drag but poorer cooling.","def_ja":"摩擦面が空気中で作動するクラッチ。引きずりがないが放熱性は劣る。","usage_en":"Danh từ đếm được. Đối lập với wet clutch. Hay đi với: single-plate dry clutch, clutch disc, pressure plate.","usage_ja":"Hay đi với: 乾式単板クラッチ, クラッチディスク, プレッシャプレート. Phải tránh dầu mỡ dính vào.","context_vi":"Dùng trong ô tô số sàn, ly hợp điện từ và nhiều máy công nghiệp.","ex_en":"Most manual cars use a single-plate dry clutch.","ex_ja":"マニュアル車の多くは単板の乾式クラッチを使っている。","ex_vi":"Phần lớn xe số sàn dùng ly hợp khô một đĩa.","syn_en":["dry friction clutch"],"syn_ja":["乾式単板クラッチ (một dạng)"]},{"en":"brake caliper","pos":"noun","ipa":"/ˈbreɪk ˌkælɪpə/","ja":"ブレーキキャリパ","kana":"ブレーキキャリパ","romaji":"bureekikyaripa","vi":"cùm phanh (heo dầu phanh đĩa)","level":2,"def_vi":"Cụm vỏ chứa piston thủy lực ôm quanh đĩa phanh, ép má phanh vào hai mặt đĩa.","def_en":"The housing with pistons that straddles the disc and presses the pads against it.","def_ja":"ディスクをまたいでピストンでパッドを押し付ける、ディスクブレーキの本体。","usage_en":"Danh từ đếm được. Hay đi với: floating / fixed caliper, caliper piston, caliper bracket; nói tắt caliper.","usage_ja":"Ngoài xưởng nói キャリパー. Hay đi với: 対向ピストンキャリパ, フローティングキャリパ.","context_vi":"Dùng khi bảo dưỡng phanh đĩa ô tô, xe máy và phanh đĩa công nghiệp.","ex_en":"A seized brake caliper caused the left front wheel to overheat.","ex_ja":"ブレーキキャリパの固着で左前輪が過熱した。","ex_vi":"Cùm phanh bị kẹt làm bánh trước bên trái quá nhiệt.","syn_en":["caliper"],"syn_ja":["キャリパー","キャリパ"]},{"en":"braking torque","pos":"noun phrase","ipa":"/ˈbreɪkɪŋ tɔːk/","ja":"制動トルク","kana":"せいどうトルク","romaji":"seidoutoruku","vi":"mô men phanh","level":2,"def_vi":"Mô men do phanh tạo ra để làm giảm tốc hoặc giữ trục đứng yên.","def_en":"The torque produced by a brake to decelerate or hold a shaft.","def_ja":"ブレーキが軸を減速または保持するために発生するトルク。","usage_en":"Danh từ không đếm được. Hay đi với: rated / static / dynamic braking torque, required braking torque.","usage_ja":"Hay đi với: 静摩擦トルク, 動摩擦トルク, 定格制動トルク, 必要制動トルクを計算する.","context_vi":"Dùng khi tính chọn phanh cho động cơ, tời, cần trục và máy quay quán tính lớn.","ex_en":"The required braking torque is 1.5 times the motor's rated torque.","ex_ja":"必要な制動トルクはモータの定格トルクの1.5倍とする。","ex_vi":"Mô men phanh yêu cầu bằng 1,5 lần mô men định mức của động cơ.","syn_en":["brake torque"],"syn_ja":["ブレーキトルク"]},{"en":"torque limiter","pos":"noun","ipa":"/ˈtɔːk ˌlɪmɪtə/","ja":"トルクリミッタ","kana":"トルクリミッタ","romaji":"torukurimitta","vi":"bộ giới hạn mô men (ly hợp an toàn)","level":2,"def_vi":"Ly hợp an toàn tự trượt hoặc ngắt khi mô men vượt giá trị cài đặt, bảo vệ máy khi bị kẹt hoặc quá tải.","def_en":"A safety clutch that slips or disconnects when torque exceeds a set value, protecting the drive.","def_ja":"設定値を超えるトルクで滑るか切り離され、駆動系を過負荷から守る安全クラッチ。","usage_en":"Danh từ đếm được. Hay đi với: set torque, friction / ball-detent torque limiter, trip; động từ: adjust the torque limiter.","usage_ja":"Hay đi với: トルクリミッタが作動する／滑る, 設定トルクを調整する. Còn viết トルクリミッター.","context_vi":"Dùng trong băng tải, máy đóng gói, máy nông nghiệp và trục truyền động có nguy cơ kẹt.","ex_en":"The torque limiter slipped and saved the gearbox when the conveyor jammed.","ex_ja":"コンベヤが詰まったとき、トルクリミッタが滑って減速機を守った。","ex_vi":"Khi băng tải bị kẹt, bộ giới hạn mô men đã trượt và cứu được hộp giảm tốc.","syn_en":["slip clutch","overload clutch"],"syn_ja":["トルクリミッター","安全クラッチ"]},{"en":"air gap","pos":"noun","ipa":"/ˈeə ɡæp/","ja":"エアギャップ","kana":"エアギャップ","romaji":"eagyappu","vi":"khe hở không khí","level":2,"def_vi":"Khe hở giữa phần ứng và mặt nam châm của ly hợp hoặc phanh điện từ khi chưa hút, tăng dần theo mòn.","def_en":"The clearance between the armature and magnet face of an electromagnetic clutch or brake.","def_ja":"電磁クラッチ・ブレーキのアーマチュアと磁極面の間のすきま。","usage_en":"Danh từ đếm được. Hay đi với: check / adjust the air gap, maximum air gap, feeler gauge.","usage_ja":"Hay đi với: エアギャップを調整する, すきまゲージで測る, ギャップ過大で吸引不良.","context_vi":"Dùng khi bảo dưỡng phanh động cơ, ly hợp điện từ và chẩn đoán phanh không nhả.","ex_en":"Check the air gap with a feeler gauge every 1,000 operating hours.","ex_ja":"運転1,000時間ごとに、すきまゲージでエアギャップを点検する。","ex_vi":"Cứ mỗi 1.000 giờ vận hành, kiểm tra khe hở không khí bằng thước lá.","syn_en":["armature gap"],"syn_ja":["ギャップ","すきま"]},{"en":"clutch slip","pos":"noun phrase","ipa":"/ˈklʌtʃ slɪp/","ja":"クラッチ滑り","kana":"クラッチすべり","romaji":"kuratchisuberi","vi":"trượt ly hợp (trượt côn)","level":2,"def_vi":"Hiện tượng hai nửa ly hợp quay với tốc độ khác nhau khi đáng lẽ phải dính chặt, gây nóng và mòn.","def_en":"A condition in which the two halves of an engaged clutch turn at different speeds.","def_ja":"連結しているはずのクラッチの両側が異なる回転数で回る状態。","usage_en":"Danh từ không đếm được; động từ: the clutch is slipping. Hay đi với: excessive clutch slip, slip time, slip energy.","usage_ja":"Hay đi với: クラッチが滑る, 滑り時間. Ngoài xưởng nói クラッチの滑り hoặc 滑り.","context_vi":"Dùng khi chẩn đoán xe mất lực kéo, ly hợp mòn hoặc lò xo ép yếu.","ex_en":"Clutch slip under full load indicated worn friction plates.","ex_ja":"全負荷時のクラッチ滑りは摩擦板の摩耗を示していた。","ex_vi":"Trượt ly hợp khi chạy đầy tải cho thấy đĩa ma sát đã mòn.","syn_en":["clutch slippage"],"syn_ja":["クラッチの滑り"]},{"en":"spring-applied brake","pos":"noun","ipa":"/ˌsprɪŋ əˈplaɪd breɪk/","ja":"無励磁作動形ブレーキ","kana":"むれいじさどうがたブレーキ","romaji":"mureijisadougatabureeki","vi":"phanh tác động bằng lò xo (phanh an toàn khi mất điện)","level":3,"def_vi":"Phanh luôn được lò xo ép đóng, chỉ nhả khi cuộn dây được cấp điện, nên tự phanh khi mất điện.","def_en":"A brake held on by springs and released only when energized, so it brakes on power loss.","def_ja":"ばねで常時制動し、通電時のみ解放されるため停電時に自動で制動するブレーキ。","usage_en":"Danh từ đếm được. Hay đi với: fail-safe, power-off brake, holding brake; đối lập với power-on brake.","usage_ja":"Còn gọi 無励磁作動ブレーキ, ネガティブ作動形. Đối lập: 励磁作動形ブレーキ.","context_vi":"Dùng trên trục đứng của robot, thang máy, cần trục và các trục cần an toàn khi mất điện.","ex_en":"A spring-applied brake is required on every vertical axis for fail-safe stopping.","ex_ja":"垂直軸にはフェールセーフのため無励磁作動形ブレーキが必須である。","ex_vi":"Mọi trục đứng đều bắt buộc có phanh tác động bằng lò xo để dừng an toàn khi mất điện.","syn_en":["power-off brake","fail-safe brake"],"syn_ja":["無励磁作動ブレーキ","ネガティブ作動形ブレーキ"]},{"en":"brake fade","pos":"noun phrase","ipa":"/ˈbreɪk feɪd/","ja":"フェード","kana":"フェード","romaji":"feedo","vi":"suy giảm phanh do nhiệt (hiện tượng fade)","level":3,"def_vi":"Hiện tượng hệ số ma sát của phanh giảm mạnh khi vật liệu ma sát quá nóng, làm phanh kém ăn.","def_en":"Loss of braking effectiveness caused by the friction coefficient falling at high temperature.","def_ja":"摩擦材の高温化により摩擦係数が低下し、ブレーキの効きが悪くなる現象。","usage_en":"Danh từ không đếm được. Hay đi với: suffer from brake fade, fade resistance, fade test; khác với vapour lock (sôi dầu phanh).","usage_ja":"Hay đi với: フェード現象, フェードが起きる, 耐フェード性. Khác với ベーパーロック.","context_vi":"Dùng khi thử nghiệm phanh xe xuống dốc dài, phanh cần trục và chọn vật liệu ma sát.","ex_en":"Repeated stops from 100 km/h caused severe brake fade.","ex_ja":"100 km/hからの制動を繰り返すと、激しいフェードが発生した。","ex_vi":"Phanh liên tục từ 100 km/h gây ra suy giảm phanh do nhiệt rất nghiêm trọng.","syn_en":["fade"],"syn_ja":["フェード現象"]},{"en":"clutch judder","pos":"noun phrase","ipa":"/ˈklʌtʃ ˌdʒʌdə/","ja":"ジャダー","kana":"ジャダー","romaji":"jadaa","vi":"rung giật ly hợp","level":3,"def_vi":"Rung động tần số thấp khi ly hợp đang đóng, do ma sát biến đổi theo tốc độ trượt hoặc bề mặt không đều.","def_en":"Low-frequency vibration during clutch engagement caused by friction variation or uneven contact.","def_ja":"クラッチ連結時に摩擦変動や当たりの不均一で起こる低周波の振動。","usage_en":"Danh từ không đếm được. Hay đi với: clutch judder on take-off, anti-judder; với phanh dùng brake judder.","usage_ja":"Hay đi với: ジャダーが発生する, 発進時のジャダー, ブレーキジャダー (khi phanh).","context_vi":"Dùng trong thử nghiệm ly hợp ô tô, hộp số tự động và đánh giá dầu ly hợp ướt.","ex_en":"Oil contamination on the facings caused clutch judder when pulling away.","ex_ja":"フェーシングへの油付着が原因で、発進時にジャダーが発生した。","ex_vi":"Dầu dính trên bề mặt bố gây rung giật ly hợp khi xe khởi hành.","syn_en":["judder","shudder"],"syn_ja":["クラッチジャダー"]},{"en":"sprag","pos":"noun","ipa":"/spræɡ/","ja":"スプラグ","kana":"スプラグ","romaji":"supuragu","vi":"con chèn (sprag của ly hợp một chiều)","level":3,"def_vi":"Con chèn hình số tám đặt giữa hai vòng của ly hợp một chiều, nghiêng để khóa khi quay theo một chiều.","def_en":"A figure-eight shaped element between two races that wedges to lock rotation in one direction.","def_ja":"内外輪間に入れた異形のこまで、一方向の回転時にくさび作用でロックする。","usage_en":"Danh từ đếm được. Hay đi với: sprag clutch, sprag-type freewheel, sprag cage.","usage_ja":"Hay đi với: スプラグ形ワンウェイクラッチ, スプラグの傾き. So với ローラ形 truyền mô men lớn hơn.","context_vi":"Dùng trong ly hợp một chiều của bộ đề, hộp số tự động và cơ cấu chống quay ngược.","ex_en":"A worn sprag no longer locked, so the starter spun without turning the engine.","ex_ja":"スプラグが摩耗してロックしなくなり、スタータが空転した。","ex_vi":"Con chèn bị mòn không khóa được nữa nên mô tơ đề quay trơn mà không kéo được động cơ.","syn_en":["sprag element"],"syn_ja":["スプラグ形ワンウェイクラッチ (liên quan)"]},{"en":"hysteresis brake","pos":"noun","ipa":"/ˌhɪstəˈriːsɪs breɪk/","ja":"ヒステリシスブレーキ","kana":"ヒステリシスブレーキ","romaji":"hisuterishisubureeki","vi":"phanh từ trễ","level":3,"def_vi":"Phanh không tiếp xúc tạo mô men nhờ tổn hao từ trễ trong rô to, mô men gần như không phụ thuộc tốc độ.","def_en":"A non-contact brake that produces torque from magnetic hysteresis in a rotor, nearly independent of speed.","def_ja":"ロータの磁気ヒステリシスでトルクを発生する非接触ブレーキ。トルクは回転数にほぼ依存しない。","usage_en":"Danh từ đếm được. Hay đi với: tension control, smooth torque, no wear; điều chỉnh mô men bằng dòng điện.","usage_ja":"Hay đi với: 張力制御, 電流でトルクを調整する, 非接触. Cùng nhóm với ヒステリシスクラッチ.","context_vi":"Dùng để điều khiển lực căng dây, màng phim, cuộn dây điện và trong máy thử mô men.","ex_en":"A hysteresis brake keeps the wire tension constant on the winding machine.","ex_ja":"巻線機ではヒステリシスブレーキで線の張力を一定に保つ。","ex_vi":"Phanh từ trễ giữ lực căng dây không đổi trên máy quấn dây.","syn_en":["magnetic hysteresis brake"],"syn_ja":["ヒステリシスクラッチ (liên quan)"]}]},{"id":29,"words":[{"en":"cam","pos":"noun","ipa":"/kæm/","ja":"カム","kana":"カム","romaji":"kamu","vi":"cam","level":1,"def_vi":"Chi tiết có biên dạng đặc biệt, khi quay hoặc tịnh tiến sẽ đẩy cần theo để tạo ra chuyển động theo quy luật mong muốn.","def_en":"A shaped part that, by rotating or sliding, drives a follower through a required motion.","def_ja":"特殊な輪郭をもち、回転や往復運動により従動節に所定の運動を与える部品。","usage_en":"Danh từ đếm được. Hay đi với: cam profile, cam follower, cam mechanism; động từ: the cam drives / lifts the follower. Đừng nhầm với camshaft (trục cam).","usage_ja":"Hay đi với: カム機構, カムで駆動する, カムを回す. Tên loại ghép phía trước: 板カム, 円筒カム, 溝カム.","context_vi":"Dùng trong máy tự động, máy đóng gói, máy dập, động cơ đốt trong và máy công cụ kiểu cơ.","ex_en":"Each station of the packaging machine is driven by a cam on the main shaft.","ex_ja":"包装機の各ステーションは主軸上のカムで駆動されている。","ex_vi":"Mỗi trạm của máy đóng gói được dẫn động bởi một cam trên trục chính.","syn_en":["cam mechanism (nghĩa rộng hơn)"],"syn_ja":["カム機構 (nghĩa rộng hơn)"]},{"en":"cam follower","pos":"noun","ipa":"/ˈkæm ˌfɒləʊə/","ja":"カムフォロア","kana":"カムフォロア","romaji":"kamuforoa","vi":"cần theo cam (con lăn theo cam)","level":1,"def_vi":"Chi tiết tiếp xúc với biên dạng cam và chuyển động theo nó; trong catalog còn chỉ con lăn có trục dùng làm cần theo.","def_en":"The part that contacts the cam profile and moves according to it; also a stud-type roller bearing used for this.","def_ja":"カム輪郭に接して動く部分。また、そのために使う軸付きのローラ軸受。","usage_en":"Danh từ đếm được. Hay đi với: roller cam follower, stud-type cam follower, follower motion; nói tắt follower.","usage_ja":"Sách cơ cấu học gọi 従動節; catalog và xưởng nói カムフォロア (con lăn có trục ren). Cũng viết カムフォロワ.","context_vi":"Dùng trong cơ cấu cam, băng tải, ray dẫn hướng và các bàn trượt lăn trên ray.","ex_en":"The cam follower was replaced because its outer ring had a flat spot.","ex_ja":"外輪にフラットが生じていたため、カムフォロアを交換した。","ex_vi":"Con lăn theo cam đã được thay vì vòng ngoài của nó bị mòn phẳng một chỗ.","syn_en":["follower"],"syn_ja":["従動節","カムフォロワ"]},{"en":"linkage","pos":"noun","ipa":"/ˈlɪŋkɪdʒ/","ja":"リンク機構","kana":"リンクきこう","romaji":"rinkukikou","vi":"cơ cấu thanh (cơ cấu khâu khớp)","level":1,"def_vi":"Cơ cấu gồm các thanh cứng nối với nhau bằng khớp, dùng để biến đổi và truyền chuyển động.","def_en":"A mechanism of rigid links connected by joints that transforms and transmits motion.","def_ja":"剛体のリンクを対偶で連結し、運動を変換・伝達する機構。","usage_en":"Danh từ đếm được. Hay đi với: four-bar linkage, parallel linkage, linkage design; trong văn kỹ thuật cũng nói link mechanism.","usage_ja":"Hay đi với: 四節リンク機構, 平行リンク機構, リンク機構で動かす. Ngoài xưởng hay nói ngắn リンク.","context_vi":"Dùng trong cần gạt nước, hệ treo xe, máy ép, robot song song và cơ cấu đóng mở.","ex_en":"A simple linkage converts the cylinder stroke into a 90° swing of the gate.","ex_ja":"簡単なリンク機構でシリンダのストロークをゲートの90°の揺動に変換する。","ex_vi":"Một cơ cấu thanh đơn giản biến hành trình xi lanh thành chuyển động lắc 90° của cửa chắn.","syn_en":["link mechanism","bar mechanism"],"syn_ja":["リンク装置","リンク"]},{"en":"link","pos":"noun","ipa":"/lɪŋk/","ja":"リンク","kana":"リンク","romaji":"rinku","vi":"khâu (thanh truyền của cơ cấu)","level":1,"def_vi":"Một vật rắn trong cơ cấu, có các khớp để nối với những khâu khác.","def_en":"A single rigid member of a mechanism with joints that connect it to other members.","def_ja":"機構を構成する一つの剛体部材で、対偶で他の部材とつながる。","usage_en":"Danh từ đếm được. Hay đi với: input link, output link, link length, fixed link; trong cơ cấu học còn gọi member.","usage_ja":"Sách giáo khoa gọi 節 (せつ): 原動節, 従動節, 固定節, 中間節. Ngoài xưởng dùng リンク, リンクアーム.","context_vi":"Dùng khi phân tích, thiết kế cơ cấu thanh và khi gọi tên từng chi tiết trong bản vẽ lắp.","ex_en":"The output link was made longer to increase the swing angle.","ex_ja":"揺動角を大きくするため、出力側のリンクを長くした。","ex_vi":"Khâu ra được làm dài hơn để tăng góc lắc.","syn_en":["member","bar"],"syn_ja":["節","リンクアーム"]},{"en":"crank","pos":"noun","ipa":"/kræŋk/","ja":"クランク","kana":"クランク","romaji":"kuranku","vi":"tay quay","level":1,"def_vi":"Khâu quay toàn vòng quanh một khớp cố định, dùng làm khâu dẫn hoặc khâu bị dẫn trong cơ cấu thanh.","def_en":"A link that makes complete revolutions about a fixed pivot.","def_ja":"固定された軸のまわりを一回転する節。","usage_en":"Danh từ đếm được; cũng là động từ (to crank = quay tay). Hay đi với: crank radius, crank angle, crank arm.","usage_ja":"Hay đi với: クランク半径, クランク角, クランクを回す. Phân biệt với てこ (khâu chỉ lắc, không quay hết vòng).","context_vi":"Dùng trong máy ép trục khuỷu, máy bơm piston, cơ cấu tay quay con trượt và cơ cấu bốn khâu.","ex_en":"The crank radius sets the stroke of the press ram.","ex_ja":"クランク半径でプレスのラムのストロークが決まる。","ex_vi":"Bán kính tay quay quyết định hành trình của đầu búa máy ép.","syn_en":["crank arm"],"syn_ja":["クランクアーム"]},{"en":"rocker","pos":"noun","ipa":"/ˈrɒkə/","ja":"揺動リンク","kana":"ようどうリンク","romaji":"youdourinku","vi":"khâu lắc (cần lắc)","level":1,"def_vi":"Khâu quay qua lại trong một góc giới hạn quanh khớp cố định, không quay được toàn vòng.","def_en":"A link that oscillates through a limited angle about a fixed pivot.","def_ja":"固定軸のまわりを一回転せず、限られた角度で往復回転する節。","usage_en":"Danh từ đếm được. Hay đi với: crank-rocker mechanism, rocker angle, double-rocker; động từ: the rocker swings / oscillates.","usage_ja":"Sách giáo khoa gọi てこ (như てこクランク機構); xưởng nói 揺動リンク hoặc 揺動アーム. Hay đi với: 揺動角.","context_vi":"Dùng trong cơ cấu bốn khâu, cần gạt nước, cơ cấu cấp phôi và máy dệt.","ex_en":"The rocker swings through 60° for each turn of the crank.","ex_ja":"クランクが1回転するごとに、揺動リンクは60°揺れる。","ex_vi":"Với mỗi vòng quay của tay quay, khâu lắc lắc qua một góc 60°.","syn_en":["rocker arm (liên quan)","oscillating link"],"syn_ja":["てこ","揺動アーム"]},{"en":"slider","pos":"noun","ipa":"/ˈslaɪdə/","ja":"スライダ","kana":"スライダ","romaji":"suraida","vi":"con trượt","level":1,"def_vi":"Khâu chuyển động tịnh tiến dọc theo một rãnh hoặc thanh dẫn trong cơ cấu.","def_en":"A link that moves in a straight line along a guide.","def_ja":"案内に沿って直線運動する節。","usage_en":"Danh từ đếm được. Hay đi với: slider-crank, slider block, guide; động từ: the slider reciprocates / slides.","usage_ja":"Còn viết スライダー; sách cơ cấu học gọi すべり子. Hay đi với: スライダが往復する, スライダクランク.","context_vi":"Dùng trong cơ cấu tay quay con trượt, máy ép, máy bơm piston và cơ cấu dẫn hướng.","ex_en":"The slider moves 120 mm between its two end positions.","ex_ja":"スライダは両端位置の間を120 mm移動する。","ex_vi":"Con trượt di chuyển 120 mm giữa hai vị trí biên.","syn_en":["sliding block","crosshead (liên quan)"],"syn_ja":["すべり子","スライダー"]},{"en":"pin joint","pos":"noun","ipa":"/ˈpɪn dʒɔɪnt/","ja":"ピン結合","kana":"ピンけつごう","romaji":"pinketsugou","vi":"khớp bản lề (khớp chốt)","level":1,"def_vi":"Khớp nối hai khâu bằng một chốt, cho phép chúng quay tương đối quanh trục chốt.","def_en":"A joint in which a pin connects two links and lets them rotate relative to each other.","def_ja":"ピンで二つの節をつなぎ、ピンの軸まわりの相対回転を許す結合。","usage_en":"Danh từ đếm được. Trong cơ cấu học gọi revolute joint hoặc turning pair. Hay đi với: clearance in the pin joint, pin and bushing.","usage_ja":"Sách giáo khoa gọi 回り対偶; ngoài xưởng nói ピン結合, ピンジョイント. Hay đi với: ピンとブシュ, ガタ (độ rơ).","context_vi":"Dùng ở mọi cơ cấu thanh, gầu máy xúc, xi lanh có tai treo và bản lề cửa.","ex_en":"Wear in each pin joint adds backlash to the linkage.","ex_ja":"各ピン結合の摩耗がリンク機構のガタを大きくする。","ex_vi":"Mòn ở từng khớp bản lề làm tăng độ rơ của cơ cấu thanh.","syn_en":["revolute joint","hinge joint"],"syn_ja":["回り対偶","ピンジョイント"]},{"en":"eccentric cam","pos":"noun","ipa":"/ɪkˌsentrɪk ˈkæm/","ja":"偏心カム","kana":"へんしんカム","romaji":"henshinkamu","vi":"cam lệch tâm","level":1,"def_vi":"Đĩa tròn quay quanh một trục lệch khỏi tâm của nó, tạo chuyển động qua lại gần dạng hình sin cho cần theo.","def_en":"A circular disc rotating about an off-centre axis, giving the follower a near-sinusoidal motion.","def_ja":"中心から外れた軸で回る円板カムで、従動節にほぼ正弦波の運動を与える。","usage_en":"Danh từ đếm được. Hay đi với: eccentricity, eccentric shaft; khẩu ngữ nói tắt eccentric.","usage_ja":"Hay đi với: 偏心量, 偏心軸, 偏心カムで往復させる. Ngoài xưởng hay nói エキセン.","context_vi":"Dùng trong bơm màng, máy sàng rung, cơ cấu kẹp nhanh và máy ép nhỏ.","ex_en":"An eccentric cam with 3 mm eccentricity drives the pump diaphragm.","ex_ja":"偏心量3 mmの偏心カムでポンプのダイヤフラムを駆動する。","ex_vi":"Một cam lệch tâm có độ lệch 3 mm dẫn động màng bơm.","syn_en":["eccentric","circular cam"],"syn_ja":["エキセン (khẩu ngữ)","円板カム"]},{"en":"cam lift","pos":"noun phrase","ipa":"/ˈkæm lɪft/","ja":"揚程","kana":"ようてい","romaji":"youtei","vi":"độ nâng của cam (hành trình cần theo)","level":1,"def_vi":"Khoảng dịch chuyển lớn nhất của cần theo do cam tạo ra, từ vị trí thấp nhất đến cao nhất.","def_en":"The maximum displacement the cam gives to the follower, from lowest to highest position.","def_ja":"カムが従動節に与える最大変位量で、最下点から最上点までの距離。","usage_en":"Danh từ không đếm được (đếm được khi so sánh nhiều cam). Hay đi với: maximum cam lift, lift curve; nói tắt lift.","usage_ja":"Hay đi với: カムの揚程, 揚程を大きくする. Catalog và động cơ hay dùng リフト, カムリフト.","context_vi":"Dùng khi thiết kế cam, chọn cơ cấu dẫn động và trong động cơ (độ nâng xú páp).","ex_en":"Increasing the cam lift to 25 mm also increases the pressure angle.","ex_ja":"揚程を25 mmに増やすと、圧力角も大きくなる。","ex_vi":"Tăng độ nâng của cam lên 25 mm thì góc áp lực cũng tăng.","syn_en":["lift","follower stroke"],"syn_ja":["リフト","カムリフト"]},{"en":"plate cam","pos":"noun","ipa":"/ˈpleɪt kæm/","ja":"板カム","kana":"いたカム","romaji":"itakamu","vi":"cam đĩa","level":2,"def_vi":"Cam dạng tấm phẳng có biên dạng ở mép ngoài, cần theo chuyển động trong mặt phẳng vuông góc với trục cam.","def_en":"A flat cam with its profile on the outer edge; the follower moves in a plane perpendicular to the camshaft.","def_ja":"外周に輪郭をもつ平板状のカムで、従動節は軸に垂直な平面内で動く。","usage_en":"Danh từ đếm được. Hay đi với: disc cam, radial cam, plate cam profile; là loại cam phổ biến nhất.","usage_ja":"Còn gọi 円板カム, 平板カム. Hay đi với: 板カムの輪郭, 板カムとローラ従動節.","context_vi":"Dùng trong máy đóng gói, máy may, máy dệt và máy tự động kiểu cơ.","ex_en":"A plate cam with a roller follower is the most common cam arrangement.","ex_ja":"板カムとローラ従動節の組合せが最も一般的なカム機構である。","ex_vi":"Cam đĩa kết hợp với cần theo con lăn là kiểu bố trí cam phổ biến nhất.","syn_en":["disc cam","radial cam"],"syn_ja":["円板カム","平板カム"]},{"en":"cylindrical cam","pos":"noun","ipa":"/sɪˌlɪndrɪkl ˈkæm/","ja":"円筒カム","kana":"えんとうカム","romaji":"entoukamu","vi":"cam trụ (cam thùng)","level":2,"def_vi":"Cam hình trụ có rãnh xoắn trên mặt trụ, làm cần theo chuyển động song song với trục cam.","def_en":"A cylinder with a groove on its surface that moves the follower parallel to the cam axis.","def_ja":"円筒面に溝を設け、従動節を軸と平行な方向に動かすカム。","usage_en":"Danh từ đếm được. Hay đi với: barrel cam, drum cam, groove; động từ: the cylindrical cam traverses the carriage.","usage_ja":"Hay đi với: 円筒カムの溝, 円筒カムで往復させる. Một số catalog gọi ドラムカム.","context_vi":"Dùng trong cơ cấu dịch chuyển ngang của máy quấn dây, máy tự động và bộ chuyển dao.","ex_en":"The cylindrical cam moves the winding guide back and forth along the bobbin.","ex_ja":"円筒カムが巻線ガイドをボビンに沿って往復させる。","ex_vi":"Cam trụ đẩy bộ dẫn dây chạy qua lại dọc theo ống cuộn.","syn_en":["barrel cam","drum cam"],"syn_ja":["ドラムカム"]},{"en":"grooved cam","pos":"noun","ipa":"/ˌɡruːvd ˈkæm/","ja":"溝カム","kana":"みぞカム","romaji":"mizokamu","vi":"cam rãnh (cam dẫn cưỡng bức)","level":2,"def_vi":"Cam có rãnh trên mặt đầu, con lăn chạy trong rãnh nên cần theo bị dẫn cưỡng bức theo cả hai chiều mà không cần lò xo.","def_en":"A cam with a groove in its face that guides the roller positively in both directions without a spring.","def_ja":"端面に溝を設け、ばねなしでローラを両方向に確実に案内するカム。","usage_en":"Danh từ đếm được. Hay đi với: face groove cam, positive-motion cam, groove width; khác với cam cần lò xo giữ tiếp xúc.","usage_ja":"Còn gọi 確動カム (nghĩa rộng). Hay đi với: 溝カムの溝幅, ローラが溝内を転がる.","context_vi":"Dùng ở máy tốc độ cao cần cần theo không bị tách khỏi cam, như máy đóng gói và máy dập nhỏ.","ex_en":"A grooved cam was used so that no return spring is needed.","ex_ja":"戻しばねが不要になるよう、溝カムを採用した。","ex_vi":"Đã dùng cam rãnh để không cần lò xo hồi vị.","syn_en":["face groove cam","positive-motion cam (nghĩa rộng hơn)"],"syn_ja":["確動カム (nghĩa rộng hơn)","正面溝カム"]},{"en":"roller follower","pos":"noun","ipa":"/ˈrəʊlə ˌfɒləʊə/","ja":"ローラ従動節","kana":"ローラじゅうどうせつ","romaji":"roorajuudousetsu","vi":"cần theo con lăn","level":2,"def_vi":"Cần theo có con lăn ở đầu tiếp xúc với cam, giảm ma sát và mòn so với tiếp xúc trượt.","def_en":"A follower with a roller that rolls on the cam, reducing friction and wear.","def_ja":"先端のローラがカム面を転がる従動節で、摩擦と摩耗が少ない。","usage_en":"Danh từ đếm được. Hay đi với: roller radius, roller follower arm; so sánh với flat-faced follower, knife-edge follower.","usage_ja":"Ngoài xưởng nói ローラフォロア hoặc chỉ カムフォロア. Hay đi với: ローラ径, ローラの滑り.","context_vi":"Dùng trong hầu hết cơ cấu cam công nghiệp, máy tự động và cò mổ động cơ.","ex_en":"The roller follower radius must be smaller than the smallest convex radius of the cam.","ex_ja":"ローラ従動節の半径はカムの凸部の最小曲率半径より小さくしなければならない。","ex_vi":"Bán kính cần theo con lăn phải nhỏ hơn bán kính cong lồi nhỏ nhất của cam.","syn_en":["roller cam follower"],"syn_ja":["ローラフォロア","カムフォロア"]},{"en":"flat-faced follower","pos":"noun","ipa":"/ˌflæt ˈfeɪst ˈfɒləʊə/","ja":"平面従動節","kana":"へいめんじゅうどうせつ","romaji":"heimenjuudousetsu","vi":"cần theo đáy bằng","level":2,"def_vi":"Cần theo có mặt phẳng tiếp xúc với cam, chịu được lực ngang tốt và gọn, nhưng ma sát trượt lớn hơn con lăn.","def_en":"A follower with a flat contact face, compact and stiff but with sliding friction.","def_ja":"平らな面でカムと接する従動節。小形で剛性が高いが滑り摩擦がある。","usage_en":"Danh từ đếm được. Hay đi với: mushroom follower, tappet; yêu cầu cam không có đoạn lõm.","usage_ja":"Hay đi với: 平面従動節では凹のカム輪郭は使えない. Trong động cơ gọi タペット hoặc バルブリフタ.","context_vi":"Dùng trong cơ cấu xú páp động cơ (con đội) và cam nhỏ gọn chịu tải cao.","ex_en":"With a flat-faced follower, the cam profile must have no concave sections.","ex_ja":"平面従動節を使う場合、カム輪郭に凹部があってはならない。","ex_vi":"Khi dùng cần theo đáy bằng, biên dạng cam không được có đoạn lõm.","syn_en":["flat follower","tappet (động cơ)"],"syn_ja":["平板従動節","タペット (động cơ)"]},{"en":"cam profile","pos":"noun phrase","ipa":"/ˈkæm ˌprəʊfaɪl/","ja":"カム輪郭","kana":"カムりんかく","romaji":"kamurinkaku","vi":"biên dạng cam","level":2,"def_vi":"Đường viền làm việc của cam, quyết định quy luật chuyển động của cần theo.","def_en":"The working contour of a cam, which determines the follower motion.","def_ja":"従動節の運動を決める、カムの作用面の形状。","usage_en":"Danh từ đếm được. Hay đi với: design / machine / grind the cam profile, profile error, pitch curve.","usage_ja":"Hay đi với: カム輪郭を設計する, 輪郭を研削する, カム輪郭の誤差. Còn gọi カムプロフィール.","context_vi":"Dùng khi thiết kế cam bằng CAD, lập trình gia công cam trên máy CNC và kiểm tra cam.","ex_en":"The cam profile was generated from the displacement diagram in CAD.","ex_ja":"カム輪郭はCADで変位線図から作成した。","ex_vi":"Biên dạng cam được tạo từ biểu đồ chuyển vị trong CAD.","syn_en":["cam contour"],"syn_ja":["カムプロフィール","カム曲面 (liên quan)"]},{"en":"displacement diagram","pos":"noun phrase","ipa":"/dɪsˈpleɪsmənt ˌdaɪəɡræm/","ja":"変位線図","kana":"へんいせんず","romaji":"hen'isenzu","vi":"biểu đồ chuyển vị (của cần theo)","level":2,"def_vi":"Đồ thị biểu diễn chuyển vị của cần theo theo góc quay của cam trong một chu kỳ.","def_en":"A graph of follower displacement against cam angle over one cycle.","def_ja":"カム1回転中の回転角に対する従動節の変位を表した線図。","usage_en":"Danh từ đếm được. Hay đi với: rise, dwell, return, draw / plot the displacement diagram; đi cùng velocity / acceleration diagrams.","usage_ja":"Hay đi với: 変位線図を描く, 速度線図, 加速度線図. Ngoài xưởng hay gọi chung カム線図.","context_vi":"Dùng ở bước đầu thiết kế cam và khi phối hợp thời điểm giữa các trạm của máy tự động.","ex_en":"The displacement diagram shows a 120° rise, a 60° dwell and a 120° return.","ex_ja":"変位線図には120°の上昇、60°の停留、120°の下降が示されている。","ex_vi":"Biểu đồ chuyển vị cho thấy 120° đi lên, 60° đứng yên và 120° đi về.","syn_en":["cam diagram","lift curve"],"syn_ja":["カム線図"]},{"en":"dwell","pos":"noun","ipa":"/dwel/","ja":"ドウェル","kana":"ドウェル","romaji":"doweru","vi":"giai đoạn đứng yên (của cần theo)","level":2,"def_vi":"Khoảng góc quay của cam trong đó cần theo đứng yên dù cam vẫn quay.","def_en":"A part of the cam cycle in which the follower stays stationary while the cam keeps turning.","def_ja":"カムは回転しているが従動節が静止している区間。","usage_en":"Danh từ đếm được; cũng là động từ (the follower dwells). Hay đi với: dwell period, dwell angle, rise-dwell-return.","usage_ja":"Văn bản Nhật hay dùng 停留 hoặc 休止区間; catalog bộ chia độ dùng ドウェル (ドエル). Hay đi với: ドウェル角.","context_vi":"Dùng khi thiết kế cam, bộ chia độ và phối hợp thời gian giữa các thao tác của máy tự động.","ex_en":"The dwell gives the gripper 0.2 s to close before the transfer starts.","ex_ja":"このドウェルにより、搬送開始前にグリッパが閉じる時間を0.2 s確保している。","ex_vi":"Giai đoạn đứng yên cho tay kẹp 0,2 giây để đóng trước khi bắt đầu chuyển phôi.","syn_en":["dwell period","rest period"],"syn_ja":["停留","休止区間"]},{"en":"four-bar linkage","pos":"noun","ipa":"/ˌfɔː bɑː ˈlɪŋkɪdʒ/","ja":"四節リンク機構","kana":"よんせつリンクきこう","romaji":"yonsetsurinkukikou","vi":"cơ cấu bốn khâu bản lề","level":2,"def_vi":"Cơ cấu gồm bốn khâu nối nhau bằng bốn khớp bản lề, trong đó một khâu cố định; là cơ cấu thanh cơ bản nhất.","def_en":"A mechanism of four links joined by four pin joints, one link being fixed.","def_ja":"四つの節を四つの回り対偶で連結し、一つを固定した基本的なリンク機構。","usage_en":"Danh từ đếm được. Hay đi với: crank-rocker, double-crank, double-rocker, coupler curve, Grashof's condition.","usage_ja":"Còn gọi 四節回転機構 hoặc 4節リンク. Ba dạng: てこクランク機構, 両クランク機構, 両てこ機構.","context_vi":"Dùng trong cần gạt nước, bản lề tủ, hệ treo xe và máy nông nghiệp.","ex_en":"The wiper drive is a four-bar linkage of the crank-rocker type.","ex_ja":"ワイパの駆動部はてこクランク形の四節リンク機構である。","ex_vi":"Bộ dẫn động gạt nước là một cơ cấu bốn khâu bản lề kiểu tay quay – cần lắc.","syn_en":["four-bar mechanism","quadric chain"],"syn_ja":["4節リンク","四節回転機構"]},{"en":"slider-crank mechanism","pos":"noun","ipa":"/ˌslaɪdə ˈkræŋk ˌmekənɪzəm/","ja":"スライダクランク機構","kana":"スライダクランクきこう","romaji":"suraidakurankukikou","vi":"cơ cấu tay quay con trượt","level":2,"def_vi":"Cơ cấu gồm tay quay, thanh truyền và con trượt, biến chuyển động quay thành tịnh tiến qua lại hoặc ngược lại.","def_en":"A crank, connecting rod and slider that convert rotation into reciprocating motion or vice versa.","def_ja":"クランク、連接棒、スライダからなり、回転運動と往復直線運動を相互に変換する機構。","usage_en":"Danh từ đếm được. Hay đi với: offset slider-crank, stroke, crank angle; trong động cơ gọi crank mechanism.","usage_ja":"Còn gọi ピストンクランク機構 hoặc 往復スライダクランク機構. Hay đi với: ストローク, クランク角.","context_vi":"Dùng trong động cơ đốt trong, máy nén piston, máy ép trục khuỷu và máy cưa lọng.","ex_en":"The press uses a slider-crank mechanism with a 100 mm stroke.","ex_ja":"このプレスはストローク100 mmのスライダクランク機構を使っている。","ex_vi":"Máy ép này dùng cơ cấu tay quay con trượt có hành trình 100 mm.","syn_en":["crank-slider mechanism","piston-crank mechanism"],"syn_ja":["ピストンクランク機構"]},{"en":"toggle mechanism","pos":"noun","ipa":"/ˈtɒɡl ˌmekənɪzəm/","ja":"トグル機構","kana":"トグルきこう","romaji":"togurukikou","vi":"cơ cấu khuỷu (cơ cấu toggle)","level":2,"def_vi":"Cơ cấu hai thanh nối khớp, khi gần thẳng hàng tạo lực đầu ra rất lớn từ lực đầu vào nhỏ.","def_en":"Two links that, as they approach a straight line, give a very large output force from a small input.","def_ja":"二つのリンクが一直線に近づくと、小さな入力で非常に大きな力が得られる機構。","usage_en":"Danh từ đếm được. Hay đi với: toggle clamp, toggle press, toggle joint, mechanical advantage; động từ: the toggle locks over centre.","usage_ja":"Hay đi với: トグル式型締め, トグルクランプ, トグルプレス. Ngoài xưởng nói ngắn トグル.","context_vi":"Dùng trong cụm kẹp khuôn máy ép phun, máy ép, kìm bấm, kẹp nhanh và máy dập đồng xu.","ex_en":"The injection machine clamps the mould with a five-point toggle mechanism.","ex_ja":"この射出成形機は5点式のトグル機構で金型を型締めする。","ex_vi":"Máy ép phun này kẹp khuôn bằng cơ cấu khuỷu năm điểm.","syn_en":["toggle joint","toggle linkage"],"syn_ja":["トグルリンク","倍力機構 (nghĩa rộng hơn)"]},{"en":"Scotch yoke","pos":"noun","ipa":"/ˌskɒtʃ ˈjəʊk/","ja":"スコッチヨーク","kana":"スコッチヨーク","romaji":"sukotchiyooku","vi":"cơ cấu culít chữ thập (cơ cấu Scotch yoke)","level":2,"def_vi":"Cơ cấu trong đó chốt trên tay quay trượt trong rãnh của một khâu tịnh tiến, tạo chuyển động điều hòa hình sin.","def_en":"A mechanism in which a crank pin slides in a slotted yoke, giving pure sinusoidal reciprocating motion.","def_ja":"クランクピンがヨークの溝内を滑り、正弦的な往復運動を生じる機構。","usage_en":"Danh từ đếm được; viết hoa Scotch. Hay đi với: slotted yoke, simple harmonic motion, Scotch yoke actuator.","usage_ja":"Thường viết katakana. Hay đi với: スコッチヨーク式アクチュエータ, 単振動.","context_vi":"Dùng trong bộ truyền động van bướm, máy thử rung, bơm nhỏ và máy tạo dao động hình sin.","ex_en":"The valve actuator uses a Scotch yoke to give high torque at both ends of travel.","ex_ja":"このバルブアクチュエータはスコッチヨークで両端位置での高トルクを得ている。","ex_vi":"Bộ truyền động van dùng cơ cấu Scotch yoke để có mô men lớn ở cả hai đầu hành trình.","syn_en":["slotted link mechanism"],"syn_ja":["ヨーク式機構"]},{"en":"quick-return mechanism","pos":"noun","ipa":"/ˌkwɪk rɪˈtɜːn ˌmekənɪzəm/","ja":"早戻り機構","kana":"はやもどりきこう","romaji":"hayamodorikikou","vi":"cơ cấu hồi nhanh","level":2,"def_vi":"Cơ cấu thanh có hành trình về nhanh hơn hành trình làm việc, giúp giảm thời gian chạy không.","def_en":"A linkage whose return stroke is faster than its working stroke, reducing idle time.","def_ja":"戻り行程が切削など作業行程より速くなるリンク機構。","usage_en":"Danh từ đếm được. Hay đi với: time ratio, Whitworth quick-return, crank-and-slotted-lever; thường dùng ví dụ máy bào.","usage_ja":"Hay đi với: 早戻り比 (tỉ số thời gian), 揺動スライダクランク機構. Ví dụ kinh điển: 形削り盤.","context_vi":"Dùng trong máy bào ngang, máy xọc và các máy có hành trình làm việc chậm, về nhanh.","ex_en":"The shaper uses a quick-return mechanism with a time ratio of 1.6.","ex_ja":"形削り盤には時間比1.6の早戻り機構が使われている。","ex_vi":"Máy bào ngang dùng cơ cấu hồi nhanh có tỉ số thời gian 1,6.","syn_en":["quick-return motion","Whitworth mechanism (một dạng)"],"syn_ja":["早戻し機構"]},{"en":"bell crank","pos":"noun","ipa":"/ˈbel kræŋk/","ja":"ベルクランク","kana":"ベルクランク","romaji":"berukuranku","vi":"tay đòn góc (cần chữ L)","level":2,"def_vi":"Đòn bẩy hai tay hợp góc (thường 90°) quay quanh một chốt giữa, dùng để đổi hướng chuyển động hoặc lực.","def_en":"A two-armed lever, usually at 90°, pivoted at the corner to change the direction of motion or force.","def_ja":"角で支点をもつ二本腕のレバー（多くは90°）で、運動や力の方向を変える。","usage_en":"Danh từ đếm được; cũng viết bellcrank. Hay đi với: bell crank lever, pivot, arm ratio.","usage_ja":"Hay đi với: ベルクランクで方向を変える, L形レバー. Sách giáo khoa còn gọi 直角てこ.","context_vi":"Dùng trong cơ cấu điều khiển máy bay, hệ treo đẩy-kéo xe đua, cơ cấu cần số và dây ga.","ex_en":"A bell crank turns the vertical rod motion into horizontal movement of the latch.","ex_ja":"ベルクランクでロッドの上下運動をラッチの水平移動に変える。","ex_vi":"Tay đòn góc biến chuyển động lên xuống của thanh thành chuyển động ngang của chốt khóa.","syn_en":["bellcrank lever","angle lever"],"syn_ja":["L形レバー","直角てこ"]},{"en":"roller gear cam","pos":"noun","ipa":"/ˈrəʊlə ɡɪə ˌkæm/","ja":"ローラギヤカム","kana":"ローラギヤカム","romaji":"rooragiyakamu","vi":"cam bánh răng con lăn (cam chia độ)","level":3,"def_vi":"Cam dạng trục có gờ xoắn ăn khớp với các con lăn trên tháp quay, tạo chuyển động chia độ không rơ.","def_en":"A globoidal cam with a ridge that engages rollers on a turret, giving backlash-free indexing.","def_ja":"鼓形のカムのリブがタレットのローラとかみ合い、バックラッシのない割出しを行うカム。","usage_en":"Danh từ đếm được. Hay đi với: globoidal cam, indexing drive, number of stops, preload; là lõi của bộ chia độ cam.","usage_ja":"Hay đi với: ローラギヤカム式インデックスユニット, 割出し数, 予圧. Là tên thương mại phổ biến ở Nhật.","context_vi":"Dùng trong bàn chia độ của máy lắp ráp tự động, máy đóng gói và bộ thay dao ATC.","ex_en":"The 8-station rotary table is driven by a roller gear cam with preloaded rollers.","ex_ja":"8ステーションの回転テーブルは、予圧をかけたローラギヤカムで駆動される。","ex_vi":"Bàn xoay 8 trạm được dẫn động bằng cam bánh răng con lăn có con lăn được tạo tải trước.","syn_en":["globoidal cam","index cam (nghĩa rộng hơn)"],"syn_ja":["鼓形カム","インデックスカム (nghĩa rộng hơn)"]},{"en":"Grashof's condition","pos":"noun phrase","ipa":"/ˈɡræshɒfs kənˌdɪʃn/","ja":"グラスホフの条件","kana":"グラスホフのじょうけん","romaji":"gurasuhofunojouken","vi":"điều kiện Grashof (điều kiện quay toàn vòng)","level":3,"def_vi":"Điều kiện cho cơ cấu bốn khâu: tổng khâu ngắn nhất và dài nhất không lớn hơn tổng hai khâu còn lại thì có khâu quay toàn vòng.","def_en":"A four-bar linkage has a fully rotating link if the shortest plus longest link ≤ the sum of the other two.","def_ja":"最短節と最長節の和が他の二節の和以下なら、四節機構に一回転できる節が存在するという条件。","usage_en":"Danh từ đếm được; viết hoa Grashof. Hay đi với: satisfy Grashof's condition, Grashof linkage, non-Grashof.","usage_ja":"Hay đi với: グラスホフの条件を満たす, グラスホフの定理. Dùng để phân loại てこクランク, 両クランク, 両てこ.","context_vi":"Dùng khi tổng hợp và kiểm tra cơ cấu bốn khâu ở giai đoạn thiết kế.","ex_en":"The proposed link lengths do not satisfy Grashof's condition, so the crank cannot rotate fully.","ex_ja":"提案されたリンク長はグラスホフの条件を満たさないため、クランクが一回転できない。","ex_vi":"Các chiều dài khâu được đề xuất không thỏa điều kiện Grashof nên tay quay không thể quay toàn vòng.","syn_en":["Grashof criterion","Grashof's law"],"syn_ja":["グラスホフの定理"]},{"en":"transmission angle","pos":"noun phrase","ipa":"/trænzˈmɪʃn ˌæŋɡl/","ja":"伝達角","kana":"でんたつかく","romaji":"dentatsukaku","vi":"góc truyền","level":3,"def_vi":"Góc giữa thanh truyền và khâu bị dẫn trong cơ cấu thanh; càng gần 90° thì truyền lực càng tốt.","def_en":"The angle between the coupler and the output link; values near 90° give the best force transmission.","def_ja":"中間節と出力節のなす角で、90°に近いほど力の伝達がよい。","usage_en":"Danh từ đếm được, ký hiệu μ. Hay đi với: minimum transmission angle, keep the transmission angle above 40°.","usage_ja":"Ký hiệu μ. Hay đi với: 最小伝達角, 伝達角が小さいと動きが渋る. Với cam dùng khái niệm tương tự là 圧力角.","context_vi":"Dùng khi thiết kế, kiểm tra cơ cấu thanh để tránh kẹt và lực ổ khớp quá lớn.","ex_en":"The minimum transmission angle should not fall below 40°.","ex_ja":"最小伝達角は40°を下回らないようにすべきである。","ex_vi":"Góc truyền nhỏ nhất không nên thấp hơn 40°.","syn_en":["pressure angle (liên quan, cho cam)"],"syn_ja":["圧力角 (liên quan)"]},{"en":"modified sine curve","pos":"noun phrase","ipa":"/ˌmɒdɪfaɪd ˈsaɪn kɜːv/","ja":"変形正弦曲線","kana":"へんけいせいげんきょくせん","romaji":"henkeiseigenkyokusen","vi":"đường cong sin biến dạng (quy luật MS)","level":3,"def_vi":"Quy luật chuyển động cam ghép từ các đoạn sin, có gia tốc lớn nhất nhỏ và vận tốc vừa phải, phù hợp tốc độ cao.","def_en":"A cam motion law built from sine segments, giving low peak acceleration for high-speed use.","def_ja":"正弦曲線を組み合わせたカム曲線で、最大加速度が小さく高速用に適する。","usage_en":"Danh từ đếm được; viết tắt MS. Hay đi với: cam motion law, peak acceleration, compared with cycloidal motion.","usage_ja":"Gọi tắt MS曲線. Hay đi với: 変形正弦曲線を採用する, 無次元加速度. Phổ biến trong インデックスユニット.","context_vi":"Dùng khi chọn quy luật chuyển động cho cam và bộ chia độ tốc độ cao.","ex_en":"The index drive uses a modified sine curve to limit vibration at the stop position.","ex_ja":"停止位置での振動を抑えるため、割出し装置には変形正弦曲線を用いている。","ex_vi":"Bộ chia độ dùng đường cong sin biến dạng để hạn chế rung tại vị trí dừng.","syn_en":["MS curve","modified sinusoidal motion"],"syn_ja":["MS曲線"]},{"en":"cycloidal motion","pos":"noun phrase","ipa":"/saɪˌklɔɪdl ˈməʊʃn/","ja":"サイクロイド曲線","kana":"サイクロイドきょくせん","romaji":"saikuroidokyokusen","vi":"quy luật chuyển động xycloit","level":3,"def_vi":"Quy luật chuyển động cam có gia tốc bằng không ở đầu và cuối hành trình, không gây xung giật.","def_en":"A cam motion law with zero acceleration at both ends of the rise, so there is no jerk shock.","def_ja":"行程の始点と終点で加速度がゼロとなり、衝撃のないカム曲線。","usage_en":"Danh từ không đếm được. Hay đi với: cycloidal motion law, cycloidal cam, zero end acceleration.","usage_ja":"Hay đi với: サイクロイド曲線のカム, 加速度連続. So với 変形正弦曲線 thì gia tốc lớn nhất cao hơn.","context_vi":"Dùng trong thiết kế cam tốc độ cao, cam chia độ và cơ cấu cần chuyển động êm.","ex_en":"Cycloidal motion was chosen for the rise to avoid shock at the start of the stroke.","ex_ja":"行程開始時の衝撃を避けるため、上昇区間にサイクロイド曲線を選んだ。","ex_vi":"Đã chọn quy luật chuyển động xycloit cho đoạn đi lên để tránh va đập khi bắt đầu hành trình.","syn_en":["cycloidal cam curve"],"syn_ja":["サイクロイドカム曲線"]},{"en":"follower jump","pos":"noun phrase","ipa":"/ˈfɒləʊə dʒʌmp/","ja":"跳躍","kana":"ちょうやく","romaji":"chouyaku","vi":"hiện tượng cần theo bị nảy (tách khỏi cam)","level":3,"def_vi":"Hiện tượng cần theo tách khỏi bề mặt cam ở tốc độ cao khi lực quán tính vượt lực lò xo giữ tiếp xúc.","def_en":"Separation of the follower from the cam at high speed when inertia force exceeds the spring force.","def_ja":"高速時に慣性力がばね力を上回り、従動節がカム面から離れる現象。","usage_en":"Danh từ không đếm được. Hay đi với: prevent follower jump, jump speed, stiffer return spring; trong động cơ gọi valve float.","usage_ja":"Hay đi với: 従動節の跳躍, 跳躍を防ぐ, ばね力不足. Ngoài xưởng hay nói 浮き上がり hoặc ジャンプ.","context_vi":"Dùng khi phân tích động lực học cơ cấu cam tốc độ cao và chọn lò xo giữ cần theo.","ex_en":"Follower jump occurred above 400 cycles per minute and damaged the cam surface.","ex_ja":"毎分400サイクルを超えると従動節の跳躍が起こり、カム面が損傷した。","ex_vi":"Trên 400 chu kỳ/phút, cần theo bị nảy khỏi cam và làm hỏng bề mặt cam.","syn_en":["follower separation","valve float (động cơ)"],"syn_ja":["浮き上がり","ジャンプ"]}]},{"id":30,"words":[{"en":"weld","pos":"noun","ipa":"/weld/","ja":"溶接部","kana":"ようせつぶ","romaji":"yousetsubu","vi":"mối hàn","level":1,"def_vi":"Phần kim loại được nóng chảy rồi đông đặc để nối các chi tiết với nhau thành một khối liền.","def_en":"The region where metal has been melted and solidified to join parts into one piece.","def_ja":"金属を溶かして凝固させ、部材を一体に接合した部分。","usage_en":"Danh từ đếm được; cũng là động từ (to weld = hàn). Hay đi với: weld size, weld quality, inspect / grind the weld; số nhiều welds.","usage_ja":"Hay đi với: 溶接部を検査する, 溶接部の割れ. Động từ là 溶接する; ngoài xưởng hay nói 溶接 cho cả mối hàn.","context_vi":"Dùng trong kết cấu thép, khung máy, bình áp lực, đường ống và bản vẽ chế tạo.","ex_en":"Grind the weld flush before painting the frame.","ex_ja":"フレームを塗装する前に溶接部を平らに研削する。","ex_vi":"Mài phẳng mối hàn trước khi sơn khung.","syn_en":["weldment (cụm hàn)","welded seam"],"syn_ja":["溶接箇所","溶接 (khẩu ngữ)"]},{"en":"welded joint","pos":"noun","ipa":"/ˌweldɪd ˈdʒɔɪnt/","ja":"溶接継手","kana":"ようせつつぎて","romaji":"yousetsutsugite","vi":"mối ghép hàn","level":1,"def_vi":"Mối ghép giữa các chi tiết được nối bằng hàn, gồm cả mối hàn và vùng kim loại cơ bản lân cận.","def_en":"A joint between parts that are connected by welding, including the weld and nearby base metal.","def_ja":"溶接によって部材を接合した継手で、溶接部と周辺の母材を含む。","usage_en":"Danh từ đếm được. Hay đi với: welded joint design, type of welded joint (butt, lap, T, corner), joint strength.","usage_ja":"Hay đi với: 溶接継手の形式 (突合せ継手, 重ね継手, T継手, かど継手), 継手強度.","context_vi":"Dùng khi thiết kế kết cấu hàn, tính bền và chọn kiểu ghép trên bản vẽ.","ex_en":"A welded joint is cheaper than a bolted one but cannot be dismantled.","ex_ja":"溶接継手はボルト継手より安価だが、分解できない。","ex_vi":"Mối ghép hàn rẻ hơn mối ghép bu lông nhưng không tháo ra được.","syn_en":["weld joint"],"syn_ja":["溶接接合部"]},{"en":"rivet","pos":"noun","ipa":"/ˈrɪvɪt/","ja":"リベット","kana":"リベット","romaji":"ribetto","vi":"đinh tán","level":1,"def_vi":"Chốt kim loại có mũ, xỏ qua lỗ các tấm rồi tán đầu còn lại để ghép cố định.","def_en":"A headed metal pin passed through holes in parts and deformed at the other end to hold them permanently.","def_ja":"頭付きの金属ピンを部材の穴に通し、反対側をかしめて永久に締結する部品。","usage_en":"Danh từ đếm được; cũng là động từ (to rivet = tán đinh). Hay đi với: rivet head, rivet hole, drive / set / drill out a rivet.","usage_ja":"Hay đi với: リベットを打つ, リベットでかしめる, リベット頭. JIS gọi theo dạng đầu: 丸リベット, 皿リベット.","context_vi":"Dùng trong vỏ máy bay, kết cấu thép cũ, thùng xe, tủ điện và đồ dùng kim loại tấm.","ex_en":"The aircraft skin is fastened to the frame with countersunk rivets.","ex_ja":"機体外板は皿リベットでフレームに取り付けられている。","ex_vi":"Vỏ máy bay được ghép vào khung bằng đinh tán đầu chìm.","syn_en":["solid rivet (loại đặc)"],"syn_ja":["鋲 (びょう, cũ)"]},{"en":"adhesive","pos":"noun","ipa":"/ədˈhiːsɪv/","ja":"接着剤","kana":"せっちゃくざい","romaji":"setchakuzai","vi":"keo dán (chất kết dính)","level":1,"def_vi":"Chất dùng để dán dính hai bề mặt với nhau nhờ lực bám dính và độ bền của lớp keo sau khi đóng rắn.","def_en":"A substance that joins two surfaces by adhesion and the strength of the cured layer.","def_ja":"硬化後の層の強さと付着力で二つの面を接合する物質。","usage_en":"Danh từ đếm được hoặc không đếm được; cũng là tính từ (adhesive tape). Hay đi với: apply adhesive, two-part adhesive, adhesive layer, bond line.","usage_ja":"Hay đi với: 接着剤を塗布する, 二液形接着剤, 接着剤が硬化する. Ngoài xưởng hay gọi ボンド (tên thương mại).","context_vi":"Dùng trong lắp ráp ô tô, điện tử, máy bay, gắn nam châm động cơ và dán vật liệu khác loại.","ex_en":"The magnets are fixed to the rotor with a heat-resistant adhesive.","ex_ja":"磁石は耐熱性の接着剤でロータに固定されている。","ex_vi":"Các nam châm được gắn vào rô to bằng keo dán chịu nhiệt.","syn_en":["glue (khẩu ngữ)","bonding agent"],"syn_ja":["ボンド (khẩu ngữ)","のり (khẩu ngữ, loại yếu)"]},{"en":"weld bead","pos":"noun","ipa":"/ˈweld biːd/","ja":"溶接ビード","kana":"ようせつビード","romaji":"yousetsubiido","vi":"đường hàn (vảy hàn)","level":1,"def_vi":"Dải kim loại đắp lên sau một lượt hàn, nhìn thấy trên bề mặt mối hàn.","def_en":"The strip of deposited metal formed by one welding pass.","def_ja":"1回の溶接パスで形成される溶着金属の帯状の盛り上がり。","usage_en":"Danh từ đếm được. Hay đi với: bead width, bead appearance, run a bead; khẩu ngữ nói tắt bead.","usage_ja":"Ngoài xưởng nói ビード. Hay đi với: ビード幅, ビード外観, ビードを置く.","context_vi":"Dùng khi kiểm tra ngoại quan mối hàn, đào tạo thợ hàn và đánh giá quy trình hàn.","ex_en":"The weld bead should be uniform in width with no undercut at the edges.","ex_ja":"溶接ビードは幅が均一で、端部にアンダカットがないこと。","ex_vi":"Đường hàn phải có bề rộng đều và không bị cháy cạnh ở mép.","syn_en":["bead","weld run"],"syn_ja":["ビード"]},{"en":"fillet weld","pos":"noun","ipa":"/ˈfɪlɪt weld/","ja":"すみ肉溶接","kana":"すみにくようせつ","romaji":"suminikuyousetsu","vi":"hàn góc (mối hàn góc)","level":1,"def_vi":"Mối hàn có tiết diện gần tam giác, nối hai bề mặt đặt vuông góc hoặc chồng lên nhau.","def_en":"A weld of roughly triangular section joining two surfaces at an angle, as in T- or lap joints.","def_ja":"ほぼ三角形断面で、直角や重ねに置いた二面を接合する溶接。","usage_en":"Danh từ đếm được. Hay đi với: fillet weld size, leg length, throat, continuous / intermittent fillet weld.","usage_ja":"JIS viết すみ肉溶接 (隅肉溶接). Hay đi với: 脚長, のど厚, 断続すみ肉溶接. Ngoài xưởng nói すみ肉.","context_vi":"Là loại mối hàn phổ biến nhất trong khung máy, kết cấu thép, giá đỡ và gân tăng cứng.","ex_en":"The bracket is attached with a 6 mm fillet weld on both sides.","ex_ja":"ブラケットは両側とも脚長6 mmのすみ肉溶接で取り付ける。","ex_vi":"Tai đỡ được hàn bằng mối hàn góc 6 mm ở cả hai phía.","syn_en":["fillet"],"syn_ja":["隅肉溶接","すみ肉 (khẩu ngữ)"]},{"en":"butt weld","pos":"noun","ipa":"/ˈbʌt weld/","ja":"突合せ溶接","kana":"つきあわせようせつ","romaji":"tsukiawaseyousetsu","vi":"hàn giáp mối","level":1,"def_vi":"Mối hàn nối hai chi tiết đặt đối đầu nhau trên cùng một mặt phẳng, thường có vát mép.","def_en":"A weld joining two parts placed edge to edge in the same plane, often with a prepared groove.","def_ja":"二つの部材を同一平面上で突き合わせて接合する溶接。開先を設けることが多い。","usage_en":"Danh từ đếm được. Hay đi với: butt weld of pipes, groove, full penetration butt weld; Mỹ hay dùng groove weld.","usage_ja":"Hay đi với: 突合せ溶接継手, 開先, 裏当て. Theo JIS mối hàn có vát mép gọi chính xác là グルーブ溶接.","context_vi":"Dùng trong nối ống, bình áp lực, dầm thép và tấm vỏ tàu.","ex_en":"All pipe butt welds must be radiographed.","ex_ja":"配管の突合せ溶接はすべて放射線透過試験を行うこと。","ex_vi":"Tất cả các mối hàn giáp mối của đường ống phải được chụp phim.","syn_en":["groove weld (Mỹ)"],"syn_ja":["グルーブ溶接","突合せ溶接継手"]},{"en":"lap joint","pos":"noun","ipa":"/ˈlæp dʒɔɪnt/","ja":"重ね継手","kana":"かさねつぎて","romaji":"kasanetsugite","vi":"mối ghép chồng","level":1,"def_vi":"Kiểu mối ghép trong đó hai tấm đặt chồng một phần lên nhau rồi hàn, tán hoặc dán.","def_en":"A joint in which two plates overlap and are welded, riveted or bonded.","def_ja":"二枚の板を一部重ね合わせ、溶接・リベット・接着で接合する継手。","usage_en":"Danh từ đếm được. Hay đi với: overlap length, single / double lap joint, lap shear test.","usage_ja":"Hay đi với: 重ね代 (độ chồng), 重ね継手のすみ肉溶接, 重ね合わせ. Khi dán gọi 重ね合わせ接着.","context_vi":"Dùng trong kết cấu tấm mỏng, thân xe, ghép đinh tán và mối dán keo.","ex_en":"Adhesives work best in a lap joint where the load is carried in shear.","ex_ja":"接着剤は荷重をせん断で受ける重ね継手で最もよく機能する。","ex_vi":"Keo dán phát huy tốt nhất ở mối ghép chồng, nơi tải được truyền dưới dạng cắt.","syn_en":["overlap joint"],"syn_ja":["重ね合わせ継手"]},{"en":"blind rivet","pos":"noun","ipa":"/ˈblaɪnd ˌrɪvɪt/","ja":"ブラインドリベット","kana":"ブラインドリベット","romaji":"buraindoribetto","vi":"đinh rút (rivê rút)","level":1,"def_vi":"Đinh tán có lõi kéo, lắp và tán được chỉ từ một phía của chi tiết bằng kìm rút.","def_en":"A rivet with a mandrel that is installed and set from one side using a rivet gun.","def_ja":"マンドレルを引き抜いて、片側からだけで取り付けられるリベット。","usage_en":"Danh từ đếm được. Hay đi với: pop rivet (khẩu ngữ), mandrel, grip range, rivet gun; động từ: pull / set a blind rivet.","usage_ja":"Ngoài xưởng gọi ポップリベット (tên thương mại). Hay đi với: リベッタ (kìm rút), 板厚範囲, マンドレル.","context_vi":"Dùng trong tủ điện, ống gió, thùng xe, vỏ máy và nơi không tiếp cận được mặt sau.","ex_en":"Use a 4.8 mm blind rivet with a grip range of 3–6 mm for this panel.","ex_ja":"このパネルには、板厚範囲3〜6 mmの4.8 mmブラインドリベットを使う。","ex_vi":"Với tấm này hãy dùng đinh rút 4,8 mm có phạm vi kẹp 3–6 mm.","syn_en":["pop rivet (khẩu ngữ)"],"syn_ja":["ポップリベット (tên thương mại)"]},{"en":"tack weld","pos":"noun","ipa":"/ˈtæk weld/","ja":"仮付け溶接","kana":"かりづけようせつ","romaji":"karizukeyousetsu","vi":"hàn đính","level":1,"def_vi":"Mối hàn ngắn tạm thời để giữ các chi tiết đúng vị trí trước khi hàn chính thức.","def_en":"A short temporary weld that holds parts in position before final welding.","def_ja":"本溶接の前に部材を所定位置に保持するための短い溶接。","usage_en":"Danh từ đếm được; cũng là động từ (to tack, tack-weld). Hay đi với: tack weld spacing, tack the parts together.","usage_ja":"Ngoài xưởng nói 仮付け, タック. Hay đi với: 仮付けする, 仮付けピッチ, 本溶接.","context_vi":"Dùng trong mọi công việc chế tạo kết cấu hàn, gá lắp khung và nối ống.","ex_en":"Place a tack weld every 150 mm before welding the seam.","ex_ja":"継ぎ目を溶接する前に、150 mmごとに仮付け溶接をする。","ex_vi":"Hàn đính cứ mỗi 150 mm một điểm trước khi hàn đường nối.","syn_en":["tack"],"syn_ja":["仮付け","タック溶接"]},{"en":"T-joint","pos":"noun","ipa":"/ˈtiː dʒɔɪnt/","ja":"T継手","kana":"ティーつぎて","romaji":"tiitsugite","vi":"mối ghép chữ T","level":2,"def_vi":"Kiểu mối ghép trong đó một tấm đặt vuông góc lên mặt tấm kia, tạo thành hình chữ T.","def_en":"A joint in which one plate meets the surface of another at a right angle, forming a T.","def_ja":"一方の板を他方の板の面に直角に突き当てて、T字形にした継手。","usage_en":"Danh từ đếm được; viết T-joint (chữ T hoa). Hay đi với: double fillet weld on a T-joint, corner joint, edge joint.","usage_ja":"Hay đi với: T継手のすみ肉溶接, かど継手, へり継手. Đọc là ティーつぎて.","context_vi":"Dùng trong khung thép, gân tăng cứng, dầm chữ I hàn và giá đỡ máy.","ex_en":"The stiffener forms a T-joint with the base plate.","ex_ja":"補強板はベースプレートとT継手を構成している。","ex_vi":"Gân tăng cứng tạo thành mối ghép chữ T với tấm đế.","syn_en":["tee joint"],"syn_ja":["T形継手"]},{"en":"weld groove","pos":"noun","ipa":"/ˈweld ɡruːv/","ja":"開先","kana":"かいさき","romaji":"kaisaki","vi":"mép vát hàn (rãnh hàn)","level":2,"def_vi":"Rãnh tạo bằng cách vát mép các chi tiết trước khi hàn để kim loại hàn ngấu hết chiều dày.","def_en":"The opening prepared by bevelling plate edges so the weld can penetrate the full thickness.","def_ja":"溶接前に部材の端を加工して設ける溝で、板厚全体を溶け込ませるためのもの。","usage_en":"Danh từ đếm được. Hay đi với: V-groove, bevel angle, root gap, root face; động từ: prepare / bevel / machine the groove.","usage_ja":"Hay đi với: V形開先, レ形開先, 開先角度, ルート間隔, 開先加工. Từ rất quan trọng trong xưởng hàn Nhật.","context_vi":"Dùng trong hàn tấm dày, nối ống, chuẩn bị phôi và bản vẽ chế tạo kết cấu.","ex_en":"A 60° V weld groove with a 2 mm root gap is specified for the 16 mm plate.","ex_ja":"板厚16 mmには、ルート間隔2 mm、角度60°のV形開先が指定されている。","ex_vi":"Với tấm dày 16 mm, bản vẽ chỉ định mép vát hàn chữ V 60° với khe hở chân 2 mm.","syn_en":["groove","bevel preparation"],"syn_ja":["グルーブ","開先形状"]},{"en":"welding symbol","pos":"noun","ipa":"/ˈweldɪŋ ˌsɪmbl/","ja":"溶接記号","kana":"ようせつきごう","romaji":"yousetsukigou","vi":"ký hiệu hàn","level":2,"def_vi":"Ký hiệu chuẩn trên bản vẽ gồm đường mũi tên, đường chuẩn và ký hiệu cơ bản cho biết loại, kích thước và vị trí mối hàn.","def_en":"A standard drawing symbol with arrow and reference line that specifies weld type, size and location.","def_ja":"矢・基線・基本記号などで、溶接の種類・寸法・位置を図面に指示する記号。","usage_en":"Danh từ đếm được. Hay đi với: arrow side, other side, reference line, weld-all-around symbol; theo AWS A2.4 hoặc ISO 2553.","usage_ja":"Theo JIS Z3021. Hay đi với: 矢の側, 矢の反対側, 基線, 全周溶接, 現場溶接.","context_vi":"Dùng khi đọc và vẽ bản vẽ chế tạo kết cấu hàn, bình áp lực và khung máy.","ex_en":"The welding symbol calls for a 5 mm fillet weld all around.","ex_ja":"この溶接記号は脚長5 mmの全周すみ肉溶接を指示している。","ex_vi":"Ký hiệu hàn này yêu cầu hàn góc 5 mm toàn chu vi.","syn_en":["weld symbol"],"syn_ja":["溶接指示記号"]},{"en":"leg length","pos":"noun phrase","ipa":"/ˈleɡ leŋθ/","ja":"脚長","kana":"きゃくちょう","romaji":"kyakuchou","vi":"cạnh mối hàn góc (chiều dài cạnh)","level":2,"def_vi":"Khoảng cách từ chân mối hàn góc đến đỉnh góc ghép, đo dọc theo mỗi tấm.","def_en":"The distance from the root of a fillet weld to its toe, measured along each plate.","def_ja":"すみ肉溶接のルートから止端までの、各板に沿った長さ。","usage_en":"Danh từ đếm được, ký hiệu z. Hay đi với: specified leg length, unequal leg lengths, measure with a weld gauge.","usage_ja":"Ký hiệu S hoặc z. Hay đi với: 脚長を測る, 脚長不足, 溶接ゲージ. Ngoài xưởng nói chung là サイズ.","context_vi":"Dùng khi ghi kích thước mối hàn góc trên bản vẽ và kiểm tra bằng dưỡng đo mối hàn.","ex_en":"Several welds failed inspection because the leg length was only 4 mm instead of 6 mm.","ex_ja":"脚長が6 mmのところ4 mmしかなかったため、数か所の溶接が検査で不合格となった。","ex_vi":"Một số mối hàn bị loại khi kiểm tra vì cạnh mối hàn chỉ đạt 4 mm thay vì 6 mm.","syn_en":["leg size","fillet size"],"syn_ja":["すみ肉のサイズ"]},{"en":"throat thickness","pos":"noun phrase","ipa":"/ˈθrəʊt ˌθɪknəs/","ja":"のど厚","kana":"のどあつ","romaji":"nodoatsu","vi":"chiều dày tính toán mối hàn (chiều cao tam giác hàn)","level":2,"def_vi":"Khoảng cách nhỏ nhất từ chân mối hàn đến bề mặt mối hàn, dùng để tính bền mối hàn góc.","def_en":"The shortest distance from the weld root to the weld face, used to calculate weld strength.","def_ja":"溶接のルートから表面までの最短距離で、溶接部の強度計算に用いる。","usage_en":"Danh từ không đếm được, ký hiệu a. Hay đi với: effective throat thickness; với hàn góc đều cạnh a ≈ 0,7 × leg length.","usage_ja":"Ký hiệu a. Hay đi với: 理論のど厚, 有効のど厚, のど断面積. a = 0.7 × 脚長 cho すみ肉 đều cạnh.","context_vi":"Dùng trong tính toán sức bền mối hàn và ký hiệu kích thước hàn theo ISO (ký hiệu a).","ex_en":"The weld stress is calculated on the throat thickness, not on the leg length.","ex_ja":"溶接部の応力は脚長ではなくのど厚で計算する。","ex_vi":"Ứng suất mối hàn được tính theo chiều dày tính toán chứ không theo cạnh mối hàn.","syn_en":["throat","effective throat"],"syn_ja":["理論のど厚","有効のど厚"]},{"en":"heat-affected zone","pos":"noun phrase","ipa":"/ˌhiːt əˈfektɪd ˌzəʊn/","ja":"熱影響部","kana":"ねつえいきょうぶ","romaji":"netsueikyoubu","vi":"vùng ảnh hưởng nhiệt","level":2,"def_vi":"Vùng kim loại cơ bản không bị nóng chảy nhưng bị thay đổi tổ chức và cơ tính do nhiệt hàn.","def_en":"The base-metal region not melted but whose structure and properties are changed by welding heat.","def_ja":"溶融はしないが、溶接熱で組織や性質が変化した母材の部分。","usage_en":"Danh từ đếm được; viết tắt HAZ. Hay đi với: HAZ hardness, HAZ cracking, narrow / wide heat-affected zone.","usage_ja":"Viết tắt HAZ. Hay đi với: 熱影響部の硬さ, 熱影響部の割れ, 溶接金属・熱影響部・母材.","context_vi":"Dùng khi đánh giá quy trình hàn, đo độ cứng, phân tích nứt và thiết kế kết cấu chịu mỏi.","ex_en":"The crack started in the heat-affected zone where hardness exceeded 350 HV.","ex_ja":"割れは硬さが350 HVを超えた熱影響部から発生した。","ex_vi":"Vết nứt bắt đầu trong vùng ảnh hưởng nhiệt, nơi độ cứng vượt 350 HV.","syn_en":["HAZ"],"syn_ja":["HAZ"]},{"en":"welding distortion","pos":"noun phrase","ipa":"/ˈweldɪŋ dɪˌstɔːʃn/","ja":"溶接変形","kana":"ようせつへんけい","romaji":"yousetsuhenkei","vi":"biến dạng hàn (cong vênh do hàn)","level":2,"def_vi":"Sự cong vênh, co ngót hoặc xoay góc của kết cấu do giãn nở và co lại không đều khi hàn.","def_en":"Warping, shrinkage or angular change of a structure caused by uneven heating and cooling during welding.","def_ja":"溶接時の不均一な加熱・冷却により、構造物に生じる収縮やそり・角変形。","usage_en":"Danh từ không đếm được. Hay đi với: angular distortion, control / minimise welding distortion, presetting, straightening.","usage_ja":"Hay đi với: 角変形, 縦収縮, ひずみ取り, 逆ひずみ法. Ngoài xưởng nói 溶接ひずみ.","context_vi":"Dùng khi lập quy trình hàn, thiết kế đồ gá hàn và nắn sửa kết cấu sau hàn.","ex_en":"Welding distortion was reduced by welding alternately from both sides.","ex_ja":"両側から交互に溶接することで溶接変形を小さくした。","ex_vi":"Biến dạng hàn được giảm bằng cách hàn xen kẽ từ hai phía.","syn_en":["weld distortion","weld warpage"],"syn_ja":["溶接ひずみ"]},{"en":"plug weld","pos":"noun","ipa":"/ˈplʌɡ weld/","ja":"栓溶接","kana":"せんようせつ","romaji":"sen'yousetsu","vi":"hàn lỗ (hàn nút)","level":2,"def_vi":"Mối hàn điền đầy một lỗ tròn khoan trên tấm trên để nối nó với tấm bên dưới trong mối ghép chồng.","def_en":"A weld that fills a round hole in the upper plate to join it to the plate below in a lap joint.","def_ja":"重ね継手で上板にあけた丸穴を溶着金属で埋めて、下板と接合する溶接。","usage_en":"Danh từ đếm được. Hay đi với: plug weld hole diameter, slot weld (lỗ dài); thường dùng thay spot weld khi sửa chữa.","usage_ja":"Hay đi với: 栓溶接の穴径, スロット溶接 (lỗ dài). Ngoài xưởng gọi プラグ溶接.","context_vi":"Dùng trong sửa chữa thân xe, ghép tấm chồng và kết cấu thép tấm.","ex_en":"Replace each factory spot weld with a plug weld through an 8 mm hole.","ex_ja":"工場出荷時のスポット溶接部は、それぞれ8 mm穴の栓溶接で置き換える。","ex_vi":"Thay mỗi điểm hàn điểm của nhà máy bằng một mối hàn lỗ qua lỗ 8 mm.","syn_en":["slot weld (lỗ dài)"],"syn_ja":["プラグ溶接","スロット溶接 (lỗ dài)"]},{"en":"riveted joint","pos":"noun","ipa":"/ˌrɪvɪtɪd ˈdʒɔɪnt/","ja":"リベット継手","kana":"リベットつぎて","romaji":"ribettotsugite","vi":"mối ghép đinh tán","level":2,"def_vi":"Mối ghép cố định giữa các tấm bằng một hoặc nhiều hàng đinh tán.","def_en":"A permanent joint between plates made with one or more rows of rivets.","def_ja":"一列または複数列のリベットで板を締結した永久継手。","usage_en":"Danh từ đếm được. Hay đi với: single-row / double-row riveted joint, lap / butt riveted joint, rivet shear, plate tearing.","usage_ja":"Hay đi với: 一列リベット継手, 重ねリベット継手, 突合せリベット継手 (có tấm ốp).","context_vi":"Dùng trong kết cấu máy bay, cầu thép cũ, nồi hơi cũ và các mối ghép không hàn được.","ex_en":"A double-row riveted joint was used because the aluminium alloy cannot be welded.","ex_ja":"そのアルミニウム合金は溶接できないため、二列リベット継手を採用した。","ex_vi":"Đã dùng mối ghép đinh tán hai hàng vì hợp kim nhôm này không hàn được.","syn_en":["rivet joint"],"syn_ja":["リベット接合"]},{"en":"rivet pitch","pos":"noun phrase","ipa":"/ˈrɪvɪt pɪtʃ/","ja":"リベットピッチ","kana":"リベットピッチ","romaji":"ribettopitchi","vi":"bước đinh tán","level":2,"def_vi":"Khoảng cách giữa tâm hai đinh tán liền kề trên cùng một hàng.","def_en":"The centre-to-centre distance between adjacent rivets in the same row.","def_ja":"同じ列で隣り合うリベットの中心間距離。","usage_en":"Danh từ đếm được, ký hiệu p. Hay đi với: edge distance, row pitch, minimum rivet pitch (thường ≥ 3d).","usage_ja":"Ký hiệu p. Hay đi với: へりあき (khoảng cách mép), 列間距離, ピッチは3d以上.","context_vi":"Dùng khi thiết kế, bố trí và kiểm tra mối ghép đinh tán trên bản vẽ.","ex_en":"The rivet pitch must be at least three times the rivet diameter.","ex_ja":"リベットピッチはリベット径の3倍以上としなければならない。","ex_vi":"Bước đinh tán phải ít nhất bằng ba lần đường kính đinh.","syn_en":["rivet spacing"],"syn_ja":["リベット間隔"]},{"en":"epoxy adhesive","pos":"noun","ipa":"/ɪˈpɒksi ədˌhiːsɪv/","ja":"エポキシ樹脂接着剤","kana":"エポキシじゅしせっちゃくざい","romaji":"epokishijushisetchakuzai","vi":"keo epoxy","level":2,"def_vi":"Keo gốc nhựa epoxy, thường hai thành phần, đóng rắn tạo mối dán bền, chịu nhiệt và hóa chất tốt.","def_en":"An adhesive based on epoxy resin, often two-part, giving strong, heat- and chemical-resistant bonds.","def_ja":"エポキシ樹脂を主成分とし、多くは二液形で、強度と耐熱・耐薬品性に優れる接着剤。","usage_en":"Danh từ đếm được hoặc không đếm được. Hay đi với: two-part epoxy adhesive, mix ratio, pot life, cure time; khẩu ngữ nói tắt epoxy.","usage_ja":"Ngoài xưởng nói エポキシ hoặc エポキシ系接着剤. Hay đi với: 主剤と硬化剤, 混合比, 可使時間.","context_vi":"Dùng để dán kim loại, composite, gắn nam châm, điền khe và sửa chữa chi tiết máy.","ex_en":"Mix the epoxy adhesive at 1:1 and use it within 30 minutes.","ex_ja":"エポキシ樹脂接着剤は1:1で混合し、30分以内に使い切ること。","ex_vi":"Trộn keo epoxy theo tỉ lệ 1:1 và dùng hết trong vòng 30 phút.","syn_en":["epoxy","two-part epoxy"],"syn_ja":["エポキシ系接着剤","エポキシ (khẩu ngữ)"]},{"en":"cyanoacrylate adhesive","pos":"noun","ipa":"/ˌsaɪənəʊˈækrɪleɪt ədˌhiːsɪv/","ja":"瞬間接着剤","kana":"しゅんかんせっちゃくざい","romaji":"shunkansetchakuzai","vi":"keo dán nhanh (keo 502)","level":2,"def_vi":"Keo một thành phần đóng rắn trong vài giây nhờ hơi ẩm trên bề mặt, dùng cho chi tiết nhỏ.","def_en":"A one-part adhesive that cures in seconds with surface moisture, used for small parts.","def_ja":"表面の水分で数秒で硬化する一液形の接着剤で、小部品に用いる。","usage_en":"Danh từ không đếm được; khẩu ngữ gọi super glue, viết tắt CA. Hay đi với: instant adhesive, fixture time, brittle.","usage_ja":"Tên hóa học シアノアクリレート系接着剤. Hay đi với: 瞬間接着剤で仮止めする, 白化 (vết mờ trắng).","context_vi":"Dùng để gắn chi tiết nhựa, cao su, nối gioăng O, cố định tạm trong lắp ráp điện tử.","ex_en":"A drop of cyanoacrylate adhesive holds the label plate until the rivets are set.","ex_ja":"リベットを打つまで、銘板は瞬間接着剤一滴で仮止めしておく。","ex_vi":"Một giọt keo dán nhanh giữ tấm nhãn cho đến khi tán đinh xong.","syn_en":["super glue (khẩu ngữ)","instant adhesive"],"syn_ja":["シアノアクリレート系接着剤"]},{"en":"brazed joint","pos":"noun","ipa":"/ˌbreɪzd ˈdʒɔɪnt/","ja":"ろう付け継手","kana":"ろうづけつぎて","romaji":"rouzuketsugite","vi":"mối hàn vảy cứng (mối hàn đồng)","level":2,"def_vi":"Mối ghép trong đó kim loại vảy hàn nóng chảy (trên 450 °C) điền vào khe hẹp mà kim loại cơ bản không chảy.","def_en":"A joint in which a filler metal melting above 450 °C fills a narrow gap without melting the base metal.","def_ja":"母材を溶かさず、450 °C以上で溶けるろう材をすきまに流し込んで接合した継手。","usage_en":"Danh từ đếm được. Hay đi với: joint clearance, filler metal, silver braze, flux; khác welded joint vì kim loại cơ bản không chảy.","usage_ja":"Hay đi với: 銀ろう, りん銅ろう, フラックス, ろう付けすきま. Ngoài xưởng nói ろう付け部.","context_vi":"Dùng trong ống đồng điều hòa, dao hợp kim gắn mảnh, bộ trao đổi nhiệt và chi tiết khác vật liệu.","ex_en":"Every brazed joint in the refrigerant line is leak-tested with nitrogen.","ex_ja":"冷媒配管のろう付け継手はすべて窒素で漏れ試験を行う。","ex_vi":"Mọi mối hàn vảy cứng trên đường ống môi chất lạnh đều được thử kín bằng nitơ.","syn_en":["braze joint"],"syn_ja":["ろう付け部"]},{"en":"curing","pos":"noun","ipa":"/ˈkjʊərɪŋ/","ja":"硬化","kana":"こうか","romaji":"kouka","vi":"đóng rắn (khô keo)","level":2,"def_vi":"Quá trình keo chuyển từ dạng lỏng sang rắn nhờ phản ứng hóa học, nhiệt, độ ẩm hoặc tia UV.","def_en":"The process by which an adhesive changes from liquid to solid by reaction, heat, moisture or UV light.","def_ja":"接着剤が化学反応・熱・湿気・紫外線などで液体から固体に変わる過程。","usage_en":"Danh từ không đếm được; động từ cure (the adhesive cures). Hay đi với: curing time, room-temperature curing, heat curing, fully cured.","usage_ja":"Hay đi với: 硬化時間, 常温硬化, 加熱硬化, UV硬化, 硬化させる. Không nhầm với 硬化 nghĩa tôi cứng kim loại (焼入れ硬化).","context_vi":"Dùng trong quy trình dán keo, sơn, composite và khi lập thời gian chờ trên dây chuyền.","ex_en":"Full strength is reached after 24 hours of curing at room temperature.","ex_ja":"常温で24時間硬化させると最大強度に達する。","ex_vi":"Mối dán đạt độ bền tối đa sau 24 giờ đóng rắn ở nhiệt độ phòng.","syn_en":["cure","setting"],"syn_ja":["キュア","固化 (liên quan)"]},{"en":"full penetration weld","pos":"noun","ipa":"/ˌfʊl ˌpenɪˈtreɪʃn weld/","ja":"完全溶込み溶接","kana":"かんぜんとけこみようせつ","romaji":"kanzentokekomiyousetsu","vi":"mối hàn ngấu hoàn toàn (ngấu thấu)","level":3,"def_vi":"Mối hàn mà kim loại hàn ngấu suốt toàn bộ chiều dày chi tiết, có độ bền tương đương kim loại cơ bản.","def_en":"A weld that penetrates the full thickness of the joint, giving strength equal to the base metal.","def_ja":"継手の板厚全体にわたって溶け込ませ、母材と同等の強度をもたせた溶接。","usage_en":"Danh từ đếm được. Hay đi với: complete joint penetration (CJP, theo AWS), back gouging, backing strip; đối lập partial penetration.","usage_ja":"Hay đi với: 完全溶込み溶接 (CJP), 部分溶込み溶接, 裏はつり, 裏当て金. Ngoài xưởng nói 完溶 hoặc フルペネ.","context_vi":"Dùng ở dầm cầu, kết cấu chịu mỏi, bình áp lực và mối nối cột – dầm của nhà thép.","ex_en":"The flange-to-column connection requires a full penetration weld with back gouging.","ex_ja":"フランジと柱の接合部には、裏はつりを伴う完全溶込み溶接が必要である。","ex_vi":"Liên kết bản cánh với cột yêu cầu mối hàn ngấu hoàn toàn có thổi/dũi mặt sau.","syn_en":["complete joint penetration weld","CJP weld"],"syn_ja":["完溶 (khẩu ngữ)","フルペネ (khẩu ngữ)"]},{"en":"welding residual stress","pos":"noun phrase","ipa":"/ˈweldɪŋ rɪˌzɪdjuəl ˈstres/","ja":"溶接残留応力","kana":"ようせつざんりゅうおうりょく","romaji":"yousetsuzanryuuouryoku","vi":"ứng suất dư do hàn","level":3,"def_vi":"Ứng suất tồn tại trong kết cấu sau khi hàn và nguội, không có tải ngoài, do co ngót không đều.","def_en":"Stress left in a structure after welding and cooling, without external load, caused by uneven shrinkage.","def_ja":"溶接後、外力がなくても不均一な収縮により構造物内に残る応力。","usage_en":"Danh từ không đếm được. Hay đi với: relieve welding residual stress, post-weld heat treatment (PWHT), tensile residual stress.","usage_ja":"Hay đi với: 溶接残留応力を除去する, 溶接後熱処理 (PWHT), 応力除去焼なまし.","context_vi":"Dùng khi đánh giá nứt, mỏi, ăn mòn ứng suất và lập quy trình xử lý nhiệt sau hàn.","ex_en":"Post-weld heat treatment at 620 °C lowered the welding residual stress by about 80%.","ex_ja":"620 °Cでの溶接後熱処理により、溶接残留応力が約80%低下した。","ex_vi":"Xử lý nhiệt sau hàn ở 620 °C làm ứng suất dư do hàn giảm khoảng 80%.","syn_en":["weld residual stress","residual stress (nghĩa rộng hơn)"],"syn_ja":["残留応力 (nghĩa rộng hơn)"]},{"en":"joint efficiency","pos":"noun phrase","ipa":"/ˈdʒɔɪnt ɪˌfɪʃnsi/","ja":"継手効率","kana":"つぎてこうりつ","romaji":"tsugitekouritsu","vi":"hệ số bền mối ghép (hiệu suất mối ghép)","level":3,"def_vi":"Tỉ số giữa độ bền của mối ghép hàn hoặc đinh tán và độ bền của tấm nguyên không có mối ghép.","def_en":"The ratio of the strength of a welded or riveted joint to that of the solid plate.","def_ja":"溶接やリベットの継手の強さと、継手のない母材の強さとの比。","usage_en":"Danh từ không đếm được, ký hiệu E hoặc η. Hay đi với: weld joint efficiency 0.85 / 1.0, depends on radiography extent.","usage_ja":"Ký hiệu η. Hay đi với: 溶接継手効率, 放射線透過試験の程度で決まる. Dùng trong tính bình áp lực theo JIS B8265.","context_vi":"Dùng khi tính chiều dày thành bình áp lực, nồi hơi và đường ống có mối hàn dọc.","ex_en":"With spot radiography, a joint efficiency of 0.85 is used in the shell thickness calculation.","ex_ja":"部分放射線透過試験の場合、胴の板厚計算では継手効率を0.85とする。","ex_vi":"Khi chụp phim xác suất, hệ số bền mối ghép 0,85 được dùng để tính chiều dày thân bình.","syn_en":["weld joint efficiency","joint factor"],"syn_ja":["溶接継手効率"]},{"en":"self-piercing rivet","pos":"noun","ipa":"/ˌself ˈpɪəsɪŋ ˈrɪvɪt/","ja":"セルフピアスリベット","kana":"セルフピアスリベット","romaji":"serufupiasuribetto","vi":"đinh tán tự đột (SPR)","level":3,"def_vi":"Đinh tán rỗng được ép xuyên tấm trên rồi loe ra trong tấm dưới nhờ khuôn, không cần khoan lỗ trước.","def_en":"A semi-tubular rivet pressed through the top sheet and flared into the bottom sheet by a die, without a pre-drilled hole.","def_ja":"下穴なしで上板を貫通させ、ダイで下板内に広げて締結する半中空リベット。","usage_en":"Danh từ đếm được; viết tắt SPR. Hay đi với: SPR joint, setting force, die, mixed-material joining.","usage_ja":"Viết tắt SPR. Hay đi với: SPR接合, ダイ形状, 異材接合 (アルミと鋼).","context_vi":"Dùng trong thân xe nhôm, ghép nhôm với thép và nơi hàn điểm không áp dụng được.","ex_en":"The aluminium body panels are joined with self-piercing rivets and structural adhesive.","ex_ja":"アルミ製ボディパネルはセルフピアスリベットと構造用接着剤で接合されている。","ex_vi":"Các tấm thân xe bằng nhôm được ghép bằng đinh tán tự đột kết hợp keo kết cấu.","syn_en":["SPR"],"syn_ja":["SPR"]},{"en":"structural adhesive","pos":"noun","ipa":"/ˈstrʌktʃərəl ədˌhiːsɪv/","ja":"構造用接着剤","kana":"こうぞうようせっちゃくざい","romaji":"kouzouyousetchakuzai","vi":"keo kết cấu","level":3,"def_vi":"Keo có độ bền cao, đủ để chịu tải chính của kết cấu trong thời gian dài, thường là epoxy, acrylic hoặc polyurethane.","def_en":"A high-strength adhesive able to carry primary structural loads over the long term.","def_ja":"構造物の主要な荷重を長期間支えられる高強度の接着剤。","usage_en":"Danh từ đếm được hoặc không đếm được. Hay đi với: crash-resistant structural adhesive, bond line thickness, weld-bonding.","usage_ja":"Hay đi với: 構造用接着剤による接合, ウェルドボンド (kết hợp hàn điểm), 接着層厚さ.","context_vi":"Dùng trong thân xe ô tô, máy bay, cánh tuabin gió và kết cấu composite.","ex_en":"The structural adhesive increased the torsional stiffness of the body by 15%.","ex_ja":"構造用接着剤により車体のねじり剛性が15%向上した。","ex_vi":"Keo kết cấu đã làm độ cứng xoắn của thân xe tăng 15%.","syn_en":["structural bonding adhesive"],"syn_ja":["構造接着剤"]},{"en":"lap shear strength","pos":"noun phrase","ipa":"/ˈlæp ʃɪə ˌstreŋθ/","ja":"引張せん断接着強さ","kana":"ひっぱりせんだんせっちゃくつよさ","romaji":"hipparisendansetchakutsuyosa","vi":"độ bền cắt mối dán chồng","level":3,"def_vi":"Độ bền của mối dán chồng một lớp khi bị kéo tách dưới tải cắt, là chỉ tiêu thử nghiệm keo phổ biến nhất.","def_en":"The shear strength of a single-lap bonded joint pulled in tension, the most common adhesive test value.","def_ja":"単純重ね合わせ接着継手を引張って求めるせん断強さで、最も一般的な接着の試験値。","usage_en":"Danh từ không đếm được, đơn vị MPa. Hay đi với: lap shear test (ASTM D1002, ISO 4587), cohesive / adhesive failure.","usage_ja":"Theo JIS K6850. Hay đi với: 引張せん断接着強さ試験, 凝集破壊, 界面破壊. Ngoài xưởng nói せん断強度.","context_vi":"Dùng khi chọn keo, so sánh nhà cung cấp và kiểm tra chất lượng mối dán.","ex_en":"The adhesive showed a lap shear strength of 25 MPa on steel with cohesive failure.","ex_ja":"この接着剤の鋼に対する引張せん断接着強さは25 MPaで、凝集破壊であった。","ex_vi":"Keo này đạt độ bền cắt mối dán chồng 25 MPa trên thép, phá hủy kiểu nội kết.","syn_en":["single-lap shear strength","tensile shear strength"],"syn_ja":["せん断接着強さ","せん断強度 (khẩu ngữ)"]}]}]};
